/* Native per-note Liberty map used by the Places Location card. */
.cv-place-local-map {
  --bases-map-embed-height: 240px;
  position: relative;
  isolation: isolate;
  width: calc(100% - 28px);
  min-height: 240px;
  margin: 14px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 26%, var(--cvp-border-strong) 74%);
  border-radius: var(--cvp-radius);
  background: var(--cvp-surface-2);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvp-text) 3%, transparent), 0 8px 24px var(--cvp-shadow-soft);
}

.cv-place-local-map::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 28px color-mix(in srgb, var(--cvp-bg) 24%, transparent);
}

.cv-place-local-map-embed,
.cv-place-local-map-embed > span {
  display: block;
  width: 100%;
  min-width: 0;
  min-height: 240px;
}

.cv-place-local-map-embed :is(.internal-embed, .markdown-embed, .bases-embed) {
  width: 100% !important;
  min-width: 0 !important;
  min-height: 240px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.cv-place-local-map-embed :is(.markdown-embed-title, .internal-embed-title, .embed-title, .bases-toolbar, .bases-header) {
  display: none !important;
}

.cv-place-local-map-embed .bases-view[data-view-type="map"],
.cv-place-local-map-embed .bases-map-container,
.cv-place-local-map-embed .bases-map {
  width: 100% !important;
  min-width: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
}

.cv-place-local-map-embed .bases-map-container,
.cv-place-local-map-embed .bases-map {
  min-height: 240px !important;
  height: 240px !important;
}

.cv-place-local-map-embed .bases-map-container {
  overflow: hidden;
}

/* Keep the native MapLibre map north-up, like the Map Base; no extra compass overlay. */
.cv-place-local-map .cv-place-map-caption,
.cv-place-local-map .cv-place-map-readout {
  position: absolute;
  z-index: 8;
  pointer-events: none;
  border: 1px solid color-mix(in srgb, var(--cvp-border-strong) 72%, transparent);
  background: color-mix(in srgb, var(--cvp-bg) 78%, transparent);
  box-shadow: 0 3px 12px var(--cvp-shadow-soft);
  backdrop-filter: blur(7px);
}

.cv-place-local-map .cv-place-map-caption {
  left: 10px;
  top: 10px;
  padding: 5px 7px;
  border-radius: 7px;
  color: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent-soft)) 78%, var(--cvp-text) 22%);
  font-size: .58rem;
  line-height: 1;
  letter-spacing: .1em;
}

.cv-place-map-readout {
  left: 10px;
  bottom: 10px;
  display: grid;
  gap: 2px;
  max-width: 42%;
  min-width: 0;
  padding: 6px 8px;
  border-radius: 8px;
}

.cv-place-map-readout strong,
.cv-place-map-readout code {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-place-map-readout strong {
  color: var(--cvp-text);
  font-size: .69rem;
  line-height: 1.2;
  font-weight: 720;
}

.cv-place-map-readout code {
  padding: 0;
  background: none;
  color: var(--cvp-faint);
  font-family: var(--font-monospace);
  font-size: .58rem;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}

/* Local Index popup: title only, compact enough not to cover the mini map. */
.cv-place-local-map-embed .bases-map-popup {
  min-width: 0 !important;
  max-width: 150px !important;
}

.cv-place-local-map-embed .maplibregl-popup-content {
  padding: 0 !important;
  border-radius: 6px !important;
}

.cv-place-local-map-embed .bases-map-popup-title {
  max-width: 150px;
  padding: 4px 7px !important;
  font-size: .66rem !important;
  line-height: 1.15 !important;
}

.cv-place-local-map-embed .bases-map-popup-title a {
  display: block;
  max-width: 136px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-place-local-map-embed .bases-map-popup-properties {
  display: none !important;
}

.cv-place-local-map:hover {
  border-color: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 50%, var(--cvp-border-strong) 50%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvp-text) 3%, transparent), 0 11px 28px var(--cvp-shadow-soft);
}

@container (max-width: 500px) {
  .cv-place-local-map {
    --bases-map-embed-height: 220px;
    min-height: 220px;
  }

  .cv-place-local-map-embed,
  .cv-place-local-map-embed > span,
  .cv-place-local-map-embed :is(.internal-embed, .markdown-embed, .bases-embed),
  .cv-place-local-map-embed .bases-map-container,
  .cv-place-local-map-embed .bases-map {
    min-height: 220px !important;
  }

  .cv-place-local-map-embed .bases-map-container,
  .cv-place-local-map-embed .bases-map {
    height: 220px !important;
  }

  .cv-place-map-readout {
    max-width: 46%;
  }
}

/* Places paper-note surface + direct metadata editing. */
.cv-place {
  --cvp-paper-line: var(--vault-note-paper-line, 30px);
  --cvp-paper: var(--vault-note-paper, color-mix(in srgb, var(--background-primary) 60%, var(--background-secondary) 40%));
  --cvp-paper-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 15%, transparent));
  --cvp-paper-margin: var(--vault-note-paper-margin-rule, color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 22%, transparent));
  --cvp-paper-edge: var(--vault-note-paper-edge, color-mix(in srgb, var(--cvp-border-strong) 72%, transparent));
}

/* Match the canonical ruled-paper note surface used by Games / Movies / TV. */
.cv-place-journal {
  min-width: 0;
  overflow: visible !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.cv-place-section-head--outer {
  min-height: 0;
  align-items: end;
  padding: 0 0 clamp(14px, 2cqi, 24px) !important;
  border: 0 !important;
  background: transparent !important;
}

.cv-place-paper {
  position: relative;
  min-height: calc(var(--cvp-paper-line) * 18);
  overflow: hidden;
  isolation: isolate;
  border: 1px solid var(--cvp-paper-edge);
  border-radius: 8px;
  background: var(--vault-note-paper-background,
    linear-gradient(90deg, transparent 0 44px, var(--cvp-paper-margin) 44px 45px, transparent 45px),
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--cvp-paper-line) - 7px),
      color-mix(in srgb, var(--cvp-paper-rule) 55%, transparent) calc(var(--cvp-paper-line) - 7px) calc(var(--cvp-paper-line) - 5px),
      transparent calc(var(--cvp-paper-line) - 5px) var(--cvp-paper-line)
    ),
    var(--cvp-paper));
  box-shadow: 0 8px 24px color-mix(in srgb, var(--cvp-shadow) 64%, transparent), 0 3px 10px color-mix(in srgb, var(--cvp-shadow) 44%, transparent);
}

.cv-place-paper-circles {
  position: absolute;
  z-index: 4;
  top: calc(var(--cvp-paper-line) * 2.4);
  bottom: calc(var(--cvp-paper-line) * 1.2);
  left: 12px;
  width: 22px;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 11px,
      color-mix(in srgb, var(--cvp-bg) 96%, transparent) 0 5px,
      color-mix(in srgb, var(--cvp-paper-edge) 78%, transparent) 5.5px 6.5px,
      transparent 7px)
    center top / 22px calc(var(--cvp-paper-line) * 3) repeat-y;
  opacity: .9;
}

.cv-place-paper .cv-place-section-head,
.cv-place-paper .cv-place-note-render {
  position: relative;
  z-index: 6;
}

.cv-place-paper .cv-place-section-head--paper {
  min-height: calc(var(--cvp-paper-line) * 2);
  align-items: center;
  padding: 0 clamp(18px, 3cqi, 32px) 0 clamp(54px, 5cqi, 66px) !important;
  border-bottom: 2px solid color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 34%, var(--cvp-border-strong) 66%) !important;
  background: transparent !important;
}

.cv-place-paper .cv-place-note-render {
  min-height: calc(var(--cvp-paper-line) * 16);
  padding: clamp(24px, 3.4cqi, 42px) clamp(20px, 3cqi, 36px) clamp(32px, 4cqi, 48px) clamp(54px, 5cqi, 66px) !important;
  background: transparent !important;
}

/* Keep metadata labels and values on the same visual baseline. */
.cv-place-meta-row {
  align-items: center !important;
}

.cv-place-meta-row dt,
.cv-place-meta-row dd {
  align-self: center;
  min-height: 28px;
  margin-top: 0;
  margin-bottom: 0;
}

.cv-place-meta-row dt {
  display: flex;
  align-items: center;
}

/* Metadata values become quiet text-like controls; values always start at the left edge of their column. */
.cv-place-meta-row dd {
  display: flex;
  align-items: center;
  justify-content: flex-start !important;
  text-align: left !important;
}

.cv-place-meta-row dd > * {
  text-align: left !important;
}

.cv-place-meta-edit {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  width: 100%;
  min-width: 0;
  min-height: 26px;
  margin: -2px -4px;
  padding: 2px 4px;
  overflow: hidden;
  border: 0;
  border-bottom: 1px solid transparent;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cvp-muted);
  cursor: text;
  text-align: left !important;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: border-color .14s var(--cvp-ease), color .14s var(--cvp-ease), background .14s var(--cvp-ease);
}

.cv-place-meta-edit:hover,
.cv-place-meta-edit:focus-visible {
  border-bottom-color: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 52%, transparent);
  background: transparent;
  color: var(--cvp-text);
}

.cv-place-meta-edit.is-empty {
  color: var(--cvp-faint);
  font-style: italic;
}

.cv-place-meta-input,
.cv-place-meta-select {
  width: 100%;
  min-width: 0;
  min-height: 29px;
  margin: -3px -5px;
  padding: 3px 5px;
  border: 1px solid var(--cvp-border-strong);
  border-radius: 5px;
  background: var(--cvp-surface-3);
  color: var(--cvp-text);
  box-shadow: none;
  font-size: .76rem;
  line-height: 1.35;
  text-align: left !important;
}

.cv-place-meta-row.is-editing dd {
  overflow: visible;
}

@container (max-width: 500px) {
  .cv-place-paper .cv-place-note-render {
    min-height: calc(var(--cvp-paper-line) * 12);
    padding-left: 48px !important;
  }

  .cv-place-paper .cv-place-section-head--paper {
    padding-left: 48px !important;
  }
}

/* Places parity with Movies / TV: Live Preview notes and 10-point rating. */

.cv-place-note-state {
  display: block;
  min-height: 1em;
  margin-top: 4px;
  color: var(--cvp-faint);
  font-family: var(--font-monospace);
  font-size: .62rem;
  line-height: 1.2;
}

.cv-place-note-render {
  cursor: text;
}

.cv-place.is-native-editor .cv-place-paper {
  border-color: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 62%, var(--cvp-paper-edge) 38%);
  box-shadow:
    0 8px 24px color-mix(in srgb, var(--cvp-shadow) 64%, transparent),
    inset 0 0 0 1px color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 10%, transparent);
}

.cv-place-note-render [data-cv-editable-placeholder],
.cv-place-note-render .markdown-source-view,
.cv-place-note-render .cm-editor,
.cv-place-note-render .cm-scroller,
.cv-place-note-render .cm-sizer,
.cv-place-note-render .cm-contentContainer,
.cv-place-note-render .cm-content {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  min-height: calc(var(--cvp-paper-line) * 14) !important;
  background: transparent !important;
}

.cv-place-note-render .cm-editor,
.cv-place-note-render .cm-scroller {
  height: auto !important;
}

.cv-place-note-render .cm-scroller {
  overflow: visible !important;
}

.cv-place-note-render .cm-content {
  padding: 0 !important;
  caret-color: var(--cvp-type-accent, var(--cvp-accent));
}

.cv-place-note-render .cm-gutters {
  display: none !important;
}

/* Rating copied from the Movies / TV interaction model: five visual stars, ten hit zones. */
.cv-place .cv-rating {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
}

.cv-place .cv-rating-stars {
  position: relative;
  width: min(100%, 186px);
  min-width: 0;
  height: clamp(22px, 3cqi, 30px);
  flex: 1 1 auto;
}

.cv-place .cv-rating-layer {
  position: absolute;
  inset: 0 auto 0 0;
  display: flex;
  gap: clamp(3px, .55cqi, 6px);
  overflow: hidden;
  pointer-events: none;
}

.cv-place .cv-rating-layer--empty {
  width: 100%;
  color: var(--cvp-border-strong);
}

.cv-place .cv-rating-layer--filled {
  width: 100%;
  color: var(--cvp-type-accent, var(--cvp-accent));
  -webkit-clip-path: inset(0 calc(100% - var(--cv-rating-fill, 0%)) 0 0);
  clip-path: inset(0 calc(100% - var(--cv-rating-fill, 0%)) 0 0);
}

.cv-place .cv-rating-star {
  width: auto;
  height: clamp(22px, 3cqi, 30px);
  min-width: 0;
  flex: 1 1 0;
  background: currentColor;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 22 12 18.56 5.82 22 7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") center / contain no-repeat;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 22 12 18.56 5.82 22 7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") center / contain no-repeat;
}

.cv-place .cv-rating-hits {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
}

.cv-place .cv-rating .cv-rating-hit {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  appearance: none !important;
  -webkit-appearance: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: transparent !important;
  cursor: pointer;
  transform: none !important;
}

.cv-place .cv-rating .cv-rating-hit:hover,
.cv-place .cv-rating .cv-rating-hit:active,
.cv-place .cv-rating .cv-rating-hit:focus,
.cv-place .cv-rating .cv-rating-hit:disabled {
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: transparent !important;
  transform: none !important;
}

.cv-place .cv-rating.is-saving .cv-rating-hit {
  cursor: wait;
}

.cv-place .cv-rating-hit:focus-visible {
  outline: 1px solid var(--cvp-type-accent, var(--cvp-accent));
  outline-offset: 1px;
}

.cv-place .cv-rating-value {
  min-width: 3.7em;
  color: var(--cvp-type-accent, var(--cvp-accent-soft));
  font-family: var(--font-monospace);
  font-size: .82rem;
  font-variant-numeric: tabular-nums;
}

/* Local Index attribution is rendered as a static credit below the map. */
.cv-place-local-map-embed .maplibregl-ctrl-bottom-right,
.cv-place-local-map-embed details.maplibregl-ctrl-attrib,
.cv-place-local-map-embed .maplibregl-ctrl-attrib {
  display: none !important;
}

@container (max-width: 500px) {
  .cv-place .cv-rating {
    gap: 8px;
  }

  .cv-place .cv-rating-value {
    font-size: .74rem;
  }
}

/* Local Index map controls: quiet zoom controls, attribution moved below the map. */
.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-in,
.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-out {
  transition: none !important;
}

.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-in:hover,
.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-in:active,
.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-out:hover,
.cv-place-local-map-embed .maplibregl-ctrl-group button.maplibregl-ctrl-zoom-out:active {
  background-color: inherit !important;
  filter: none !important;
}

/* The source credit is rendered immediately below Local Index instead. */
.cv-place-local-map-embed details.maplibregl-ctrl-attrib,
.cv-place-local-map-embed .maplibregl-ctrl-attrib {
  display: none !important;
}

.cv-place-map-credit {
  margin: -5px 16px 7px;
  color: color-mix(in srgb, var(--cvp-faint) 86%, transparent);
  font-family: var(--font-monospace);
  font-size: .54rem;
  line-height: 1.3;
  letter-spacing: .015em;
  text-align: right;
  user-select: none;
}

@container (max-width: 500px) {
  .cv-place-map-credit {
    margin-inline: 14px;
    font-size: .5rem;
  }
}

/* Places weather card — current conditions from OpenWeatherMap. */
.cv-place-weather-card {
  overflow: hidden;
}

.cv-place-weather-card > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.cv-place-weather-card > header h2 {
  margin-top: 4px;
  font-size: clamp(.92rem, 1.55cqi, 1.08rem);
  line-height: 1.14;
  letter-spacing: -.015em;
  white-space: nowrap;
}

.cv-place-weather-actions {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
}

.cv-place-weather-action {
  min-width: 32px;
  min-height: 30px;
  padding: 6px 9px;
  border: 1px solid var(--cvp-border) !important;
  border-radius: 9px !important;
  background: color-mix(in srgb, var(--cvp-surface-2) 88%, transparent) !important;
  color: var(--cvp-muted) !important;
  box-shadow: none !important;
  font-family: var(--font-monospace);
  font-size: .64rem;
  line-height: 1;
  letter-spacing: .04em;
}

.cv-place-weather-action:hover,
.cv-place-weather-action:focus-visible {
  border-color: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 48%, var(--cvp-border) 52%) !important;
  background: color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 9%, var(--cvp-surface-2) 91%) !important;
  color: var(--cvp-text) !important;
}

.cv-place-weather-action:disabled {
  opacity: .42;
  cursor: default;
}

.cv-place-weather-main {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  min-height: 84px;
  margin-top: 14px;
  padding-inline: 12px;
}

.cv-place-weather-icon-wrap {
  display: grid;
  place-items: center;
  width: 76px;
  height: 76px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 27%, var(--cvp-border) 73%);
  border-radius: 18px;
  background:
    radial-gradient(circle at 50% 35%, color-mix(in srgb, var(--cvp-type-accent, var(--cvp-accent)) 16%, transparent), transparent 64%),
    color-mix(in srgb, var(--cvp-surface-2) 90%, transparent);
}

.cv-place-weather-icon {
  display: block;
  width: 72px;
  height: 72px;
  object-fit: contain;
  filter: saturate(.82) contrast(1.03);
}

.cv-place-weather-icon[hidden] {
  display: none !important;
}

.cv-place-weather-symbol {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  color: var(--cvp-type-accent, var(--cvp-accent));
  font-size: 1.7rem;
  line-height: 1;
}

.cv-place-weather-symbol[hidden] {
  display: none !important;
}

.cv-place-weather-copy {
  min-width: 0;
}

.cv-place-weather-temp-line {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
}

.cv-place-weather-temp {
  color: var(--cvp-text);
  font-family: var(--font-text);
  font-size: clamp(2.15rem, 5.5cqi, 3.2rem);
  line-height: .92;
  font-weight: 760;
  letter-spacing: -.04em;
}

.cv-place-weather-unit {
  color: var(--cvp-muted);
  font-family: var(--font-monospace);
  font-size: .72rem;
}

.cv-place-weather-condition {
  display: block;
  margin-top: 7px;
  overflow: hidden;
  color: color-mix(in srgb, var(--cvp-text) 88%, var(--cvp-muted) 12%);
  font-size: .9rem;
  line-height: 1.3;
  font-weight: 680;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-place-weather-description {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  color: var(--cvp-muted);
  font-size: .72rem;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-place-weather-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  margin: 14px 12px 0;
  overflow: hidden;
  border: 1px solid var(--cvp-border);
  border-radius: 12px;
  background: var(--cvp-border);
}

.cv-place-weather-metric {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 10px 11px;
  background: color-mix(in srgb, var(--cvp-surface-2) 94%, transparent);
}

.cv-place-weather-metric span {
  color: var(--cvp-muted);
  font-family: var(--font-monospace);
  font-size: .56rem;
  line-height: 1.1;
  font-weight: 720;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.cv-place-weather-metric strong {
  overflow: hidden;
  color: var(--cvp-text);
  font-size: .74rem;
  line-height: 1.2;
  font-weight: 690;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-place-weather-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 9px;
  padding: 0 12px 10px;
  overflow: hidden;
  color: var(--cvp-faint);
  font-family: var(--font-monospace);
  font-size: .54rem;
  line-height: 1.35;
  white-space: nowrap;
}

.cv-place-weather-footer a {
  color: inherit !important;
  text-decoration: none !important;
}

.cv-place-weather-footer a:hover {
  color: var(--cvp-muted) !important;
}

.cv-place-weather-state {
  margin: 12px 12px 0;
  padding: 10px 12px;
  border: 1px dashed var(--cvp-border);
  border-radius: 10px;
  color: var(--cvp-muted);
  font-size: .7rem;
  line-height: 1.45;
}

.cv-place-weather-state[hidden] {
  display: none !important;
}

.cv-place-weather-state[data-tone="error"] {
  border-color: color-mix(in srgb, var(--color-red, #ef4444) 38%, var(--cvp-border) 62%);
  color: color-mix(in srgb, var(--color-red, #ef4444) 76%, var(--cvp-text) 24%);
}

.cv-place-weather-card.is-loading .cv-place-weather-main,
.cv-place-weather-card.is-loading .cv-place-weather-metrics {
  opacity: .54;
}

.cv-place-weather-card.is-stale .cv-place-weather-footer {
  color: color-mix(in srgb, var(--color-orange, #d97706) 64%, var(--cvp-muted) 36%);
}

@container (max-width: 420px) {
  .cv-place-weather-card > header h2 {
    font-size: .9rem;
  }

  .cv-place-weather-main {
    grid-template-columns: 62px minmax(0, 1fr);
    gap: 11px;
    padding-inline: 10px;
  }

  .cv-place-weather-icon-wrap,
  .cv-place-weather-icon,
  .cv-place-weather-symbol {
    width: 62px;
    height: 62px;
  }

  .cv-place-weather-metrics {
    margin-inline: 10px;
  }
}

