const placeContext = tp;
const placeContainer = placeContext.container || this;
const placeRoot = placeContainer.querySelector('[data-role="place-root"]');

if (placeRoot) {
  const placeApp = placeContext.app;
  const placeFile = placeContext.file;
  const placeFrontmatter = placeContext.frontmatter || {};
  const placeDocument = placeContext.activeDocument || placeRoot.ownerDocument;
  const placeWindow = placeDocument.defaultView;
  const bodyContent = String(placeContext.bodyContent || "");
  const q = selector => placeRoot.querySelector(selector);

  const TYPE_INFO = {
    tourist: { label: "Tourist destination", icon: "⌖" },
    restaurant: { label: "Restaurant", icon: "◉" },
    cafe: { label: "Café", icon: "◌" },
    bar: { label: "Bar", icon: "◆" },
    misc: { label: "Saved place", icon: "•" },
  };

  const text = value => value == null ? "" : String(value).trim();
  const bool = value => value === true || String(value).toLowerCase() === "true";
  const type = text(placeFrontmatter.place_type).toLowerCase() || "misc";
  const typeInfo = TYPE_INFO[type] || { label: type.replace(/[_-]+/g, " ") || "Place", icon: "⌖" };
  placeRoot.dataset.placeType = type;

  function setText(role, value) {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = value;
  }

  function resolveImage(value) {
    const raw = text(value);
    if (!raw) return "";
    if (/^https?:\/\//i.test(raw)) return raw;
    const wiki = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    const candidate = text(wiki ? wiki[1] : raw);
    if (!candidate || !placeApp?.metadataCache || !placeFile) return "";
    const target = placeApp.metadataCache.getFirstLinkpathDest(candidate, placeFile.path);
    if (target) return placeApp.vault.getResourcePath(target);
    const direct = placeApp.vault.getFileByPath?.(candidate);
    return direct ? placeApp.vault.getResourcePath(direct) : "";
  }

  function formatLocation() {
    return [placeFrontmatter.city, placeFrontmatter.region, placeFrontmatter.country]
      .map(text).filter(Boolean).filter((value, index, all) => all.indexOf(value) === index).join(" · ");
  }

  function addChip(label, positive = false) {
    const list = q('[data-role="hero-chips"]');
    if (!list || !label) return;
    const chip = placeDocument.createElement("span");
    chip.className = `cv-place-chip${positive ? " is-positive" : ""}`;
    chip.textContent = label;
    list.appendChild(chip);
  }

  function addMeta(list, label, value) {
    const clean = text(value);
    if (!list || !clean) return;
    const row = placeDocument.createElement("div");
    row.className = "cv-place-meta-row";
    const dt = placeDocument.createElement("dt");
    const dd = placeDocument.createElement("dd");
    dt.textContent = label;
    dd.textContent = clean;
    row.append(dt, dd);
    list.appendChild(row);
  }

  function renderMeta() {
    const locationList = q('[data-role="location-meta"]');
    const detailList = q('[data-role="details-meta"]');
    locationList?.replaceChildren();
    detailList?.replaceChildren();

    addMeta(locationList, "Address", placeFrontmatter.address);
    addMeta(locationList, "City", placeFrontmatter.city);
    addMeta(locationList, "Region", placeFrontmatter.region);
    addMeta(locationList, "Country", placeFrontmatter.country);

    addMeta(detailList, "Type", typeInfo.label);
    if (type === "restaurant" || type === "cafe" || type === "bar") {
      addMeta(detailList, "Cuisine", placeFrontmatter.cuisine);
      addMeta(detailList, "Price", placeFrontmatter.price_level);
    }
    addMeta(detailList, "Hours", placeFrontmatter.opening_hours);
    addMeta(detailList, "Last visit", placeFrontmatter.last_visited);
    addMeta(detailList, "Phone", placeFrontmatter.phone);
    addMeta(detailList, "Website", placeFrontmatter.website);

    if (detailList && !detailList.children.length) {
      const empty = placeDocument.createElement("div");
      empty.className = "cv-place-meta-empty";
      empty.textContent = "No extra details yet.";
      detailList.appendChild(empty);
    }
  }

  function paintControls() {
    placeRoot.querySelectorAll("[data-toggle-property]").forEach(button => {
      const property = button.dataset.toggleProperty;
      const active = bool(placeFrontmatter[property]);
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });

    const rating = Math.max(0, Math.min(5, Number(placeFrontmatter.rating) || 0));
    placeRoot.querySelectorAll("[data-rating]").forEach(button => {
      const score = Number(button.dataset.rating);
      button.classList.toggle("is-active", score <= rating);
      button.setAttribute("aria-pressed", score === rating ? "true" : "false");
    });
  }

  function renderSummary() {
    setText("type-label", typeInfo.label);
    setText("type-icon", typeInfo.icon);
    setText("location-line", formatLocation() || "Saved location");
    setText("hero-address", text(placeFrontmatter.address));
    setText("coordinates", text(placeFrontmatter.coordinates) || "No coordinates");
    setText("location-title", text(placeFrontmatter.city) || text(placeFrontmatter.region) || "Saved coordinates");
    setText("details-title", type === "tourist" ? "Destination profile" : typeInfo.label);

    const cover = q('[data-role="place-cover"]');
    const coverSrc = resolveImage(placeFrontmatter.cover);
    if (cover) {
      cover.hidden = !coverSrc;
      if (coverSrc) {
        cover.src = coverSrc;
        cover.alt = `Cover for ${placeFile?.basename || "place"}`;
      }
    }

    const chips = q('[data-role="hero-chips"]');
    chips?.replaceChildren();
    addChip(typeInfo.label);
    if (bool(placeFrontmatter.visited)) addChip("Visited", true);
    if (bool(placeFrontmatter.want_to_visit)) addChip("Want to visit");
    if (bool(placeFrontmatter.favorite)) addChip("Favorite", true);
    const rating = Number(placeFrontmatter.rating);
    if (Number.isFinite(rating) && rating > 0) addChip(`${rating}/5`);

    const website = q('[data-role="website-link"]');
    const websiteUrl = text(placeFrontmatter.website);
    if (website) {
      website.hidden = !/^https?:\/\//i.test(websiteUrl);
      if (!website.hidden) website.href = websiteUrl;
    }

    const noteRender = q('[data-role="note-render"]');
    if (noteRender) noteRender.classList.toggle("is-empty", !bodyContent.replace(/[#>*_`\-\s]/g, ""));
    renderMeta();
    paintControls();
  }

  function setSaveState(message, tone = "") {
    const state = q('[data-role="save-state"]');
    if (!state) return;
    state.textContent = message;
    state.dataset.tone = tone;
  }

  let frontmatterQueue = Promise.resolve();
  function updateFrontmatter(property, value) {
    if (!placeApp?.fileManager || !placeFile) return Promise.reject(new Error("Place file is unavailable"));
    const task = frontmatterQueue.then(async () => {
      await placeApp.fileManager.processFrontMatter(placeFile, draft => { draft[property] = value; });
      placeFrontmatter[property] = value;
    });
    frontmatterQueue = task.catch(() => {});
    return task;
  }

  placeRoot.querySelectorAll("[data-toggle-property]").forEach(button => {
    button.addEventListener("click", async () => {
      const property = button.dataset.toggleProperty;
      const next = !bool(placeFrontmatter[property]);
      button.disabled = true;
      setSaveState("Saving…");
      try {
        await updateFrontmatter(property, next);
        renderSummary();
        setSaveState("Saved", "success");
      } catch (error) {
        console.error(error);
        setSaveState("Could not save", "error");
      } finally {
        button.disabled = false;
      }
    });
  });

  placeRoot.querySelectorAll("[data-rating]").forEach(button => {
    button.addEventListener("click", async () => {
      const score = Number(button.dataset.rating);
      const currentRating = Math.max(0, Math.min(5, Number(placeFrontmatter.rating) || 0));
      const nextRating = currentRating === score ? null : score;
      setSaveState("Saving…");
      try {
        await updateFrontmatter("rating", nextRating);
        renderSummary();
        setSaveState(nextRating == null ? "Rating cleared" : "Saved", "success");
      } catch (error) {
        console.error(error);
        setSaveState("Could not save", "error");
      }
    });
  });

  async function openLibertyMap() {
    try {
      await placeApp.workspace.openLinkText("20_Personal_Life/23_Places/Map.base", placeFile?.path || "", false);
    } catch (error) {
      console.error(error);
      setSaveState("Could not open Map Base", "error");
    }
  }

  placeRoot.querySelectorAll('[data-action="open-map"]').forEach(button => {
    button.addEventListener("click", () => void openLibertyMap());
  });

  q('[data-action="directions"]')?.addEventListener("click", () => {
    const destination = text(placeFrontmatter.coordinates) || text(placeFrontmatter.address) || formatLocation();
    if (!destination) {
      setSaveState("Add coordinates or an address first", "error");
      return;
    }
    const url = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}`;
    placeWindow?.open?.(url, "_blank", "noopener,noreferrer");
  });

  q('[data-action="copy-coordinates"]')?.addEventListener("click", async () => {
    const coordinates = text(placeFrontmatter.coordinates);
    if (!coordinates) {
      setSaveState("No coordinates to copy", "error");
      return;
    }
    const clipboard = placeWindow?.navigator?.clipboard;
    if (!clipboard?.writeText) {
      setSaveState("Clipboard is unavailable", "error");
      return;
    }
    try {
      await clipboard.writeText(coordinates);
      setSaveState("Coordinates copied", "success");
    } catch (error) {
      console.error(error);
      setSaveState("Could not copy coordinates", "error");
    }
  });

  renderSummary();
}

(() => {
  const editContext = tp;
  const editContainer = editContext.container || this;
  const root = editContainer.querySelector('[data-role="place-root"]');
  if (!root) return;

  const app = editContext.app;
  const file = editContext.file;
  const frontmatter = editContext.frontmatter || {};
  const doc = editContext.activeDocument || root.ownerDocument;
  const q = selector => root.querySelector(selector);
  const text = value => value == null ? "" : String(value).trim();
  const bool = value => value === true || String(value).toLowerCase() === "true";

  const TYPE_INFO = {
    tourist: { label: "Tourist destination", icon: "⌖" },
    restaurant: { label: "Restaurant", icon: "◉" },
    cafe: { label: "Café", icon: "◌" },
    bar: { label: "Bar", icon: "◆" },
    misc: { label: "Saved place", icon: "•" },
  };

  const LOCATION_FIELDS = [
    { label: "Coordinates", property: "coordinates", placeholder: "latitude, longitude" },
    { label: "Address", property: "address", placeholder: "Add address" },
    { label: "City", property: "city", placeholder: "Add city" },
    { label: "Region", property: "region", placeholder: "Add region" },
    { label: "Country", property: "country", placeholder: "Add country" },
  ];

  const DETAIL_FIELDS = [
    {
      label: "Type",
      property: "place_type",
      control: "select",
      options: [
        ["tourist", "Tourist destination"],
        ["misc", "Saved place"],
        ["restaurant", "Restaurant"],
        ["cafe", "Café"],
        ["bar", "Bar"],
      ],
    },
    { label: "Cuisine", property: "cuisine", placeholder: "Add cuisine", foodOnly: true },
    { label: "Price", property: "price_level", placeholder: "Add price level", foodOnly: true },
    { label: "Hours", property: "opening_hours", placeholder: "Add opening hours" },
    { label: "Last visit", property: "last_visited", placeholder: "Add date", inputType: "date" },
    { label: "Phone", property: "phone", placeholder: "Add phone", inputType: "tel" },
    { label: "Website", property: "website", placeholder: "Add website", inputType: "url" },
  ];

  let frontmatterQueue = Promise.resolve();
  function updateFrontmatter(property, value) {
    if (!app?.fileManager || !file) return Promise.reject(new Error("Place file is unavailable"));
    const task = frontmatterQueue.then(async () => {
      await app.fileManager.processFrontMatter(file, draft => {
        draft[property] = value;
      });
      frontmatter[property] = value;
    });
    frontmatterQueue = task.catch(() => {});
    return task;
  }

  function setState(message, tone = "") {
    const state = q('[data-role="save-state"]');
    if (!state) return;
    state.textContent = message;
    state.dataset.tone = tone;
  }

  function currentType() {
    const candidate = text(frontmatter.place_type).toLowerCase();
    return TYPE_INFO[candidate] ? candidate : "misc";
  }

  function typeInfo() {
    return TYPE_INFO[currentType()];
  }

  function setText(role, value) {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = value;
  }

  function addChip(host, label, positive = false) {
    if (!host || !label) return;
    const chip = doc.createElement("span");
    chip.className = `cv-place-chip${positive ? " is-positive" : ""}`;
    chip.textContent = label;
    host.appendChild(chip);
  }

  function refreshDerivedUi() {
    const info = typeInfo();
    root.dataset.placeType = currentType();
    setText("type-label", info.label);
    setText("type-icon", info.icon);
    setText("details-title", currentType() === "tourist" ? "Destination profile" : info.label);

    const location = [frontmatter.city, frontmatter.region, frontmatter.country]
      .map(text)
      .filter(Boolean)
      .filter((value, index, all) => all.indexOf(value) === index)
      .join(" · ");
    setText("location-line", location || "Saved location");
    setText("location-title", text(frontmatter.city) || text(frontmatter.region) || "Saved coordinates");
    setText("hero-address", text(frontmatter.address));
    setText("coordinates", text(frontmatter.coordinates) || "No coordinates");

    const website = q('[data-role="website-link"]');
    const websiteUrl = text(frontmatter.website);
    if (website) {
      website.hidden = !/^https?:\/\//i.test(websiteUrl);
      if (!website.hidden) website.href = websiteUrl;
    }

    const chips = q('[data-role="hero-chips"]');
    if (chips) {
      chips.replaceChildren();
      addChip(chips, info.label);
      if (bool(frontmatter.visited)) addChip(chips, "Visited", true);
      if (bool(frontmatter.want_to_visit)) addChip(chips, "Want to visit");
      if (bool(frontmatter.favorite)) addChip(chips, "Favorite", true);
      const rating = Number(frontmatter.rating);
      if (Number.isFinite(rating) && rating > 0) addChip(chips, `${rating}/5`);
    }
  }

  function displayValue(field) {
    const value = frontmatter[field.property];
    if (field.property === "place_type") return typeInfo().label;
    return text(value);
  }

  function normalizeValue(field, raw) {
    const value = text(raw);
    if (field.property === "place_type") return TYPE_INFO[value] ? value : "misc";
    if (field.inputType === "date") return value || null;
    return value;
  }

  function makeEditor(row, detail, field, button) {
    if (row.classList.contains("is-editing")) return;
    row.classList.add("is-editing");
    button.hidden = true;

    const original = frontmatter[field.property];
    const editor = field.control === "select" ? doc.createElement("select") : doc.createElement("input");
    editor.className = field.control === "select" ? "cv-place-meta-select" : "cv-place-meta-input";
    editor.dataset.property = field.property;

    if (field.control === "select") {
      for (const [value, label] of field.options || []) {
        const option = doc.createElement("option");
        option.value = value;
        option.textContent = label;
        editor.appendChild(option);
      }
      editor.value = currentType();
    } else {
      editor.type = field.inputType || "text";
      editor.value = text(original);
      editor.placeholder = field.placeholder || "";
      editor.autocomplete = "off";
      editor.spellcheck = false;
    }

    detail.appendChild(editor);
    editor.focus();
    if (editor instanceof HTMLInputElement && editor.type === "text") editor.select();

    let finished = false;
    const finish = async save => {
      if (finished) return;
      finished = true;
      const next = normalizeValue(field, editor.value);
      if (!save || String(next ?? "") === String(original ?? "")) {
        buildAll();
        return;
      }

      editor.disabled = true;
      setState("Saving…");
      try {
        await updateFrontmatter(field.property, next);
        refreshDerivedUi();
        buildAll();
        setState("Saved", "success");
      } catch (error) {
        console.error("[custom-view:places] Could not save metadata", error);
        buildAll();
        setState("Could not save", "error");
      }
    };

    editor.addEventListener("keydown", event => {
      if (event.key === "Escape") {
        event.preventDefault();
        void finish(false);
      } else if (event.key === "Enter" && !(event.shiftKey || event.ctrlKey || event.metaKey)) {
        event.preventDefault();
        void finish(true);
      }
    });
    editor.addEventListener("blur", () => void finish(true));
    if (field.control === "select") editor.addEventListener("change", () => void finish(true));
  }

  function makeRow(field, editable = true) {
    const row = doc.createElement("div");
    row.className = "cv-place-meta-row";
    row.dataset.property = field.property;

    const term = doc.createElement("dt");
    term.textContent = field.label;
    const detail = doc.createElement("dd");
    row.append(term, detail);

    const value = displayValue(field);
    if (!editable) {
      detail.textContent = value || "—";
      return row;
    }

    const button = doc.createElement("button");
    button.type = "button";
    button.className = `cv-place-meta-edit${value ? "" : " is-empty"}`;
    button.dataset.property = field.property;
    button.textContent = value || field.placeholder || "Add value";
    button.addEventListener("click", () => makeEditor(row, detail, field, button));
    detail.appendChild(button);
    return row;
  }

  function rebuildList(role, fields) {
    const list = q(`[data-role="${role}"]`);
    if (!list) return;
    list.replaceChildren();
    const type = currentType();
    const isFood = type === "restaurant" || type === "cafe" || type === "bar";
    for (const field of fields) {
      if (field.foodOnly && !isFood) continue;
      list.appendChild(makeRow(field, true));
    }
  }

  const locationList = q('[data-role="location-meta"]');
  const detailsList = q('[data-role="details-meta"]');
  let observer = null;

  function observeLists() {
    if (!observer) {
      observer = new MutationObserver(() => {
        observer.disconnect();
        refreshDerivedUi();
        rebuildList("location-meta", LOCATION_FIELDS);
        rebuildList("details-meta", DETAIL_FIELDS);
        observeLists();
      });
    }
    if (locationList) observer.observe(locationList, { childList: true });
    if (detailsList) observer.observe(detailsList, { childList: true });
  }

  function buildAll() {
    observer?.disconnect();
    refreshDerivedUi();
    rebuildList("location-meta", LOCATION_FIELDS);
    rebuildList("details-meta", DETAIL_FIELDS);
    observeLists();
  }

  buildAll();
})();

(() => {
  const ctx = tp;
  const container = ctx.container || this;
  const root = container.querySelector('[data-role="place-root"]');
  if (!root) return;

  const app = ctx.app;
  const file = ctx.file;
  const frontmatter = ctx.frontmatter || {};
  const bodyContent = String(ctx.bodyContent || "");
  const doc = ctx.activeDocument || root.ownerDocument;
  const win = ctx.activeWindow || doc.defaultView;
  const q = selector => root.querySelector(selector);

  async function updateFrontmatter(property, value) {
    if (!app?.fileManager || !file) throw new Error("Place file is unavailable");
    await app.fileManager.processFrontMatter(file, draft => {
      draft[property] = value;
    });
    frontmatter[property] = value;
  }

  function setSaveState(message, tone = "") {
    const state = q('[data-role="save-state"]');
    if (!state) return;
    state.textContent = message;
    state.dataset.tone = tone;
  }

  function makeElement(tag, className, text) {
    const element = doc.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined) element.textContent = String(text);
    return element;
  }

  function ensureRatingChip() {
    const host = q('[data-role="hero-chips"]');
    if (!host) return;
    const rating = Math.max(0, Math.min(10, Number(frontmatter.rating) || 0));
    const candidates = Array.from(host.children).filter(element => /^\d+(?:\.\d+)?\/(?:5|10)$/.test(String(element.textContent || "").trim()));

    if (!rating) {
      candidates.forEach(element => element.remove());
      return;
    }

    const chip = candidates.shift() || makeElement("span", "cv-place-chip");
    const label = `${rating}/10`;
    chip.dataset.cvpRatingChip = "true";
    if (String(chip.textContent || "").trim() !== label) chip.textContent = label;
    candidates.forEach(element => element.remove());
    if (!chip.isConnected) host.appendChild(chip);
  }

  function initRating() {
    const rating = q('[data-role="rating"]');
    const emptyLayer = q('[data-role="rating-empty"]');
    const filledLayer = q('[data-role="rating-filled"]');
    const hits = q('[data-role="rating-hits"]');
    const output = q('[data-role="rating-value"]');
    if (!rating || !emptyLayer || !filledLayer || !hits || !output) return;

    emptyLayer.replaceChildren();
    filledLayer.replaceChildren();
    for (let index = 0; index < 5; index += 1) {
      emptyLayer.appendChild(makeElement("span", "cv-rating-star"));
      filledLayer.appendChild(makeElement("span", "cv-rating-star"));
    }

    let committed = Math.max(0, Math.min(10, Number(frontmatter.rating) || 0));

    function paint(value) {
      const safe = Math.max(0, Math.min(10, Number(value) || 0));
      rating.style.setProperty("--cv-rating-fill", `${safe * 10}%`);
      output.value = `${safe}/10`;
      output.textContent = `${safe}/10`;
      rating.setAttribute("aria-label", `Rating ${safe} out of 10`);
    }

    let saving = false;
    async function commit(next) {
      if (saving) return;
      saving = true;
      const previous = committed;
      committed = next;
      paint(next);
      rating.classList.add("is-saving");
      const hitButtons = Array.from(hits.querySelectorAll("button"));
      hitButtons.forEach(button => { button.disabled = true; });
      setSaveState("Saving…");
      try {
        await updateFrontmatter("rating", next);
        ensureRatingChip();
        setSaveState("Saved", "success");
      } catch (error) {
        committed = previous;
        paint(previous);
        setSaveState("Could not save", "error");
        console.error("[custom-view:places] Could not save rating", error);
      } finally {
        rating.classList.remove("is-saving");
        hitButtons.forEach(button => { button.disabled = false; });
        saving = false;
      }
    }

    hits.replaceChildren();
    for (let score = 1; score <= 10; score += 1) {
      const hit = makeElement("button", "cv-rating-hit");
      hit.type = "button";
      hit.dataset.score = String(score);
      hit.setAttribute("aria-label", `Rate ${score} out of 10`);
      hit.addEventListener("mouseenter", () => paint(score));
      hit.addEventListener("focus", () => paint(score));
      hit.addEventListener("click", () => void commit(score));
      hit.addEventListener("blur", () => paint(committed));
      hits.appendChild(hit);
    }

    hits.addEventListener("mouseleave", () => paint(committed));
    paint(committed);
    ensureRatingChip();

    const chipHost = q('[data-role="hero-chips"]');
    if (chipHost && win?.MutationObserver) {
      let scheduled = false;
      const observer = new win.MutationObserver(() => {
        if (scheduled) return;
        scheduled = true;
        win.queueMicrotask(() => {
          scheduled = false;
          ensureRatingChip();
        });
      });
      observer.observe(chipHost, { childList: true, subtree: true, characterData: true });
    }
  }

  function initBodyEditor() {
    const render = q('[data-role="note-render"]');
    const state = q('[data-role="note-state"]');
    if (!render || !state) return;

    let switchingMode = false;

    function findLeaf() {
      const leaves = typeof app?.workspace?.getLeavesOfType === "function"
        ? app.workspace.getLeavesOfType("markdown")
        : [];
      return leaves.find(candidate =>
        candidate?.view?.file?.path === file?.path &&
        candidate.view.contentEl?.contains(container)
      );
    }

    async function switchMode(mode, source, pendingText) {
      if (switchingMode) return;
      const leaf = findLeaf();
      if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
        state.textContent = "Open this note in Live Preview to write here";
        return;
      }

      switchingMode = true;
      state.textContent = pendingText;
      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode,
            source,
          },
        });
      } catch (error) {
        switchingMode = false;
        state.textContent = mode === "preview" ? "Could not return to reading" : "Could not start writing";
        console.error("[custom-view:places] Could not switch note mode", error);
      }
    }

    const nativePlaceholder = render.querySelector("[data-cv-editable-placeholder]");
    if (nativePlaceholder) {
      root.classList.add("is-native-editor");
      state.textContent = "Writing · autosaved";
      render.setAttribute("role", "textbox");
      render.removeAttribute("aria-label");
      render.removeAttribute("title");

      const Controller = win?.AbortController || AbortController;
      const outsideController = new Controller();
      doc.addEventListener("click", event => {
        if (!root.isConnected) {
          outsideController.abort();
          return;
        }
        if (render.contains(event.target)) return;
        win?.setTimeout?.(() => {
          void switchMode("preview", false, "Returning to reading…");
        }, 0);
      }, { capture: true, signal: outsideController.signal });
      return;
    }

    render.classList.toggle("is-empty", !bodyContent.trim());
    render.setAttribute("tabindex", "0");
    render.setAttribute("role", "textbox");
    render.removeAttribute("aria-label");
    render.removeAttribute("title");
    state.textContent = "Click notes to write";

    render.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void switchMode("source", false, "Opening Live Preview…");
    });

    render.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void switchMode("source", false, "Opening Live Preview…");
    });
  }

  function initCompactAttribution() {
    const mapHost = q('[data-role="local-map-embed"]');
    if (!mapHost || !win?.MutationObserver) return;

    function compact() {
      const controls = Array.from(mapHost.querySelectorAll("details.maplibregl-ctrl-attrib"));
      for (const control of controls) {
        if (control.dataset.cvpCompactReady === "true") continue;
        control.removeAttribute("open");
        control.dataset.cvpCompactReady = "true";
      }
      return controls.length > 0;
    }

    compact();
    const observer = new win.MutationObserver(() => compact());
    observer.observe(mapHost, { childList: true, subtree: true });
  }

  initRating();
  initBodyEditor();
  initCompactAttribution();
})();

(() => {
  const ctx = tp;
  const container = ctx.container || this;
  const root = container.querySelector('[data-role="place-root"]');
  if (!root) return;

  const doc = ctx.activeDocument || root.ownerDocument;
  const win = ctx.activeWindow || doc.defaultView;
  const mapHost = root.querySelector('[data-role="local-map-embed"]');
  if (!mapHost || !win?.MutationObserver) return;

  function polishControls() {
    const controls = [
      ...mapHost.querySelectorAll('button.maplibregl-ctrl-zoom-in'),
      ...mapHost.querySelectorAll('button.maplibregl-ctrl-zoom-out'),
    ];

    for (const control of controls) {
      // Remove browser hover tooltips while preserving aria-label accessibility text.
      control.removeAttribute('title');
    }
  }

  polishControls();
  const observer = new win.MutationObserver(() => polishControls());
  observer.observe(mapHost, { childList: true, subtree: true, attributes: true, attributeFilter: ['title'] });
})();

(() => {
  const ctx = tp;
  const container = ctx.container || this;
  const root = container.querySelector('[data-role="place-root"]');
  if (!root) return;

  const app = ctx.app;
  const frontmatter = ctx.frontmatter || {};
  const q = selector => root.querySelector(selector);
  const card = q('[data-role="weather-card"]');
  if (!card) return;

  const SETTINGS_PATH = "90_System/93_Configuration/settings.md";
  const text = value => value == null ? "" : String(value).trim();

  function parseCoordinates(value) {
    if (Array.isArray(value) && value.length >= 2) {
      const lat = Number(value[0]);
      const lon = Number(value[1]);
      if (Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180) return { lat, lon };
    }
    const raw = text(value);
    const match = raw.match(/(-?\d+(?:\.\d+)?)\s*[,;]\s*(-?\d+(?:\.\d+)?)/);
    if (!match) return null;
    const lat = Number(match[1]);
    const lon = Number(match[2]);
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
    return { lat, lon };
  }

  function plugin() {
    return app?.plugins?.getPlugin?.("places-weather") ?? app?.plugins?.plugins?.["places-weather"] ?? null;
  }

  function setText(role, value) {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = value;
  }

  function showState(message, tone = "") {
    const state = q('[data-role="weather-state"]');
    if (!state) return;
    state.hidden = !message;
    state.textContent = message || "";
    state.dataset.tone = tone;
  }

  function render(data) {
    setText("weather-temp", data?.temp == null ? "—" : String(data.temp));
    setText("weather-temp-unit", data?.tempUnit || "");
    setText("weather-condition", data?.condition || "Current weather");
    setText("weather-description", data?.description ? data.description.charAt(0).toUpperCase() + data.description.slice(1) : "Current conditions");
    setText("weather-humidity", data?.humidity == null ? "—" : `${Math.round(data.humidity)}%`);
    setText("weather-wind", data?.windSpeed == null ? "—" : `${data.windSpeed} ${data?.windUnit || "m/s"}`);
    setText("weather-clouds", data?.clouds == null ? "—" : `${Math.round(data.clouds)}%`);
    setText("weather-pressure", data?.pressure == null ? "—" : `${Math.round(data.pressure)} hPa`);
    setText("weather-updated", "Live · cached up to 15m");

    const icon = q('[data-role="weather-icon"]');
    const symbol = q('[data-role="weather-symbol"]');
    if (icon) {
      icon.hidden = !data?.icon;
      if (data?.icon) {
        icon.src = `https://openweathermap.org/img/wn/${encodeURIComponent(data.icon)}@2x.png`;
        icon.alt = data?.condition ? `${data.condition} weather icon` : "Weather icon";
      }
    }
    if (symbol) {
      symbol.hidden = Boolean(data?.icon);
      symbol.textContent = data?.symbol || "◌";
    }
    card.classList.remove("is-stale");
  }

  function renderEmpty(message) {
    setText("weather-temp", "—");
    setText("weather-temp-unit", "");
    setText("weather-condition", "Weather unavailable");
    setText("weather-description", message || "Current conditions are unavailable");
    setText("weather-humidity", "—");
    setText("weather-wind", "—");
    setText("weather-clouds", "—");
    setText("weather-pressure", "—");
    setText("weather-updated", "Not loaded");
    const icon = q('[data-role="weather-icon"]');
    const symbol = q('[data-role="weather-symbol"]');
    if (icon) icon.hidden = true;
    if (symbol) {
      symbol.hidden = false;
      symbol.textContent = "◌";
    }
  }

  async function refresh(force = false) {
    const coordinates = parseCoordinates(frontmatter.coordinates);
    if (!coordinates) {
      renderEmpty("Add coordinates to this Place note first.");
      showState("Weather needs latitude and longitude.");
      return;
    }

    const weather = plugin();
    if (!weather?.getWeather) {
      renderEmpty("Places Weather plugin is not active.");
      showState("Reload Obsidian so the Places Weather runtime can start.", "error");
      return;
    }

    const refreshButton = q('[data-action="weather-refresh"]');
    if (refreshButton) refreshButton.disabled = true;
    card.classList.add("is-loading");
    showState(force ? "Refreshing current weather…" : "Loading current weather…");
    try {
      const data = await weather.getWeather(coordinates.lat, coordinates.lon, { force });
      render(data);
      showState("");
    } catch (error) {
      console.warn("[Places weather view]", error);
      const noKey = error?.code === "NO_API_KEY";
      renderEmpty(noKey ? "Weather API key is not configured in Vault Settings." : text(error?.message));
      showState(noKey ? `Set openweathermap_key in ${SETTINGS_PATH}.` : `Could not load weather: ${text(error?.message) || "Unknown error"}`, noKey ? "" : "error");
    } finally {
      card.classList.remove("is-loading");
      if (refreshButton) refreshButton.disabled = false;
    }
  }

  q('[data-action="weather-refresh"]')?.addEventListener("click", () => void refresh(true));

  void refresh(false);
})();

views.css:
/* Movies and TV Series detail view. */

.obsidian-custom-view-render {
  padding: 0 !important;
}

.cv-media {
  --cv-bg: var(--background-primary);
  --cv-surface: var(--lake-surface, var(--background-primary));
  --cv-surface-2: var(--lake-surface-2, var(--background-secondary));
  --cv-surface-3: var(--lake-surface-3, var(--background-secondary-alt));
  --cv-hover: var(--lake-surface-4, var(--background-modifier-hover));
  --cv-active: var(--lake-active, var(--background-modifier-active-hover));
  --cv-accent: var(--lake-accent, var(--interactive-accent));
  --cv-accent-soft: var(--lake-accent-soft, var(--interactive-accent-hover));
  --cv-text: var(--lake-text, var(--text-normal));
  --cv-muted: var(--lake-text-soft, var(--text-muted));
  --cv-faint: color-mix(in srgb, var(--cv-muted) 58%, var(--cv-bg) 42%);
  --cv-border: var(--lake-border-2, var(--background-modifier-border));
  --cv-border-strong: var(--lake-border-3, var(--background-modifier-border-hover));
  --cv-shadow: color-mix(in srgb, var(--shadow) 42%, transparent);
  --cv-shadow-soft: color-mix(in srgb, var(--shadow) 22%, transparent);
  --cv-on-accent: var(--background-primary);
  --cv-radius-lg: clamp(16px, 2.1cqi, 24px);
  --cv-radius: clamp(10px, 1.3cqi, 14px);
  --cv-pad: clamp(18px, 4cqi, 54px);
  --cv-gap: clamp(16px, 2.4cqi, 30px);
  --cv-ease: cubic-bezier(.22, .61, .36, 1);

  position: relative;
  width: 100%;
  max-width: none;
  min-width: 0;
  container-type: inline-size;
  overflow: hidden;
  background: var(--cv-bg);
  color: var(--cv-text);
  font-family: var(--font-interface);
}

.cv-media *,
.cv-media *::before,
.cv-media *::after {
  box-sizing: border-box;
}

.cv-media button {
  font: inherit;
}

.cv-media button:focus-visible,
.cv-media a:focus-visible {
  outline: 2px solid var(--cv-accent);
  outline-offset: 3px;
}

.cv-media-hero {
  position: relative;
  min-height: clamp(390px, 48cqi, 590px);
  overflow: hidden;
  border-bottom: 1px solid var(--cv-border);
  background: var(--cv-surface-2);
}

.cv-media-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center 28%;
  opacity: .72;
  filter: saturate(.82) contrast(1.04);
}

.cv-media-backdrop:not([src]),
.cv-media-backdrop[src=""] {
  opacity: 0;
}

.cv-media-hero-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--cv-bg) 96%, transparent) 0%, color-mix(in srgb, var(--cv-bg) 76%, transparent) 48%, color-mix(in srgb, var(--cv-bg) 38%, transparent) 100%),
    linear-gradient(0deg, var(--cv-bg) 0%, color-mix(in srgb, var(--cv-bg) 72%, transparent) 30%, transparent 72%);
}

.cv-media-hero-inner {
  position: relative;
  z-index: 2;
  width: min(100%, 1440px);
  min-height: inherit;
  margin: 0 auto;
  padding: clamp(34px, 5cqi, 74px) var(--cv-pad);
  display: grid;
  grid-template-columns: clamp(150px, 21cqi, 252px) minmax(0, 1fr) max-content;
  align-items: center;
  gap: clamp(22px, 3cqi, 44px);
}

.cv-media-poster-wrap {
  position: relative;
  width: 100%;
  margin: 0;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border: 1px solid var(--cv-border-strong);
  border-radius: var(--cv-radius);
  background: var(--cv-surface-3);
  box-shadow: 0 16px 38px var(--cv-shadow), 0 2px 8px var(--cv-shadow-soft);
  transform: rotate(-.35deg);
}

.cv-media-poster-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cv-text) 10%, transparent);
}

.cv-media-poster {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.cv-media-hero-copy {
  min-width: 0;
  align-self: center;
  padding-bottom: clamp(2px, 1cqi, 12px);
  text-shadow: 0 2px 16px var(--cv-shadow);
}

.cv-media-eyebrow,
.cv-media-kicker,
.cv-note-label,
.cv-control-label {
  display: block;
  color: var(--cv-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(.68rem, 1.2cqi, .8rem);
  line-height: 1.25;
  font-weight: 760;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.cv-media-title {
  max-width: 18ch;
  margin: clamp(8px, 1.2cqi, 14px) 0 0;
  color: var(--cv-text);
  font-size: clamp(2.2rem, 6.2cqi, 5.6rem);
  line-height: .98;
  font-weight: 820;
  letter-spacing: -.045em;
  text-wrap: balance;
}

.cv-media-tagline {
  margin: clamp(12px, 1.7cqi, 20px) 0 0;
  color: var(--cv-accent-soft);
  font-size: clamp(.74rem, 1.3cqi, .95rem);
  line-height: 1.4;
  font-weight: 700;
  letter-spacing: .09em;
  text-transform: uppercase;
}

.cv-media-tagline:empty {
  display: none;
}

.cv-media-overview {
  max-width: 68ch;
  margin: clamp(10px, 1.5cqi, 18px) 0 0;
  color: color-mix(in srgb, var(--cv-text) 78%, var(--cv-muted) 22%);
  font-size: clamp(.86rem, 1.45cqi, 1.02rem);
  line-height: 1.65;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.cv-media-facts,
.cv-genre-list--hero {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.cv-media-facts {
  margin-top: clamp(14px, 2cqi, 24px);
}

.cv-media-fact {
  border: 1px solid var(--cv-border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--cv-surface-3) 78%, transparent);
  color: var(--cv-muted);
  backdrop-filter: blur(9px);
  padding: 5px 10px;
  font-family: var(--font-monospace);
  font-size: .72rem;
  line-height: 1.2;
}

.cv-media-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-self: end;
  align-self: center;
  gap: 16px;
  min-width: max-content;
  text-align: right;
  text-shadow: 0 2px 16px var(--cv-shadow);
}

.cv-media-nav a {
  color: var(--cv-muted);
  text-decoration: none;
  font-size: clamp(.78rem, 1.25cqi, .92rem);
  font-weight: 600;
  transition: color .18s var(--cv-ease);
}

.cv-media-nav a:hover {
  color: var(--cv-text);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.cv-media-nav a[aria-selected="true"] {
  color: var(--cv-accent-soft);
  font-weight: 720;
}

.cv-media-content {
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: 0 var(--cv-pad);
}

.cv-media-section {
  padding-top: clamp(38px, 6cqi, 78px);
  padding-bottom: clamp(48px, 7cqi, 90px);
  scroll-margin-top: 20px;
}

.cv-media-section[hidden] {
  display: none !important;
}

.cv-media-section:not([hidden]) {
  animation: cv-media-section-in .22s var(--cv-ease) both;
}

@keyframes cv-media-section-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.cv-media-section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: clamp(14px, 2cqi, 24px);
}

.cv-media-section-head h2 {
  margin: 5px 0 0;
  color: var(--cv-text);
  font-size: clamp(1.35rem, 2.5cqi, 2.1rem);
  line-height: 1.1;
  font-weight: 760;
  letter-spacing: -.025em;
}

.cv-media-section-head > p {
  max-width: 36ch;
  margin: 0;
  color: var(--cv-muted);
  font-size: .82rem;
  line-height: 1.5;
  text-align: right;
}

.cv-media-dashboard {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(250px, .8fr);
  align-items: stretch;
  gap: var(--cv-gap);
}

.cv-media-panel {
  border: 1px solid var(--cv-border);
  border-radius: var(--cv-radius);
  background: color-mix(in srgb, var(--cv-surface-2) 92%, var(--cv-surface-3) 8%);
  box-shadow: 0 8px 24px var(--cv-shadow-soft);
}

.cv-note-panel {
  min-width: 0;
  min-height: clamp(310px, 35cqi, 500px);
  align-self: stretch;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--cv-bg);
}

.cv-note-toolbar {
  min-height: 58px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 14px;
  padding: 12px clamp(14px, 2cqi, 22px);
  border-bottom: 1px solid var(--cv-border);
  background: color-mix(in srgb, var(--cv-surface-3) 66%, var(--cv-surface-2) 34%);
}

.cv-note-save-state {
  display: block;
  min-height: 1em;
  margin-top: 4px;
  color: var(--cv-muted);
  font-family: var(--font-monospace);
  font-size: .66rem;
  line-height: 1.2;
}

.cv-status-list button {
  min-height: 32px;
  border: 1px solid var(--cv-border);
  border-radius: 8px;
  background: transparent;
  color: var(--cv-muted);
  cursor: pointer;
  transition: background-color .16s var(--cv-ease), border-color .16s var(--cv-ease), color .16s var(--cv-ease), transform .16s var(--cv-ease);
}

.cv-status-list button:hover {
  border-color: var(--cv-border-strong);
  background: var(--cv-hover);
  color: var(--cv-text);
}

.cv-status-list button.is-active {
  border-color: var(--cv-accent);
  background: var(--cv-accent);
  color: var(--cv-on-accent);
}

.cv-status-list button.is-active:hover {
  border-color: var(--cv-accent-soft);
  background: var(--cv-accent-soft);
  color: var(--cv-on-accent);
}

.cv-status-list button[disabled] {
  cursor: wait;
  opacity: .58;
}

.cv-note-render {
  flex: 1 1 auto;
  width: 100%;
  min-height: clamp(250px, 30cqi, 430px);
  padding: clamp(18px, 2.6cqi, 30px);
  border: 0;
  background: transparent;
  color: var(--cv-text);
}

.cv-note-render {
  position: relative;
  overflow: auto;
  cursor: text;
  font-size: clamp(.88rem, 1.3cqi, .98rem);
  line-height: 1.75;
  transition: background-color .18s var(--cv-ease);
}

.cv-media:not(.is-native-editor) .cv-note-render:hover {
  background: color-mix(in srgb, var(--cv-accent) 5%, transparent);
}

.cv-note-render.is-empty::before {
  content: "Start writing your thoughts, favorite scenes, quotes, or review…";
  position: absolute;
  top: clamp(18px, 2.6cqi, 30px);
  left: clamp(18px, 2.6cqi, 30px);
  right: clamp(18px, 2.6cqi, 30px);
  color: var(--cv-faint);
  font-style: italic;
  pointer-events: none;
}

.cv-note-render .markdown-rendered-content,
.cv-note-render .markdown-preview-sizer,
.cv-note-render .markdown-preview-section {
  width: 100%;
  max-width: none;
  min-height: 100%;
  margin: 0;
  padding: 0;
}

.cv-note-render :is(p, ul, ol, blockquote):first-child {
  margin-top: 0;
}

.cv-note-render :is(p, ul, ol, blockquote):last-child {
  margin-bottom: 0;
}

.cv-media.is-native-editor .cv-note-panel {
  border-color: color-mix(in srgb, var(--cv-accent) 62%, var(--cv-border) 38%);
  box-shadow: 0 8px 24px var(--cv-shadow-soft), inset 0 0 0 1px color-mix(in srgb, var(--cv-accent) 10%, transparent);
}

/* Embedded Live Preview editor width. */
.cv-note-render [data-cv-editable-placeholder],
.cv-note-render .markdown-source-view,
.cv-note-render .cm-editor,
.cv-note-render .cm-scroller,
.cv-note-render .cm-content {
  width: 100% !important;
  max-width: none !important;
  min-height: clamp(250px, 30cqi, 430px) !important;
  background: transparent !important;
}

.cv-note-render .markdown-source-view,
.cv-note-render .cm-editor {
  position: relative !important;
  inset: auto !important;
}

.cv-note-render .cm-scroller {
  overflow: visible !important;
