  function resolveImage(value) {
    const raw = asArray(value).map(item => String(item ?? "").trim()).find(Boolean) || "";
    if (!raw) return "";
    const wikiMatch = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    if (!wikiMatch) return raw;
