.cv-video-thumb {
  min-width: 0;
}

.cv-people-rail {
  --cv-people-pad: clamp(14px, 2cqi, 24px);
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
  align-items: start;
  gap: clamp(12px, 1.7cqi, 20px);
  padding: var(--cv-people-pad);
  overflow: visible;
  scroll-snap-type: none;
}

.cv-people-rail > .cv-person-card:first-child,
.cv-people-rail > .cv-media-empty:first-child {
  margin-inline-start: 0;
}

.cv-people-rail > .cv-person-card:last-child,
.cv-people-rail > .cv-media-empty:last-child {
  margin-inline-end: 0;
}

.cv-person-card {
  width: auto;
  min-width: 0;
  margin: 0;
  padding: 8px;
  border: 1px solid var(--cv-border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--cv-paper) 88%, var(--cv-surface-3) 12%);
}

@container (max-width: 900px) {
  .cv-video-layout {
    grid-template-columns: 1fr;
  }

  .cv-video-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container (max-width: 560px) {
  .cv-video-list {
    grid-template-columns: 1fr;
  }
}

/* Canonical 30px paper/content baseline with no hover tint or Markdown gaps. */
.cv-note-panel .cv-note-toolbar {
  min-height: calc(var(--cv-paper-line) * 2);
  padding-block: 0;
}

.cv-note-panel .cv-note-render {
  padding: 0 clamp(18px, 2.8cqi, 32px) var(--cv-paper-line) clamp(54px, 5cqi, 66px);
  background-color: transparent;
}

.cv-media:not(.is-native-editor) .cv-note-render:hover {
  background-color: transparent;
}

.cv-note-render.is-empty::before {
  inset: 0 clamp(18px, 2.8cqi, 32px) auto clamp(54px, 5cqi, 66px);
  line-height: var(--cv-paper-line);
}

.cv-note-render > :is(h1, h2, h3, h4, h5, h6, p, ul, ol, pre),
.cv-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6, p, ul, ol, pre) {
  min-height: var(--cv-paper-line);
  margin-block: 0 !important;
  line-height: var(--cv-paper-line) !important;
}

.cv-note-render > :is(h1, h2, h3, h4, h5, h6),
.cv-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6) {
  padding-block: 0 !important;
}

.cv-note-render > :is(ul, ol),
.cv-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) {
  padding-block: 0 !important;
}

.cv-note-render .cm-line {
  min-height: var(--cv-paper-line);
  line-height: var(--cv-paper-line) !important;
}

