const mediaContext = tp;
const cvContainer = mediaContext.container || this;
const mediaRoot = cvContainer.querySelector(".cv-media");

if (mediaRoot) {
  const mediaApp = mediaContext.app;
  const mediaFile = mediaContext.file;
  const mediaFrontmatter = mediaContext.frontmatter || {};
  const mediaBodyContent = String(mediaContext.bodyContent || "");
  const mediaDocument = mediaContext.activeDocument || cvContainer.ownerDocument;
  const mediaWindow = mediaContext.activeWindow || mediaDocument.defaultView;
  const mediaType = mediaRoot.dataset.mediaType === "tv" ? "tv" : "movie";
  const tmdbId = String(mediaFrontmatter.tmdbId || mediaRoot.dataset.tmdbId || "").trim();
  const settingsPath = "90_System/93_Configuration/settings.md";
  const settingsFile = typeof mediaApp?.vault?.getAbstractFileByPath === "function"
    ? mediaApp.vault.getAbstractFileByPath(settingsPath)
    : null;
  const settingsFrontmatter = settingsFile && typeof mediaApp?.metadataCache?.getFileCache === "function"
    ? mediaApp.metadataCache.getFileCache(settingsFile)?.frontmatter
    : (typeof mediaApp?.metadataCache?.getCache === "function" ? mediaApp.metadataCache.getCache(settingsPath)?.frontmatter : null);
  const tmdbApiKey = String(settingsFrontmatter?.tmdb_key || "").trim();
  const tmdbBase = "https://api.themoviedb.org/3";
  const tmdbImageBase = "https://image.tmdb.org/t/p";
  const query = selector => mediaRoot.querySelector(selector);

  function asArray(value) {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return [value];
  }

  function cleanWiki(value) {
    return String(value ?? "")
      .replace(/^!?\[\[([^\]|]+)\|([^\]]+)\]\]$/, "$2")
      .replace(/^!?\[\[([^\]]+)\]\]$/, "$1")
      .trim();
  }

  function joined(value, limit = 4) {
    return asArray(value).map(cleanWiki).filter(Boolean).slice(0, limit).join(", ");
  }

  function resolveImage(value) {
    const raw = asArray(value).map(item => String(item ?? "").trim()).find(Boolean) || "";
    if (!raw) return "";
    const wikiMatch = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    if (!wikiMatch) return raw;
    if (!mediaApp?.metadataCache || !mediaFile) return "";
    const target = mediaApp.metadataCache.getFirstLinkpathDest(wikiMatch[1], mediaFile.path);
    return target ? mediaApp.vault.getResourcePath(target) : "";
  }

  function makeElement(tag, className, text) {
    const element = mediaDocument.createElement(tag);
    if (className) element.className = className;
    if (text !== undefined) element.textContent = String(text);
    return element;
  }

  function setImage(element, source, fallback = "") {
    if (!element) return;
    if (!source) {
      element.removeAttribute("src");
      return;
    }
    element.src = source;
    if (fallback && fallback !== source) {
      element.addEventListener("error", () => {
        if (element.src !== fallback) element.src = fallback;
      }, { once: true });
    }
  }

  function formatRuntime(value) {
    const minutes = Number(value);
    if (!Number.isFinite(minutes) || minutes <= 0) return "";
    const hours = Math.floor(minutes / 60);
    const remainder = Math.round(minutes % 60);
    if (!hours) return `${remainder} min`;
    return remainder ? `${hours} hr ${remainder} min` : `${hours} hr`;
  }

  function yearOf(value) {
    const match = String(value ?? "").match(/\d{4}/);
    return match ? match[0] : "";
  }

  function renderImagesAndFacts() {
    const posterSource = resolveImage(mediaFrontmatter.cover);
    const backdropSource = resolveImage(mediaFrontmatter.backdrop) || posterSource;
    setImage(query('[data-role="poster"]'), posterSource);
    setImage(query('[data-role="backdrop"]'), backdropSource, posterSource);

    const facts = [];
    const publishedYear = yearOf(mediaFrontmatter.published) || String(mediaFrontmatter.year || "").trim();
    if (mediaType === "tv") {
      const airingStatus = String(mediaFrontmatter.airing_status || "").toLowerCase().trim();
      const endedYear = ["ended", "canceled"].includes(airingStatus)
        ? yearOf(mediaFrontmatter.ended)
        : "";
      if (publishedYear) facts.push(endedYear && endedYear !== publishedYear ? `${publishedYear}–${endedYear}` : `${publishedYear}${endedYear ? "" : "–"}`);
      const runtime = formatRuntime(mediaFrontmatter.runtime);
      if (runtime) facts.push(`${runtime} per episode`);
      const seasons = Number(mediaFrontmatter.seasons);
      if (Number.isFinite(seasons) && seasons > 0) facts.push(`${seasons} season${seasons === 1 ? "" : "s"}`);
      const episodes = Number(mediaFrontmatter.episodes);
      if (Number.isFinite(episodes) && episodes > 0) facts.push(`${episodes} episodes`);
    } else {
      const runtime = formatRuntime(mediaFrontmatter.runtime);
      if (runtime) facts.push(runtime);
      if (publishedYear) facts.push(publishedYear);
    }

    const factRow = query('[data-role="hero-facts"]');
    if (!factRow) return;
    factRow.replaceChildren();
    for (const fact of facts) factRow.appendChild(makeElement("span", "cv-media-fact", fact));
  }

  function renderGenres() {
    const row = query('[data-role="genres"]');
    if (!row) return;
    row.replaceChildren();
    const genres = asArray(mediaFrontmatter.genres).map(cleanWiki).filter(Boolean).slice(0, 5);
    if (!genres.length) {
      row.appendChild(makeElement("span", "cv-genre-pill", "Unclassified"));
      return;
    }
    for (const genre of genres) row.appendChild(makeElement("span", "cv-genre-pill", genre));
  }

  function appendMetaRow(list, label, value) {
    if (!value) return;
    const row = makeElement("div", "cv-meta-row");
    row.appendChild(makeElement("dt", "", label));
    row.appendChild(makeElement("dd", "", value));
    list.appendChild(row);
  }

  function renderMetadata() {
    const list = query('[data-role="metadata"]');
    if (!list) return;
    list.replaceChildren();
    if (mediaType === "tv") {
      appendMetaRow(list, "Creators", joined(mediaFrontmatter.creators));
      appendMetaRow(list, "Directors", joined(mediaFrontmatter.directors));
      appendMetaRow(list, "Network", joined(mediaFrontmatter.networks));
      appendMetaRow(list, "Airing", String(mediaFrontmatter.airing_status || "").trim());
      appendMetaRow(list, "First aired", String(mediaFrontmatter.published || "").trim());
      appendMetaRow(list, "Last aired", String(mediaFrontmatter.ended || "").trim());
    } else {
      appendMetaRow(list, "Directors", joined(mediaFrontmatter.directors));
      appendMetaRow(list, "Writers", joined(mediaFrontmatter.writers));
      appendMetaRow(list, "Released", String(mediaFrontmatter.published || "").trim());
      appendMetaRow(list, "Runtime", formatRuntime(mediaFrontmatter.runtime));
    }
    appendMetaRow(list, "IMDb", String(mediaFrontmatter.imdbId || "").trim());
    appendMetaRow(list, "TMDB", String(mediaFrontmatter.tmdbId || "").trim());
  }

  async function updateFrontmatter(property, value) {
    if (!mediaApp?.fileManager || !mediaFile) throw new Error("Media file is unavailable");
    await mediaApp.fileManager.processFrontMatter(mediaFile, draft => {
      draft[property] = value;
    });
  }

  function normalizeStatus(value) {
    const normalized = String(value || "").toLowerCase().trim();
    return ["queue", "watching", "finished"].includes(normalized) ? normalized : "queue";
  }

  function initStatus() {
    const row = query('[data-role="status"]');
    if (!row) return;
    const buttons = Array.from(row.querySelectorAll("button[data-status]"));
    let committed = normalizeStatus(mediaFrontmatter.status);

    function paint(value) {
      for (const button of buttons) {
        const active = button.dataset.status === value;
        button.classList.toggle("is-active", active);
        button.setAttribute("aria-pressed", String(active));
      }
    }

    paint(committed);
    row.addEventListener("click", async event => {
      const button = event.target.closest("button[data-status]");
      if (!button || !row.contains(button)) return;
      const next = normalizeStatus(button.dataset.status);
      const previous = committed;
      committed = next;
      paint(next);
      for (const item of buttons) item.disabled = true;
      try {
        await updateFrontmatter("status", next);
      } catch (error) {
        committed = previous;
        paint(previous);
        console.error(`[custom-view:${mediaType}] Could not save status`, error);
      } finally {
        for (const item of buttons) item.disabled = false;
      }
    });
  }

  function initRating() {
    const rating = query('[data-role="rating"]');
    const emptyLayer = query('[data-role="rating-empty"]');
    const filledLayer = query('[data-role="rating-filled"]');
    const hits = query('[data-role="rating-hits"]');
    const output = query('[data-role="rating-value"]');
    if (!rating || !emptyLayer || !filledLayer || !hits || !output) return;

    for (let index = 0; index < 5; index += 1) {
      emptyLayer.appendChild(makeElement("span", "cv-rating-star"));
      filledLayer.appendChild(makeElement("span", "cv-rating-star"));
    }

    let committed = Math.max(0, Math.min(10, Number(mediaFrontmatter.rating) || 0));
    function paint(value) {
      const safe = Math.max(0, Math.min(10, Number(value) || 0));
      rating.style.setProperty("--cv-rating-fill", `${safe * 10}%`);
      output.value = `${safe}/10`;
      output.textContent = `${safe}/10`;
      rating.setAttribute("aria-label", `Rating ${safe} out of 10`);
    }

    let saving = false;
    async function commit(next) {
      if (saving) return;
      saving = true;
      const previous = committed;
      committed = next;
      paint(next);
      rating.classList.add("is-saving");
      const hitButtons = Array.from(hits.querySelectorAll("button"));
      for (const button of hitButtons) button.disabled = true;
      try {
        await updateFrontmatter("rating", next);
      } catch (error) {
        committed = previous;
        paint(previous);
        console.error(`[custom-view:${mediaType}] Could not save rating`, error);
      } finally {
        rating.classList.remove("is-saving");
        for (const button of hitButtons) button.disabled = false;
        saving = false;
      }
    }

    hits.replaceChildren();
    for (let score = 1; score <= 10; score += 1) {
      const hit = makeElement("button", "cv-rating-hit");
      hit.type = "button";
      hit.dataset.score = String(score);
      hit.setAttribute("aria-label", `Rate ${score} out of 10`);
      hit.addEventListener("mouseenter", () => paint(score));
      hit.addEventListener("focus", () => paint(score));
      hit.addEventListener("click", () => commit(score));
      hit.addEventListener("blur", () => paint(committed));
      hits.appendChild(hit);
    }
    hits.addEventListener("mouseleave", () => paint(committed));
    paint(committed);
  }

  function initBodyEditor() {
    const render = query('[data-role="note-render"]');
    const state = query('[data-role="note-state"]');
    if (!render || !state) return;

    let switchingMode = false;
    function findLeaf() {
      const leaves = typeof mediaApp?.workspace?.getLeavesOfType === "function"
        ? mediaApp.workspace.getLeavesOfType("markdown")
        : [];
      return leaves.find(candidate =>
        candidate?.view?.file?.path === mediaFile?.path &&
        candidate.view.contentEl?.contains(cvContainer)
      );
    }

    async function switchMode(mode, source, pendingText) {
      if (switchingMode) return;
      const leaf = findLeaf();
      if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
        state.textContent = "Open this note in Live Preview to write here";
        return;
      }
      switchingMode = true;
      state.textContent = pendingText;
      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode,
            source,
          },
        });
      } catch (error) {
        switchingMode = false;
        state.textContent = mode === "preview" ? "Could not return to reading" : "Could not start writing";
        console.error(`[custom-view:${mediaType}] Could not switch note mode`, error);
      }
    }

    const nativePlaceholder = render.querySelector("[data-cv-editable-placeholder]");
    if (nativePlaceholder) {
      mediaRoot.classList.add("is-native-editor");
      state.textContent = "Writing · autosaved";
      render.setAttribute("role", "textbox");
      render.setAttribute("aria-label", "Writing notes. Click outside this area to finish.");

      const outsideController = new mediaWindow.AbortController();
      mediaDocument.addEventListener("click", event => {
        if (!mediaRoot.isConnected) {
          outsideController.abort();
          return;
        }
        if (render.contains(event.target)) return;
        mediaWindow.setTimeout(() => {
          void switchMode("preview", false, "Returning to reading…");
        }, 0);
      }, { capture: true, signal: outsideController.signal });
      return;
    }

    render.classList.toggle("is-empty", !mediaBodyContent.trim());
    render.setAttribute("tabindex", "0");
    render.setAttribute("role", "textbox");
    render.setAttribute("aria-label", "Notes. Click to start writing.");
    state.textContent = "Click notes to write";

    render.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void switchMode("source", false, "Opening writing mode…");
    });
    render.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void switchMode("source", false, "Opening writing mode…");
    });
  }

  function initLocalNavigation() {
    const nav = query(".cv-media-nav");
    if (!nav) return;
    const anchors = Array.from(nav.querySelectorAll("a[data-media-view]"));
    const sections = new Map(
      Array.from(mediaRoot.querySelectorAll("[data-media-section]"))
        .map(section => [section.dataset.mediaSection, section])
    );
    const validKeys = anchors.map(anchor => anchor.dataset.mediaView).filter(key => sections.has(key));
    if (!validKeys.length) return;

    if (!mediaWindow.__lakeCustomViewPendingSection) {
      mediaWindow.__lakeCustomViewPendingSection = new Map();
    }
    const stateKey = mediaFile?.path || `${mediaType}:${tmdbId || "current"}`;
    const pendingKey = mediaWindow.__lakeCustomViewPendingSection.get(stateKey);
    mediaWindow.__lakeCustomViewPendingSection.delete(stateKey);

    function showSection(requestedKey, options = {}) {
      const key = sections.has(requestedKey) ? requestedKey : "journal";
      for (const [sectionKey, section] of sections) {
        const active = sectionKey === key;
        section.hidden = !active;
        section.setAttribute("aria-hidden", String(!active));
      }
      for (const anchor of anchors) {
        const active = anchor.dataset.mediaView === key;
        anchor.setAttribute("aria-selected", String(active));
        anchor.tabIndex = active ? 0 : -1;
      }
      if (options.preserveAfterWriting && mediaRoot.classList.contains("is-native-editor")) {
        mediaWindow.__lakeCustomViewPendingSection.set(stateKey, key);
      }
      if (options.scroll) {
        mediaWindow.requestAnimationFrame(() => {
          sections.get(key)?.scrollIntoView({ behavior: "smooth", block: "start" });
        });
      }
      return key;
    }

    showSection(pendingKey || "journal");

    for (const anchor of anchors) {
      anchor.addEventListener("click", event => {
        event.preventDefault();
        showSection(anchor.dataset.mediaView, { scroll: true, preserveAfterWriting: true });
      });
      anchor.addEventListener("keydown", event => {
        if (!["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"].includes(event.key)) return;
        event.preventDefault();
        const currentIndex = Math.max(0, validKeys.indexOf(anchor.dataset.mediaView));
        let nextIndex = currentIndex;
        if (["ArrowDown", "ArrowRight"].includes(event.key)) nextIndex = (currentIndex + 1) % validKeys.length;
        if (["ArrowUp", "ArrowLeft"].includes(event.key)) nextIndex = (currentIndex - 1 + validKeys.length) % validKeys.length;
        if (event.key === "Home") nextIndex = 0;
        if (event.key === "End") nextIndex = validKeys.length - 1;
        const nextAnchor = anchors.find(item => item.dataset.mediaView === validKeys[nextIndex]);
        showSection(validKeys[nextIndex], { scroll: true, preserveAfterWriting: true });
        nextAnchor?.focus();
      });
    }
  }

  function cacheStore() {
    if (!mediaWindow.__lakeCustomViewTmdbCache) {
      mediaWindow.__lakeCustomViewTmdbCache = new Map();
    }
    return mediaWindow.__lakeCustomViewTmdbCache;
  }

  async function fetchTmdb(path) {
    const cache = cacheStore();
    const key = `${path}`;
    if (cache.has(key)) return cache.get(key);
    const separator = path.includes("?") ? "&" : "?";
    const request = mediaWindow.fetch(`${tmdbBase}${path}${separator}api_key=${tmdbApiKey}`)
      .then(response => {
        if (!response.ok) throw new Error(`TMDB returned ${response.status}`);
        return response.json();
      })
      .catch(error => {
        cache.delete(key);
        throw error;
      });
    cache.set(key, request);
    return request;
  }

  function personAvatar(name) {
    return makeElement("div", "cv-person-avatar", String(name || "?").trim().charAt(0).toUpperCase() || "?");
  }

  function renderPeople(data) {
    const rail = query('[data-role="people"]');
    if (!rail) return;
    const cast = asArray(data?.cast).slice(0, 10).map(person => ({
      id: person.id,
      name: person.name,
      role: person.character || asArray(person.roles)[0]?.character || "Cast",
      photo: person.profile_path,
    }));
    const keyJobs = mediaType === "tv"
      ? new Set(["Creator", "Executive Producer", "Director", "Series Director"])
      : new Set(["Director", "Director of Photography", "Original Music Composer", "Producer"]);
    const crew = asArray(data?.crew)
      .filter(person => keyJobs.has(person.job))
      .slice(0, 4)
      .map(person => ({ id: person.id, name: person.name, role: person.job, photo: person.profile_path }));
    const seen = new Set();
    const people = [...cast, ...crew].filter(person => {
      const key = person.id || person.name;
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    rail.replaceChildren();
    if (!people.length) {
      rail.appendChild(makeElement("div", "cv-media-empty", "No cast information is available."));
      return;
    }

    for (const person of people) {
      const card = makeElement("article", "cv-person-card");
      if (person.photo) {
        const image = makeElement("img", "cv-person-photo");
        image.src = `${tmdbImageBase}/w342${person.photo}`;
        image.alt = person.name || "Cast member";
        image.loading = "lazy";
        image.addEventListener("error", () => image.replaceWith(personAvatar(person.name)), { once: true });
        card.appendChild(image);
      } else {
        card.appendChild(personAvatar(person.name));
      }
      card.appendChild(makeElement("p", "cv-person-name", person.name || "Unknown"));
      card.appendChild(makeElement("p", "cv-person-role", person.role || ""));
      rail.appendChild(card);
    }
    rail.scrollLeft = 0;
  }

  function selectVideo(list, frame, player, key) {
    player.src = `https://www.youtube-nocookie.com/embed/${key}`;
    frame.classList.add("has-video");
    for (const card of list.querySelectorAll(".cv-video-card")) {
      card.classList.toggle("is-active", card.dataset.key === key);
    }
  }

  function renderVideos(data) {
    const list = query('[data-role="video-list"]');
    const frame = query('[data-role="video-frame"]');
    const player = query('[data-role="video-player"]');
    const empty = query('[data-role="video-empty"]');
    if (!list || !frame || !player || !empty) return;

    const videos = asArray(data?.results)
      .filter(video => video.site === "YouTube" && ["Trailer", "Teaser", "Clip"].includes(video.type))
      .filter(video => /^[\w-]+$/.test(String(video.key || "")))
      .filter((video, index, all) => all.findIndex(candidate => candidate.key === video.key) === index)
      .slice(0, 12);
    list.replaceChildren();
    if (!videos.length) {
      empty.textContent = "No trailer is currently available.";
      list.appendChild(makeElement("div", "cv-media-empty", "TMDB did not return additional videos."));
      return;
    }

    for (const video of videos) {
      const card = makeElement("button", "cv-video-card");
      card.type = "button";
      card.dataset.key = video.key;
      card.setAttribute("aria-label", `Play ${video.name || video.type}`);
      const image = makeElement("img", "cv-video-thumb");
      image.src = `https://img.youtube.com/vi/${video.key}/hqdefault.jpg`;
      image.alt = "";
      image.loading = "lazy";
      card.appendChild(image);
      card.addEventListener("click", () => selectVideo(list, frame, player, video.key));
      list.appendChild(card);
    }
    selectVideo(list, frame, player, videos[0].key);
  }

  async function loadRemoteMedia() {
    const peopleRail = query('[data-role="people"]');
    const videoList = query('[data-role="video-list"]');
    const videoEmpty = query('[data-role="video-empty"]');
    if (!tmdbId || !tmdbApiKey) {
      const message = !tmdbId
        ? "Add tmdbId to load TMDB media."
        : "Add tmdb_key to the vault settings note to load TMDB media.";
      if (peopleRail) peopleRail.replaceChildren(makeElement("div", "cv-media-empty", message));
      if (videoList) videoList.replaceChildren(makeElement("div", "cv-media-empty", message));
      if (videoEmpty) videoEmpty.textContent = !tmdbId ? "No TMDB ID" : "TMDB key unavailable";
      return;
    }

    const [creditsResult, videosResult] = await Promise.allSettled([
      fetchTmdb(`/${mediaType}/${encodeURIComponent(tmdbId)}/credits`),
      fetchTmdb(`/${mediaType}/${encodeURIComponent(tmdbId)}/videos`),
    ]);

    if (!mediaRoot.isConnected) return;
    if (creditsResult.status === "fulfilled") renderPeople(creditsResult.value);
    else if (peopleRail) peopleRail.replaceChildren(makeElement("div", "cv-media-empty", "Cast could not be loaded right now."));

    if (videosResult.status === "fulfilled") renderVideos(videosResult.value);
    else {
      if (videoList) videoList.replaceChildren(makeElement("div", "cv-media-empty", "Videos could not be loaded right now."));
      if (videoEmpty) videoEmpty.textContent = "Video unavailable";
    }
  }

  function initPaperTape() {
    const paper = query(".cv-note-panel");
    if (!paper) return;
    const seed = String(mediaFile?.path || mediaFile?.basename || `${mediaType}-note`);
    let hash = 0;
    for (const character of seed) hash = ((hash * 31) + character.charCodeAt(0)) | 0;
    paper.dataset.tapeSide = Math.abs(hash) % 2 ? "right" : "left";
  }

  renderImagesAndFacts();
  renderGenres();
  renderMetadata();
  initStatus();
  initRating();
  initBodyEditor();
  initLocalNavigation();
  initPaperTape();
  loadRemoteMedia();
}

views.css:
/* Recipe detail view. */

.obsidian-custom-view-render:has(> .cv-recipe) {
  padding: 0 !important;
  background: var(--background-mod-root-split, var(--border-theme-pane, var(--background-primary))) !important;
}

.cv-recipe {
  --cvr-bg: var(--background-mod-root-split, var(--border-theme-pane, var(--background-primary)));
  --cvr-surface: var(--lake-surface, var(--background-primary));
  --cvr-surface-2: var(--lake-surface-2, var(--background-secondary));
  --cvr-surface-3: var(--lake-surface-3, var(--background-secondary-alt));
  --cvr-hover: var(--lake-surface-4, var(--background-modifier-hover));
  --cvr-active: var(--lake-active, var(--background-modifier-active-hover));
  --cvr-accent: var(--lake-accent, var(--interactive-accent));
  --cvr-accent-soft: var(--lake-accent-soft, var(--interactive-accent-hover));
  --cvr-text: var(--lake-text, var(--text-normal));
  --cvr-muted: var(--lake-text-soft, var(--text-muted));
  --cvr-faint: var(--text-faint);
  --cvr-border: var(--lake-border-2, var(--background-modifier-border));
  --cvr-border-strong: var(--lake-border-3, var(--background-modifier-border-hover));
  --cvr-panel: var(--cvr-bg);
  --cvr-card: color-mix(in srgb, var(--cvr-bg) 62%, var(--cvr-surface-2) 38%);
  --cvr-shadow: color-mix(in srgb, var(--shadow) 38%, transparent);
  --cvr-shadow-soft: color-mix(in srgb, var(--shadow) 20%, transparent);
  --cvr-on-accent: var(--text-on-accent, var(--background-primary));
  --cvr-pad: clamp(22px, 2.7cqi, 40px);
  --cvr-gap: clamp(18px, 3cqi, 38px);
  --cvr-radius-lg: clamp(16px, 2cqi, 24px);
  --cvr-radius: clamp(10px, 1.3cqi, 15px);
  --cvr-ease: cubic-bezier(.22, .61, .36, 1);

  width: 100%;
  min-height: 100%;
  min-width: 0;
  display: flex;
  padding: 0;
  container-type: inline-size;
  background: var(--cvr-bg);
  color: var(--cvr-text);
  font-family: var(--font-interface);
}

.cv-recipe *,
.cv-recipe *::before,
.cv-recipe *::after {
  box-sizing: border-box;
}

.cv-recipe button {
  font: inherit;
}

.cv-recipe button:focus-visible,
.cv-recipe a:focus-visible {
  outline: 2px solid var(--cvr-accent);
  outline-offset: 3px;
}

.cv-recipe-sheet {
  position: relative;
  width: 100%;
  min-height: 100%;
  flex: 1 0 auto;
  margin: 0 auto;
  overflow: clip;
  border: 0;
  border-radius: 0 0 var(--cvr-radius-lg) var(--cvr-radius-lg);
  background: var(--cvr-panel);
  box-shadow: 0 3px 10px var(--cvr-shadow-soft), 0 22px 54px var(--cvr-shadow);
}

.cv-recipe-sheet::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(118deg, transparent 0 7px, color-mix(in srgb, var(--cvr-text) 2%, transparent) 7px 8px);
  opacity: .6;
}

.cv-recipe-layout,
.cv-recipe-notes-grid {
  position: relative;
  z-index: 1;
}

.cv-recipe-layout {
  display: grid;
  grid-template-columns: minmax(300px, .78fr) minmax(0, 1.45fr);
  align-items: start;
  gap: clamp(32px, 4cqi, 58px);
  padding: var(--cvr-pad);
}

.cv-recipe-sidebar,
.cv-recipe-main {
  min-width: 0;
}

.cv-recipe-sidebar {
  display: flex;
  flex-direction: column;
  gap: clamp(18px, 2.4cqi, 30px);
}

.cv-recipe-photo-card {
  position: relative;
  margin: clamp(22px, 3cqi, 38px) 0 0;
  padding: clamp(9px, 1.2cqi, 14px);
  border: 1px solid var(--cvr-border);
  border-radius: calc(var(--cvr-radius) + 2px);
  background: color-mix(in srgb, var(--cvr-card) 92%, var(--cvr-accent) 8%);
  box-shadow: 0 12px 28px var(--cvr-shadow-soft);
  transform: rotate(-.55deg);
}

.cv-recipe-photo-card::after {
  content: "";
  position: absolute;
  inset: clamp(9px, 1.2cqi, 14px);
  pointer-events: none;
  border-radius: calc(var(--cvr-radius) - 2px);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvr-text) 12%, transparent);
}

.cv-recipe-tape {
  position: absolute;
  top: clamp(-11px, -1cqi, -6px);
  left: 50%;
  z-index: 5;
  width: clamp(80px, 24cqi, 138px);
  height: clamp(24px, 5cqi, 34px);
  background: color-mix(in srgb, var(--cvr-accent-soft) 28%, var(--cvr-surface-3) 72%);
  clip-path: polygon(3% 8%, 97% 0, 100% 92%, 0 100%);
  opacity: .82;
  transform: translateX(-50%) rotate(1.2deg);
}

.cv-recipe-photo {
  width: 100%;
  aspect-ratio: 1.15 / 1;
  display: block;
  object-fit: cover;
  border-radius: calc(var(--cvr-radius) - 2px);
  background: var(--cvr-surface-3);
}

.cv-recipe-photo:not([src]),
.cv-recipe-photo[src=""] {
  min-height: 240px;
  background:
    radial-gradient(circle at 34% 30%, color-mix(in srgb, var(--cvr-accent) 15%, transparent), transparent 42%),
    var(--cvr-card);
}

.cv-recipe-photo-label {
  position: absolute;
  top: clamp(-24px, -2cqi, -14px);
  left: clamp(-15px, -1cqi, -8px);
  z-index: 6;
  width: clamp(112px, 14cqi, 146px);
  height: clamp(84px, 10cqi, 108px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 12px 20px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--cvr-accent) 62%, var(--cvr-border) 38%);
  border-radius: 0;
  background: color-mix(in srgb, var(--cvr-accent) 16%, var(--cvr-surface-2) 84%);
  color: var(--cvr-accent-soft);
  clip-path: polygon(0 0, 100% 0, 100% 82%, 50% 100%, 0 82%);
  backdrop-filter: blur(9px);
  font-family: var(--font-monospace);
  font-size: clamp(.64rem, 1.2cqi, .78rem);
  line-height: 1.1;
  font-weight: 720;
  letter-spacing: .07em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.cv-recipe-photo-actions {
  position: absolute;
  right: clamp(16px, 2.5cqi, 24px);
  bottom: clamp(-17px, -1.2cqi, -10px);
  z-index: 7;
  display: flex;
  gap: 7px;
}

.cv-recipe-action-state {
  position: absolute;
  right: clamp(16px, 2.5cqi, 24px);
  bottom: clamp(-34px, -2.7cqi, -24px);
  z-index: 7;
  min-height: 1em;
  color: var(--text-error, var(--cvr-accent-soft));
  font-family: var(--font-monospace);
  font-size: .62rem;
}

.cv-recipe-photo-actions button {
  border: 1px solid var(--cvr-border);
  background: color-mix(in srgb, var(--cvr-surface-2) 84%, transparent);
  color: var(--cvr-muted);
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: border-color .16s var(--cvr-ease), background-color .16s var(--cvr-ease), color .16s var(--cvr-ease), transform .16s var(--cvr-ease);
}

.cv-recipe-photo-actions button {
  width: clamp(32px, 6cqi, 40px);
  height: clamp(32px, 6cqi, 40px);
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 50%;
}

.cv-recipe-photo-actions button:hover {
  border-color: var(--cvr-border-strong);
  background: var(--cvr-hover);
  color: var(--cvr-text);
}

.cv-recipe-photo-actions button.is-active {
  border-color: var(--cvr-accent);
  background: color-mix(in srgb, var(--cvr-accent) 16%, var(--cvr-bg) 84%);
  color: var(--cvr-accent);
}

.cv-recipe-photo-actions button[disabled] {
  cursor: wait;
  opacity: .58;
}

.cv-recipe-card {
  border: 1px solid var(--cvr-border);
  border-radius: var(--cvr-radius);
  background: var(--cvr-card);
  box-shadow: 0 8px 22px var(--cvr-shadow-soft);
}

.cv-recipe-card-head {
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px clamp(14px, 2cqi, 20px);
  border-bottom: 1px solid var(--cvr-border);
  color: var(--cvr-accent-soft);
}

.cv-recipe-card-head h2 {
  margin: 0;
  color: var(--cvr-text);
  font-family: ui-serif, Georgia, serif;
  font-size: clamp(1rem, 1.8cqi, 1.28rem);
  line-height: 1.1;
  font-weight: 700;
}

.cv-ingredient-list {
  margin: 0;
  padding: clamp(12px, 2cqi, 20px);
  list-style: none;
}

.cv-ingredient-row {
  display: block;
  min-width: 0;
  align-items: baseline;
  padding: 9px 2px;
  border-bottom: 1px dashed var(--cvr-border);
  font-size: clamp(.76rem, 1.25cqi, .88rem);
  line-height: 1.35;
}

.cv-ingredient-row.has-amount {
  display: grid;
  grid-template-columns: minmax(0, 1fr) max-content;
  gap: 12px;
}

.cv-ingredient-row:last-child {
  border-bottom: 0;
}

.cv-ingredient-name {
  min-width: 0;
  display: block;
  overflow-wrap: anywhere;
  color: var(--cvr-muted);
}

.cv-ingredient-amount {
  color: var(--cvr-accent-soft);
  font-family: var(--font-monospace);
  font-size: .78em;
  text-align: right;
  white-space: nowrap;
}

.cv-recipe-main {
  padding-top: clamp(4px, 1cqi, 14px);
}

.cv-recipe-title-block {
  position: relative;
  padding-bottom: clamp(18px, 3cqi, 34px);
  border-bottom: 0;
}

.cv-recipe-eyebrow,
.cv-recipe-section-kicker,
.cv-recipe-stat-label {
  display: block;
  color: var(--cvr-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(.63rem, 1.05cqi, .76rem);
  line-height: 1.25;
  font-weight: 740;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.cv-recipe-title-block h1 {
  max-width: 16ch;
  margin: clamp(8px, 1.5cqi, 16px) 0 0;
  color: var(--cvr-text);
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-size: clamp(2.7rem, 6.2cqi, 6.2rem);
  line-height: .96;
  font-style: normal;
  font-weight: 600;
  letter-spacing: -.055em;
  text-wrap: balance;
}

.cv-recipe-tagline {
  margin: clamp(16px, 2.5cqi, 28px) 0 0;
  color: var(--cvr-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(.72rem, 1.3cqi, .9rem);
  line-height: 1.4;
  font-weight: 720;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.cv-recipe-tagline:empty {
  display: none;
}

.cv-recipe-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  margin-top: clamp(24px, 4cqi, 44px);
  overflow: hidden;
  border: 1px solid var(--cvr-border-strong);
  border-radius: 8px;
  background: transparent;
}

.cv-recipe-stat {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  column-gap: 9px;
  row-gap: 3px;
  padding: clamp(12px, 2cqi, 19px);
  border: 0;
  border-left: 1px solid var(--cvr-border-strong);
  border-radius: 0;
  background: transparent;
}

.cv-recipe-stat:first-child {
  border-left: 0;
}

.cv-recipe-stat dd {
  min-width: 0;
  margin: 0;
}

.cv-recipe-stat > .cv-recipe-icon {
  grid-row: 1 / 3;
  width: clamp(22px, 3cqi, 31px);
  height: clamp(22px, 3cqi, 31px);
  color: var(--cvr-accent);
}

.cv-recipe-stat strong {
  min-width: 0;
  overflow: hidden;
  color: var(--cvr-text);
  font-size: clamp(.76rem, 1.25cqi, .92rem);
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-recipe-description {
  max-width: 76ch;
  margin: clamp(22px, 3.5cqi, 40px) 0 0;
  padding: clamp(10px, 3.5cqi, 4px);
  border-bottom: 0;
  color: color-mix(in srgb, var(--cvr-text) 76%, var(--cvr-muted) 24%);
  font-family: var(--font-text-theme, var(--font-interface));
  font-size: clamp(.98rem, 1.65cqi, 1.22rem);
  line-height: 1.72;
  font-style: normal;
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
}

.cv-recipe-description:empty {
  display: none;
}

.cv-instructions-section {
  margin-top: clamp(28px, 4.5cqi, 54px);
}

.cv-recipe-section-title {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: clamp(16px, 2.4cqi, 26px);
}

.cv-recipe-section-title > .cv-recipe-icon {
  width: clamp(31px, 4cqi, 42px);
  height: clamp(31px, 4cqi, 42px);
  color: var(--cvr-accent);
}

.cv-recipe-section-title h2 {
  margin: 3px 0 0;
  color: var(--cvr-text);
  font-family: ui-serif, Georgia, serif;
  font-size: clamp(1.35rem, 2.5cqi, 2rem);
  line-height: 1.05;
}

.cv-instruction-list {
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: recipe-step;
}

.cv-instruction-list > .cv-recipe-list-item {
  position: relative;
  min-height: 60px;
  padding: 9px 0 clamp(20px, 2.6cqi, 28px) clamp(60px, 6.5cqi, 68px);
  border-bottom: 0;
  color: var(--cvr-muted);
  font-size: clamp(.82rem, 1.35cqi, .98rem);
  line-height: 1.68;
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
  counter-increment: recipe-step;
}

.cv-instruction-list > .cv-recipe-list-item + .cv-recipe-list-item {
  padding-top: 16px;
}

.cv-instruction-list > .cv-recipe-list-item::before {
  content: counter(recipe-step);
  position: absolute;
  z-index: 3;
  top: 9px;
  left: 0;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 2px solid color-mix(in srgb, var(--cvr-accent) 58%, var(--cvr-border) 42%);
  border-radius: 999px;
  background: color-mix(in srgb, var(--cvr-card) 90%, var(--cvr-surface-2) 10%);
  color: var(--cvr-accent-soft);
  font-family: var(--font-monospace);
  font-size: .72rem;
  font-weight: 760;
  box-shadow:
    0 4px 10px var(--cvr-shadow-soft),
    0 0 0 3px color-mix(in srgb, var(--cvr-card) 76%, transparent),
    0 0 0 4px color-mix(in srgb, var(--cvr-border-strong) 54%, transparent);
}

.cv-instruction-list > .cv-recipe-list-item + .cv-recipe-list-item::before {
  top: 16px;
}

.cv-instruction-list > .cv-recipe-list-item:has(~ .cv-recipe-list-item)::after {
  content: "";
  position: absolute;
  z-index: 1;
  top: 52px;
  bottom: -18px;
  left: 16px;
  width: 12px;
  border: 2px solid color-mix(in srgb, var(--cvr-border-strong) 78%, transparent);
  border-block: 0;
  border-radius: 999px;
  background: color-mix(in srgb, var(--cvr-surface-3) 72%, transparent);
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--cvr-card) 86%, transparent);
  pointer-events: none;
}

.cv-instruction-list > .cv-recipe-list-item + .cv-recipe-list-item:has(~ .cv-recipe-list-item)::after {
  top: 59px;
}

.cv-recipe-notes-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
  gap: var(--cvr-gap);
  padding: 0 var(--cvr-pad) var(--cvr-pad);
}

.cv-recipe-small-card {
  min-width: 0;
  height: auto;
  min-height: clamp(160px, 14cqi, 220px);
  overflow: hidden;
}

.cv-recipe-note-card {
  grid-column: 1 / -1;
  grid-row: 2;
  min-height: clamp(220px, 22cqi, 340px);
  display: flex;
  flex-direction: column;
}

.cv-recipe-mini-list {
  max-height: calc(100% - 52px);
  margin: 0;
  padding: clamp(14px, 2cqi, 20px) clamp(18px, 2.5cqi, 26px) clamp(16px, 2.2cqi, 22px) clamp(34px, 4cqi, 44px);
  color: var(--cvr-muted);
  font-size: clamp(.76rem, 1.2cqi, .88rem);
  line-height: 1.58;
  overflow: auto;
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
}

.cv-recipe-mini-list li + li {
  margin-top: 8px;
}

.cv-recipe-mini-list li::marker {
  color: var(--cvr-accent);
}

.cv-recipe-note-head {
  justify-content: flex-start;
  align-items: center;
}

.cv-recipe-note-head > div {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 9px;
}

.cv-recipe-note-state {
  grid-column: 2;
  min-height: 1em;
  color: var(--cvr-faint);
  font-family: var(--font-monospace);
  font-size: .62rem;
  line-height: 1.2;
}


.cv-recipe-note-render {
  position: relative;
  max-height: none;
  min-height: clamp(150px, 16cqi, 260px);
  flex: 1 1 auto;
  padding: clamp(15px, 2.2cqi, 24px);
  overflow: auto;
  color: var(--cvr-muted);
  font-size: clamp(.76rem, 1.2cqi, .88rem);
  line-height: 1.65;
  cursor: text;
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
}

.cv-recipe-note-render.is-empty::before {
  content: "Add substitutions, serving notes, or what to change next time…";
  position: absolute;
  inset: clamp(15px, 2.2cqi, 24px);
  color: var(--cvr-faint);
  font-style: italic;
  pointer-events: none;
}

.cv-recipe-note-render :is(p, li) {
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
}

.cv-recipe-note-render .markdown-rendered-content,
.cv-recipe-note-render .markdown-preview-sizer,
.cv-recipe-note-render .markdown-preview-section {
  width: 100%;
  max-width: none;
  min-height: 100%;
  margin: 0;
  padding: 0;
}

.cv-recipe-note-render .markdown-rendered-content.markdown-preview-view.markdown-rendered {
  padding-top: 10px;
}

.cv-recipe-note-render [data-cv-editable-placeholder],
.cv-recipe-note-render .markdown-source-view,
.cv-recipe-note-render .cm-editor,
.cv-recipe-note-render .cm-scroller,
.cv-recipe-note-render .cm-content {
  width: 100% !important;
  max-width: none !important;
  min-height: clamp(150px, 16cqi, 260px) !important;
  background: transparent !important;
}

.cv-recipe-note-render .markdown-source-view,
.cv-recipe-note-render .cm-editor {
  position: relative !important;
  inset: auto !important;
}

.cv-recipe-note-render .cm-scroller {
  overflow: visible !important;
}

.cv-recipe-note-render .cm-content {
  padding: 0 !important;
  font-size: clamp(.76rem, 1.2cqi, .88rem) !important;
  line-height: 1.65 !important;
}


.cv-recipe-empty {
  padding: 18px;
  color: var(--cvr-faint);
  font-size: .74rem;
  font-style: italic;
  text-align: center;
}

.cv-recipe-icon {
  width: 1.1em;
  height: 1.1em;
  flex: 0 0 auto;
  display: inline-block;
  background: currentColor;
  -webkit-mask-position: center;
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-size: contain;
  mask-position: center;
  mask-repeat: no-repeat;
  mask-size: contain;
