@container (max-width: 980px) {
  .cv-recipe-layout {
    grid-template-columns: minmax(240px, .72fr) minmax(0, 1.2fr);
    gap: 28px;
  }

  .cv-recipe-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cv-recipe-stat:nth-child(odd) {
    border-left: 0;
  }

  .cv-recipe-stat:nth-child(n + 3) {
    border-top: 1px solid var(--cvr-border-strong);
  }

  .cv-recipe-notes-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cv-recipe-note-card {
    grid-column: 1 / -1;
    grid-row: 2;
  }
}

@container (max-width: 720px) {
  .cv-recipe-layout {
    grid-template-columns: 1fr;
  }

  .cv-recipe-sidebar {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
    align-items: start;
  }

  .cv-recipe-main {
    padding-top: 10px;
  }

  .cv-recipe-title-block h1 {
    max-width: 100%;
  }
}

@container (max-width: 520px) {
  .cv-recipe {
    padding: 0;
  }

  .cv-recipe-sheet {
    border-inline: 0;
    border-radius: 0;
  }

  .cv-recipe-sidebar,
  .cv-recipe-notes-grid {
    grid-template-columns: 1fr;
  }

  .cv-recipe-note-card {
    grid-column: auto;
    grid-row: auto;
  }

  .cv-recipe-stats {
    grid-template-columns: 1fr 1fr;
  }

  .cv-recipe-note-head {
    align-items: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cv-recipe *,
  .cv-recipe *::before,
  .cv-recipe *::after {
    transition-duration: 0s !important;
    animation-duration: 0s !important;
  }
}
/* Inline editing for recipe-owned data. */
.cv-recipe-inline-edit {
  min-width: 0;
  border-radius: 6px;
  cursor: text;
  transition: background-color .14s var(--cvr-ease), outline-color .14s var(--cvr-ease), color .14s var(--cvr-ease);
}

.cv-recipe-inline-edit:not(:focus):hover {
  background: color-mix(in srgb, var(--cvr-accent) 7%, transparent);
}

.cv-recipe-inline-edit:focus {
  outline: 1px solid color-mix(in srgb, var(--cvr-accent) 72%, var(--cvr-border));
  outline-offset: 3px;
  background: color-mix(in srgb, var(--cvr-accent) 8%, var(--cvr-bg));
}

.cv-recipe-inline-edit[data-placeholder]:empty::before,
.cv-recipe-draft-row [data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--cvr-faint);
  font-style: italic;
  pointer-events: none;
}

.cv-recipe-tagline.cv-recipe-inline-edit:empty,
.cv-recipe-description.cv-recipe-inline-edit:empty {
  display: block;
  min-height: 1.5em;
}

.cv-recipe-description.cv-recipe-inline-edit--multiline {
  white-space: pre-wrap;
}

.cv-recipe-context-separator[hidden] {
  display: none;
}

.cv-recipe-edit-state {
  display: block;
  min-height: 1em;
  margin-top: 8px;
  color: var(--cvr-faint);
  font-family: var(--font-monospace);
  font-size: .62rem;
  line-height: 1.2;
}

.cv-recipe-edit-state[data-tone="success"] {
  color: var(--text-success, var(--cvr-accent-soft));
}

.cv-recipe-edit-state[data-tone="error"] {
  color: var(--text-error, var(--cvr-accent-soft));
}

.cv-ingredient-name[contenteditable],
.cv-ingredient-amount[contenteditable],
.cv-recipe-list-item[contenteditable],
.cv-recipe-step-copy[contenteditable] {
  min-height: 1.35em;
}

.cv-ingredient-amount[contenteditable]:empty::before,
.cv-ingredient-name[contenteditable]:empty::before,
.cv-recipe-list-item[data-placeholder]:empty::before,
.cv-recipe-step-copy[data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--cvr-faint);
  font-style: italic;
  pointer-events: none;
}

.cv-recipe-list-add {
  list-style: none;
  margin-top: 10px;
}

.cv-recipe-list-add button {
  width: 100%;
  min-height: 32px;
  color: var(--cvr-faint);
  cursor: pointer;
}

.cv-recipe-list-add button:hover {
  color: var(--cvr-accent-soft);
}

.cv-instruction-list .cv-recipe-list-add {
  min-height: 0;
  padding: 12px 0 0;
  border-bottom: 0;
  counter-increment: none;
}

.cv-instruction-list .cv-recipe-list-add::before {
  content: none;
}

.cv-recipe-draft-row {
  background: color-mix(in srgb, var(--cvr-accent) 5%, transparent);
}

/* Recipe paper notes, compact section actions and sequential liquid checklist. */
.cv-recipe {
  --cvr-step-gutter: clamp(62px, 6.7cqi, 70px);
  --cvr-paper-line: var(--vault-note-paper-line, 30px);
  --cvr-paper: var(--vault-note-paper, color-mix(in srgb, var(--background-primary) 60%, var(--background-secondary) 40%));
  --cvr-paper-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--interactive-accent) 15%, transparent));
  --cvr-paper-margin: var(--vault-note-paper-margin-rule, color-mix(in srgb, var(--interactive-accent) 22%, transparent));
  --cvr-tape: var(--vault-note-paper-tape, color-mix(in srgb, var(--interactive-accent-hover, var(--interactive-accent)) 17%, var(--background-secondary) 83%));
  --cvr-tape-edge: var(--vault-note-paper-tape-edge, color-mix(in srgb, var(--text-normal) 13%, var(--background-secondary-alt, var(--background-secondary)) 87%));
  --cvr-liquid: var(--cvr-accent);
  --cvr-liquid-soft: var(--cvr-accent-soft);
}

.cv-recipe-notes-grid {
  padding-top: clamp(20px, 2.6cqi, 30px);
}

.cv-recipe-notes-grid > .cv-recipe-small-card {
  position: relative;
  overflow: visible;
  isolation: isolate;
  border-radius: 8px;
  border-color: color-mix(in srgb, var(--cvr-border-strong) 76%, transparent);
  background: var(--vault-note-paper-background,
    linear-gradient(90deg, transparent 0 44px, var(--cvr-paper-margin) 44px 45px, transparent 45px),
    repeating-linear-gradient(to bottom, transparent 0 calc(var(--cvr-paper-line) - 7px),
            color-mix(in srgb, var(--cvr-paper-rule) 55%, transparent) calc(var(--cvr-paper-line) - 7px) calc(var(--cvr-paper-line) - 5px),
            transparent calc(var(--cvr-paper-line) - 5px) var(--cvr-paper-line)),
    var(--cvr-paper));
  box-shadow:
    0 16px 34px var(--cvr-shadow-soft),
    0 3px 9px var(--cvr-shadow-soft);
}

.cv-recipe-notes-grid > .cv-recipe-small-card::before {
  content: "";
  position: absolute;
  z-index: 8;
  top: 0;
  width: clamp(54px, 7cqi, 72px);
  height: clamp(20px, 2.5cqi, 24px);
  pointer-events: none;
  border: 1px solid var(--cvr-tape-edge);
  border-radius: 0;
  background:
    linear-gradient(105deg, color-mix(in srgb, var(--cvr-text) 5%, transparent) 0 12%, transparent 12% 88%, color-mix(in srgb, var(--cvr-text) 4%, transparent) 88%),
    var(--cvr-tape);
  box-shadow:
    0 2px 5px var(--cvr-shadow-soft),
    inset 0 0 0 1px color-mix(in srgb, var(--cvr-text) 4%, transparent);
  opacity: 1;
  left: 0;
  transform: translate(-50%, -50%) rotate(-34deg);
}

.cv-recipe-notes-grid > .cv-recipe-small-card[data-tape-side="right"]::before {
  left: auto;
  right: 0;
  transform: translate(50%, -50%) rotate(34deg);
}

.cv-recipe-notes-grid > .cv-recipe-small-card::after {
  content: none;
}

.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-card-head,
.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-note-render {
  background: transparent;
}

.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-card-head {
  border-bottom: 2px solid color-mix(in srgb, var(--cvr-accent) 34%, var(--cvr-border-strong) 66%);
}

.cv-recipe-notes-grid > .cv-recipe-small-card :is(.cv-recipe-mini-list, .cv-recipe-note-render) {
  padding-left: clamp(40px, 4.4cqi, 52px);
}

.cv-recipe-card-head,
.cv-recipe-section-title {
  position: relative;
}

.cv-recipe-compact-add {
  min-height: 26px;
  margin-inline-start: auto;
  padding: 4px 8px;
  flex: 0 0 auto;
  border: 1px solid var(--cvr-border);
  border-radius: 7px;
  background: color-mix(in srgb, var(--cvr-bg) 72%, var(--cvr-card) 28%);
  color: var(--cvr-accent-soft);
  box-shadow: none;
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: clamp(.58rem, .9cqi, .68rem);
  font-weight: 720;
  line-height: 1;
  letter-spacing: .02em;
  transition:
    border-color .15s var(--cvr-ease),
    background-color .15s var(--cvr-ease),
    color .15s var(--cvr-ease),
    transform .15s var(--cvr-ease);
}

.cv-recipe-compact-add:hover {
  border-color: var(--cvr-border-strong);
  background: var(--cvr-hover);
  color: var(--cvr-text);
  transform: translateY(-1px);
}

.cv-ingredients-card .cv-ingredient-list > .cv-recipe-list-add,
.cv-instruction-list > .cv-recipe-list-add,
.cv-recipe-mini-list > .cv-recipe-list-add {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .cv-recipe-compact-add {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  .cv-recipe-notes-grid > .cv-recipe-small-card {
    transform: none !important;
  }
}

/* Final alignment and one-surface paper composition. */
.cv-recipe-description {
  max-width: none;
  margin: 0;
  padding: clamp(20px, 3cqi, 32px) clamp(12px, 1.6cqi, 20px) clamp(22px, 3cqi, 34px);
  text-align: justify;
}

.cv-recipe-photo-actions {
  right: clamp(20px, 2.5cqi, 28px);
  bottom: clamp(20px, 2.5cqi, 28px);
}

.cv-recipe-action-state {
  right: clamp(20px, 2.5cqi, 28px);
  bottom: 4px;
}

.cv-recipe-notes-grid > .cv-recipe-small-card :is(.cv-recipe-mini-list, .cv-recipe-note-render) {
  line-height: var(--cvr-paper-line);
}

.cv-recipe-note-render .cm-content,
.cv-recipe-note-render :is(p, li) {
  line-height: var(--cvr-paper-line) !important;
}

.cv-recipe-note-render p,
.cv-recipe-mini-list li + li {
  margin-block: 0;
}

.cv-recipe-mini-list li {
  min-height: var(--cvr-paper-line);
}

@container (max-width: 620px) {
  .cv-recipe {
    --cvr-step-gutter: 58px;
  }
}

/* Canonical 30px paper/content baseline with no unruled Markdown gaps. */
.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-card-head {
  min-height: calc(var(--cvr-paper-line) * 2);
  padding-block: 0;
}

.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-mini-list,
.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-note-render {
  padding: 0 clamp(18px, 2.5cqi, 26px) var(--cvr-paper-line) clamp(54px, 5cqi, 66px);
}

.cv-recipe-note-render.is-empty::before {
  inset: 0 clamp(18px, 2.5cqi, 26px) auto clamp(54px, 5cqi, 66px);
  line-height: var(--cvr-paper-line);
}

.cv-recipe-note-render > :is(h1, h2, h3, h4, h5, h6, p, ul, ol, pre),
.cv-recipe-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6, p, ul, ol, pre),
.cv-recipe-mini-list li {
  min-height: var(--cvr-paper-line);
  margin-block: 0 !important;
  line-height: var(--cvr-paper-line) !important;
}

.cv-recipe-note-render > :is(h1, h2, h3, h4, h5, h6),
.cv-recipe-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6) {
  padding-block: 0 !important;
}

.cv-recipe-note-render > :is(ul, ol),
.cv-recipe-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) {
  padding-block: 0 !important;
}

.cv-recipe-note-render .cm-line {
  min-height: var(--cvr-paper-line);
  line-height: var(--cvr-paper-line) !important;
}

/* 2026 Recipe rework: semantic paper surfaces and native gooey progress. */
.cv-recipe {
  --cvr-step-size: 48px;
  --cvr-step-gutter: clamp(70px, 7.4cqi, 82px);
  --cvr-progress-track: color-mix(in srgb, var(--cvr-border-strong) 72%, var(--cvr-surface-2) 28%);
  --cvr-progress-fill: var(--cvr-accent);
  --cvr-progress-fill-soft: color-mix(in srgb, var(--cvr-accent-soft) 76%, var(--cvr-accent) 24%);
  --cvr-progress-surface: color-mix(in srgb, var(--cvr-card) 88%, var(--cvr-surface-2) 12%);
  --cvr-progress-ink: var(--cvr-on-accent);
  --cvr-paper-divider: color-mix(in srgb, var(--cvr-accent) 54%, var(--cvr-border-strong) 46%);
}

.cv-recipe-section-title > div {
  min-width: 0;
}

.cv-recipe-progress-summary {
  display: block;
  margin-top: 5px;
  color: var(--cvr-faint);
  font-family: var(--font-monospace);
  font-size: clamp(.58rem, .9cqi, .68rem);
  line-height: 1.25;
  letter-spacing: .03em;
}

.cv-recipe-goo-defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

/* Ingredients remain contained and become two-column only when an amount exists. */
.cv-ingredients-card .cv-ingredient-list {
  min-width: 0;
  overflow: hidden;
}

.cv-ingredient-row:not(.has-amount) .cv-ingredient-name {
  width: 100%;
}

.cv-ingredient-row.has-amount .cv-ingredient-amount {
  max-width: min(16ch, 42%);
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Paper rules run through the full card; content height follows its content. */
.cv-recipe-notes-grid > .cv-recipe-small-card {
  min-height: calc(var(--cvr-paper-line) * 4);
  height: auto;
  overflow: visible;
  border: 1px solid color-mix(in srgb, var(--cvr-border-strong) 82%, transparent);
  border-radius: 8px;
  background: var(--vault-note-paper-background,
    linear-gradient(90deg, transparent 0 44px, var(--cvr-paper-margin) 44px 45px, transparent 45px),
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--cvr-paper-line) - 7px),
            color-mix(in srgb, var(--cvr-paper-rule) 55%, transparent) calc(var(--cvr-paper-line) - 7px) calc(var(--cvr-paper-line) - 5px),
            transparent calc(var(--cvr-paper-line) - 5px) var(--cvr-paper-line)
    ),
    var(--cvr-paper));
  background-position: 0 0;
}

.cv-recipe-notes-grid > .cv-recipe-note-card {
  min-height: calc(var(--cvr-paper-line) * 5);
}

.cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-card-head {
  min-height: calc(var(--cvr-paper-line) * 2);
  padding-block: 0;
  border-bottom: 2px solid var(--cvr-paper-divider);
  background: transparent;
  box-shadow: 0 1px 0 color-mix(in srgb, var(--cvr-text) 8%, transparent);
}

.cv-recipe-notes-grid > .cv-recipe-small-card :is(.cv-recipe-mini-list, .cv-recipe-note-render) {
  max-height: none;
  min-height: calc(var(--cvr-paper-line) * 2);
  flex: 0 1 auto;
  margin: 0;
  padding: 0 clamp(18px, 2.5cqi, 26px) var(--cvr-paper-line) clamp(54px, 5cqi, 66px);
  overflow: visible;
  background: transparent;
  line-height: var(--cvr-paper-line);
}

.cv-recipe-note-render.is-empty::before {
  inset: 0 clamp(18px, 2.5cqi, 26px) auto clamp(54px, 5cqi, 66px);
  line-height: var(--cvr-paper-line);
}

.cv-recipe-mini-list li,
.cv-recipe-note-render > :is(h1, h2, h3, h4, h5, h6, p, ul, ol),
.cv-recipe-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6, p, ul, ol) {
  min-height: var(--cvr-paper-line);
  margin-block: 0 !important;
  line-height: var(--cvr-paper-line) !important;
}

.cv-recipe-note-render > :is(h1, h2, h3, h4, h5, h6, ul, ol),
.cv-recipe-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6, ul, ol) {
  padding-block: 0 !important;
}

.cv-recipe-note-render :is(
  [data-cv-editable-placeholder],
  .markdown-rendered-content,
  .markdown-preview-sizer,
  .markdown-preview-section,
  .markdown-source-view,
  .cm-editor,
  .cm-scroller,
  .cm-content,
  .cm-line
) {
  min-height: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.cv-recipe-note-render .cm-line {
  min-height: var(--cvr-paper-line) !important;
  line-height: var(--cvr-paper-line) !important;
}

/* The visible compact controls proxy the hidden list add actions. */
.cv-ingredients-card .cv-ingredient-list > .cv-recipe-list-add,
.cv-instruction-list > .cv-recipe-list-add,
.cv-recipe-mini-list > .cv-recipe-list-add {
  display: none;
}

/* Native checkbox + label; the ordered list remains the sequential structure. */
.cv-instruction-list > .cv-recipe-step {
  position: relative;
  min-height: calc(var(--cvr-step-size) + 24px);
  padding: 12px 0 12px var(--cvr-step-gutter);
  color: var(--cvr-muted);
  line-height: 1.68;
  text-align: justify;
  text-justify: inter-word;
  hyphens: auto;
}

.cv-instruction-list > .cv-recipe-step + .cv-recipe-step {
  padding-top: 12px;
}

.cv-recipe-step-copy {
  min-width: 0;
  display: block;
  padding: 7px 0;
  overflow-wrap: anywhere;
}

.cv-recipe-step-input {
  position: absolute;
  top: 50%;
  left: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  clip-path: inset(50%);
  white-space: nowrap;
}

.cv-recipe-step-toggle,
.cv-instruction-list > .cv-recipe-step + .cv-recipe-step .cv-recipe-step-toggle {
  position: absolute;
  z-index: 6;
  top: 50%;
  left: 0;
  width: var(--cvr-step-size);
  height: var(--cvr-step-size);
  display: grid;
  place-items: center;
  padding: 0;
  overflow: visible;
  border: 2px solid color-mix(in srgb, var(--cvr-accent) 55%, var(--cvr-border-strong) 45%);
  border-radius: 50%;
  background: var(--cvr-progress-surface);
  color: var(--cvr-accent-soft);
  box-shadow:
    0 4px 12px var(--cvr-shadow-soft),
    0 0 0 3px color-mix(in srgb, var(--cvr-card) 78%, transparent);
  cursor: pointer;
  isolation: isolate;
  transform: translateY(-50%);
  transition:
    border-color .2s var(--cvr-ease),
    box-shadow .2s var(--cvr-ease),
    color .2s var(--cvr-ease);
}

.cv-recipe-step-toggle::before,
.cv-recipe-step-toggle::after {
  content: none;
}

.cv-recipe-step-input:focus-visible + .cv-recipe-step-toggle {
  outline: 2px solid var(--cvr-accent);
  outline-offset: 4px;
  box-shadow:
    0 4px 12px var(--cvr-shadow-soft),
    0 0 0 3px color-mix(in srgb, var(--cvr-card) 78%, transparent),
    0 0 0 6px color-mix(in srgb, var(--cvr-accent) 24%, transparent);
}

.cv-recipe-step.is-current .cv-recipe-step-toggle {
  border-color: var(--cvr-accent);
  box-shadow:
    0 4px 12px var(--cvr-shadow-soft),
    0 0 0 3px color-mix(in srgb, var(--cvr-card) 78%, transparent),
    0 0 0 5px color-mix(in srgb, var(--cvr-accent) 16%, transparent);
}

.cv-recipe-step-goo {
  position: absolute;
  z-index: 1;
  inset: -8px;
  pointer-events: none;
  filter: var(--cvr-goo-filter);
}

.cv-recipe-step-blob,
.cv-recipe-step-neck,
.cv-recipe-step-flow-capsule,
.cv-recipe-step-flow-droplet {
  position: absolute;
  display: block;
  background: linear-gradient(to bottom, var(--cvr-progress-fill-soft), var(--cvr-progress-fill));
}

.cv-recipe-step-blob {
  inset: 12px;
  border-radius: 50%;
  transform: scale(0);
  transform-origin: center;
  transition: transform .42s cubic-bezier(.2, .76, .2, 1);
}

.cv-recipe-step-neck {
  top: -2px;
  left: calc(50% - 7px);
  width: 14px;
  height: 27px;
  border-radius: 999px;
  opacity: 0;
  transform: translateY(-16px) scale(.68);
  transform-origin: center;
}

.cv-recipe-step-glyph {
  position: relative;
  z-index: 3;
  font-family: var(--font-monospace);
  font-size: .72rem;
  font-weight: 790;
  line-height: 1;
  pointer-events: none;
}

.cv-recipe-step.is-checked .cv-recipe-step-toggle {
  border-color: color-mix(in srgb, var(--cvr-progress-fill) 82%, var(--cvr-border));
  color: var(--cvr-progress-ink);
}

.cv-recipe-step.is-checked .cv-recipe-step-blob {
  transform: scale(1);
}

/* Neutral rail is continuous; active halves meet at every checked node. */
.cv-instruction-list > .cv-recipe-step::before {
  content: "";
  position: absolute;
  z-index: 1;
  top: 0;
  bottom: 0;
  left: calc((var(--cvr-step-size) - 8px) / 2);
  width: 8px;
  border-radius: 999px;
  background: var(--cvr-progress-track);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvr-text) 8%, transparent);
  pointer-events: none;
}

.cv-instruction-list > .cv-recipe-step:first-child::before {
  top: 50%;
}

.cv-instruction-list > .cv-recipe-step:last-child::before {
  bottom: 50%;
}

.cv-instruction-list > .cv-recipe-step:only-child::before {
  content: none;
}

.cv-instruction-list > .cv-recipe-step:not(:first-child)::after {
  content: "";
  position: absolute;
  z-index: 2;
  top: 0;
  bottom: auto;
  left: calc((var(--cvr-step-size) - 8px) / 2);
  width: 8px;
  height: 50%;
  background: linear-gradient(to bottom, var(--cvr-progress-fill-soft), var(--cvr-progress-fill));
  box-shadow: 0 0 9px color-mix(in srgb, var(--cvr-progress-fill) 20%, transparent);
  pointer-events: none;
  transform: scaleY(0);
  transform-origin: top;
}

.cv-instruction-list > .cv-recipe-step.is-checked:not(:first-child)::after {
  top: 0;
  bottom: auto;
  left: calc((var(--cvr-step-size) - 8px) / 2);
  width: 8px;
  height: 50%;
  background: linear-gradient(to bottom, var(--cvr-progress-fill-soft), var(--cvr-progress-fill));
  transform: scaleY(1);
}

.cv-recipe-step-flow,
.cv-instruction-list > .cv-recipe-step + .cv-recipe-step .cv-recipe-step-flow {
  position: absolute;
  z-index: 3;
  top: 50%;
  bottom: 0;
  left: calc((var(--cvr-step-size) / 2) - 10px);
  width: 20px;
  border-radius: 0;
  background: none;
  box-shadow: none;
  pointer-events: none;
  filter: var(--cvr-goo-filter);
  transform: none;
  animation: none !important;
}

.cv-recipe-step-flow-capsule {
  inset: 0 6px;
  border-radius: 999px;
  transform: scaleY(0);
  transform-origin: top;
}

.cv-recipe-step-flow-droplet {
  top: -6px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  opacity: 0;
  transform: scale(.72);
}

.cv-recipe-step.is-flowing-to-next > .cv-recipe-step-flow .cv-recipe-step-flow-capsule {
  transform: scaleY(1);
}

.cv-recipe-step.is-flowing-to-next > .cv-recipe-step-flow {
  transform: none;
}

.cv-recipe-step.is-filling-down .cv-recipe-step-blob {
  animation: cvr-goo-node-fill 520ms cubic-bezier(.16, .78, .18, 1) forwards;
}

.cv-recipe-step.is-filling-down .cv-recipe-step-neck {
  animation: cvr-goo-neck-down 520ms cubic-bezier(.16, .78, .18, 1) forwards;
}

.cv-recipe-step.is-draining-up .cv-recipe-step-blob {
  animation: cvr-goo-node-drain 520ms cubic-bezier(.16, .78, .18, 1) forwards;
}

.cv-recipe-step.is-draining-up .cv-recipe-step-neck {
  animation: cvr-goo-neck-up 520ms cubic-bezier(.16, .78, .18, 1) forwards;
}

.cv-instruction-list > .cv-recipe-step.is-filling-down:not(:first-child)::after {
  animation: cvr-goo-upper-fill 520ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-instruction-list > .cv-recipe-step.is-draining-up:not(:first-child)::after {
  animation: cvr-goo-upper-drain 520ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-recipe-step-flow.is-flowing-down .cv-recipe-step-flow-capsule {
  animation: cvr-goo-rail-fill 520ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-recipe-step-flow.is-flowing-down .cv-recipe-step-flow-droplet {
  animation: cvr-goo-droplet-down 520ms cubic-bezier(.16, .72, .18, 1) forwards;
}

.cv-recipe-step-flow.is-draining-up .cv-recipe-step-flow-capsule {
  animation: cvr-goo-rail-drain 520ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-recipe-step-flow.is-draining-up .cv-recipe-step-flow-droplet {
  animation: cvr-goo-droplet-up 520ms cubic-bezier(.16, .72, .18, 1) forwards;
}

@keyframes cvr-goo-node-fill {
  0% { transform: scale(0); }
  68% { transform: scale(1.12, .94); }
  100% { transform: scale(1); }
}

@keyframes cvr-goo-node-drain {
  0% { transform: scale(1); }
  35% { transform: scale(.92, 1.08); }
  100% { transform: scale(0); }
}

@keyframes cvr-goo-neck-down {
  0% { opacity: 0; transform: translateY(-18px) scale(.62); }
  24% { opacity: 1; }
  78% { opacity: 1; transform: translateY(18px) scale(1); }
  100% { opacity: 0; transform: translateY(25px) scale(.72); }
}

@keyframes cvr-goo-neck-up {
  0% { opacity: 0; transform: translateY(25px) scale(.72); }
  24% { opacity: 1; }
  78% { opacity: 1; transform: translateY(-8px) scale(.92); }
  100% { opacity: 0; transform: translateY(-18px) scale(.62); }
}

@keyframes cvr-goo-upper-fill {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}

@keyframes cvr-goo-upper-drain {
  from { transform: scaleY(1); }
  to { transform: scaleY(0); }
}

@keyframes cvr-goo-rail-fill {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}

@keyframes cvr-goo-rail-drain {
  from { transform: scaleY(1); }
  to { transform: scaleY(0); }
}

@keyframes cvr-goo-droplet-down {
  0% { top: -6px; opacity: 0; transform: scale(.7); }
  18% { opacity: 1; }
  84% { top: calc(100% - 10px); opacity: 1; transform: scale(1.08); }
  100% { top: calc(100% - 8px); opacity: 0; transform: scale(.76); }
}

@keyframes cvr-goo-droplet-up {
  0% { top: calc(100% - 8px); opacity: 0; transform: scale(.76); }
  18% { opacity: 1; }
  84% { top: -4px; opacity: 1; transform: scale(1); }
  100% { top: -6px; opacity: 0; transform: scale(.7); }
}

/* Preserve the requested reading rhythm and existing photo action placement. */
.cv-recipe-description {
  max-width: none;
  margin: 0;
  padding: clamp(20px, 3cqi, 32px) clamp(12px, 1.6cqi, 20px) clamp(22px, 3cqi, 34px);
  text-align: justify;
  text-justify: inter-word;
}

.cv-recipe-photo-actions {
  right: clamp(20px, 2.5cqi, 28px);
  bottom: clamp(20px, 2.5cqi, 28px);
}

.cv-recipe-action-state {
  right: clamp(20px, 2.5cqi, 28px);
  bottom: 4px;
}

@container (max-width: 620px) {
  .cv-recipe {
    --cvr-step-size: 44px;
    --cvr-step-gutter: 60px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cv-recipe-step-toggle,
  .cv-recipe-step-box,
  .cv-recipe-step-check,
  .cv-recipe-step-blob,
  .cv-recipe-step-neck,
  .cv-recipe-step-flow,
  .cv-recipe-step-flow-capsule,
  .cv-recipe-step-flow-droplet,
  .cv-instruction-list > .cv-recipe-step::after {
    animation: none !important;
    transition: none !important;
  }
}

@media (forced-colors: active) {
  .cv-recipe-notes-grid > .cv-recipe-small-card {
    border-color: CanvasText;
    background: Canvas;
  }

  .cv-recipe-notes-grid > .cv-recipe-small-card .cv-recipe-card-head {
    border-bottom-color: CanvasText;
  }

  .cv-recipe-step-goo,
  .cv-recipe-step-flow {
    filter: none;
  }

  .cv-recipe-step-toggle,
  .cv-instruction-list > .cv-recipe-step + .cv-recipe-step .cv-recipe-step-toggle {
    border-color: ButtonText;
    background: Canvas;
    color: CanvasText;
    box-shadow: none;
  }

  .cv-recipe-step-input:focus-visible + .cv-recipe-step-toggle {
    outline-color: Highlight;
    box-shadow: none;
  }

  .cv-instruction-list > .cv-recipe-step::before {
    background: GrayText;
    box-shadow: none;
  }

  .cv-recipe-step-blob,
  .cv-recipe-step-neck,
  .cv-recipe-step-flow-capsule,
  .cv-recipe-step-flow-droplet,
  .cv-instruction-list > .cv-recipe-step::after {
    background: Highlight;
    box-shadow: none;
  }

  .cv-recipe-step.is-checked .cv-recipe-step-toggle {
    border-color: Highlight;
    color: HighlightText;
  }
}

/* Three-section recipe workspace: mirrors the local navigation model used by Media. */
.cv-recipe {
  --cvr-checkbox-size: 30px;
  display: block;
}

.cv-recipe-hero {
  width: min(100%, 1440px);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(240px, .72fr) minmax(0, 1.4fr) max-content;
  align-items: center;
  gap: clamp(28px, 4cqi, 58px);
  padding: var(--cvr-pad);
  border-bottom: 1px solid var(--cvr-border);
  background:
    linear-gradient(105deg, color-mix(in srgb, var(--cvr-accent) 6%, transparent), transparent 46%),
    var(--cvr-bg);
}

.cv-recipe-hero .cv-recipe-photo-card {
  width: 100%;
  max-width: 390px;
  margin: clamp(16px, 2cqi, 24px) 0 0;
}

.cv-recipe-hero .cv-recipe-title-block {
  min-width: 0;
  padding: 0;
}

.cv-recipe-nav {
  min-width: max-content;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-self: end;
  gap: 16px;
  text-align: right;
}

.cv-recipe-nav a {
  color: var(--cvr-muted);
  font-size: clamp(.78rem, 1.25cqi, .92rem);
  font-weight: 600;
  text-decoration: none;
  transition: color .18s var(--cvr-ease);
}

.cv-recipe-nav a:hover {
  color: var(--cvr-text);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.cv-recipe-nav a[aria-selected="true"] {
  color: var(--cvr-accent-soft);
  font-weight: 740;
}

.cv-recipe-sheet {
  width: min(100%, 1440px);
  min-height: 0;
  margin: 0 auto;
  overflow: visible;
  border-radius: 0;
  background: var(--cvr-panel);
  box-shadow: none;
}

.cv-recipe-view {
  position: relative;
  z-index: 1;
  padding: clamp(38px, 6cqi, 78px) var(--cvr-pad) clamp(48px, 7cqi, 90px);
  scroll-margin-top: 20px;
}

.cv-recipe-view[hidden] {
  display: none !important;
}

.cv-recipe-view:not([hidden]) {
  animation: cvr-view-in .22s var(--cvr-ease) both;
}

@keyframes cvr-view-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.cv-recipe-view-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: clamp(18px, 2.5cqi, 28px);
}

.cv-recipe-view-head h2 {
  margin: 5px 0 0;
  color: var(--cvr-text);
  font-size: clamp(1.35rem, 2.5cqi, 2.1rem);
  line-height: 1.1;
  font-weight: 760;
  letter-spacing: -.025em;
}

.cv-recipe-view .cv-recipe-stats {
  margin-top: 0;
}

.cv-recipe-overview-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(280px, .75fr);
  align-items: start;
  gap: var(--cvr-gap);
  margin-top: var(--cvr-gap);
}

.cv-recipe-overview-grid .cv-recipe-description {
  min-height: 100%;
  margin: 0;
  padding: clamp(18px, 2.6cqi, 28px);
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  text-align: justify;
  text-justify: inter-word;
}

.cv-recipe-overview-grid .cv-recipe-description:empty {
  display: block;
}

.cv-recipe-overview-grid .cv-ingredients-card {
  min-width: 0;
}

.cv-recipe-view .cv-instructions-section {
  margin-top: 0;
}

.cv-recipe-view .cv-recipe-notes-grid {
  position: relative;
  z-index: 1;
  margin-top: var(--cvr-gap);
  padding: 0;
}

.cv-recipe-support-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

#cv-recipe-method .cv-recipe-notes-grid > .cv-recipe-small-card
  :is(.cv-recipe-mini-list, .cv-recipe-note-render) {
  min-height: calc(var(--cvr-paper-line) * 10);
}

.cv-recipe-personal-grid {
  grid-template-columns: minmax(0, 1fr);
}

.cv-recipe-personal-grid > .cv-recipe-note-card {
  grid-column: auto;
  grid-row: auto;
  min-height: calc(var(--cvr-paper-line) * 11);
}

/* Recipe instructions now use one plain, centered rounded-square checkbox per row. */
.cv-instruction-list > .cv-recipe-step,
.cv-instruction-list > .cv-recipe-step + .cv-recipe-step {
  min-height: 54px;
  display: grid;
  grid-template-columns: var(--cvr-checkbox-size) minmax(0, 1fr);
  align-items: center;
  column-gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--cvr-border) 72%, transparent);
  counter-increment: none;
}

.cv-instruction-list > .cv-recipe-step:last-of-type {
  border-bottom: 0;
}

.cv-instruction-list > .cv-recipe-step::before,
.cv-instruction-list > .cv-recipe-step::after {
  content: none !important;
}

.cv-recipe-step-copy {
  grid-column: 2;
  grid-row: 1;
  align-self: center;
  display: block;
  min-width: 0;
  padding: 0;
  line-height: 1.65;
}

.cv-recipe-step-input {
  position: absolute;
  grid-column: 1;
  grid-row: 1;
  width: 1px;
  height: 1px;
  min-width: 0;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  border: 0;
  white-space: nowrap;
}

.cv-recipe-step-box {
  grid-column: 1;
  grid-row: 1;
  width: var(--cvr-checkbox-size);
  height: var(--cvr-checkbox-size);
  min-width: var(--cvr-checkbox-size);
  display: grid;
  place-items: center;
  align-self: center;
  margin: 0;
  border: 2px solid color-mix(in srgb, var(--cvr-accent) 55%, var(--cvr-border-strong) 45%);
  border-radius: 10px;
  background: color-mix(in srgb, var(--cvr-card) 88%, var(--cvr-surface-2) 12%);
  color: var(--cvr-on-accent);
  box-shadow: 0 3px 9px var(--cvr-shadow-soft);
  cursor: pointer;
  user-select: none;
  transition: border-color .16s var(--cvr-ease), background-color .16s var(--cvr-ease), box-shadow .16s var(--cvr-ease), transform .16s var(--cvr-ease);
}

.cv-recipe-step-check {
  width: 7px;
  height: 13px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-1px) rotate(45deg) scale(0);
  transition: transform .14s var(--cvr-ease);
}

.cv-recipe-step-box:hover {
  border-color: var(--cvr-accent);
  transform: translateY(-1px);
}

.cv-recipe-step-input:checked + .cv-recipe-step-box {
  border-color: var(--cvr-accent);
  background: var(--cvr-accent);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--cvr-accent) 28%, transparent);
}

.cv-recipe-step-input:checked + .cv-recipe-step-box .cv-recipe-step-check {
  transform: translateY(-1px) rotate(45deg) scale(1);
}

.cv-recipe-step-input:focus-visible + .cv-recipe-step-box {
  outline: 2px solid var(--cvr-accent-soft);
  outline-offset: 3px;
}

@container (max-width: 950px) {
  .cv-recipe-hero {
    grid-template-columns: minmax(220px, .72fr) minmax(0, 1.28fr);
  }

  .cv-recipe-nav {
    grid-column: 1 / -1;
    flex-direction: row;
    align-items: center;
    justify-self: start;
    gap: 18px;
    text-align: left;
  }

  .cv-recipe-overview-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@container (max-width: 620px) {
  .cv-recipe-hero {
    grid-template-columns: minmax(0, 1fr);
  }

  .cv-recipe-hero .cv-recipe-photo-card {
    max-width: 100%;
  }

  .cv-recipe-nav {
    grid-column: auto;
    width: 100%;
    justify-content: space-between;
    gap: 12px;
  }

  .cv-recipe-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cv-recipe-stat:nth-child(3) {
