const recipeContext = tp;
const recipeContainer = recipeContext.container || this;
const recipeRoot = recipeContainer.querySelector(".cv-recipe");

if (recipeRoot) {
  const recipeApp = recipeContext.app;
  const recipeFile = recipeContext.file;
  const recipeFrontmatter = recipeContext.frontmatter || {};
  const recipeBodyContent = String(recipeContext.bodyContent || "");
  const recipeDocument = recipeContext.activeDocument || recipeContainer.ownerDocument;
  const recipeWindow = recipeDocument.defaultView;
  const recipeQuery = selector => recipeRoot.querySelector(selector);
  const recipeQueryAll = selector => Array.from(recipeRoot.querySelectorAll(selector));
  const recipeViewToken = String(
    recipeDocument.defaultView?.crypto?.randomUUID?.() ||
    `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
  ).replace(/[^a-zA-Z0-9_-]/g, "");

  const asArray = value => {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return [value];
  };

  const text = value => String(value ?? "").trim();

  function cleanWiki(value) {
    return String(value ?? "")
      .replace(/^!?\[\[([^\]|]+)\|([^\]]+)\]\]$/, "$2")
      .replace(/^!?\[\[([^\]]+)\]\]$/, "$1")
      .trim();
  }

  function makeElement(tag, className, value) {
    const element = recipeDocument.createElement(tag);
    if (className) element.className = className;
    if (value !== undefined) element.textContent = String(value);
    return element;
  }

  function resolveImage(value) {
    const raw = asArray(value).map(item => String(item ?? "").trim()).find(Boolean) || "";
    if (!raw) return "";
    const wikiMatch = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    if (!wikiMatch) return raw;
    if (!recipeApp?.metadataCache || !recipeFile) return "";
    const target = recipeApp.metadataCache.getFirstLinkpathDest(wikiMatch[1], recipeFile.path);
    return target ? recipeApp.vault.getResourcePath(target) : "";
  }

  const numericValue = value => {
    if (value === null || value === undefined || text(value) === "") return null;
    const parsed = Number(String(value).replace(/[^0-9.+-]/g, ""));
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
  };

  const recipeState = {
    recipe_category: text(recipeFrontmatter.recipe_category),
    cuisine: text(recipeFrontmatter.cuisine),
    tagline: text(recipeFrontmatter.tagline),
    description: text(recipeFrontmatter.description),
    servings: numericValue(recipeFrontmatter.servings),
    prep_time: numericValue(recipeFrontmatter.prep_time),
    cook_time: numericValue(recipeFrontmatter.cook_time),
    difficulty: text(recipeFrontmatter.difficulty),
    ingredients: asArray(recipeFrontmatter.ingredients).map(item => String(item ?? "")).filter(item => text(item)),
    instructions: asArray(recipeFrontmatter.instructions).map(item => String(item ?? "")).filter(item => text(item)),
    instruction_done: asArray(recipeFrontmatter.instruction_done).map(value => value === true || String(value).toLowerCase() === "true"),
    tips: asArray(recipeFrontmatter.tips).map(item => String(item ?? "")).filter(item => text(item)),
    pairs_well_with: asArray(recipeFrontmatter.pairs_well_with).map(item => String(item ?? "")).filter(item => text(item)),
  };

  let recipeTitle = recipeFile?.basename || "Untitled recipe";
  let frontmatterQueue = Promise.resolve();

  function setEditState(message, tone = "") {
    const state = recipeQuery('[data-role="recipe-edit-state"]');
    if (!state) return;
    state.textContent = message;
    state.dataset.tone = tone;
  }

  function updateFrontmatter(patch) {
    if (!recipeApp?.fileManager || !recipeFile) {
      return Promise.reject(new Error("Recipe file is unavailable"));
    }
    const task = frontmatterQueue.then(() =>
      recipeApp.fileManager.processFrontMatter(recipeFile, draft => {
        for (const [property, value] of Object.entries(patch)) draft[property] = value;
      })
    );
    frontmatterQueue = task.catch(() => {});
    return task;
  }

  function displayScalar(property) {
    const value = recipeState[property];
    if (property === "prep_time" || property === "cook_time") {
      return Number.isFinite(value) ? `${value} min` : "";
    }
    if (property === "servings") return Number.isFinite(value) ? String(value) : "";
    return String(value ?? "");
  }

  function renderEditableProperty(property) {
    const value = displayScalar(property);
    for (const element of recipeQueryAll(`[data-edit-property="${property}"]`)) {
      if (recipeDocument.activeElement === element) continue;
      element.textContent = value;
    }
  }

  function renderContext() {
    renderEditableProperty("recipe_category");
    renderEditableProperty("cuisine");
    const separator = recipeQuery('[data-role="recipe-context-separator"]');
    if (separator) separator.hidden = !(text(recipeState.recipe_category) && text(recipeState.cuisine));
  }

  function renderCover() {
    const cover = recipeQuery('[data-role="recipe-cover"]');
    const source = resolveImage(recipeFrontmatter.cover);
    if (cover) {
      cover.alt = recipeTitle;
      if (source) cover.src = source;
      else cover.removeAttribute("src");
    }
  }

  function renderIdentity() {
    const title = recipeQuery('[data-role="recipe-title"]');
    if (title && recipeDocument.activeElement !== title) title.textContent = recipeTitle;
    renderContext();
    renderEditableProperty("tagline");
    renderEditableProperty("description");
    renderEditableProperty("servings");
    renderEditableProperty("prep_time");
    renderEditableProperty("cook_time");
    renderEditableProperty("difficulty");
  }

  function parseScalarEdit(element, property) {
    const raw = text(element.textContent);
    const kind = element.dataset.editKind || "text";
    if (kind === "integer" || kind === "minutes") {
      if (!raw) return null;
      const parsed = Number(raw.replace(/[^0-9.+-]/g, ""));
      if (!Number.isFinite(parsed) || parsed < 0) return Symbol.for("invalid");
      return kind === "integer" ? Math.round(parsed) : parsed;
    }
    return raw;
  }

  function initScalarEditors() {
    for (const element of recipeQueryAll("[data-edit-property]")) {
      const property = element.dataset.editProperty;
      if (!property || !(property in recipeState)) continue;

      element.addEventListener("focus", () => {
        if (element.dataset.editKind === "minutes" && Number.isFinite(recipeState[property])) {
          element.textContent = String(recipeState[property]);
        }
      });

      element.addEventListener("keydown", event => {
        if (event.key === "Escape") {
          event.preventDefault();
          element.textContent = displayScalar(property);
          element.blur();
          return;
        }
        if (event.key === "Enter" && element.dataset.editMultiline !== "true") {
          event.preventDefault();
          element.blur();
        }
      });

      element.addEventListener("blur", async () => {
        const next = parseScalarEdit(element, property);
        if (next === Symbol.for("invalid")) {
          renderEditableProperty(property);
          setEditState(`${property.replaceAll("_", " ")} must be a non-negative number`, "error");
          return;
        }
        const previous = recipeState[property];
        if (next === previous) {
          renderEditableProperty(property);
          return;
        }

        recipeState[property] = next;
        renderIdentity();
        setEditState(`Saving ${property.replaceAll("_", " ")}…`);
        try {
          await updateFrontmatter({ [property]: next });
          setEditState(`${property.replaceAll("_", " ")} saved`, "success");
        } catch (error) {
          recipeState[property] = previous;
          renderIdentity();
          setEditState(`${property.replaceAll("_", " ")} was not saved`, "error");
          console.error(`[custom-view:recipe] Could not save ${property}`, error);
        }
      });
    }
  }

  function initTitleEditor() {
    const title = recipeQuery('[data-edit-file-name="true"]');
    if (!title || !recipeFile || !recipeApp?.fileManager) return;

    title.addEventListener("keydown", event => {
      if (event.key === "Escape") {
        event.preventDefault();
        title.textContent = recipeTitle;
        title.blur();
        return;
      }
      if (event.key === "Enter") {
        event.preventDefault();
        title.blur();
      }
    });

    title.addEventListener("blur", async () => {
      const proposed = text(title.textContent)
        .replace(/\.md$/i, "")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, " ")
        .trim();
      if (!proposed) {
        title.textContent = recipeTitle;
        setEditState("Recipe title cannot be empty", "error");
        return;
      }
      if (proposed === recipeTitle) return;

      const previous = recipeTitle;
      const parentPath = recipeFile.parent?.path || "";
      const nextPath = `${parentPath ? `${parentPath}/` : ""}${proposed}.md`;
      const existing = recipeApp.vault.getAbstractFileByPath?.(nextPath);
      if (existing && existing !== recipeFile) {
        title.textContent = recipeTitle;
        setEditState("A note with that title already exists", "error");
        return;
      }

      recipeTitle = proposed;
      renderIdentity();
      renderCover();
      setEditState("Renaming recipe…");
      try {
        await recipeApp.fileManager.renameFile(recipeFile, nextPath);
        setEditState("Recipe title saved", "success");
      } catch (error) {
        recipeTitle = previous;
        renderIdentity();
        renderCover();
        setEditState("Recipe title was not saved", "error");
        console.error("[custom-view:recipe] Could not rename recipe", error);
      }
    });
  }

  function instructionProgressFromDone(done, count) {
    let furthest = 0;
    for (let index = 0; index < count; index += 1) {
      if (done[index] === true) furthest = index + 1;
    }
    return furthest;
  }

  function instructionDoneFromProgress(progress, count) {
    const bounded = Math.max(0, Math.min(count, Number(progress) || 0));
    return Array.from({ length: count }, (_, index) => index < bounded);
  }

  function reconcileInstructionDone(previousInstructions, nextInstructions, previousDone) {
    const used = new Set();
    const mapped = nextInstructions.map((value, nextIndex) => {
      let sourceIndex = previousInstructions.findIndex((candidate, index) =>
        !used.has(index) && candidate === value
      );
      if (sourceIndex < 0 && nextIndex < previousInstructions.length && !used.has(nextIndex)) {
        sourceIndex = nextIndex;
      }
      if (sourceIndex < 0) return false;
      used.add(sourceIndex);
      return previousDone[sourceIndex] === true;
    });
    return instructionDoneFromProgress(
      instructionProgressFromDone(mapped, nextInstructions.length),
      nextInstructions.length
    );
  }

  async function saveArray(property, next, render) {
    const previous = [...recipeState[property]];
    if (JSON.stringify(previous) === JSON.stringify(next)) return;
    const previousInstructionDone = property === "instructions"
      ? [...recipeState.instruction_done]
      : null;
    const nextInstructionDone = property === "instructions"
      ? reconcileInstructionDone(previous, next, previousInstructionDone)
      : null;

    recipeState[property] = next;
    if (nextInstructionDone) recipeState.instruction_done = nextInstructionDone;
    render();
    setEditState(`Saving ${property.replaceAll("_", " ")}…`);
    try {
      const patch = property === "instructions"
        ? { [property]: next, instruction_done: nextInstructionDone }
        : { [property]: next };
      await updateFrontmatter(patch);
      setEditState(`${property.replaceAll("_", " ")} saved`, "success");
    } catch (error) {
      recipeState[property] = previous;
      if (previousInstructionDone) recipeState.instruction_done = previousInstructionDone;
      render();
      setEditState(`${property.replaceAll("_", " ")} was not saved`, "error");
      console.error(`[custom-view:recipe] Could not save ${property}`, error);
    }
  }

  function makeAddButton(label, onClick) {
    const row = makeElement("li", "cv-recipe-list-add");
    const button = makeElement("button", "", `+ ${label}`);
    button.type = "button";
    button.addEventListener("click", onClick);
    row.appendChild(button);
    return row;
  }

  function renderIngredients() {
    const list = recipeQuery('[data-role="ingredients"]');
    if (!list) return;
    list.replaceChildren();

    recipeState.ingredients.forEach((rawIngredient, index) => {
      const display = cleanWiki(rawIngredient);
      const dividerIndex = display.indexOf("|");
      const namePart = (dividerIndex >= 0 ? display.slice(0, dividerIndex) : display).trim();
      const amountPart = dividerIndex >= 0 ? display.slice(dividerIndex + 1).trim() : "";
      const hasAmount = Boolean(amountPart);
      const row = makeElement("li", `cv-ingredient-row${hasAmount ? " has-amount" : ""}`);
      const name = makeElement("span", "cv-ingredient-name cv-recipe-inline-edit", namePart);
      const amount = hasAmount
        ? makeElement("span", "cv-ingredient-amount cv-recipe-inline-edit", amountPart)
        : null;
      const editors = [name, amount].filter(Boolean);

      name.setAttribute(
        "aria-label",
        hasAmount
          ? `Ingredient ${index + 1}`
          : `Ingredient ${index + 1}. Add an amount after a vertical bar if needed.`
      );
      if (amount) amount.setAttribute("aria-label", `Amount for ingredient ${index + 1}`);

      for (const element of editors) {
        element.contentEditable = "plaintext-only";
        element.setAttribute("role", "textbox");
        element.spellcheck = true;
        element.addEventListener("keydown", event => {
          if (event.key === "Enter") {
            event.preventDefault();
            element.blur();
          } else if (event.key === "Escape") {
            event.preventDefault();
            renderIngredients();
          }
        });
      }
      name.dataset.placeholder = "Ingredient";

      const commit = async () => {
        let nextName = text(name.textContent);
        let nextAmount = amount ? text(amount.textContent) : "";
        if (!amount) {
          const inlineDivider = nextName.indexOf("|");
          if (inlineDivider >= 0) {
            nextAmount = nextName.slice(inlineDivider + 1).trim();
            nextName = nextName.slice(0, inlineDivider).trim();
          }
        }
        const originalDisplay = [namePart, amountPart].filter(Boolean).join(" | ");
        const nextDisplay = [nextName, nextAmount].filter(Boolean).join(" | ");
        if (nextDisplay === originalDisplay) return;
        const next = [...recipeState.ingredients];
        if (!nextName) next.splice(index, 1);
        else next[index] = nextDisplay;
        await saveArray("ingredients", next, renderIngredients);
      };
      name.addEventListener("blur", () => void commit());
      amount?.addEventListener("blur", () => void commit());

      row.append(...editors);
      list.appendChild(row);
    });

    list.appendChild(makeAddButton("Add ingredient", () => {
      const addRow = list.lastElementChild;
      const row = makeElement("li", "cv-ingredient-row cv-recipe-draft-row");
      const name = makeElement("span", "cv-ingredient-name cv-recipe-inline-edit");
      name.contentEditable = "plaintext-only";
      name.setAttribute("role", "textbox");
      name.setAttribute("aria-label", "New ingredient. Add an amount after a vertical bar if needed.");
      name.spellcheck = true;
      name.dataset.placeholder = "Ingredient | amount (optional)";
      row.append(name);
      list.insertBefore(row, addRow);

      let committed = false;
      const commitDraft = async () => {
        if (committed) return;
        if (row.contains(recipeDocument.activeElement)) return;
        const rawValue = text(name.textContent);
        const inlineDivider = rawValue.indexOf("|");
        const nextName = (inlineDivider >= 0 ? rawValue.slice(0, inlineDivider) : rawValue).trim();
        const nextAmount = inlineDivider >= 0 ? rawValue.slice(inlineDivider + 1).trim() : "";
        if (!nextName) {
          row.remove();
          return;
        }
        committed = true;
        const next = [...recipeState.ingredients, [nextName, nextAmount].filter(Boolean).join(" | ")];
        await saveArray("ingredients", next, renderIngredients);
      };
      name.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          name.blur();
        } else if (event.key === "Escape") {
          event.preventDefault();
          committed = true;
          row.remove();
        }
      });
      name.addEventListener("blur", () => setTimeout(() => void commitDraft(), 0));
      name.focus();
    }));
  }

  function renderEditableTextList(role, property, addLabel) {
    const list = recipeQuery(`[data-role="${role}"]`);
    if (!list) return;
    list.replaceChildren();

    recipeState[property].forEach((rawValue, index) => {
      const display = cleanWiki(rawValue);
      const item = makeElement("li", "cv-recipe-list-item cv-recipe-inline-edit", display);
      item.contentEditable = "plaintext-only";
      item.setAttribute("role", "textbox");
      item.spellcheck = true;
      item.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          item.blur();
        } else if (event.key === "Escape") {
          event.preventDefault();
          renderEditableTextList(role, property, addLabel);
        }
      });
      item.addEventListener("blur", () => {
        const nextText = text(item.textContent);
        if (nextText === display) return;
        const next = [...recipeState[property]];
        if (!nextText) next.splice(index, 1);
        else next[index] = nextText;
        void saveArray(property, next, () => renderEditableTextList(role, property, addLabel));
      });
      list.appendChild(item);
    });

    list.appendChild(makeAddButton(addLabel, () => {
      const addRow = list.lastElementChild;
      const draft = makeElement("li", "cv-recipe-list-item cv-recipe-inline-edit cv-recipe-draft-row");
      draft.contentEditable = "plaintext-only";
      draft.setAttribute("role", "textbox");
      draft.dataset.placeholder = addLabel;
      list.insertBefore(draft, addRow);
      draft.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          draft.blur();
        } else if (event.key === "Escape") {
          event.preventDefault();
          draft.remove();
        }
      });
      draft.addEventListener("blur", () => {
        const nextText = text(draft.textContent);
        if (!nextText) {
          draft.remove();
          return;
        }
        void saveArray(property, [...recipeState[property], nextText], () => renderEditableTextList(role, property, addLabel));
      }, { once: true });
      draft.focus();
    }));
  }

  function renderInstructions() {
    const list = recipeQuery('[data-role="instructions"]');
    if (!list) return;
    list.replaceChildren();

    recipeState.instructions.forEach((rawValue, index) => {
      const display = cleanWiki(rawValue);
      const item = makeElement("li", "cv-recipe-list-item");
      const copy = makeElement("span", "cv-recipe-step-copy cv-recipe-inline-edit", display);
      copy.id = `cvr-instruction-copy-${recipeViewToken}-${index}`;
      copy.contentEditable = "plaintext-only";
      copy.setAttribute("role", "textbox");
      copy.setAttribute("aria-label", `Instruction step ${index + 1}`);
      copy.spellcheck = true;
      copy.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          copy.blur();
        } else if (event.key === "Escape") {
          event.preventDefault();
          renderInstructions();
        }
      });
      copy.addEventListener("blur", () => {
        const nextText = text(copy.textContent);
        if (nextText === display) return;
        const next = [...recipeState.instructions];
        if (!nextText) next.splice(index, 1);
        else next[index] = nextText;
        void saveArray("instructions", next, renderInstructions);
      });
      item.appendChild(copy);
      list.appendChild(item);
    });

    list.appendChild(makeAddButton("Add step", () => {
      const addRow = list.lastElementChild;
      const item = makeElement("li", "cv-recipe-list-item cv-recipe-draft-row");
      const copy = makeElement("span", "cv-recipe-step-copy cv-recipe-inline-edit");
      copy.contentEditable = "plaintext-only";
      copy.setAttribute("role", "textbox");
      copy.setAttribute("aria-label", "New instruction step");
      copy.dataset.placeholder = "Add step";
      copy.spellcheck = true;
      item.appendChild(copy);
      list.insertBefore(item, addRow);
      copy.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          copy.blur();
        } else if (event.key === "Escape") {
          event.preventDefault();
          item.remove();
        }
      });
      copy.addEventListener("blur", () => {
        const nextText = text(copy.textContent);
        if (!nextText) {
          item.remove();
          return;
        }
        void saveArray(
          "instructions",
          [...recipeState.instructions, nextText],
          renderInstructions
        );
      }, { once: true });
      copy.focus();
    }));
  }

  function renderLists() {
    renderIngredients();
    renderInstructions();
    renderEditableTextList("tips", "tips", "Add tip");
    renderEditableTextList("pairings", "pairs_well_with", "Add pairing");
  }

  function instructionSteps() {
    const list = recipeQuery('[data-role="instructions"]');
    if (!list) return [];
    return Array.from(list.children).filter(item =>
      item.classList.contains("cv-recipe-list-item") &&
      !item.classList.contains("cv-recipe-draft-row")
    );
  }

  let instructionCurrentProgress = instructionProgressFromDone(
    recipeState.instruction_done,
    recipeState.instructions.length
  );
  let instructionPersistedProgress = instructionCurrentProgress;
  let instructionSaveRevision = 0;

  function normalizeInstructionDone(count) {
    const progress = instructionProgressFromDone(recipeState.instruction_done, count);
    recipeState.instruction_done = instructionDoneFromProgress(progress, count);
    return progress;
  }

  function paintInstructionChecklist(progress = instructionCurrentProgress) {
    const steps = instructionSteps();
    instructionCurrentProgress = Math.max(0, Math.min(steps.length, progress));
    recipeState.instruction_done = instructionDoneFromProgress(instructionCurrentProgress, steps.length);

    steps.forEach((item, index) => {
      const checked = index < instructionCurrentProgress;
      const input = item.querySelector(':scope > .cv-recipe-step-input');
      const copy = item.querySelector(':scope > .cv-recipe-step-copy');
      item.classList.toggle("is-checked", checked);
      item.dataset.stepState = checked ? "complete" : "pending";

      if (input) {
        input.checked = checked;
        input.dataset.stepIndex = String(index);
        input.setAttribute("aria-label", checked
          ? `Clear progress from instruction step ${index + 1}`
          : `Complete through instruction step ${index + 1}`);
        if (copy?.id) input.setAttribute("aria-describedby", copy.id);
      }
    });

    const summary = recipeQuery('[data-role="instruction-progress"]');
    if (summary) {
      summary.textContent = steps.length
        ? `${instructionCurrentProgress} of ${steps.length} complete`
        : "No steps yet";
    }
  }

  async function requestInstructionProgress(targetProgress) {
    const count = instructionSteps().length;
    const nextProgress = Math.max(0, Math.min(count, targetProgress));
    if (nextProgress === instructionCurrentProgress) return;

    const revision = ++instructionSaveRevision;
    instructionCurrentProgress = nextProgress;
    const snapshot = instructionDoneFromProgress(nextProgress, count);
    recipeState.instruction_done = snapshot;
    paintInstructionChecklist(nextProgress);
    setEditState(nextProgress > 0
      ? `Saving progress through step ${nextProgress}…`
      : "Clearing instruction progress…");

    try {
      await updateFrontmatter({ instruction_done: snapshot });
      instructionPersistedProgress = nextProgress;
      if (revision === instructionSaveRevision) {
        setEditState(
          nextProgress > 0 ? `Progress saved through step ${nextProgress}` : "Instruction progress cleared",
          "success"
        );
      }
    } catch (error) {
      if (revision === instructionSaveRevision) {
        instructionCurrentProgress = instructionPersistedProgress;
        recipeState.instruction_done = instructionDoneFromProgress(
          instructionPersistedProgress,
          instructionSteps().length
        );
        paintInstructionChecklist(instructionPersistedProgress);
        setEditState("Instruction progress was not saved", "error");
      }
      console.error("[custom-view:recipe] Could not save instruction progress", error);
    }
  }

  let decoratingInstructionSteps = false;

  function createInstructionCheckbox(item, index) {
    const copy = item.querySelector(':scope > .cv-recipe-step-copy');
    const input = makeElement("input", "cv-recipe-step-input");
    const box = makeElement("label", "cv-recipe-step-box");
    const check = makeElement("span", "cv-recipe-step-check");
    const inputId = `cvr-instruction-${recipeViewToken}-${index}`;
    input.type = "checkbox";
    input.id = inputId;
    input.name = `recipe-instructions-${recipeViewToken}`;
    input.dataset.stepIndex = String(index);
    input.contentEditable = "false";
    if (copy?.id) input.setAttribute("aria-describedby", copy.id);
    input.addEventListener("click", event => event.stopPropagation());
    input.addEventListener("change", () => {
      const stepIndex = Number(input.dataset.stepIndex);
      if (!Number.isInteger(stepIndex) || stepIndex < 0) return;
      void requestInstructionProgress(input.checked ? stepIndex + 1 : stepIndex);
    });

    box.htmlFor = inputId;
    box.appendChild(check);
    item.prepend(box);
    item.prepend(input);
  }

  function decorateInstructionSteps() {
    if (decoratingInstructionSteps) return;
    decoratingInstructionSteps = true;
    try {
      const steps = instructionSteps();
      const normalizedProgress = normalizeInstructionDone(steps.length);
      instructionCurrentProgress = normalizedProgress;

      steps.forEach((item, index) => {
        item.classList.add("cv-recipe-step");

        const input = item.querySelector(':scope > .cv-recipe-step-input');
        if (!input) createInstructionCheckbox(item, index);
      });
      paintInstructionChecklist(normalizedProgress);
    } finally {
      decoratingInstructionSteps = false;
    }
  }

  function initInstructionChecklist() {
    const list = recipeQuery('[data-role="instructions"]');
    if (!list) return;
    list.setAttribute("aria-label", "Recipe instruction checklist");
    const rawDone = [...recipeState.instruction_done];
    decorateInstructionSteps();
    const normalized = instructionDoneFromProgress(
      instructionCurrentProgress,
      instructionSteps().length
    );
    instructionPersistedProgress = instructionCurrentProgress;
    if (JSON.stringify(rawDone) !== JSON.stringify(normalized)) {
      void updateFrontmatter({ instruction_done: normalized }).catch(error =>
        console.error("[custom-view:recipe] Could not normalize legacy instruction progress", error)
      );
    }
    const Observer = recipeDocument.defaultView?.MutationObserver || globalThis.MutationObserver;
    if (!Observer) return;
    const observer = new Observer(() => decorateInstructionSteps());
    observer.observe(list, { childList: true });
  }

  function initCompactAddActions() {
    const actions = [
      {
        header: ".cv-ingredients-card .cv-recipe-card-head",
        list: '[data-role="ingredients"]',
        label: "+ Ingredient",
        aria: "Add ingredient",
      },
      {
        header: ".cv-instructions-section .cv-recipe-section-title",
        list: '[data-role="instructions"]',
        label: "+ Step",
        aria: "Add instruction step",
      },
      {
        header: '.cv-recipe-small-card:has([data-role="tips"]) .cv-recipe-card-head',
        list: '[data-role="tips"]',
        label: "+ Tip",
        aria: "Add recipe tip",
      },
      {
        header: '.cv-recipe-small-card:has([data-role="pairings"]) .cv-recipe-card-head',
        list: '[data-role="pairings"]',
        label: "+ Pairing",
        aria: "Add recipe pairing",
      },
    ];

    for (const config of actions) {
      const header = recipeQuery(config.header);
      if (!header || header.querySelector(':scope > .cv-recipe-compact-add')) continue;
      const button = makeElement("button", "cv-recipe-compact-add", config.label);
      button.type = "button";
      button.setAttribute("aria-label", config.aria);
      button.addEventListener("click", () => {
        const list = recipeQuery(config.list);
        const legacyButton = list?.querySelector(':scope > .cv-recipe-list-add button');
        legacyButton?.click();
      });
      header.appendChild(button);
    }
  }

  function initToggle(action, property) {
    const button = recipeQuery(`[data-action="${action}"]`);
    const state = recipeQuery('[data-role="recipe-action-state"]');
    if (!button) return;
    let active = recipeFrontmatter[property] === true;

    function paint(value) {
      button.classList.toggle("is-active", value);
      button.setAttribute("aria-pressed", String(value));
    }

    paint(active);
    button.addEventListener("click", async () => {
      if (button.disabled) return;
      const previous = active;
      active = !active;
      paint(active);
      button.disabled = true;
      if (state) state.textContent = "";
      try {
        await updateFrontmatter({ [property]: active });
      } catch (error) {
        active = previous;
        paint(previous);
        if (state) state.textContent = `${property} was not saved`;
        console.error(`[custom-view:recipe] Could not save ${property}`, error);
      } finally {
        button.disabled = false;
      }
    });
  }

  function initPaperTapeSides() {
    const seed = String(recipeFile?.path || recipeFile?.basename || "recipe-note");
    const papers = Array.from(recipeRoot.querySelectorAll(".cv-recipe-notes-grid > .cv-recipe-small-card"));
    papers.forEach((paper, index) => {
      let hash = index + 17;
      for (const character of `${seed}:${index}`) hash = ((hash * 31) + character.charCodeAt(0)) | 0;
      paper.dataset.tapeSide = Math.abs(hash) % 2 ? "right" : "left";
    });
  }

  function initRecipeNavigation() {
    const nav = recipeQuery(".cv-recipe-nav");
    if (!nav || !recipeWindow) return;
    const anchors = Array.from(nav.querySelectorAll("a[data-recipe-view]"));
    const sections = new Map(
      recipeQueryAll("[data-recipe-section]")
        .map(section => [section.dataset.recipeSection, section])
    );
    const validKeys = anchors
      .map(anchor => anchor.dataset.recipeView)
      .filter(key => sections.has(key));
    if (!validKeys.length) return;

    if (!recipeWindow.__lakeRecipeCustomViewSection) {
      recipeWindow.__lakeRecipeCustomViewSection = new Map();
    }
    const stateKey = recipeFile?.path || `recipe:${recipeFile?.basename || "current"}`;

    function showSection(requestedKey, options = {}) {
      const key = sections.has(requestedKey) ? requestedKey : "overview";
      for (const [sectionKey, section] of sections) {
        const active = sectionKey === key;
        section.hidden = !active;
        section.setAttribute("aria-hidden", String(!active));
      }
      for (const anchor of anchors) {
        const active = anchor.dataset.recipeView === key;
        anchor.setAttribute("aria-selected", String(active));
        anchor.tabIndex = active ? 0 : -1;
      }
      recipeWindow.__lakeRecipeCustomViewSection.set(stateKey, key);
      if (options.scroll) {
        recipeWindow.requestAnimationFrame(() => {
          sections.get(key)?.scrollIntoView({ behavior: "smooth", block: "start" });
        });
      }
      return key;
    }

    showSection(recipeWindow.__lakeRecipeCustomViewSection.get(stateKey) || "overview");

    for (const anchor of anchors) {
      anchor.addEventListener("click", event => {
        event.preventDefault();
        showSection(anchor.dataset.recipeView, { scroll: true });
      });
      anchor.addEventListener("keydown", event => {
        if (!["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"].includes(event.key)) return;
        event.preventDefault();
        const currentIndex = Math.max(0, validKeys.indexOf(anchor.dataset.recipeView));
        let nextIndex = currentIndex;
        if (["ArrowDown", "ArrowRight"].includes(event.key)) nextIndex = (currentIndex + 1) % validKeys.length;
        if (["ArrowUp", "ArrowLeft"].includes(event.key)) nextIndex = (currentIndex - 1 + validKeys.length) % validKeys.length;
        if (event.key === "Home") nextIndex = 0;
        if (event.key === "End") nextIndex = validKeys.length - 1;
        const nextKey = validKeys[nextIndex];
        showSection(nextKey, { scroll: true });
        anchors.find(item => item.dataset.recipeView === nextKey)?.focus();
      });
    }
  }

  function initNoteEditor() {
    const render = recipeQuery('[data-role="recipe-note-render"]');
    const state = recipeQuery('[data-role="recipe-note-state"]');
    if (!render || !state) return;

    const nativePlaceholder = render.querySelector("[data-cv-editable-placeholder]");
    if (nativePlaceholder) {
      recipeRoot.classList.add("is-native-editor");
      state.textContent = "Autosaved by Obsidian";
      return;
    }

    render.classList.toggle("is-empty", !recipeBodyContent.trim());
    render.setAttribute("tabindex", "0");
    render.setAttribute("role", "textbox");
    render.setAttribute("aria-label", "Recipe notes. Click to edit.");
    state.textContent = "Click notes to edit";

    let openingEditor = false;
    const openInlineEditor = async () => {
      if (openingEditor) return;
      const leaves = typeof recipeApp?.workspace?.getLeavesOfType === "function"
        ? recipeApp.workspace.getLeavesOfType("markdown")
        : [];
      const leaf = leaves.find(candidate =>
        candidate?.view?.file?.path === recipeFile?.path &&
        candidate.view.contentEl?.contains(recipeContainer)
      );
      if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
        state.textContent = "Open this note in Live Preview to edit here";
        return;
      }
      state.textContent = "Opening inline editor…";
      openingEditor = true;
      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode: "source",
            source: false,
          },
        });
      } catch (error) {
        state.textContent = "Could not open inline editor";
        openingEditor = false;
        console.error("[custom-view:recipe] Could not enter Live Preview", error);
      }
    };

    render.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void openInlineEditor();
    });
    render.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void openInlineEditor();
    });
  }

  renderCover();
  renderIdentity();
  renderLists();
  initInstructionChecklist();
  initCompactAddActions();
  initScalarEditors();
  initTitleEditor();
  initToggle("toggle-favorite", "favorite");
  initToggle("toggle-bookmark", "bookmarked");
  initNoteEditor();
  initPaperTapeSides();
  initRecipeNavigation();
}

views.css:
/* Exercise detail view. */

.obsidian-custom-view-render:has(> .cv-exercise) {
  padding: 0 !important;
  background: var(--background-primary) !important;
}

.cv-exercise {
  --cve-bg: var(--background-primary);
  --cve-surface: var(--background-primary);
  --cve-surface-2: var(--background-secondary);
  --cve-surface-3: var(--background-secondary-alt);
  --cve-hover: var(--background-modifier-hover);
  --cve-accent: var(--interactive-accent);
  --cve-accent-hover: var(--interactive-accent-hover);
  --cve-accent-soft: var(--text-accent);
  --cve-on-accent: var(--text-on-accent, var(--background-primary));
  --cve-muscle-primary: var(--interactive-accent);
  --cve-muscle-secondary: var(--text-warning);
  --cve-text: var(--text-normal);
  --cve-muted: var(--text-muted);
  --cve-faint: var(--text-faint);
  --cve-border: var(--background-modifier-border);
  --cve-border-strong: var(--background-modifier-border-hover);
  --cve-focus: var(--background-modifier-border-focus);
  --cve-shadow: color-mix(in oklch, var(--shadow) 24%, transparent);
  --cve-beginner: var(--text-accent);
  --cve-intermediate: var(--text-warning);
  --cve-advanced: var(--text-error);
  --cve-level: var(--cve-beginner);
  --cve-paper-line: var(--vault-note-paper-line, 30px);
  --cve-paper: var(--vault-note-paper,
    color-mix(in oklch, var(--background-primary) 64%,
      var(--background-secondary) 36%));
  --cve-paper-rule: var(--vault-note-paper-rule,
    color-mix(in oklch, var(--background-modifier-border) 72%, transparent));
  --cve-paper-margin: var(--vault-note-paper-margin-rule,
    color-mix(in oklch, var(--interactive-accent) 30%, transparent));
  --cve-tape: var(--vault-note-paper-tape,
    color-mix(in oklch, var(--interactive-accent-hover) 18%,
      var(--background-secondary) 82%));
  --cve-tape-edge: var(--vault-note-paper-tape-edge,
    color-mix(in oklch, var(--text-normal) 14%,
      var(--background-secondary-alt) 86%));
  --cve-liquid: var(--interactive-accent);
  --cve-liquid-soft: var(--interactive-accent-hover);
  --cve-progress-filter: none;
  --cve-checkbox-size: 30px;
  --cve-pad: clamp(18px, 4cqi, 54px);
  --cve-gap: clamp(16px, 2.3cqi, 30px);
  --cve-radius: clamp(11px, 1.35cqi, 16px);
  --cve-ease: cubic-bezier(.22, .61, .36, 1);

  position: relative;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  container-type: inline-size;
  background: var(--cve-bg);
  color: var(--cve-text);
  font-family: var(--font-interface);
}

.cv-exercise[data-level="intermediate"] {
  --cve-level: var(--cve-intermediate);
}

.cv-exercise[data-level="expert"],
.cv-exercise[data-level="advanced"] {
  --cve-level: var(--cve-advanced);
}

.cv-exercise *,
.cv-exercise *::before,
.cv-exercise *::after {
  box-sizing: border-box;
}

.cv-exercise button {
  font: inherit;
}

.cv-exercise button:focus-visible {
  outline: 2px solid var(--cve-accent);
  outline-offset: 3px;
}

.cv-exercise-hero {
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: clamp(24px, 4.5cqi, 64px) var(--cve-pad);
  display: grid;
  grid-template-columns: minmax(330px, 1.18fr) minmax(300px, .82fr);
  align-items: center;
  gap: clamp(28px, 4.6cqi, 70px);
  border-bottom: 1px solid var(--cve-border);
  background: var(--cve-bg);
}

.cv-exercise-media {
  position: relative;
  width: 100%;
  margin: 0;
  aspect-ratio: 3 / 2;
  overflow: hidden;
  border: 1px solid var(--cve-border-strong);
  border-radius: var(--cve-radius);
  background: var(--cve-surface-3);
  box-shadow: 0 16px 38px var(--cve-shadow);
  isolation: isolate;
}

.cv-exercise-preview,
.cv-exercise-animation {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  background: var(--cve-surface-3);
}

.cv-exercise-preview {
  z-index: 0;
}

.cv-exercise-animation {
  z-index: 1;
  visibility: hidden;
  opacity: 0;
  transition: opacity .18s var(--cve-ease), visibility 0s linear .18s;
}

.cv-exercise-media.is-playing .cv-exercise-animation {
  visibility: visible;
  opacity: 1;
  transition-delay: 0s;
}

.cv-exercise-preview:not([src]),
.cv-exercise-preview[src=""],
.cv-exercise-animation:not([src]),
.cv-exercise-animation[src=""] {
  opacity: 0;
}

.cv-exercise-media-shade {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(to bottom, color-mix(in srgb, var(--shadow) 54%,
    transparent), transparent 32%),
    linear-gradient(to top, color-mix(in srgb, var(--shadow) 72%, transparent),
    transparent 34%);
}

.cv-exercise-media-top {
  position: absolute;
  inset: clamp(11px, 2cqi, 18px) clamp(12px, 2.2cqi, 20px) auto;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.cv-exercise-level,
.cv-exercise-play {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  border: 1px solid color-mix(in srgb, currentColor 62%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--shadow) 82%, transparent);
  font-family: var(--font-monospace);
  font-size: clamp(.64rem, 1.15cqi, .76rem);
  font-weight: 760;
  line-height: 1;
  letter-spacing: .04em;
}

.cv-exercise-level {
  gap: 7px;
  padding: 6px 11px;
  color: var(--cve-level);
}

.cv-exercise-level > span:first-child {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: currentColor;
}

.cv-exercise-play {
  gap: 8px;
  padding: 5px 11px 5px 8px;
  color: var(--cve-accent-soft);
  cursor: pointer;
  transition: background-color .16s var(--cve-ease), border-color .16s
    var(--cve-ease), color .16s var(--cve-ease);
}

.cv-exercise-play:hover,
.cv-exercise-play[aria-pressed="true"] {
  border-color: var(--cve-accent);
  background: color-mix(in srgb, var(--cve-accent) 20%, var(--shadow));
  color: var(--cve-text);
}

.cv-exercise-play-icon {
  position: relative;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, currentColor 56%, transparent);
  border-radius: 50%;
}

.cv-exercise-play-icon::before {
  content: "";
  width: 0;
  height: 0;
  margin-inline-start: 2px;
  border-block: 4px solid transparent;
  border-inline-start: 7px solid currentColor;
}

.cv-exercise-play[aria-pressed="true"] .cv-exercise-play-icon::before {
  width: 7px;
  height: 8px;
  margin: 0;
  border: 0;
  background: linear-gradient(90deg, currentColor 0 38%, transparent 38% 62%,
    currentColor 62% 100%);
}

.cv-exercise-media-caption {
  position: absolute;
  z-index: 3;
  inset: auto clamp(12px, 2.2cqi, 20px) clamp(11px, 1.8cqi, 16px);
  color: color-mix(in srgb, var(--cve-text) 82%, transparent);
  font-family: var(--font-monospace);
  font-size: .65rem;
  line-height: 1.3;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.cv-exercise-summary {
  min-width: 0;
}

.cv-exercise-eyebrow,
.cv-exercise-kicker,
.cv-exercise-target-label {
  display: block;
  color: var(--cve-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(.66rem, 1.1cqi, .78rem);
  font-weight: 760;
  line-height: 1.25;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.cv-exercise-summary h1 {
  max-width: 17ch;
  margin: clamp(9px, 1.3cqi, 15px) 0 0;
  color: var(--cve-text);
  font-size: clamp(2.25rem, 5.2cqi, 4.9rem);
  font-weight: 820;
  line-height: .98;
  letter-spacing: -.045em;
  text-wrap: balance;
}

.cv-exercise-subtitle {
  max-width: 58ch;
  margin: clamp(14px, 2cqi, 24px) 0 0;
  color: color-mix(in srgb, var(--cve-text) 72%, var(--cve-muted) 28%);
  font-size: clamp(.82rem, 1.3cqi, .98rem);
  line-height: 1.65;
}

.cv-exercise-facts {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: clamp(15px, 2cqi, 24px);
}

.cv-exercise-facts > span {
  padding: 5px 10px;
  border: 1px solid var(--cve-border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--cve-surface-3) 84%, transparent);
  color: var(--cve-muted);
  font-family: var(--font-monospace);
  font-size: .68rem;
  line-height: 1.25;
  text-transform: capitalize;
}

.cv-exercise-target-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: clamp(18px, 2.6cqi, 30px);
}

.cv-exercise-target-card {
  min-width: 0;
  min-height: 78px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 10px;
  border: 1px solid var(--cve-border);
  border-radius: 11px;
  background: color-mix(in srgb, var(--cve-surface-2) 90%, transparent);
  text-align: center;
}

.cv-exercise-target-card strong {
  display: block;
  margin-top: 7px;
  overflow: hidden;
  color: var(--cve-text);
  font-size: clamp(.76rem, 1.2cqi, .9rem);
  font-weight: 700;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-exercise-equipment-card {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 13px;
}

.cv-exercise-equipment-card > span:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.cv-exercise-equipment-icon {
  width: 38px;
  height: 38px;
  display: block;
  flex: 0 0 auto;
  background: var(--cve-accent);
  -webkit-mask: var(--cve-equipment-mask,
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M6 12h4v8H6zm16 0h4v8h-4zM10 14h12v4H10z'/></svg>"))
    center / contain no-repeat;
  mask: var(--cve-equipment-mask,
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M6 12h4v8H6zm16 0h4v8h-4zM10 14h12v4H10z'/></svg>"))
    center / contain no-repeat;
}

.cv-exercise-equipment-icon:is([data-equipment="body only"], [data-equipment="none"]) {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><circle cx='16' cy='5' r='3'/><path d='M12 10h8l5 6-3 2-3-4v6l4 9h-4l-3-6-3 6H9l4-9v-6l-3 4-3-2z'/></svg>");
}

.cv-exercise-equipment-icon[data-equipment="barbell"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M2 14h4v-3h3v10H6v-3H2zm28 0h-4v-3h-3v10h3v-3h4zM9 15h14v2H9z'/></svg>");
}

.cv-exercise-equipment-icon[data-equipment="dumbbell"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M4 12h3V9h4v5h10V9h4v3h3v8h-3v3h-4v-5H11v5H7v-3H4z'/></svg>");
