.cv-exercise-equipment-icon[data-equipment="cable"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M6 3h20v4H9v20H5V3z'/><circle cx='22' cy='9' r='4'/><path d='M21 13h2v9h-2zm-4 9h10v3H17z'/></svg>");
