}

.cv-exercise-equipment-icon[data-equipment="kettlebells"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M11 11V8a5 5 0 0 1 10 0v3h3l4 17H4l4-17h3zm3 0h4V8a2 2 0 0 0-4 0v3z'/></svg>");
