.cv-exercise-equipment-icon[data-equipment="bands"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path fill-rule='evenodd' d='M16 3c8 0 13 5 13 13s-5 13-13 13S3 24 3 16 8 3 16 3Zm0 5c-5 0-8 3-8 8s3 8 8 8 8-3 8-8-3-8-8-8Z'/><path d='m7 7 4-3 14 21-4 3z'/></svg>");
}

.cv-exercise-equipment-icon[data-equipment="medicine ball"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><circle cx='16' cy='16' r='13'/><path d='M4 14h24v4H4zm10-10h4v24h-4z'/></svg>");
}

.cv-exercise-equipment-icon[data-equipment="exercise ball"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><circle cx='16' cy='16' r='14'/><path d='M4 10h24v2H4zm-2 5h28v2H2zm2 5h24v2H4z'/></svg>");
