.cv-exercise-equipment-icon[data-equipment="other"] {
  --cve-equipment-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><path d='M10 5h12l2 5h4v17H4V10h4zm3 5h6l-1-2h-4zM8 14v9h16v-9z'/><path d='M14 15h4v7h-4z'/></svg>");
}

.cv-exercise-progress-defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

.cv-exercise-content {
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: clamp(28px, 4.5cqi, 64px) var(--cve-pad) clamp(44px, 6cqi, 84px);
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(290px, .72fr);
  align-items: stretch;
  gap: var(--cve-gap);
}

.cv-exercise-panel {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--cve-border);
  border-radius: var(--cve-radius);
  background: color-mix(in oklch, var(--cve-surface-2) 94%,
    var(--cve-surface-3) 6%);
}

.cv-exercise-panel-head {
  min-height: 70px;
  padding: clamp(14px, 2cqi, 22px) clamp(16px, 2.4cqi, 26px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border-bottom: 1px solid var(--cve-border);
  background: color-mix(in oklch, var(--cve-surface-3) 64%,
    var(--cve-surface-2) 36%);
}

.cv-exercise-panel-head--compact {
  min-height: 62px;
  align-items: flex-end;
}

.cv-exercise-panel-head h2 {
  margin: 5px 0 0;
  color: var(--cve-text);
  font-size: clamp(1.15rem, 2cqi, 1.55rem);
  font-weight: 760;
  line-height: 1.12;
  letter-spacing: -.025em;
}

.cv-exercise-edit-state {
  color: var(--cve-faint);
  font-family: var(--font-monospace);
  font-size: .67rem;
  line-height: 1.35;
  text-align: right;
}

.cv-exercise-instructions {
  position: relative;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-self: stretch;
  overflow: visible;
  isolation: isolate;
  border-radius: 8px;
  background: var(--vault-note-paper-background,
    linear-gradient(90deg,
      transparent 0 44px,
      var(--cve-paper-margin) 44px 45px,
      transparent 45px),
    repeating-linear-gradient(to bottom,
      transparent 0 calc(var(--cve-paper-line) - 7px),
      color-mix(in srgb, var(--cve-paper-rule) 55%, transparent) calc(var(--cve-paper-line) - 7px)
        calc(var(--cve-paper-line) - 5px),
      transparent calc(var(--cve-paper-line) - 5px) var(--cve-paper-line)),
    var(--cve-paper));
  box-shadow:
    0 18px 40px var(--cve-shadow),
    0 4px 12px var(--cve-shadow);
}

.cv-exercise-instructions::before {
  content: "";
  position: absolute;
  z-index: 8;
  top: 0;
  left: 0;
  width: clamp(62px, 8cqi, 84px);
  height: clamp(20px, 2.5cqi, 25px);
  pointer-events: none;
  border: 1px solid var(--cve-tape-edge);
  background: var(--cve-tape);
  box-shadow: 0 2px 5px var(--cve-shadow);
  transform: translate(-50%, -50%) rotate(-34deg);
}

.cv-exercise-instructions[data-tape-side="right"]::before {
  right: 0;
  left: auto;
  transform: translate(50%, -50%) rotate(34deg);
}

.cv-exercise-instructions .cv-exercise-panel-head {
  min-height: calc(var(--cve-paper-line) * 2);
  padding-block: 0;
  padding-left: clamp(54px, 5cqi, 66px);
  border-bottom-color: color-mix(in oklch, var(--cve-accent) 34%,
    var(--cve-border-strong) 66%);
  background: transparent;
}

.cv-exercise-note {
  position: relative;
  min-height: calc(var(--cve-paper-line) * 3);
  flex: 1 0 auto;
  padding: 0 clamp(18px, 2.8cqi, 32px) var(--cve-paper-line)
    clamp(54px, 5cqi, 66px);
  overflow: visible;
  background: transparent;
  color: color-mix(in oklch, var(--cve-text) 86%, var(--cve-muted) 14%);
  font-size: clamp(.88rem, 1.25cqi, 1rem);
  line-height: var(--cve-paper-line);
  cursor: text;
}

.cv-exercise:not(.is-native-editor) .cv-exercise-note:hover {
  background-color: color-mix(in oklch, var(--cve-accent) 3%, transparent);
}

.cv-exercise-note .markdown-rendered-content,
.cv-exercise-note .markdown-preview-sizer,
.cv-exercise-note .markdown-preview-section {
  width: 100%;
  max-width: none;
  min-height: 0;
  margin: 0;
  padding: 9px 0 0;
  text-align: justify;
}

.cv-exercise-note :is(h1, h2, h3, h4, h5, h6, p, ul, ol, pre) {
  margin-block: 0;
}

.cv-exercise-note :is(h1, h2, h3, h4, h5, h6) {
  min-height: var(--cve-paper-line);
  padding-block: 0;
  color: var(--cve-text);
  line-height: var(--cve-paper-line);
  letter-spacing: -.02em;
}

.cv-exercise-note h2:first-child {
  text-align: center;
}

.cv-exercise-note :is(p, li),
.cv-exercise-note .cm-content,
.cv-exercise-note .cm-line {
  line-height: var(--cve-paper-line) !important;
}

.cv-exercise-note ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.cv-exercise-note ol > li.cv-exercise-step {
  position: relative;
  min-height: 54px;
  padding: 10px 0 10px 44px;
  border-bottom: 1px solid color-mix(in srgb, var(--cve-border) 72%, transparent);
  line-height: 1.65;
}

.cv-exercise-note ol > li.cv-exercise-step:last-child {
  border-bottom: 0;
}

.cv-exercise-note ol > li.cv-exercise-step::before,
.cv-exercise-note ol > li.cv-exercise-step::after {
  content: none;
}

.cv-exercise-step-control {
  position: absolute;
  top: 50%;
  left: 0;
  width: var(--cve-checkbox-size);
  height: var(--cve-checkbox-size);
  margin: 0;
  transform: translateY(-50%);
  cursor: pointer;
  user-select: none;
}

.cv-exercise-step-input {
  position: absolute;
  z-index: 7;
  width: 1px;
  height: 1px;
  min-width: 0;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  border: 0;
  white-space: nowrap;
}

.cv-exercise-step-marker {
  position: absolute;
  z-index: 4;
  inset: 0;
  border: 2px solid color-mix(in srgb, var(--cve-accent) 55%,
    var(--cve-border-strong) 45%);
  border-radius: 10px;
  background: color-mix(in srgb, var(--cve-surface-2) 88%,
    var(--cve-surface-3) 12%);
  box-shadow: 0 3px 9px var(--cve-shadow);
  pointer-events: none;
  transition:
    border-color .16s var(--cve-ease),
    background-color .16s var(--cve-ease),
    box-shadow .16s var(--cve-ease),
    transform .16s var(--cve-ease);
}

.cv-exercise-step-check {
  position: absolute;
  z-index: 6;
  top: 50%;
  left: 50%;
  width: 7px;
  height: 13px;
  border-right: 2px solid var(--cve-on-accent);
  border-bottom: 2px solid var(--cve-on-accent);
  pointer-events: none;
  transform: translate(-50%, -58%) rotate(45deg) scale(0);
  transition: transform .14s var(--cve-ease);
}

.cv-exercise-step-control:hover .cv-exercise-step-marker {
  border-color: var(--cve-accent);
  transform: translateY(-1px);
}

.cv-exercise-step-input:focus-visible + .cv-exercise-step-marker {
  outline: 2px solid var(--cve-focus);
  outline-offset: 3px;
}

.cv-exercise-step-input:checked + .cv-exercise-step-marker {
  border-color: var(--cve-accent);
  background: var(--cve-accent);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--cve-accent) 28%, transparent);
}

.cv-exercise-step-input:checked ~ .cv-exercise-step-check {
  transform: translate(-50%, -58%) rotate(45deg) scale(1);
}

.cv-exercise-step-goo,
.cv-exercise-step-track {
  display: none !important;
}

.cv-exercise-step-track {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: 18px;
  width: 8px;
  height: var(--cve-step-connector-length, 0);
  border-radius: 999px;
  background: color-mix(in oklch, var(--cve-border-strong) 68%,
    var(--cve-paper) 32%);
  box-shadow: inset 0 0 0 1px
    color-mix(in oklch, var(--cve-text) 7%, transparent);
  pointer-events: none;
}

.cv-exercise-step-goo {
  position: absolute;
  z-index: 5;
  top: 50%;
  left: 0;
  width: 44px;
  height: calc(var(--cve-step-connector-length, 0px) + 44px);
  overflow: visible;
  color: var(--cve-liquid);
  filter: var(--cve-progress-filter, none);
  transform: translateY(-22px);
  pointer-events: none;
}

.cv-exercise-step-liquid-marker {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(to bottom,
    var(--cve-liquid-soft),
    var(--cve-liquid));
  box-shadow: 0 0 10px
    color-mix(in oklch, var(--cve-liquid) 24%, transparent);
  opacity: 0;
  transform: scale(.16);
  transform-origin: center;
}

.cv-exercise-step-liquid-stream {
  position: absolute;
  top: 22px;
  left: 18px;
  width: 8px;
  height: var(--cve-step-connector-length, 0);
  border-radius: 999px;
  background: linear-gradient(to bottom,
    var(--cve-liquid-soft),
    var(--cve-liquid));
  box-shadow: 0 0 9px
    color-mix(in oklch, var(--cve-liquid) 22%, transparent);
  transform: scaleY(0);
  transform-origin: top;
}

.cv-exercise-step-liquid-droplet {
  position: absolute;
  top: 15px;
  left: 15px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--cve-liquid-soft);
  opacity: 0;
  transform: translateY(0) scale(.35);
}

.cv-exercise-step.is-checked > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-marker {
  opacity: 1;
  transform: scale(1);
}

.cv-exercise-step.is-flowing-to-next > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-stream {
  transform: scaleY(1);
}

.cv-exercise-step.is-marker-filling > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-marker {
  animation: cve-marker-fill 240ms cubic-bezier(.2, .72, .18, 1) forwards;
}

.cv-exercise-step.is-marker-draining > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-marker {
  animation: cve-marker-drain 240ms cubic-bezier(.2, .72, .18, 1) forwards;
}

.cv-exercise-step.is-connector-filling > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-stream {
  animation: cve-connector-fill 360ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-exercise-step.is-connector-draining > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-stream {
  animation: cve-connector-drain 360ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-exercise-step.is-connector-filling > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-droplet {
  animation: cve-droplet-down 360ms cubic-bezier(.18, .72, .2, 1) forwards;
}

.cv-exercise-step.is-connector-draining > .cv-exercise-step-goo
  > .cv-exercise-step-liquid-droplet {
  animation: cve-droplet-up 360ms cubic-bezier(.18, .72, .2, 1) forwards;
}

@keyframes cve-marker-fill {
  0% {
    opacity: 0;
    transform: scale(.16);
  }
  68% {
    opacity: 1;
    transform: scale(1.09, .92);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes cve-marker-drain {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  35% {
    opacity: 1;
    transform: scale(.88, 1.08);
  }
  100% {
    opacity: 0;
    transform: scale(.16);
  }
}

@keyframes cve-connector-fill {
  from {
    transform: scaleY(0);
    transform-origin: top;
  }
  to {
    transform: scaleY(1);
    transform-origin: top;
  }
}

@keyframes cve-connector-drain {
  from {
    transform: scaleY(1);
    transform-origin: top;
  }
  to {
    transform: scaleY(0);
    transform-origin: top;
  }
}

@keyframes cve-droplet-down {
  0% {
    opacity: 0;
    transform: translateY(0) scale(.35);
  }
  22% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform:
      translateY(var(--cve-step-connector-length, 0px)) scale(.9);
  }
}

@keyframes cve-droplet-up {
  0% {
    opacity: 0;
    transform:
      translateY(var(--cve-step-connector-length, 0px)) scale(.9);
  }
  22% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(0) scale(.35);
  }
}

.cv-exercise-note [data-cv-editable-placeholder],
.cv-exercise-note .markdown-source-view,
.cv-exercise-note .cm-editor,
.cv-exercise-note .cm-scroller,
.cv-exercise-note .cm-content {
  width: 100% !important;
  max-width: none !important;
  min-height: calc(var(--cve-paper-line) * 3) !important;
  background: transparent !important;
}

.cv-exercise-note .markdown-source-view,
.cv-exercise-note .cm-editor {
  position: relative !important;
  inset: auto !important;
}

.cv-exercise-note .cm-scroller {
  overflow: visible !important;
}

.cv-exercise-note .cm-content {
  padding: 0 !important;
  font-size: clamp(.86rem, 1.2cqi, .98rem) !important;
}

.cv-exercise-note .cm-line {
  min-height: var(--cve-paper-line);
}

.cv-exercise.is-native-editor .cv-exercise-instructions {
  border-color: color-mix(in oklch, var(--cve-accent) 58%,
    var(--cve-border) 42%);
}

@media (forced-colors: active) {
  .cv-exercise-step-goo {
    filter: none;
  }

  .cv-exercise-step-track {
    background: GrayText;
    box-shadow: none;
    forced-color-adjust: none;
  }

  .cv-exercise-step-marker {
    border-color: CanvasText;
    background: Canvas;
    box-shadow: none;
    forced-color-adjust: none;
  }

  .cv-exercise-step-check {
    color: CanvasText;
    forced-color-adjust: none;
  }

  .cv-exercise-step-liquid-marker,
  .cv-exercise-step-liquid-stream,
  .cv-exercise-step-liquid-droplet {
    background: Highlight;
    box-shadow: none;
    forced-color-adjust: none;
  }

  .cv-exercise-step-input:checked + .cv-exercise-step-marker {
    border-color: Highlight;
    background: Highlight;
  }

  .cv-exercise-step-input:checked ~ .cv-exercise-step-check {
    border-color: HighlightText;
  }

