const exerciseContext = tp;
const exerciseContainer = exerciseContext.container || this;
const exerciseRoot = exerciseContainer.querySelector(".cv-exercise");

if (exerciseRoot) {
  const exerciseApp = exerciseContext.app;
  const exerciseFile = exerciseContext.file;
  const exerciseFrontmatter = exerciseContext.frontmatter || {};
  const exerciseQuery = (selector) => exerciseRoot.querySelector(selector);
  const exerciseDocument = exerciseRoot.ownerDocument;
  const exerciseViewToken = Math.random().toString(36).slice(2, 10);
  const exerciseBodyMapPath =
    "90_System/95_Media_Assets/Exercise/Anatomy/muscle-map.svg";

  function asArray(value) {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return [value];
  }

  function normalize(value) {
    return String(value ?? "").trim().toLowerCase();
  }

  function displayText(value, fallback = "—") {
    const text = String(value ?? "").trim();
    if (!text || text.toLowerCase() === "none") return fallback;
    return text
      .replaceAll("_", " ")
      .replace(/\b\w/g, (character) => character.toUpperCase());
  }

  function listText(value, fallback = "—") {
    const values = asArray(value).map((item) => displayText(item, "")).filter(
      Boolean,
    );
    return values.length ? values.join(", ") : fallback;
  }

  function resolveImage(value) {
    const raw = asArray(value).map((item) =>
      String(item ?? "").trim()
    ).find(Boolean) || "";
    if (!raw) return "";
    const wikiMatch = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    if (!wikiMatch) return raw;
    if (!exerciseApp?.metadataCache || !exerciseFile) return "";
    const target = exerciseApp.metadataCache.getFirstLinkpathDest(
      wikiMatch[1],
      exerciseFile.path,
    );
    return target ? exerciseApp.vault.getResourcePath(target) : "";
  }

  function setText(role, value) {
    const element = exerciseQuery(`[data-role="${role}"]`);
    if (element) element.textContent = value;
  }

  function canonicalLevel(value) {
    const level = normalize(value);
    if (level === "expert" || level === "advanced") return "expert";
    if (level === "intermediate") return "intermediate";
    return "beginner";
  }

  function levelLabel(value) {
    const level = canonicalLevel(value);
    return level === "expert" ? "Advanced" : displayText(level);
  }

  function renderSummary() {
    const title = String(
      exerciseFrontmatter.name || exerciseFile?.basename || "Exercise",
    ).trim();
    const primary = asArray(exerciseFrontmatter.primaryMuscles).map(normalize)
      .filter(Boolean);
    const secondary = asArray(exerciseFrontmatter.secondaryMuscles).map(
      normalize,
    ).filter(Boolean);
    const equipment = normalize(exerciseFrontmatter.equipment) || "body only";
    const category = displayText(exerciseFrontmatter.category, "Exercise");
    const force = displayText(exerciseFrontmatter.force, "Neutral");
    const mechanic = displayText(exerciseFrontmatter.mechanic, "Unspecified");
    const level = canonicalLevel(exerciseFrontmatter.level);

    exerciseRoot.dataset.level = level;
    setText("exercise-title", title);
    setText("exercise-level-label", levelLabel(level));
    setText("exercise-category", category);
    setText("exercise-force", force);
    setText("exercise-mechanic", mechanic);
    setText("exercise-primary", listText(exerciseFrontmatter.primaryMuscles));
    setText(
      "exercise-secondary",
      listText(exerciseFrontmatter.secondaryMuscles, "No secondary target"),
    );
    setText(
      "exercise-equipment",
      displayText(exerciseFrontmatter.equipment, "Body only"),
    );
    setText("profile-force", force);
    setText("profile-mechanic", mechanic);
    setText("profile-category", category);
    setText(
      "profile-id",
      String(exerciseFrontmatter.id || exerciseFile?.basename || "—"),
    );

    const equipmentIcon = exerciseQuery(
      '[data-role="exercise-equipment-icon"]',
    );
    if (equipmentIcon) equipmentIcon.dataset.equipment = equipment;

    return { primary, secondary };
  }

  function paintBodyMap(bodyMap, targets) {
    const primarySet = new Set(targets.primary);
    const secondarySet = new Set(
      targets.secondary.filter((muscle) => !primarySet.has(muscle)),
    );
    const secondaryRegions = [];
    const primaryRegions = [];

    for (const region of bodyMap.querySelectorAll("[data-muscle]")) {
      const muscle = normalize(region.dataset.muscle);
      const isPrimary = primarySet.has(muscle);
      const isSecondary = secondarySet.has(muscle);
      region.classList.toggle("is-primary", isPrimary);
      region.classList.toggle("is-secondary", isSecondary);
      if (isPrimary) primaryRegions.push(region);
      else if (isSecondary) secondaryRegions.push(region);
    }

    // Paint active muscle groups above inactive ones.
    const firstLabel = bodyMap.querySelector(".muscle-map__label");
    for (const region of [...secondaryRegions, ...primaryRegions]) {
      bodyMap.insertBefore(region, firstLabel || null);
    }
  }

  function sanitizeBodyMap(bodyMap) {
    for (const unsafe of bodyMap.querySelectorAll("script, foreignObject")) {
      unsafe.remove();
    }
    for (const element of bodyMap.querySelectorAll("*")) {
      element.removeAttribute("id");
      for (const attribute of [...element.attributes]) {
        const name = attribute.name.toLowerCase();
        const value = attribute.value.trim();
        if (name.startsWith("on")) element.removeAttribute(attribute.name);
        if (
          (name === "href" || name === "xlink:href") &&
          /^(?:data|file|https?|javascript):/i.test(value)
        ) {
          element.removeAttribute(attribute.name);
        }
      }
    }
  }

  async function initBodyMap(targets) {
    const host = exerciseQuery('[data-role="exercise-bodymap"]');
    if (!host || !exerciseApp?.vault || !exerciseDocument) return;

    try {
      const asset = exerciseApp.vault.getFileByPath?.(exerciseBodyMapPath) ||
        exerciseApp.vault.getAbstractFileByPath?.(exerciseBodyMapPath);
      if (!asset || asset.extension !== "svg") {
        throw new Error(`Missing local SVG: ${exerciseBodyMapPath}`);
      }

      const markup = await exerciseApp.vault.cachedRead(asset);
      const Parser = exerciseDocument.defaultView?.DOMParser;
      if (!Parser) throw new Error("DOMParser is unavailable");
      const parsed = new Parser().parseFromString(markup, "image/svg+xml");
      if (parsed.querySelector("parsererror")) {
        throw new Error("Local anatomy SVG could not be parsed");
      }

      const source = parsed.documentElement;
      if (source.localName !== "svg") {
        throw new Error("Local anatomy asset is not an SVG document");
      }

      const bodyMap = exerciseDocument.importNode(source, true);
      sanitizeBodyMap(bodyMap);
      bodyMap.classList.add("cv-exercise-bodymap-svg");
      bodyMap.removeAttribute("width");
      bodyMap.removeAttribute("height");
      bodyMap.setAttribute("aria-label", "Front and back muscle target map");
      bodyMap.removeAttribute("aria-labelledby");
      bodyMap.querySelector("title")?.removeAttribute("id");
      paintBodyMap(bodyMap, targets);

      host.replaceChildren(bodyMap);
      host.classList.add("is-ready");
      host.setAttribute("aria-busy", "false");
    } catch (error) {
      host.classList.add("is-error");
      host.setAttribute("aria-busy", "false");
      host.textContent = "Local muscle map unavailable";
      console.error("[custom-view:exercise] Could not load muscle map", error);
    }
  }

  function initDemo() {
    const media = exerciseQuery(".cv-exercise-media");
    const preview = exerciseQuery('[data-role="exercise-preview"]');
    const animation = exerciseQuery('[data-role="exercise-animation"]');
    const button = exerciseQuery('[data-action="toggle-exercise-demo"]');
    const label = exerciseQuery('[data-role="exercise-play-label"]');
    const state = exerciseQuery('[data-role="exercise-media-state"]');
    if (!media || !preview || !animation || !button || !label || !state) return;

    const previewSource = resolveImage(exerciseFrontmatter.preview);
    const animationSource = resolveImage(exerciseFrontmatter.animation);
    if (previewSource) preview.src = previewSource;
    else {
      preview.removeAttribute("src");
      state.textContent = "Preview unavailable";
    }

    let playing = false;
    const paint = () => {
      media.classList.toggle("is-playing", playing);
      button.setAttribute("aria-pressed", String(playing));
      label.textContent = playing ? "Pause demo" : "Play demo";
      state.textContent = playing
        ? "Animated technique demonstration"
        : "Static first frame";
    };

    if (!animationSource) {
      button.disabled = true;
      button.setAttribute("aria-label", "Animated demonstration unavailable");
      label.textContent = "No demo";
      if (previewSource) state.textContent = "Static preview only";
      return;
    }

    button.addEventListener("click", () => {
      playing = !playing;
      if (playing) animation.src = animationSource;
      else animation.removeAttribute("src");
      paint();
    });

    animation.addEventListener("error", () => {
      playing = false;
      animation.removeAttribute("src");
      paint();
      state.textContent = "Animated demonstration unavailable";
    });

    paint();
  }

  let exerciseFrontmatterQueue = Promise.resolve();

  function updateFrontmatter(property, value) {
    if (!exerciseApp?.fileManager || !exerciseFile) {
      return Promise.reject(new Error("Exercise file is unavailable"));
    }
    const task = exerciseFrontmatterQueue.then(() =>
      exerciseApp.fileManager.processFrontMatter(exerciseFile, (draft) => {
        draft[property] = value;
      })
    );
    exerciseFrontmatterQueue = task.catch(() => {});
    return task;
  }

  function instructionProgressFromDone(done, count) {
    let progress = 0;
    for (let index = 0; index < count; index += 1) {
      const complete = done[index] === true ||
        String(done[index]).toLowerCase() === "true";
      if (!complete) break;
      progress = index + 1;
    }
    return progress;
  }

  function instructionDoneFromProgress(progress, count) {
    const bounded = Math.max(0, Math.min(count, Number(progress) || 0));
    return Array.from({ length: count }, (_, index) => index < bounded);
  }

  function initInstructionChecklist() {
    const render = exerciseQuery('[data-role="exercise-note"]');
    const state = exerciseQuery('[data-role="exercise-note-state"]');
    if (!render) return;

    let currentProgress = 0;
    let persistedProgress = 0;
    let saveRevision = 0;
    let initialized = false;
    let decorating = false;

    render.querySelectorAll(
      ".cv-exercise-step-control, .cv-exercise-step-goo, " +
        ".cv-exercise-step-track, .cv-exercise-step-toggle, " +
        ".cv-exercise-step-flow",
    ).forEach((element) => element.remove());
    render.querySelectorAll(".cv-exercise-step").forEach((item) => {
      item.classList.remove(
        "cv-exercise-step",
        "is-checked",
        "is-flowing-to-next",
        "is-marker-filling",
        "is-marker-draining",
        "is-connector-filling",
        "is-connector-draining",
      );
      item.style.removeProperty("--cve-step-connector-length");
    });

    const steps = () => {
      const list = render.querySelector(
        ":scope > ol, .markdown-preview-sizer > ol, .markdown-rendered ol",
      );
      return list
        ? Array.from(list.children).filter((item) => item.matches("li"))
        : [];
    };

    function paint(progress = currentProgress) {
      const items = steps();
      currentProgress = Math.max(0, Math.min(items.length, progress));
      items.forEach((item, index) => {
        const checked = index < currentProgress;
        const checkbox = item.querySelector(
          ":scope > .cv-exercise-step-control > .cv-exercise-step-input",
        );
        item.classList.toggle("is-checked", checked);
        item.dataset.stepState = checked ? "complete" : "pending";
        if (!checkbox) return;
        checkbox.checked = checked;
        checkbox.dataset.stepIndex = String(index);
        checkbox.setAttribute(
          "aria-label",
          checked
            ? "Clear progress from instruction step " + (index + 1)
            : "Complete through instruction step " + (index + 1),
        );
      });
    }

    async function requestProgress(target) {
      const count = steps().length;
      const nextProgress = Math.max(0, Math.min(count, Number(target) || 0));
      if (nextProgress === currentProgress) {
        paint(currentProgress);
        return;
      }

      const revision = ++saveRevision;
      currentProgress = nextProgress;
      const snapshot = instructionDoneFromProgress(nextProgress, count);
      paint(nextProgress);
      if (state) {
        state.textContent = nextProgress
          ? "Saving progress through step " + nextProgress + "…"
          : "Clearing instruction progress…";
      }

      try {
        await updateFrontmatter("instruction_done", snapshot);
        persistedProgress = nextProgress;
        if (revision === saveRevision && state) {
          state.textContent = nextProgress
            ? "Progress saved through step " + nextProgress
            : "Instruction progress cleared";
        }
      } catch (error) {
        if (revision === saveRevision) {
          currentProgress = persistedProgress;
          paint(persistedProgress);
          if (state) state.textContent = "Instruction progress was not saved";
        }
        console.error(
          "[custom-view:exercise] Could not save instruction progress",
          error,
        );
      }
    }

    function createStepControl(item, index) {
      const control = exerciseDocument.createElement("span");
      control.className = "cv-exercise-step-control";

      const checkbox = exerciseDocument.createElement("input");
      const inputId = `cve-instruction-${exerciseViewToken}-${index}`;
      checkbox.className = "cv-exercise-step-input";
      checkbox.type = "checkbox";
      checkbox.id = inputId;
      checkbox.name = `exercise-instructions-${exerciseViewToken}`;
      checkbox.dataset.stepIndex = String(index);
      checkbox.contentEditable = "false";

      const marker = exerciseDocument.createElement("label");
      marker.className = "cv-exercise-step-marker";
      marker.htmlFor = inputId;
      marker.style.pointerEvents = "auto";
      marker.style.cursor = "pointer";

      const check = exerciseDocument.createElement("span");
      check.className = "cv-exercise-step-check";
      check.setAttribute("aria-hidden", "true");

      control.addEventListener("pointerdown", (event) => event.stopPropagation());
      control.addEventListener("click", (event) => event.stopPropagation());
      checkbox.addEventListener("click", (event) => event.stopPropagation());
      checkbox.addEventListener("change", (event) => {
        event.stopPropagation();
        const stepIndex = Number(checkbox.dataset.stepIndex);
        if (!Number.isInteger(stepIndex) || stepIndex < 0) return;
        void requestProgress(checkbox.checked ? stepIndex + 1 : stepIndex);
      });

      control.append(checkbox, marker, check);
      item.prepend(control);
    }

    function decorate() {
      if (decorating) return;
      decorating = true;
      try {
        const items = steps();
        if (!items.length) return;

        if (!initialized) {
          const rawDone = asArray(exerciseFrontmatter.instruction_done);
          currentProgress = instructionProgressFromDone(rawDone, items.length);
          persistedProgress = currentProgress;
          initialized = true;

          const normalized = instructionDoneFromProgress(
            currentProgress,
            items.length,
          );
          const parsedRaw = rawDone.map(
            (value) => value === true || String(value).toLowerCase() === "true",
          );
          if (JSON.stringify(parsedRaw) !== JSON.stringify(normalized)) {
            void updateFrontmatter("instruction_done", normalized).catch(
              (error) => console.error(
                "[custom-view:exercise] Could not normalize instruction progress",
                error,
              ),
            );
          }
        }

        items.forEach((item, index) => {
          item.classList.add("cv-exercise-step");
          item.querySelectorAll(
            ":scope > .cv-exercise-step-goo, " +
              ":scope > .cv-exercise-step-track, " +
              ":scope > .cv-exercise-step-toggle, " +
              ":scope > .cv-exercise-step-flow",
          ).forEach((element) => element.remove());

          if (!item.querySelector(":scope > .cv-exercise-step-control")) {
            createStepControl(item, index);
          }
          const checkbox = item.querySelector(
            ":scope > .cv-exercise-step-control > .cv-exercise-step-input",
          );
          if (checkbox) checkbox.dataset.stepIndex = String(index);
        });
        paint(currentProgress);
      } finally {
        decorating = false;
      }
    }

    decorate();
    const Observer =
      exerciseDocument.defaultView?.MutationObserver ||
      globalThis.MutationObserver;
    if (Observer) {
      new Observer(decorate).observe(render, {
        childList: true,
        subtree: true,
      });
    }
  }
  function initPaperTape() {
    const paper = exerciseQuery(".cv-exercise-instructions");
    if (!paper) return;
    const seed = String(exerciseFile?.path || exerciseFile?.basename || "exercise-note");
    let hash = 0;
    for (const character of seed) hash = ((hash * 31) + character.charCodeAt(0)) | 0;
    paper.dataset.tapeSide = Math.abs(hash) % 2 ? "right" : "left";
  }

  function initLevelControl() {
    const buttons = [...exerciseRoot.querySelectorAll("[data-level-value]")];
    const state = exerciseQuery('[data-role="exercise-save-state"]');
    const levelLabelElement = exerciseQuery(
      '[data-role="exercise-level-label"]',
    );
    if (!buttons.length) return;
    let current = canonicalLevel(exerciseFrontmatter.level);

    const paint = () => {
      exerciseRoot.dataset.level = current;
      if (levelLabelElement) {
        levelLabelElement.textContent = levelLabel(current);
      }
      for (const button of buttons) {
        const active = button.dataset.levelValue === current;
        button.classList.toggle("is-active", active);
        button.setAttribute("aria-pressed", String(active));
      }
    };

    paint();
    for (const button of buttons) {
      button.addEventListener("click", async () => {
        const next = canonicalLevel(button.dataset.levelValue);
        if (next === current || buttons.some((item) => item.disabled)) return;
        const previous = current;
        current = next;
        paint();
        for (const item of buttons) item.disabled = true;
        if (state) state.textContent = "Saving…";
        try {
          await updateFrontmatter("level", next);
          if (state) state.textContent = "Saved";
        } catch (error) {
          current = previous;
          paint();
          if (state) state.textContent = "Level was not saved";
          console.error("[custom-view:exercise] Could not save level", error);
        } finally {
          for (const item of buttons) item.disabled = false;
        }
      });
    }
  }

  function initNoteEditor() {
    const render = exerciseQuery('[data-role="exercise-note"]');
    const state = exerciseQuery('[data-role="exercise-note-state"]');
    if (!render || !state) return;

    const nativePlaceholder = render.querySelector(
      "[data-cv-editable-placeholder]",
    );
    if (nativePlaceholder) {
      exerciseRoot.classList.add("is-native-editor");
      state.textContent = "Autosaved by Obsidian";
      return;
    }

    render.setAttribute("tabindex", "0");
    render.setAttribute("role", "group");
    render.setAttribute(
      "aria-label",
      "Exercise instructions and progress. Click the text to edit in Live Preview.",
    );
    state.textContent = "Click instructions to edit";
    let openingEditor = false;

    const openInlineEditor = async () => {
      if (openingEditor) return;
      const leaves =
        typeof exerciseApp?.workspace?.getLeavesOfType === "function"
          ? exerciseApp.workspace.getLeavesOfType("markdown")
          : [];
      const leaf = leaves.find((candidate) =>
        candidate?.view?.file?.path === exerciseFile?.path &&
        candidate.view.contentEl?.contains(exerciseContainer)
      );
      if (
        !leaf || typeof leaf.getViewState !== "function" ||
        typeof leaf.setViewState !== "function"
      ) {
        state.textContent = "Open this note in Live Preview to edit here";
        return;
      }

      state.textContent = "Opening inline editor…";
      openingEditor = true;
      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode: "source",
            source: false,
          },
        });
      } catch (error) {
        openingEditor = false;
        state.textContent = "Could not open inline editor";
        console.error(
          "[custom-view:exercise] Could not enter Live Preview",
          error,
        );
      }
    };

    render.addEventListener("click", (event) => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void openInlineEditor();
    });
    render.addEventListener("keydown", (event) => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void openInlineEditor();
    });
  }

  const muscleTargets = renderSummary();
  void initBodyMap(muscleTargets);
  initDemo();
  initLevelControl();
  initNoteEditor();
  initInstructionChecklist();
  initPaperTape();
}

views.css:
/* Book detail view — editable reading dossier with theme-derived marginalia. */

.obsidian-custom-view-render {
  padding: 0 !important;
}

.cv-book {
  --cv-book-bg: var(--background-primary);
  --cv-book-surface: var(--lake-surface, var(--background-primary));
  --cv-book-surface-2: var(--lake-surface-2, var(--background-secondary));
  --cv-book-surface-3: var(--lake-surface-3, var(--background-secondary-alt));
  --cv-book-hover: var(--lake-surface-4, var(--background-modifier-hover));
  --cv-book-accent: var(--lake-accent, var(--interactive-accent));
  --cv-book-accent-soft: var(--lake-accent-soft, var(--interactive-accent-hover));
  --cv-book-text: var(--lake-text, var(--text-normal));
  --cv-book-muted: var(--lake-text-soft, var(--text-muted));
  --cv-book-faint: var(--text-faint);
  --cv-book-border: var(--lake-border-2, var(--background-modifier-border));
  --cv-book-border-strong: var(--lake-border-3, var(--background-modifier-border-hover));
  --cv-book-shadow: color-mix(in srgb, var(--shadow) 38%, transparent);
  --cv-book-shadow-soft: color-mix(in srgb, var(--shadow) 20%, transparent);
  --cv-book-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--interactive-accent) 15%, transparent));
  --cv-book-margin-rule: var(--vault-note-paper-margin-rule, color-mix(in srgb, var(--interactive-accent) 22%, transparent));
  --cv-book-paper: var(--vault-note-paper, color-mix(in srgb, var(--background-primary) 60%, var(--background-secondary) 40%));
  --cv-book-paper-line: var(--vault-note-paper-line, 30px);
  --cv-book-radius-lg: clamp(18px, 2.2cqi, 26px);
  --cv-book-radius: clamp(12px, 1.4cqi, 16px);
  --cv-book-pad: clamp(18px, 4cqi, 56px);
  --cv-book-gap: clamp(18px, 2.5cqi, 32px);
  --cv-book-ease: cubic-bezier(.22, .61, .36, 1);

  width: 100%;
  max-width: none;
  min-width: 0;
  min-height: 100%;
  container-type: inline-size;
  overflow: hidden;
  background: var(--cv-book-bg);
  color: var(--cv-book-text);
  font-family: var(--font-interface);
}

.cv-book *,
.cv-book *::before,
.cv-book *::after {
  box-sizing: border-box;
}

.cv-book button,
.cv-book input {
  font: inherit;
}

.cv-book button:focus-visible,
.cv-book input:focus-visible,
.cv-book [tabindex="0"]:focus-visible,
.cv-book [contenteditable]:focus-visible {
  outline: 2px solid var(--cv-book-accent);
  outline-offset: 3px;
}

.cv-book-hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--cv-book-border);
  background:
    radial-gradient(circle at 13% 18%, color-mix(in srgb, var(--cv-book-accent) 8%, transparent), transparent 34%),
    linear-gradient(155deg, color-mix(in srgb, var(--cv-book-surface-2) 62%, var(--cv-book-bg) 38%), var(--cv-book-bg) 56%);
}

.cv-book-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .44;
  background-image: linear-gradient(
    to bottom,
    transparent calc(var(--cv-book-paper-line) - 2px),
    color-mix(in srgb, var(--cv-book-rule) 55%, transparent) calc(var(--cv-book-paper-line) - 2px)
  );
  background-size: 100% var(--cv-book-paper-line);
  background-repeat: repeat;
  mask-image: linear-gradient(90deg, transparent, var(--cv-book-text) 18%, var(--cv-book-text) 82%, transparent);
}

.cv-book-hero-inner {
  position: relative;
  z-index: 1;
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: clamp(34px, 5cqi, 72px) var(--cv-book-pad);
  display: grid;
  grid-template-columns: clamp(150px, 18cqi, 232px) minmax(0, 1fr) minmax(285px, 340px);
  align-items: center;
  gap: clamp(24px, 3.4cqi, 48px);
}

.cv-book-cover-shell {
  position: relative;
  width: 100%;
  margin: 0;
  align-self: center;
}

.cv-book-cover-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border: 1px solid var(--cv-book-border-strong);
  border-radius: calc(var(--cv-book-radius) - 2px);
  background: var(--cv-book-surface-3);
  box-shadow:
    0 22px 48px var(--cv-book-shadow),
    0 3px 10px var(--cv-book-shadow-soft),
    inset -8px 0 14px color-mix(in srgb, var(--cv-book-bg) 18%, transparent);
  transform: rotate(-.45deg);
}

.cv-book-cover-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, var(--cv-book-text) 8%, transparent),
    inset -1px 0 0 color-mix(in srgb, var(--cv-book-bg) 45%, transparent);
}

.cv-book-cover {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.cv-book-cover-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--cv-book-muted);
  font-family: var(--font-monospace);
  font-size: clamp(.82rem, 1.6cqi, 1rem);
  letter-spacing: .24em;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--cv-book-accent) 8%, transparent), transparent 20%),
    var(--cv-book-surface-3);
}

.cv-book-cover[hidden],
.cv-book-cover-fallback[hidden] {
  display: none !important;
}

.cv-book-cover-caption {
  position: absolute;
  top: clamp(12px, 1.5cqi, 18px);
  left: clamp(-7px, -.55cqi, -4px);
  z-index: 2;
}

.cv-book-status-badge {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 6px 11px 6px 14px;
  border: 1px solid color-mix(in srgb, var(--cv-book-accent) 38%, var(--cv-book-border) 62%);
  border-left: 0;
  border-radius: 0 999px 999px 0;
  background: color-mix(in srgb, var(--cv-book-paper) 90%, var(--cv-book-accent) 10%);
  color: var(--cv-book-text);
  box-shadow: 0 6px 16px var(--cv-book-shadow-soft);
  font-family: var(--font-monospace);
  font-size: .69rem;
  line-height: 1;
  font-weight: 760;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.cv-book-status-badge[data-status="Finished"] {
  color: var(--text-success, var(--cv-book-accent-soft));
}

.cv-book-status-badge[data-status="Currently reading"] {
  color: var(--cv-book-accent-soft);
}

.cv-book-identity {
  min-width: 0;
}

.cv-book-eyebrow,
.cv-book-kicker,
.cv-book-control-label {
  display: block;
  color: var(--cv-book-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(.67rem, 1.05cqi, .78rem);
  line-height: 1.25;
  font-weight: 760;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.cv-book-title {
  max-width: 19ch;
  margin: 9px 0 0;
  color: var(--cv-book-text);
  font-family: var(--font-text);
  font-size: clamp(2.25rem, 5.2cqi, 4.8rem);
  line-height: 1.02;
  font-weight: 780;
  letter-spacing: -.038em;
  text-wrap: balance;
}

.cv-book-author {
  margin: clamp(10px, 1.4cqi, 16px) 0 0;
  color: var(--cv-book-muted);
  font-size: clamp(.9rem, 1.5cqi, 1.08rem);
  line-height: 1.45;
}

.cv-book-author span {
  color: color-mix(in srgb, var(--cv-book-text) 84%, var(--cv-book-muted) 16%);
  font-weight: 650;
}

.cv-book-inline-edit {
  border-radius: 6px;
  outline: none;
  cursor: text;
  transition:
    background .16s var(--cv-book-ease),
    box-shadow .16s var(--cv-book-ease);
}

.cv-book-inline-edit:hover {
  background: color-mix(in srgb, var(--cv-book-accent) 7%, transparent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--cv-book-accent) 7%, transparent);
}

.cv-book-inline-edit:focus {
  background: color-mix(in srgb, var(--cv-book-surface-3) 72%, transparent);
  box-shadow: 0 0 0 1px var(--cv-book-border-strong);
}

.cv-book-inline-edit:empty::before {
  content: attr(data-placeholder);
  color: var(--cv-book-faint);
}

.cv-book-genres {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: clamp(14px, 1.7cqi, 20px);
}

.cv-book-genres span {
  padding: 5px 9px;
  border: 1px solid var(--cv-book-border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--cv-book-surface-3) 72%, transparent);
  color: var(--cv-book-muted);
  font-size: .72rem;
  line-height: 1.1;
}

.cv-book-progress {
  max-width: 620px;
  margin-top: clamp(22px, 2.8cqi, 34px);
}

.cv-book-progress-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
}

.cv-book-progress-head strong {
  display: block;
  margin-top: 5px;
  color: var(--cv-book-text);
  font-size: .9rem;
  font-variant-numeric: tabular-nums;
}

.cv-book-progress-head output {
  color: var(--cv-book-accent-soft);
  font-family: var(--font-monospace);
  font-size: clamp(1.15rem, 2cqi, 1.55rem);
  font-weight: 760;
  font-variant-numeric: tabular-nums;
}

.cv-book-progress-track {
  position: relative;
  height: 7px;
  margin-top: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--cv-book-border) 66%, transparent);
}

.cv-book-progress-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--book-progress, 0%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cv-book-accent), var(--cv-book-accent-soft));
  box-shadow: 0 0 12px color-mix(in srgb, var(--cv-book-accent) 25%, transparent);
  transition: width .28s var(--cv-book-ease);
}

.cv-book-quick-panel {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 22px;
  padding: clamp(18px, 2.2cqi, 26px);
  border: 1px solid var(--cv-book-border);
  border-radius: var(--cv-book-radius-lg);
  background: var(--cv-book-paper);
  box-shadow: 0 14px 34px var(--cv-book-shadow-soft);
  backdrop-filter: blur(12px);
}

.cv-book-control-group {
  min-width: 0;
}

.cv-book-status-controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
  margin-top: 9px;
  padding: 4px;
  border: 1px solid var(--cv-book-border);
  border-radius: 10px;
  background: var(--cv-book-surface-3);
}

.cv-book-status-controls button,
.cv-book-page-control button,
.cv-book-note-actions button {
  min-height: 31px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--cv-book-muted);
  box-shadow: none;
  cursor: pointer;
  transition:
    background .16s var(--cv-book-ease),
    color .16s var(--cv-book-ease),
    border-color .16s var(--cv-book-ease);
}

.cv-book-status-controls button {
  padding: 5px 7px;
  font-size: .68rem;
  font-weight: 680;
  white-space: nowrap;
}

.cv-book-status-controls button:hover,
.cv-book-page-control button:hover,
.cv-book-note-actions button:hover {
  border-color: var(--cv-book-border-strong);
  background: var(--cv-book-hover);
  color: var(--cv-book-text);
}

.cv-book-status-controls button.is-active {
  border-color: color-mix(in srgb, var(--cv-book-accent) 35%, var(--cv-book-border) 65%);
  background: color-mix(in srgb, var(--cv-book-accent) 14%, var(--cv-book-surface-3) 86%);
  color: var(--cv-book-accent-soft);
}

.cv-book-page-control {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto;
  align-items: end;
  gap: 8px;
  margin-top: 9px;
}

.cv-book-page-control label {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.cv-book-page-control label > span {
  color: var(--cv-book-faint);
  font-family: var(--font-monospace);
  font-size: .62rem;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.cv-book-page-control input,
.cv-book-field input {
  width: 100%;
  min-width: 0;
  height: 34px;
  padding: 5px 8px;
  border: 1px solid var(--cv-book-border);
  border-radius: 8px;
  background: var(--cv-book-surface-3);
  color: var(--cv-book-text);
  box-shadow: none;
}

.cv-book-page-control input {
  font-variant-numeric: tabular-nums;
}

.cv-book-page-divider {
  align-self: center;
  margin-top: 15px;
  color: var(--cv-book-faint);
  font-family: var(--font-monospace);
}

.cv-book-page-control button {
  min-height: 34px;
  padding: 5px 9px;
  border-color: var(--cv-book-border);
  font-size: .72rem;
  font-weight: 680;
}

.cv-book-rating {
  display: flex;
  gap: 2px;
  margin-top: 8px;
}

.cv-book-rating button {
  width: 30px;
  height: 30px;
  min-height: 30px;
  padding: 0;
  border: 0;
  background: transparent;
  color: color-mix(in srgb, var(--cv-book-muted) 38%, transparent);
  box-shadow: none;
  cursor: pointer;
  font-size: 1.2rem;
  line-height: 1;
  transition: color .15s, transform .15s;
}

.cv-book-rating button:hover {
  color: var(--cv-book-accent-soft);
  transform: translateY(-1px);
}

.cv-book-rating button.is-active {
  color: var(--cv-book-accent-soft);
}

.cv-book-save-state {
  min-height: 1.2em;
  color: var(--cv-book-faint);
  font-size: .7rem;
  line-height: 1.3;
}

.cv-book-save-state[data-tone="success"] {
  color: var(--text-success, var(--cv-book-accent-soft));
}

.cv-book-save-state[data-tone="error"] {
  color: var(--text-error, var(--text-warning));
}

.cv-book-workspace {
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: clamp(34px, 5cqi, 70px) var(--cv-book-pad) clamp(54px, 7cqi, 90px);
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(280px, .62fr);
  align-items: start;
  gap: var(--cv-book-gap);
}

.cv-book-journal-card,
.cv-book-meta-card,
.cv-book-map-card {
  min-width: 0;
  border: 1px solid var(--cv-book-border);
  border-radius: var(--cv-book-radius-lg);
  background: var(--cv-book-paper);
  box-shadow: 0 10px 30px var(--cv-book-shadow-soft);
}

.cv-book-journal-card {
  overflow: hidden;
}

.cv-book-section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  padding: clamp(18px, 2.5cqi, 28px) clamp(18px, 2.8cqi, 32px);
  border-bottom: 1px solid var(--cv-book-border);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--cv-book-accent) 5%, transparent), transparent 45%),
    var(--cv-book-surface-2);
}

.cv-book-section-head h2,
.cv-book-meta-card h2,
.cv-book-map-card h2 {
  margin: 5px 0 0;
  color: var(--cv-book-text);
  font-size: clamp(1.25rem, 2cqi, 1.65rem);
  line-height: 1.15;
  font-weight: 740;
  letter-spacing: -.02em;
}

.cv-book-note-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 9px;
}

.cv-book-note-actions button {
  min-height: 32px;
  padding: 5px 10px;
  border-color: var(--cv-book-border);
  font-size: .73rem;
  font-weight: 670;
}

.cv-book-note-state {
  color: var(--cv-book-faint);
  font-size: .7rem;
}

.cv-book-note-render,
.cv-book-map-card {
  background-color: var(--cv-book-paper);
  background-image:
    linear-gradient(
      90deg,
      transparent 0 46px,
      var(--cv-book-margin-rule) 46px 47px,
      transparent 47px
    ),
    linear-gradient(
      to bottom,
      transparent calc(var(--cv-book-paper-line) - 2px),
      color-mix(in srgb, var(--cv-book-rule) 55%, transparent) calc(var(--cv-book-paper-line) - 2px)
    );
  background-size:
    100% 100%,
    100% var(--cv-book-paper-line);
  background-repeat:
    no-repeat,
    repeat;
  background-position:
    0 0,
    0 0;
}

.cv-book-note-render {
  position: relative;
  min-height: 460px;
  padding: clamp(22px, 3.4cqi, 42px);
  color: var(--cv-book-text);
}

.cv-book-note-render.is-empty::before {
  content: "Start with a synopsis, then capture ideas, highlights and connections as you read.";
  display: block;
  color: var(--cv-book-faint);
  font-style: italic;
  line-height: 1.7;
}

.cv-book-note-render > .markdown-rendered-content,
.cv-book-note-render > [data-cv-editable-placeholder] {
  width: 100%;
  max-width: none;
  min-width: 0;
}

.cv-book-note-render .markdown-rendered,
.cv-book-note-render .markdown-source-view {
  color: var(--cv-book-text);
}

.cv-book-note-render .markdown-rendered-content > :first-child {
  margin-top: 0;
}

