const bookContext = tp;
const bookContainer = bookContext.container || this;
const bookRoot = bookContainer.querySelector(".cv-book");

if (bookRoot) {
  const bookApp = bookContext.app;
  const bookFile = bookContext.file;
  const initialFrontmatter = bookContext.frontmatter || {};
  const bookBodyContent = String(bookContext.bodyContent || "");
  const bookDocument = bookContext.activeDocument || bookContainer.ownerDocument;
  const bookQuery = selector => bookRoot.querySelector(selector);
  const bookQueryAll = selector => Array.from(bookRoot.querySelectorAll(selector));
  const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

  const asArray = value => {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return [value];
  };

  const text = value => String(value ?? "").trim();

  const scalarText = value => {
    const first = asArray(value)[0];
    if (first === null || first === undefined) return "";
    if (typeof first === "object") {
      return text(first.path ?? first.link ?? first.value ?? first.display ?? "");
    }
    return text(first);
  };

  const cleanWiki = value => text(value)
    .replace(/^!?\[\[([^\]|]+)\|([^\]]+)\]\]$/, "$2")
    .replace(/^!?\[\[([^\]]+)\]\]$/, "$1")
    .trim();

  const canonicalStatus = value => {
    const raw = text(value).toLowerCase();
    if (["currently reading", "reading", "in progress"].includes(raw)) return "Currently reading";
    if (["finished", "read", "completed", "complete"].includes(raw)) return "Finished";
    if (["haven't started", "havent started", "to-read", "to read", "want to read", "not started"].includes(raw)) {
      return "Haven't started";
    }
    return text(value) || "Haven't started";
  };

  const statusLabel = value => {
    const status = canonicalStatus(value);
    if (status === "Currently reading") return "Reading";
    if (status === "Haven't started") return "To read";
    return status;
  };

  const numberValue = (value, fallback = 0) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
  };

  const ratingValue = value => {
    if (typeof value === "number" && Number.isFinite(value)) return Math.max(0, Math.min(5, Math.round(value)));
    const raw = text(value);
    const stars = (raw.match(/[⭐★]/g) || []).length;
    if (stars) return Math.max(0, Math.min(5, stars));
    const numeric = Number(raw);
    return Number.isFinite(numeric) ? Math.max(0, Math.min(5, Math.round(numeric))) : 0;
  };

  const dateValue = value => {
    if (!value) return "";
    if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString().slice(0, 10);
    const raw = text(value);
    const iso = raw.match(/^\d{4}-\d{2}-\d{2}/);
    return iso ? iso[0] : "";
  };

  const coverProperty = hasOwn(initialFrontmatter, "Cover") || !hasOwn(initialFrontmatter, "cover") ? "Cover" : "cover";
  const genreProperty = hasOwn(initialFrontmatter, "Genre") || !hasOwn(initialFrontmatter, "genre") ? "Genre" : "genre";

  const bookState = {
    Title: text(initialFrontmatter.Title),
    Author: text(initialFrontmatter.Author),
    Cover: scalarText(initialFrontmatter[coverProperty]),
    Genre: asArray(initialFrontmatter[genreProperty]).map(item => text(item)).filter(Boolean),
    Status: canonicalStatus(initialFrontmatter.Status),
    CurrentPage: numberValue(initialFrontmatter.CurrentPage),
    TotalPages: numberValue(initialFrontmatter.TotalPages),
    DateStarted: dateValue(initialFrontmatter.DateStarted),
    DateFinished: dateValue(initialFrontmatter.DateFinished),
    Rating: ratingValue(initialFrontmatter.Rating),
  };

  let frontmatterQueue = Promise.resolve();

  function setSaveState(message, tone = "") {
    const state = bookQuery('[data-role="book-save-state"]');
    if (!state) return;
    state.textContent = message;
    state.dataset.tone = tone;
  }

  function updateFrontmatter(patch) {
    if (!bookApp?.fileManager || !bookFile) return Promise.reject(new Error("Book file is unavailable"));
    const task = frontmatterQueue.then(() =>
      bookApp.fileManager.processFrontMatter(bookFile, draft => {
        for (const [property, value] of Object.entries(patch)) {
          draft[property] = value;
        }
      })
    );
    frontmatterQueue = task.catch(() => {});
    return task;
  }

  function localImagePath(value) {
    let raw = scalarText(value);
    if (!raw) return "";

    if (/^(?:https?:|data:|blob:|app:)/i.test(raw)) return raw;

    const markdownImage = raw.match(/^!\[[^\]]*\]\((.+?)\)$/);
    if (markdownImage) {
      raw = markdownImage[1].trim().replace(/^<|>$/g, "");
      if (/^https?:/i.test(raw)) return raw;
    }

    const wiki = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    const candidate = text(wiki ? wiki[1] : raw);
    if (!candidate || !bookApp?.metadataCache || !bookFile) return "";

    const target = bookApp.metadataCache.getFirstLinkpathDest(candidate, bookFile.path);
    if (target) return bookApp.vault.getResourcePath(target);

    if (typeof bookApp.vault.getFileByPath === "function") {
      const direct = bookApp.vault.getFileByPath(candidate);
      if (direct) return bookApp.vault.getResourcePath(direct);

      const parentPath = bookFile.parent?.path || "";
      const relative = parentPath ? `${parentPath}/${candidate}` : candidate;
      const sibling = bookApp.vault.getFileByPath(relative);
      if (sibling) return bookApp.vault.getResourcePath(sibling);
    }

    return "";
  }

  function renderCover() {
    const cover = bookQuery('[data-role="book-cover"]');
    const fallback = bookQuery('[data-role="book-cover-fallback"]');
    if (!cover || !fallback) return;

    const source = localImagePath(bookState.Cover);
    cover.alt = `Cover for ${bookState.Title || bookFile?.basename || "book"}`;

    if (!source) {
      cover.removeAttribute("src");
      cover.hidden = true;
      fallback.hidden = false;
      return;
    }

    fallback.hidden = false;
    cover.hidden = false;
    cover.onload = () => {
      cover.hidden = false;
      fallback.hidden = true;
    };
    cover.onerror = () => {
      cover.hidden = true;
      fallback.hidden = false;
    };
    cover.src = source;

    if (cover.complete && cover.naturalWidth > 0) {
      cover.hidden = false;
      fallback.hidden = true;
    }
  }

  function renderIdentity() {
    const title = bookQuery('[data-role="book-title"]');
    const author = bookQuery('[data-role="book-author"]');

    if (title && bookDocument.activeElement !== title) {
      title.textContent = bookState.Title;
      title.dataset.placeholder = bookFile?.basename || "Untitled book";
    }
    if (author && bookDocument.activeElement !== author) {
      author.textContent = bookState.Author;
      author.dataset.placeholder = "Unknown author";
    }

    const genreList = bookQuery('[data-role="book-genres"]');
    if (genreList) {
      genreList.replaceChildren();
      const genres = bookState.Genre.map(cleanWiki).filter(Boolean);
      const values = genres.length ? genres : ["Uncategorised"];
      for (const genre of values) {
        const chip = bookDocument.createElement("span");
        chip.textContent = genre;
        genreList.appendChild(chip);
      }
    }
  }

  function renderStatus() {
    const badge = bookQuery('[data-role="book-status-badge"]');
    if (badge) {
      badge.textContent = statusLabel(bookState.Status);
      badge.dataset.status = bookState.Status;
    }

    for (const button of bookQueryAll("[data-status-value]")) {
      const active = canonicalStatus(button.dataset.statusValue) === bookState.Status;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    }
  }

  function renderProgress() {
    const safeCurrent = bookState.TotalPages > 0
      ? Math.min(bookState.CurrentPage, bookState.TotalPages)
      : bookState.CurrentPage;
    const percent = bookState.TotalPages > 0
      ? Math.max(0, Math.min(100, Math.round((safeCurrent / bookState.TotalPages) * 100)))
      : 0;

    const pages = bookQuery('[data-role="book-progress-pages"]');
    const percentOutput = bookQuery('[data-role="book-progress-percent"]');
    const fill = bookQuery('[data-role="book-progress-fill"]');
    const track = bookQuery('[data-role="book-progress-track"]');
    const pageInput = bookQuery('[data-role="book-page-input"]');
    const totalInput = bookQuery('[data-role="book-total-input"]');

    if (pages) {
      pages.textContent = bookState.TotalPages > 0
        ? `${safeCurrent} / ${bookState.TotalPages} pages`
        : `${safeCurrent} pages read`;
    }
    if (percentOutput) percentOutput.textContent = bookState.TotalPages > 0 ? `${percent}%` : "—";
    if (fill) fill.style.setProperty("--book-progress", `${percent}%`);
    if (track) {
      track.setAttribute("aria-valuenow", String(percent));
      track.setAttribute(
        "aria-valuetext",
        bookState.TotalPages > 0
          ? `${safeCurrent} of ${bookState.TotalPages} pages, ${percent}%`
          : `${safeCurrent} pages read; total pages unavailable`
      );
    }

    if (pageInput && bookDocument.activeElement !== pageInput) {
      pageInput.value = String(bookState.CurrentPage);
      if (bookState.TotalPages > 0) pageInput.max = String(bookState.TotalPages);
      else pageInput.removeAttribute("max");
    }
    if (totalInput && bookDocument.activeElement !== totalInput) {
      totalInput.value = bookState.TotalPages > 0 ? String(bookState.TotalPages) : "";
    }
  }

  function renderRating() {
    for (const button of bookQueryAll("[data-rating]")) {
      const value = Number(button.dataset.rating);
      const active = value <= bookState.Rating;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(value === bookState.Rating));
    }
  }

  function renderDetails() {
    const coverInput = bookQuery('[data-role="book-cover-input"]');
    const genresInput = bookQuery('[data-role="book-genres-input"]');
    const startedInput = bookQuery('[data-role="book-started-input"]');
    const finishedInput = bookQuery('[data-role="book-finished-input"]');

    if (coverInput && bookDocument.activeElement !== coverInput) coverInput.value = bookState.Cover;
    if (genresInput && bookDocument.activeElement !== genresInput) genresInput.value = bookState.Genre.join(", ");
    if (startedInput && bookDocument.activeElement !== startedInput) startedInput.value = bookState.DateStarted;
    if (finishedInput && bookDocument.activeElement !== finishedInput) finishedInput.value = bookState.DateFinished;
  }

  function renderAll() {
    renderCover();
    renderIdentity();
    renderStatus();
    renderProgress();
    renderRating();
    renderDetails();
  }

  function initInlineTextEditing() {
    for (const element of bookQueryAll("[data-edit-property]")) {
      const property = element.dataset.editProperty;
      if (!property || !(property in bookState)) continue;

      element.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          element.blur();
          return;
        }
        if (event.key === "Escape") {
          event.preventDefault();
          element.textContent = bookState[property] || "";
          element.blur();
        }
      });

      element.addEventListener("blur", async () => {
        const next = text(element.textContent);
        const previous = bookState[property] || "";

        if (property === "Title" && !next) {
          element.textContent = previous;
          setSaveState("Title cannot be empty", "error");
          return;
        }
        if (next === previous) return;

        bookState[property] = next;
        renderIdentity();
        if (property === "Title") renderCover();
        setSaveState(`Saving ${property.toLowerCase()}…`);

        try {
          await updateFrontmatter({ [property]: next });
          setSaveState(`${property} saved`, "success");
        } catch (error) {
          bookState[property] = previous;
          renderIdentity();
          if (property === "Title") renderCover();
          setSaveState(`${property} was not saved`, "error");
          console.error(`[custom-view:book] Could not save ${property}`, error);
        }
      });
    }
  }

  function initStatusControls() {
    for (const button of bookQueryAll("[data-status-value]")) {
      button.addEventListener("click", async () => {
        if (button.disabled) return;
        const next = canonicalStatus(button.dataset.statusValue);
        if (next === bookState.Status) return;

        const previous = bookState.Status;
        bookState.Status = next;
        renderStatus();
        setSaveState("Saving status…");
        for (const peer of bookQueryAll("[data-status-value]")) peer.disabled = true;

        try {
          await updateFrontmatter({ Status: next });
          setSaveState("Status saved", "success");
        } catch (error) {
          bookState.Status = previous;
          renderStatus();
          setSaveState("Status was not saved", "error");
          console.error("[custom-view:book] Could not save Status", error);
        } finally {
          for (const peer of bookQueryAll("[data-status-value]")) peer.disabled = false;
        }
      });
    }
  }

  function initPageControls() {
    const currentInput = bookQuery('[data-role="book-page-input"]');
    const totalInput = bookQuery('[data-role="book-total-input"]');
    const save = bookQuery('[data-action="save-book-pages"]');
    if (!currentInput || !totalInput || !save) return;

    const commit = async () => {
      if (save.disabled) return;

      const nextTotal = Math.round(numberValue(totalInput.value, 0));
      let nextCurrent = Math.round(numberValue(currentInput.value, bookState.CurrentPage));
      if (nextTotal > 0) nextCurrent = Math.min(nextCurrent, nextTotal);

      if (nextCurrent === bookState.CurrentPage && nextTotal === bookState.TotalPages) {
        renderProgress();
        setSaveState("Page progress unchanged");
        return;
      }

      const previous = {
        CurrentPage: bookState.CurrentPage,
        TotalPages: bookState.TotalPages,
      };

      bookState.CurrentPage = nextCurrent;
      bookState.TotalPages = nextTotal;
      renderProgress();
      setSaveState("Saving page progress…");
      save.disabled = true;
      currentInput.disabled = true;
      totalInput.disabled = true;

      try {
        await updateFrontmatter({
          CurrentPage: nextCurrent,
          TotalPages: nextTotal,
        });
        setSaveState("Page progress saved", "success");
      } catch (error) {
        bookState.CurrentPage = previous.CurrentPage;
        bookState.TotalPages = previous.TotalPages;
        renderProgress();
        setSaveState("Page progress was not saved", "error");
        console.error("[custom-view:book] Could not save page progress", error);
      } finally {
        save.disabled = false;
        currentInput.disabled = false;
        totalInput.disabled = false;
      }
    };

    save.addEventListener("click", () => void commit());
    for (const input of [currentInput, totalInput]) {
      input.addEventListener("keydown", event => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        void commit();
      });
    }
  }

  function initRating() {
    for (const button of bookQueryAll("[data-rating]")) {
      button.addEventListener("click", async () => {
        if (button.disabled) return;
        const next = Math.max(1, Math.min(5, Number(button.dataset.rating) || 0));
        if (next === bookState.Rating) return;

        const previous = bookState.Rating;
        bookState.Rating = next;
        renderRating();
        setSaveState("Saving rating…");
        for (const peer of bookQueryAll("[data-rating]")) peer.disabled = true;

        try {
          await updateFrontmatter({ Rating: "⭐".repeat(next) });
          setSaveState("Rating saved", "success");
        } catch (error) {
          bookState.Rating = previous;
          renderRating();
          setSaveState("Rating was not saved", "error");
          console.error("[custom-view:book] Could not save Rating", error);
        } finally {
          for (const peer of bookQueryAll("[data-rating]")) peer.disabled = false;
        }
      });
    }
  }

  function splitGenres(value) {
    return text(value)
      .split(",")
      .map(item => item.trim())
      .filter(Boolean);
  }

  function initDetailEditors() {
    const coverInput = bookQuery('[data-role="book-cover-input"]');
    const genresInput = bookQuery('[data-role="book-genres-input"]');
    const startedInput = bookQuery('[data-role="book-started-input"]');
    const finishedInput = bookQuery('[data-role="book-finished-input"]');

    if (coverInput) {
      const commitCover = async () => {
        const next = text(coverInput.value);
        if (next === bookState.Cover) return;
        const previous = bookState.Cover;
        bookState.Cover = next;
        renderCover();
        setSaveState("Saving cover…");

        try {
          await updateFrontmatter({ [coverProperty]: next });
          const resolved = !next || !!localImagePath(next);
          setSaveState(
            resolved ? "Cover saved" : "Cover saved, but the image could not be resolved",
            resolved ? "success" : "error"
          );
        } catch (error) {
          bookState.Cover = previous;
          renderCover();
          renderDetails();
          setSaveState("Cover was not saved", "error");
          console.error("[custom-view:book] Could not save Cover", error);
        }
      };

      coverInput.addEventListener("change", () => void commitCover());
      coverInput.addEventListener("keydown", event => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        coverInput.blur();
      });
    }

    if (genresInput) {
      const commitGenres = async () => {
        const next = splitGenres(genresInput.value);
        if (JSON.stringify(next) === JSON.stringify(bookState.Genre)) return;
        const previous = [...bookState.Genre];
        bookState.Genre = next;
        renderIdentity();
        setSaveState("Saving genres…");

        try {
          await updateFrontmatter({ [genreProperty]: next });
          setSaveState("Genres saved", "success");
        } catch (error) {
          bookState.Genre = previous;
          renderIdentity();
          renderDetails();
          setSaveState("Genres were not saved", "error");
          console.error(`[custom-view:book] Could not save ${genreProperty}`, error);
        }
      };

      genresInput.addEventListener("change", () => void commitGenres());
      genresInput.addEventListener("keydown", event => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        genresInput.blur();
      });
    }

    const initDate = (input, property, label) => {
      if (!input) return;
      input.addEventListener("change", async () => {
        const next = dateValue(input.value);
        if (next === bookState[property]) return;
        const previous = bookState[property];
        bookState[property] = next;
        setSaveState(`Saving ${label.toLowerCase()} date…`);

        try {
          await updateFrontmatter({ [property]: next || null });
          setSaveState(`${label} date saved`, "success");
        } catch (error) {
          bookState[property] = previous;
          renderDetails();
          setSaveState(`${label} date was not saved`, "error");
          console.error(`[custom-view:book] Could not save ${property}`, error);
        }
      });
    };

    initDate(startedInput, "DateStarted", "Started");
    initDate(finishedInput, "DateFinished", "Finished");
  }

  function initNoteEditor() {
    const render = bookQuery('[data-role="book-note-render"]');
    const state = bookQuery('[data-role="book-note-state"]');
    if (!render || !state) return;

    const nativePlaceholder = render.querySelector("[data-cv-editable-placeholder]");
    if (nativePlaceholder) {
      bookRoot.classList.add("is-native-editor");
      state.textContent = "Live Preview · autosaved by Obsidian";
      return;
    }

    render.classList.toggle("is-empty", !bookBodyContent.trim());
    render.setAttribute("tabindex", "0");
    render.setAttribute("role", "textbox");
    render.setAttribute("aria-label", "Reading notebook. Click to edit.");
    state.textContent = "Click to edit";

    let openingEditor = false;

    const openInlineEditor = async () => {
      if (openingEditor) return;
      const leaves = typeof bookApp?.workspace?.getLeavesOfType === "function"
        ? bookApp.workspace.getLeavesOfType("markdown")
        : [];
      const leaf = leaves.find(candidate =>
        candidate?.view?.file?.path === bookFile?.path &&
        candidate.view.contentEl?.contains(bookContainer)
      );

      if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
        state.textContent = "Open this note in Live Preview to edit here";
        return;
      }

      state.textContent = "Opening inline editor…";
      openingEditor = true;

      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode: "source",
            source: false,
          },
        });
      } catch (error) {
        state.textContent = "Could not open inline editor";
        openingEditor = false;
        console.error("[custom-view:book] Could not enter Live Preview", error);
      }
    };

    render.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void openInlineEditor();
    });
    render.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void openInlineEditor();
    });
  }

  function initPaperTape() {
    const paper = bookQuery(".cv-book-journal-card");
    if (!paper) return;
    const seed = String(bookFile?.path || bookFile?.basename || "book-note");
    let hash = 0;
    for (const character of seed) hash = ((hash * 31) + character.charCodeAt(0)) | 0;
    paper.dataset.tapeSide = Math.abs(hash) % 2 ? "right" : "left";
  }

  function initJournalMinimumHeight() {
    const journal = bookQuery(".cv-book-journal-card");
    const metadata = bookQuery(".cv-book-meta-column");
    if (!journal || !metadata) return;

    const syncHeight = () => {
      if (!journal.isConnected || !metadata.isConnected) return;
      const journalRect = journal.getBoundingClientRect();
      const metadataRect = metadata.getBoundingClientRect();
      const sideBySide = Math.abs(journalRect.top - metadataRect.top) < 2;
      if (!sideBySide) {
        journal.style.removeProperty("--cv-book-journal-min-height");
        return;
      }
      const lineHeight = Number.parseFloat(
        bookDocument.defaultView?.getComputedStyle?.(bookRoot)
          ?.getPropertyValue("--cv-book-paper-line")
      ) || 30;
      const minimum = Math.max(lineHeight * 14, Math.ceil(metadataRect.height));
      journal.style.setProperty("--cv-book-journal-min-height", `${minimum}px`);
    };

    const ResizeObserverClass = bookDocument.defaultView?.ResizeObserver;
    if (ResizeObserverClass) {
      const observer = new ResizeObserverClass(syncHeight);
      observer.observe(bookRoot);
      observer.observe(metadata);
    }
    bookDocument.defaultView?.requestAnimationFrame?.(syncHeight);
  }

  renderAll();
  initInlineTextEditing();
  initStatusControls();
  initPageControls();
  initRating();
  initDetailEditors();
  initNoteEditor();
  initPaperTape();
  initJournalMinimumHeight();
}

views.css:
.obsidian-custom-view-render:has(> .cv-finance) {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: 0 !important;
  overflow-x: clip;
}

.cv-finance {
  --fin-bg: var(--cc-p00, var(--background-primary));
  --fin-surface: color-mix(in srgb, var(--cc-p01, var(--background-secondary)) 88%, var(--cc-p02, var(--background-primary)) 12%);
  --fin-surface-2: color-mix(in srgb, var(--cc-p02, var(--background-secondary)) 82%, var(--cc-p03, var(--background-primary)) 18%);
  --fin-surface-hover: color-mix(in srgb, var(--cc-p03, var(--background-modifier-hover)) 72%, var(--cc-p04, var(--background-modifier-hover)) 28%);
  --fin-border: color-mix(in srgb, var(--cc-p06, var(--background-modifier-border)) 48%, transparent);
  --fin-border-strong: color-mix(in srgb, var(--cc-p07, var(--background-modifier-border)) 68%, transparent);
  --fin-text: var(--cc-p12, var(--text-normal));
  --fin-muted: var(--cc-p09, var(--text-muted));
  --fin-faint: var(--cc-p07, var(--text-faint));
  --fin-accent: var(--cc-accent, var(--interactive-accent));
  --fin-accent-soft: var(--cc-p10, var(--text-accent));
  --fin-positive: var(--color-green, var(--fin-accent));
  --fin-negative: var(--color-red, var(--fin-accent));
  --fin-warning: var(--color-yellow, var(--fin-accent));
  --fin-radius-lg: 16px;
  --fin-radius-md: 12px;
  --fin-radius-sm: 8px;
  --fin-gap: clamp(12px, 1.8cqi, 22px);
  --fin-pad: clamp(14px, 2.2cqi, 28px);
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: grid;
  gap: var(--fin-gap);
  overflow-x: clip;
  color: var(--fin-text);
  container-type: inline-size;
}

.cv-finance,
.cv-finance * {
  box-sizing: border-box;
}

.cv-finance-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--fin-gap);
  padding: 2px 2px 0;
}

.cv-finance-heading {
  min-width: 0;
}

.cv-finance-eyebrow,
.cv-finance-panel-kicker {
  display: block;
  margin-bottom: 5px;
  color: var(--fin-accent-soft);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.cv-finance-heading h1,
.cv-finance-panel-head h2 {
  margin: 0;
  color: var(--fin-text);
  line-height: 1.1;
}

.cv-finance-heading h1 {
  font-size: clamp(1.55rem, 4cqi, 2.45rem);
}

.cv-finance-heading p,
.cv-finance-panel-head p {
  margin: 6px 0 0;
  color: var(--fin-muted);
}

.cv-finance-header-actions {
  display: grid;
  justify-items: end;
  gap: 8px;
}

.cv-finance-currency {
  color: var(--fin-muted);
  font-size: .74rem;
  letter-spacing: .04em;
}

.cv-finance-range {
  display: inline-flex;
  align-items: center;
  padding: 3px;
  border: 1px solid var(--fin-border);
  border-radius: 10px;
  background: var(--fin-surface);
}

.cv-finance-range button {
  min-width: 0;
  margin: 0;
  padding: 6px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--fin-muted);
  box-shadow: none;
  font-size: .76rem;
  line-height: 1.15;
}

.cv-finance-range button:hover,
.cv-finance-range button:focus-visible {
  background: var(--fin-surface-hover);
  color: var(--fin-text);
}

.cv-finance-range button.is-active {
  background: color-mix(in srgb, var(--fin-accent) 16%, var(--fin-surface-2));
  color: var(--fin-text);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fin-accent) 36%, transparent);
}

.cv-finance-warning {
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--fin-warning) 38%, var(--fin-border));
  border-radius: var(--fin-radius-md);
  background: color-mix(in srgb, var(--fin-warning) 7%, var(--fin-surface));
  color: var(--fin-text);
}

.cv-finance-warning strong {
  display: block;
  margin-bottom: 4px;
}

.cv-finance-warning ul {
  margin: 0;
  padding-left: 1.2rem;
  color: var(--fin-muted);
}

.cv-finance-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--fin-gap);
}

.cv-finance-kpi,
.cv-finance-panel {
  border: 1px solid var(--fin-border);
  background: var(--fin-surface);
  box-shadow: 0 12px 32px color-mix(in srgb, var(--fin-bg) 42%, transparent);
}

.cv-finance-kpi {
  min-width: 0;
  padding: clamp(15px, 2cqi, 23px);
  border-radius: var(--fin-radius-md);
  background-image: linear-gradient(
    155deg,
    color-mix(in srgb, var(--fin-accent) 4%, transparent),
    transparent 58%
  );
}

.cv-finance-kpi-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--fin-muted);
  font-size: .8rem;
}

.cv-finance-kpi-value {
  display: block;
  margin-top: 12px;
  overflow-wrap: anywhere;
  color: var(--fin-text);
  font-size: clamp(1.35rem, 3.2cqi, 2.05rem);
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
}

.cv-finance-kpi-detail {
  display: block;
  margin-top: 14px;
  color: var(--fin-muted);
  font-size: .76rem;
  line-height: 1.35;
}

.cv-finance-kpi[data-tone="positive"] .cv-finance-kpi-value {
  color: color-mix(in srgb, var(--fin-positive) 62%, var(--fin-text));
}

.cv-finance-kpi[data-tone="negative"] .cv-finance-kpi-value {
  color: color-mix(in srgb, var(--fin-negative) 56%, var(--fin-text));
}

.cv-finance-kpi[data-tone="warning"] .cv-finance-kpi-value {
  color: color-mix(in srgb, var(--fin-warning) 60%, var(--fin-text));
}

.cv-finance-trend {
  flex: 0 0 auto;
  padding: 3px 6px;
  border: 1px solid var(--fin-border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--fin-surface-2) 82%, transparent);
  font-size: .68rem;
  font-variant-numeric: tabular-nums;
}

.cv-finance-trend[data-tone="positive"] {
  border-color: color-mix(in srgb, var(--fin-positive) 42%, var(--fin-border));
  color: var(--fin-positive);
}

.cv-finance-trend[data-tone="negative"] {
  border-color: color-mix(in srgb, var(--fin-negative) 42%, var(--fin-border));
  color: var(--fin-negative);
}

.cv-finance-panel {
  min-width: 0;
  overflow: hidden;
  border-radius: var(--fin-radius-lg);
}

.cv-finance-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px var(--fin-pad) 14px;
  border-bottom: 1px solid var(--fin-border);
  background: color-mix(in srgb, var(--fin-surface-2) 58%, var(--fin-surface));
}

.cv-finance-panel-head h2 {
  font-size: 1rem;
}

.cv-finance-panel-head p {
  font-size: .76rem;
}

.cv-finance-chart {
  min-height: 250px;
  padding: clamp(15px, 2.4cqi, 28px);
  background: color-mix(in srgb, var(--fin-surface) 92%, var(--fin-bg) 8%);
}

.cv-finance-chart--primary {
  min-height: clamp(300px, 35cqi, 430px);
}

.cv-finance-analysis-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, .8fr);
  gap: var(--fin-gap);
}

.cv-finance-svg {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  overflow: hidden;
}

.cv-finance-gridline {
  stroke: var(--fin-border);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.cv-finance-axis-label {
  fill: var(--fin-faint);
  font-size: 12px;
}

.cv-finance-line {
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.cv-finance-line.cv-finance-series-1 {
  stroke: var(--fin-accent);
}

.cv-finance-line.cv-finance-series-2 {
  stroke: var(--fin-accent-soft);
}

.cv-finance-area.cv-finance-series-1 {
  fill: color-mix(in srgb, var(--fin-accent) 1%, transparent);
}

.cv-finance-area.cv-finance-series-2 {
  fill: color-mix(in srgb, var(--fin-accent-soft) 10%, transparent);
}

.cv-finance-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 10px;
  color: var(--fin-muted);
  font-size: .7rem;
}

.cv-finance-legend-item::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 6px;
  border-radius: 50%;
  background: var(--fin-accent);
}

.cv-finance-legend-item.cv-finance-series-2::before,
.cv-finance-legend-item.is-expense::before {
  background: var(--fin-negative);
}

.cv-finance-legend-item.is-income::before {
  background: var(--fin-positive);
}

.cv-finance-grouped-bars {
  min-height: 205px;
  display: flex;
  align-items: stretch;
  justify-content: stretch;
  gap: clamp(6px, 1.4cqi, 14px);
  padding-top: 8px;
  border-bottom: 1px solid var(--fin-border);
}

.cv-finance-bar-group {
  flex: 1 1 0;
  min-width: 0;
  display: grid;
  grid-template-rows: minmax(150px, 1fr) auto;
  gap: 8px;
}

.cv-finance-bar-pair {
  min-width: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
}

.cv-finance-bar {
  width: min(28%, 30px);
  min-height: 2px;
  height: var(--fin-bar-size);
  border-radius: 4px 4px 1px 1px;
  transition: filter .15s ease, opacity .15s ease;
}

.cv-finance-bar:hover {
