}

.cv-finance-table-amount,
.cv-finance-amount {
  text-align: right !important;
  font-variant-numeric: tabular-nums;
}

.cv-finance-type-pill {
  display: inline-flex;
  align-items: center;
  padding: 3px 7px;
  border: 1px solid var(--fin-border);
