}

.cv-finance-type-pill[data-type="income"] {
  border-color: color-mix(in srgb, var(--fin-positive) 38%, var(--fin-border));
  color: var(--fin-positive);
}

.cv-finance-type-pill[data-type="expense"] {
  border-color: color-mix(in srgb, var(--fin-negative) 38%, var(--fin-border));
