}

@container (max-width: 980px) {
  .cv-finance-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cv-finance-analysis-grid {
    grid-template-columns: 1fr;
  }
}

@container (max-width: 700px) {
  .cv-finance-header {
    align-items: stretch;
    flex-direction: column;
  }

  .cv-finance-header-actions {
