/* Financial worksheet rework: one continuous paper plane and compact prompts. */
.cv-finance {
  --fin-paper-line: var(--vault-note-paper-line, 30px);
  --fin-paper: var(--vault-note-paper-bg, color-mix(in srgb, var(--background-primary) 91%, var(--background-secondary) 9%));
  --fin-paper-rule: var(--vault-note-paper-rule, color-mix(in oklch, var(--interactive-accent) 15%, transparent));
}

.cv-finance-review {
  position: relative;
  min-height: calc(var(--fin-paper-line) * 10);
  overflow: hidden;
  isolation: isolate;
  border: 1px solid var(--vault-note-paper-edge, var(--fin-border-strong));
  border-radius: 3px;
  background:
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--fin-paper-line) - 7px),
      color-mix(in srgb, var(--fin-paper-rule) 55%, transparent)
        calc(var(--fin-paper-line) - 7px)
        calc(var(--fin-paper-line) - 5px),
      transparent calc(var(--fin-paper-line) - 5px) var(--fin-paper-line)
    ),
    var(--fin-paper);
  box-shadow: 0 18px 46px color-mix(in srgb, var(--shadow, #000) 22%, transparent);
}


.cv-finance-review .cv-finance-panel-head {
  position: relative;
  z-index: 1;
  align-items: center;
  height: calc(var(--fin-paper-line) * 2);
  min-height: calc(var(--fin-paper-line) * 2);
  padding: 0 clamp(18px, 2.8cqi, 32px);
  border-bottom: 1px solid color-mix(in srgb, var(--fin-accent) 30%, var(--fin-border-strong));
  background: transparent;
}

.cv-finance-review .cv-finance-panel-head :is(.cv-finance-panel-kicker, h2, p) {
  margin-block: 0;
}

.cv-finance-review .cv-finance-note-render {
  position: relative;
  z-index: 1;
  min-height: calc(var(--fin-paper-line) * 8);
  padding: 0 clamp(18px, 2.8cqi, 32px) var(--fin-paper-line);
  background: transparent;
  line-height: var(--fin-paper-line);
}

.cv-finance:not(.is-native-editor) .cv-finance-note-render:hover {
  background: transparent;
}

/* The card header already supplies the worksheet title in read mode. */
.cv-finance:not(.is-native-editor) .cv-finance-note-render .markdown-preview-sizer > h2:first-child {
  display: none;
}

.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h3, h4, h5, h6, p, ul, ol),
.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) > li {
  margin-block: 0;
}

.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h3, h4, h5, h6),
.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > p,
.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) > li,
.cv-finance-note-render .cm-line {
  min-height: var(--fin-paper-line);
  line-height: var(--fin-paper-line);
}

.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) {
  padding-block: 0;
  padding-inline-start: 1.25rem;
}

.cv-finance-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(ul, ol) + :is(h3, h4, h5, h6) {
  margin-top: var(--fin-paper-line);
}

.cv-finance-note-render .cm-content {
  line-height: var(--fin-paper-line);
}

.cv-finance-note-render [data-cv-editable-placeholder],
.cv-finance-note-render [data-cv-editable-placeholder] .markdown-source-view,
.cv-finance-note-render [data-cv-editable-placeholder] :is(.cm-editor, .cm-scroller, .cm-sizer, .cm-contentContainer, .cm-content) {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.cv-finance-note-render [data-cv-editable-placeholder] .markdown-source-view,
.cv-finance-note-render [data-cv-editable-placeholder] .cm-editor {
  position: relative !important;
  inset: auto !important;
}

.cv-finance-note-render [data-cv-editable-placeholder] .cm-scroller {
  overflow: visible !important;
}

.cv-finance-note-render [data-cv-editable-placeholder] .cm-content {
  padding: 0 !important;
}

.cv-finance-note-render:focus-visible {
  outline: 2px solid var(--fin-accent);
  outline-offset: 3px;
}

@container (max-width: 480px) {
  .cv-finance-review .cv-finance-panel-head {
    padding-inline: 16px;
  }

  .cv-finance-review .cv-finance-note-render {
    padding-inline: 16px;
  }
}

.cv-finance-quick-add {
