const financeContext = tp;
const financeContainer = financeContext.container || this;
const financeRoot = financeContainer.querySelector(".cv-finance");

if (financeRoot) {
  const financeApp = financeContext.app;
  const financeFile = financeContext.file;
  const reportFrontmatter = financeContext.frontmatter || {};
  const reportBodyContent = String(financeContext.bodyContent || "");
  const financeDocument = financeContext.activeDocument || financeContainer.ownerDocument;
  const q = selector => financeRoot.querySelector(selector);
  const qa = selector => Array.from(financeRoot.querySelectorAll(selector));
  const GLOBAL_SETTINGS_PATH = "90_System/93_Configuration/settings.md";

  const RECORDS = Object.freeze({
    account: "FinanceAccount",
    transaction: "FinanceTransaction",
    commitment: "FinanceCommitment",
  });
  const RANGE_LABELS = Object.freeze({
    week: "Weekly",
    month: "Monthly",
    quarter: "Quarterly",
    year: "Yearly",
  });
  const RANGE_ORDER = ["week", "month", "quarter", "year"];
  const DAY_MS = 86400000;

  const text = value => String(value ?? "").trim();

  const numberValue = (value, fallback = NaN) => {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    if (typeof value === "string" && value.trim() !== "") {
      const parsed = Number(value.replaceAll(",", ""));
      if (Number.isFinite(parsed)) return parsed;
    }
    return fallback;
  };

  const boolValue = (value, fallback = false) => {
    if (typeof value === "boolean") return value;
    const raw = text(value).toLowerCase();
    if (["true", "yes", "1", "on"].includes(raw)) return true;
    if (["false", "no", "0", "off"].includes(raw)) return false;
    return fallback;
  };

  const currencyCode = value => {
    const code = text(value).toUpperCase();
    return /^[A-Z]{3}$/.test(code) ? code : "";
  };

  const normalizeRange = value => {
    const raw = text(value).toLowerCase();
    if (["week", "weekly"].includes(raw)) return "week";
    if (["month", "monthly"].includes(raw)) return "month";
    if (["quarter", "quarterly"].includes(raw)) return "quarter";
    if (["year", "yearly", "annual"].includes(raw)) return "year";
    return "month";
  };

  const parseDate = value => {
    if (value instanceof Date && !Number.isNaN(value.getTime())) {
      return new Date(value.getFullYear(), value.getMonth(), value.getDate());
    }
    const raw = text(value);
    const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (match) {
      const parsed = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
      return Number.isNaN(parsed.getTime()) ? null : parsed;
    }
    if (raw) {
      const parsed = new Date(raw);
      if (!Number.isNaN(parsed.getTime())) {
        return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
      }
    }
    return null;
  };

  const addDays = (date, days) => {
    const copy = new Date(date);
    copy.setDate(copy.getDate() + days);
    return copy;
  };

  const addMonths = (date, months) => {
    const copy = new Date(date);
    copy.setMonth(copy.getMonth() + months);
    return copy;
  };

  function collectFinanceRecords() {
    const records = [];
    const files = typeof financeApp?.vault?.getMarkdownFiles === "function"
      ? financeApp.vault.getMarkdownFiles()
      : [];

    for (const file of files) {
      if (!file.path.startsWith("20_Personal_Life/22_Finance/Records/")) continue;
      const cache = financeApp.metadataCache?.getFileCache?.(file);
      const frontmatter = cache?.frontmatter;
      const recordType = text(frontmatter?.RecordType);
      if (!recordType.startsWith("Finance")) continue;
      records.push({ file, frontmatter });
    }
    return records;
  }

  const allRecords = collectFinanceRecords();
  const globalSettingsFile = financeApp?.vault?.getAbstractFileByPath?.(GLOBAL_SETTINGS_PATH);
  const globalSettings = globalSettingsFile
    ? financeApp.metadataCache?.getFileCache?.(globalSettingsFile)?.frontmatter || {}
    : {};
  const reportBook = text(reportFrontmatter.FinanceBook)
    || text(globalSettings.FinanceBook)
    || "default";
  const settingValue = key => globalSettings?.[key] ?? reportFrontmatter?.[key];

  const settings = {
    FinanceSchema: numberValue(settingValue("FinanceSchema"), 1),
    FinanceBook: reportBook,
    BookCurrency: currencyCode(globalSettings.BookCurrency) || currencyCode(reportFrontmatter.BookCurrency),
    DisplayLocale: text(settingValue("DisplayLocale")) || "auto",
    CurrencyDisplay: text(settingValue("CurrencyDisplay")) || "symbol",
    NegativeFormat: text(settingValue("NegativeFormat")) || "standard",
    WeekStartsOn: text(settingValue("WeekStartsOn")).toLowerCase() || "monday",
    FiscalYearStartMonth: Math.max(
      1,
      Math.min(12, Math.round(numberValue(settingValue("FiscalYearStartMonth"), 1)))
    ),
    Budgets: settingValue("Budgets") ?? {},
  };

  const locale = settings.DisplayLocale === "auto" ? undefined : settings.DisplayLocale;
  const bookCurrency = settings.BookCurrency;

  function makeMoneyFormatter(currency, compact = false, currencyDisplay = settings.CurrencyDisplay) {
    if (!currency) return null;
    const options = {
      style: "currency",
      currency,
      currencyDisplay: ["symbol", "narrowSymbol", "code", "name"].includes(currencyDisplay)
        ? currencyDisplay
        : "symbol",
      currencySign: settings.NegativeFormat === "accounting" ? "accounting" : "standard",
    };
    if (compact) {
      options.notation = "compact";
      options.maximumFractionDigits = 1;
    }
    try {
      return new Intl.NumberFormat(locale, options);
    } catch {
      try {
        return new Intl.NumberFormat(undefined, { ...options, currencyDisplay: "code" });
      } catch {
        return null;
      }
    }
  }

  const bookMoney = makeMoneyFormatter(bookCurrency);
  const compactMoney = makeMoneyFormatter(bookCurrency, true);
  const percentFormatter = (() => {
    try {
      return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 });
    } catch {
      return new Intl.NumberFormat(undefined, { style: "percent", maximumFractionDigits: 1 });
    }
  })();
  const dateFormatter = (() => {
    try {
      return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" });
    } catch {
      return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" });
    }
  })();
  const monthFormatter = (() => {
    try {
      return new Intl.DateTimeFormat(locale, { month: "short" });
    } catch {
      return new Intl.DateTimeFormat(undefined, { month: "short" });
    }
  })();
  const longMonthFormatter = (() => {
    try {
      return new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" });
    } catch {
      return new Intl.DateTimeFormat(undefined, { month: "long", year: "numeric" });
    }
  })();

  const displayMoney = value => {
    if (!Number.isFinite(value)) return "—";
    if (bookMoney) return bookMoney.format(value);
    return `${value.toLocaleString(locale)}${bookCurrency ? ` ${bookCurrency}` : ""}`;
  };

  const displayCompactMoney = value => {
    if (!Number.isFinite(value)) return "—";
    if (compactMoney) return compactMoney.format(value);
    return displayMoney(value);
  };

  const displayNativeMoney = (value, currency) => {
    if (!Number.isFinite(value)) return "—";
    const formatter = makeMoneyFormatter(currency);
    return formatter ? formatter.format(value) : `${value.toLocaleString(locale)} ${currency || ""}`.trim();
  };

  const warnings = [];
  const warnOnce = message => {
    if (!warnings.includes(message)) warnings.push(message);
  };

  const accountRecords = allRecords.filter(record =>
    text(record.frontmatter.RecordType) === RECORDS.account &&
    (text(record.frontmatter.FinanceBook) || "default") === reportBook
  );

  const accounts = accountRecords.map(record => {
    const fm = record.frontmatter;
    return {
      file: record.file,
      id: text(fm.AccountId) || record.file.path,
      name: text(fm.Account) || record.file.basename,
      type: text(fm.AccountType) || "account",
      currency: currencyCode(fm.Currency) || bookCurrency,
      openingBalance: numberValue(fm.OpeningBalance, 0),
      baseOpeningBalance: numberValue(fm.BaseOpeningBalance),
      openingFxRate: numberValue(fm.OpeningFxRateToBase),
      openingDate: parseDate(fm.OpeningDate),
      includeInNetWorth: boolValue(fm.IncludeInNetWorth, true),
      active: boolValue(fm.Active, true),
    };
  });

  const accountByName = new Map();
  for (const account of accounts) {
    accountByName.set(account.name.toLowerCase(), account);
    accountByName.set(account.id.toLowerCase(), account);
  }

  function normalizeToBook(amount, currency, baseAmount, fxRate, label) {
    if (!Number.isFinite(amount)) return NaN;
    if (!bookCurrency) return NaN;
    const code = currencyCode(currency) || bookCurrency;
    if (code === bookCurrency) return amount;
    if (Number.isFinite(baseAmount)) return baseAmount;
    if (Number.isFinite(fxRate) && fxRate > 0) return amount * fxRate;
    warnOnce(`${label || "A record"} uses ${code} without BaseAmount or FxRateToBase.`);
    return NaN;
  }

  const openingBalanceBase = account => {
    if (!account.includeInNetWorth) return 0;
    return normalizeToBook(
      account.openingBalance,
      account.currency,
      account.baseOpeningBalance,
      account.openingFxRate,
      `Account ${account.name}`
    );
  };

  const transactionRecords = allRecords.filter(record =>
    text(record.frontmatter.RecordType) === RECORDS.transaction &&
    (text(record.frontmatter.FinanceBook) || "default") === reportBook
  );

  const transactions = transactionRecords.map(record => {
    const fm = record.frontmatter;
    const accountName = text(fm.Account);
    const account = accountByName.get(accountName.toLowerCase());
    const amount = Math.abs(numberValue(fm.Amount));
    const currency = currencyCode(fm.Currency) || account?.currency || bookCurrency;
    const baseAmount = normalizeToBook(
      amount,
      currency,
      numberValue(fm.BaseAmount),
      numberValue(fm.FxRateToBase),
      `Transaction ${record.file.basename}`
    );
    const type = text(fm.Type).toLowerCase() || "expense";
    const feeAmount = Math.abs(numberValue(fm.FeeAmount));
    const feeCurrency = currencyCode(fm.FeeCurrency) || currency;
    const feeBaseAmount = Number.isFinite(feeAmount)
      ? normalizeToBook(
          feeAmount,
          feeCurrency,
          numberValue(fm.FeeBaseAmount),
          numberValue(fm.FeeFxRateToBase),
          `Transfer fee ${record.file.basename}`
        )
      : 0;

    return {
      file: record.file,
      id: text(fm.TransactionId) || record.file.path,
      date: parseDate(fm.Date),
      type,
      description: text(fm.Description) || record.file.basename,
      amount,
      currency,
      baseAmount,
      account: accountName || "—",
      category: text(fm.Category) || "Uncategorised",
      fixed: boolValue(fm.Fixed, false) || Boolean(text(fm.CommitmentId)),
      commitmentId: text(fm.CommitmentId),
      feeBaseAmount: Number.isFinite(feeBaseAmount) ? feeBaseAmount : 0,
    };
  }).filter(transaction => transaction.date);

  const commitmentRecords = allRecords.filter(record =>
    text(record.frontmatter.RecordType) === RECORDS.commitment &&
    (text(record.frontmatter.FinanceBook) || "default") === reportBook
  );

  const commitments = commitmentRecords.map(record => {
    const fm = record.frontmatter;
    const accountName = text(fm.Account);
    const account = accountByName.get(accountName.toLowerCase());
    const amount = Math.abs(numberValue(fm.Amount));
    const currency = currencyCode(fm.Currency) || account?.currency || bookCurrency;
    return {
      file: record.file,
      id: text(fm.CommitmentId) || record.file.path,
      name: text(fm.Name) || record.file.basename,
      amount,
      currency,
      baseAmount: normalizeToBook(
        amount,
        currency,
        numberValue(fm.BaseAmount),
        numberValue(fm.FxRateToBase),
        `Commitment ${record.file.basename}`
      ),
      category: text(fm.Category) || "Fixed",
      frequency: text(fm.Frequency).toLowerCase() || "monthly",
      dueDay: Math.max(1, Math.min(31, Math.round(numberValue(fm.DueDay, 1)))),
      startDate: parseDate(fm.StartDate),
      endDate: parseDate(fm.EndDate),
      active: boolValue(fm.Active, true),
    };
  });

  function transactionDelta(transaction) {
    if (!Number.isFinite(transaction.baseAmount)) return 0;
    if (transaction.type === "income") return transaction.baseAmount;
    if (transaction.type === "expense") return -transaction.baseAmount;
    if (transaction.type === "transfer") return -Math.max(0, transaction.feeBaseAmount || 0);
    return 0;
  }

  function rangeBounds(range, anchor) {
    const date = new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate());
    if (range === "week") {
      const startDay = settings.WeekStartsOn === "sunday" ? 0 : 1;
      const offset = (date.getDay() - startDay + 7) % 7;
      const start = addDays(date, -offset);
      return { start, end: addDays(start, 7) };
    }
    if (range === "month") {
      const start = new Date(date.getFullYear(), date.getMonth(), 1);
      return { start, end: new Date(date.getFullYear(), date.getMonth() + 1, 1) };
    }
    if (range === "quarter") {
      const fiscalStart = settings.FiscalYearStartMonth - 1;
      const relativeMonth = (date.getMonth() - fiscalStart + 12) % 12;
      const quarterOffset = relativeMonth - (relativeMonth % 3);
      let startYear = date.getFullYear();
      let startMonth = fiscalStart + quarterOffset;
      if (startMonth >= 12) {
        startMonth -= 12;
        startYear += 1;
      }
      if (new Date(startYear, startMonth, 1) > date) startYear -= 1;
      const start = new Date(startYear, startMonth, 1);
      return { start, end: addMonths(start, 3) };
    }
    const fiscalStart = settings.FiscalYearStartMonth - 1;
    const startYear = date.getMonth() >= fiscalStart ? date.getFullYear() : date.getFullYear() - 1;
    const start = new Date(startYear, fiscalStart, 1);
    return { start, end: new Date(startYear + 1, fiscalStart, 1) };
  }

  function previousBounds(range, bounds) {
    if (range === "week") return { start: addDays(bounds.start, -7), end: bounds.start };
    if (range === "month") return { start: addMonths(bounds.start, -1), end: bounds.start };
    if (range === "quarter") return { start: addMonths(bounds.start, -3), end: bounds.start };
    return { start: addMonths(bounds.start, -12), end: bounds.start };
  }

  const inRange = (date, bounds) => date >= bounds.start && date < bounds.end;

  function periodTransactions(bounds) {
    return transactions.filter(transaction => inRange(transaction.date, bounds));
  }

  function periodMetrics(bounds) {
    const rows = periodTransactions(bounds);
    let income = 0;
    let expenses = 0;
    let fixedExpenses = 0;

    for (const transaction of rows) {
      if (!Number.isFinite(transaction.baseAmount)) continue;
      if (transaction.type === "income") income += transaction.baseAmount;
      if (transaction.type === "expense") {
        expenses += transaction.baseAmount;
        if (transaction.fixed) fixedExpenses += transaction.baseAmount;
      }
      if (transaction.type === "transfer" && transaction.feeBaseAmount > 0) {
        expenses += transaction.feeBaseAmount;
      }
    }

    const net = income - expenses;
    return {
      rows,
      income,
      expenses,
      fixedExpenses,
      variableExpenses: Math.max(0, expenses - fixedExpenses),
      net,
      savingsRate: income > 0 ? net / income : NaN,
    };
  }

  function balanceAt(dateExclusive) {
    let total = 0;
    for (const account of accounts) {
      if (!account.includeInNetWorth) continue;
      if (account.openingDate && account.openingDate >= dateExclusive) continue;
      const opening = openingBalanceBase(account);
      if (Number.isFinite(opening)) total += opening;
    }
    for (const transaction of transactions) {
      if (transaction.date >= dateExclusive) continue;
      total += transactionDelta(transaction);
    }
    return total;
  }

  const balanceAtEnd = bounds => balanceAt(bounds.end);

  function bucketSeries(bounds, granularity) {
    const buckets = [];
    if (granularity === "day") {
      for (let cursor = new Date(bounds.start); cursor < bounds.end; cursor = addDays(cursor, 1)) {
        buckets.push({ start: new Date(cursor), end: addDays(cursor, 1), label: dateFormatter.format(cursor) });
      }
    } else if (granularity === "week") {
      let cursor = new Date(bounds.start);
      let index = 1;
      while (cursor < bounds.end) {
        const proposed = addDays(cursor, 7);
        const end = proposed < bounds.end ? proposed : bounds.end;
        buckets.push({ start: new Date(cursor), end: new Date(end), label: `W${index}` });
        cursor = new Date(end);
        index += 1;
      }
    } else {
      for (let cursor = new Date(bounds.start); cursor < bounds.end; cursor = addMonths(cursor, 1)) {
        const proposed = addMonths(cursor, 1);
        buckets.push({
          start: new Date(cursor),
          end: proposed < bounds.end ? proposed : bounds.end,
          label: monthFormatter.format(cursor),
        });
      }
    }

    return buckets.map(bucket => {
      const metrics = periodMetrics(bucket);
      return {
        ...bucket,
        income: metrics.income,
        expenses: metrics.expenses,
        net: metrics.net,
        savingsRate: metrics.savingsRate,
        fixedExpenses: metrics.fixedExpenses,
        variableExpenses: metrics.variableExpenses,
      };
    });
  }

  function balanceSeries(bounds, granularity) {
    return bucketSeries(bounds, granularity).map(bucket => ({
      ...bucket,
      balance: balanceAt(bucket.end),
    }));
  }

  function categorySeries(bounds, limit = 8) {
    const totals = new Map();
    for (const transaction of periodTransactions(bounds)) {
      if (transaction.type !== "expense" || !Number.isFinite(transaction.baseAmount)) continue;
      totals.set(transaction.category, (totals.get(transaction.category) || 0) + transaction.baseAmount);
    }
    return [...totals.entries()]
      .map(([category, value]) => ({ category, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, limit);
  }

  function commitmentDueDate(commitment, year, month) {
    const day = Math.min(commitment.dueDay, new Date(year, month + 1, 0).getDate());
    return new Date(year, month, day);
  }

  function commitmentOccurrences(bounds) {
    const rows = [];
    for (const commitment of commitments) {
      if (!commitment.active || commitment.frequency !== "monthly" || !Number.isFinite(commitment.baseAmount)) continue;
      for (
        let cursor = new Date(bounds.start.getFullYear(), bounds.start.getMonth(), 1);
        cursor < bounds.end;
        cursor = addMonths(cursor, 1)
      ) {
        const due = commitmentDueDate(commitment, cursor.getFullYear(), cursor.getMonth());
        if (!inRange(due, bounds)) continue;
        if (commitment.startDate && due < commitment.startDate) continue;
        if (commitment.endDate && due > commitment.endDate) continue;
        const paid = transactions.some(transaction =>
          transaction.commitmentId &&
          transaction.commitmentId === commitment.id &&
          transaction.date <= due &&
          transaction.date >= new Date(due.getFullYear(), due.getMonth(), 1)
        );
        rows.push({ ...commitment, due, paid });
      }
    }
    return rows;
  }

  function upcomingCommitments(anchor, days = 7) {
    const bounds = { start: anchor, end: addDays(anchor, days + 1) };
    return commitmentOccurrences(bounds).filter(row => !row.paid);
  }

  function periodLabel(range, bounds) {
    if (range === "week") {
      const last = addDays(bounds.end, -1);
      return `${dateFormatter.format(bounds.start)} – ${dateFormatter.format(last)}`;
    }
    if (range === "month") return longMonthFormatter.format(bounds.start);
    if (range === "quarter") {
      const fiscalStart = settings.FiscalYearStartMonth - 1;
      const relativeMonth = (bounds.start.getMonth() - fiscalStart + 12) % 12;
      const quarter = Math.floor(relativeMonth / 3) + 1;
      const fiscalEndYear = addDays(bounds.end, -1).getFullYear();
      return `Q${quarter} · FY ${fiscalEndYear}`;
    }
    const fiscalEndYear = addDays(bounds.end, -1).getFullYear();
    return settings.FiscalYearStartMonth === 1 ? String(fiscalEndYear) : `FY ${fiscalEndYear}`;
  }

  function deltaPercent(current, previous) {
    if (!Number.isFinite(current) || !Number.isFinite(previous) || previous === 0) return NaN;
    return (current - previous) / Math.abs(previous);
  }

  function setKpi(role, label, value, detail = "", trend = NaN, tone = "", goodDirection = 1) {
    const card = q(`[data-kpi="${role}"]`);
    if (!card) return;
    const labelEl = card.querySelector("[data-kpi-label]");
    const valueEl = card.querySelector("[data-kpi-value]");
    const detailEl = card.querySelector("[data-kpi-detail]");
    const trendEl = card.querySelector("[data-kpi-trend]");
    if (labelEl) labelEl.textContent = label;
    if (valueEl) valueEl.textContent = value;
    if (detailEl) detailEl.textContent = detail;
    if (trendEl) {
      if (Number.isFinite(trend)) {
        trendEl.hidden = false;
        trendEl.textContent = `${trend >= 0 ? "↗" : "↘"} ${Math.abs(trend * 100).toFixed(1)}%`;
        trendEl.dataset.tone = trend * goodDirection >= 0 ? "positive" : "negative";
      } else {
        trendEl.hidden = true;
        trendEl.textContent = "";
        delete trendEl.dataset.tone;
      }
    }
    card.dataset.tone = tone;
  }

  function svgElement(name, attrs = {}) {
    const element = financeDocument.createElementNS("http://www.w3.org/2000/svg", name);
    for (const [key, value] of Object.entries(attrs)) element.setAttribute(key, String(value));
    return element;
  }

  function clearChart(host) {
    if (host) host.replaceChildren();
  }

  function renderEmptyChart(host, message) {
    clearChart(host);
    const empty = financeDocument.createElement("div");
    empty.className = "cv-finance-chart-empty";
    empty.textContent = message;
    host?.appendChild(empty);
  }

  function renderLineChart(host, rows, series, { yFormat = displayCompactMoney } = {}) {
    clearChart(host);
    if (!host || !rows.length || !series.length) {
      renderEmptyChart(host, "Not enough data for this period.");
      return;
    }

    const width = 900;
    const height = 280;
    const pad = { left: 64, right: 18, top: 20, bottom: 42 };
    const values = rows.flatMap(row => series.map(item => numberValue(row[item.key])).filter(Number.isFinite));
    if (!values.length) {
      renderEmptyChart(host, "Not enough data for this period.");
      return;
    }

    let min = Math.min(...values);
    let max = Math.max(...values);
    if (min === max) {
      const spread = Math.abs(min || 1) * 0.1 || 1;
      min -= spread;
      max += spread;
    }

    const x = index => pad.left + (rows.length === 1 ? 0 : index * (width - pad.left - pad.right) / (rows.length - 1));
    const y = value => pad.top + (max - value) * (height - pad.top - pad.bottom) / (max - min);
    const svg = svgElement("svg", {
      viewBox: `0 0 ${width} ${height}`,
      role: "img",
      "aria-label": series.map(item => item.label).join(" and "),
    });
    svg.classList.add("cv-finance-svg");

    for (let index = 0; index <= 4; index += 1) {
      const value = min + ((max - min) * index / 4);
      const yy = y(value);
      svg.appendChild(svgElement("line", {
        x1: pad.left,
        x2: width - pad.right,
        y1: yy,
        y2: yy,
        class: "cv-finance-gridline",
      }));
      const label = svgElement("text", {
        x: pad.left - 10,
        y: yy + 4,
        "text-anchor": "end",
        class: "cv-finance-axis-label",
      });
      label.textContent = yFormat(value);
      svg.appendChild(label);
    }

    const tickIndexes = [...new Set([
      0,
      Math.floor((rows.length - 1) * 0.25),
      Math.floor((rows.length - 1) * 0.5),
      Math.floor((rows.length - 1) * 0.75),
      rows.length - 1,
    ])].filter(index => index >= 0);

    for (const index of tickIndexes) {
      const label = svgElement("text", {
        x: x(index),
        y: height - 14,
        "text-anchor": index === 0 ? "start" : index === rows.length - 1 ? "end" : "middle",
        class: "cv-finance-axis-label",
      });
      label.textContent = rows[index].label;
      svg.appendChild(label);
    }

    series.forEach((item, seriesIndex) => {
      const points = rows
        .map((row, index) => ({ x: x(index), y: y(numberValue(row[item.key])), value: numberValue(row[item.key]) }))
        .filter(point => Number.isFinite(point.value));
      if (!points.length) return;

      if (item.area && points.length > 1) {
        const areaPath = [
          `M ${points[0].x} ${height - pad.bottom}`,
          ...points.map(point => `L ${point.x} ${point.y}`),
          `L ${points[points.length - 1].x} ${height - pad.bottom}`,
          "Z",
        ].join(" ");
        svg.appendChild(svgElement("path", {
          d: areaPath,
          class: `cv-finance-area cv-finance-series-${seriesIndex + 1}`,
        }));
      }

      const linePath = points.map((point, index) => `${index ? "L" : "M"} ${point.x} ${point.y}`).join(" ");
      svg.appendChild(svgElement("path", {
        d: linePath,
        class: `cv-finance-line cv-finance-series-${seriesIndex + 1}`,
      }));
    });

    host.appendChild(svg);
    const legend = financeDocument.createElement("div");
    legend.className = "cv-finance-legend";
    for (const [index, item] of series.entries()) {
      const entry = financeDocument.createElement("span");
      entry.className = `cv-finance-legend-item cv-finance-series-${index + 1}`;
      entry.textContent = item.label;
      legend.appendChild(entry);
    }
    host.appendChild(legend);
  }

  function renderGroupedBars(host, rows) {
    clearChart(host);
    if (!host) return;
    const max = Math.max(0, ...rows.flatMap(row => [row.income, row.expenses]));
    if (!rows.length || max <= 0) {
      renderEmptyChart(host, "No cash flow recorded for this period.");
      return;
    }

    const chart = financeDocument.createElement("div");
    chart.className = "cv-finance-grouped-bars";
    for (const row of rows) {
      const group = financeDocument.createElement("div");
      group.className = "cv-finance-bar-group";
      const bars = financeDocument.createElement("div");
      bars.className = "cv-finance-bar-pair";

      for (const [key, label] of [["income", "Income"], ["expenses", "Expenses"]]) {
        const bar = financeDocument.createElement("div");
        bar.className = `cv-finance-bar cv-finance-bar-${key}`;
        bar.style.setProperty("--fin-bar-size", `${Math.max(2, (row[key] / max) * 100)}%`);
        bar.title = `${row.label} · ${label}: ${displayMoney(row[key])}`;
        bars.appendChild(bar);
      }

      const label = financeDocument.createElement("span");
      label.className = "cv-finance-bar-label";
      label.textContent = row.label;
      group.append(bars, label);
      chart.appendChild(group);
    }
    host.appendChild(chart);

    const legend = financeDocument.createElement("div");
    legend.className = "cv-finance-legend";
    const income = financeDocument.createElement("span");
    income.className = "cv-finance-legend-item is-income";
    income.textContent = "Income";
    const expenses = financeDocument.createElement("span");
    expenses.className = "cv-finance-legend-item is-expense";
    expenses.textContent = "Expenses";
    legend.append(income, expenses);
    host.appendChild(legend);
  }

  function renderCategoryBars(host, rows) {
    clearChart(host);
    if (!host) return;
    const max = Math.max(0, ...rows.map(row => row.value));
    if (!rows.length || max <= 0) {
      renderEmptyChart(host, "No expenses recorded for this period.");
      return;
    }

    const list = financeDocument.createElement("div");
    list.className = "cv-finance-category-bars";
    for (const row of rows) {
      const item = financeDocument.createElement("div");
      item.className = "cv-finance-category-row";
      const head = financeDocument.createElement("div");
      head.className = "cv-finance-category-head";
      const name = financeDocument.createElement("span");
      name.textContent = row.category;
      const value = financeDocument.createElement("span");
      value.textContent = displayMoney(row.value);
      head.append(name, value);

      const track = financeDocument.createElement("div");
      track.className = "cv-finance-category-track";
      const fill = financeDocument.createElement("div");
      fill.className = "cv-finance-category-fill";
      fill.style.setProperty("--fin-bar-size", `${(row.value / max) * 100}%`);
      track.appendChild(fill);
      item.append(head, track);
      list.appendChild(item);
    }
    host.appendChild(list);
  }

  function renderComposition(host, rows) {
    clearChart(host);
    if (!host) return;
    if (!rows.length || rows.every(row => row.expenses <= 0)) {
      renderEmptyChart(host, "No expenses recorded for this period.");
      return;
    }

    const list = financeDocument.createElement("div");
    list.className = "cv-finance-composition";
    for (const row of rows) {
      const total = row.fixedExpenses + row.variableExpenses;
      if (total <= 0) continue;
      const fixedPct = row.fixedExpenses / total;
      const item = financeDocument.createElement("div");
      item.className = "cv-finance-composition-row";
      const header = financeDocument.createElement("div");
      header.className = "cv-finance-composition-head";
      const label = financeDocument.createElement("span");
      label.textContent = row.label;
      const share = financeDocument.createElement("span");
      share.textContent = `${Math.round(fixedPct * 100)}% fixed`;
      header.append(label, share);

      const track = financeDocument.createElement("div");
      track.className = "cv-finance-composition-track";
      const fixed = financeDocument.createElement("div");
      fixed.className = "cv-finance-composition-fixed";
      fixed.style.setProperty("--fin-bar-size", `${fixedPct * 100}%`);
      const variable = financeDocument.createElement("div");
      variable.className = "cv-finance-composition-variable";
      variable.style.setProperty("--fin-bar-size", `${(1 - fixedPct) * 100}%`);
      track.append(fixed, variable);
      item.append(header, track);
      list.appendChild(item);
    }
    host.appendChild(list);
  }

  function renderLedger(bounds) {
    const body = q('[data-role="finance-ledger-body"]');
    const empty = q('[data-role="finance-ledger-empty"]');
    if (!body || !empty) return;
    body.replaceChildren();

    const rows = periodTransactions(bounds)
      .slice()
      .sort((a, b) => b.date - a.date || a.description.localeCompare(b.description));

    empty.hidden = rows.length > 0;
    for (const transaction of rows.slice(0, 50)) {
      const tr = financeDocument.createElement("tr");
      tr.dataset.type = transaction.type;
      tr.dataset.filePath = transaction.file?.path || "";
      tr.title = "Click to edit transaction";

      const date = financeDocument.createElement("td");
      date.textContent = dateFormatter.format(transaction.date);

      const description = financeDocument.createElement("td");
      const strong = financeDocument.createElement("strong");
      strong.textContent = transaction.description;
      const account = financeDocument.createElement("small");
      account.textContent = transaction.account;
      description.append(strong, account);

      const category = financeDocument.createElement("td");
      category.textContent = transaction.category;

      const type = financeDocument.createElement("td");
      const pill = financeDocument.createElement("span");
      pill.className = "cv-finance-type-pill";
      pill.dataset.type = transaction.type;
      pill.textContent = transaction.type;
      type.appendChild(pill);

      const amount = financeDocument.createElement("td");
      amount.className = "cv-finance-amount";
      const native = financeDocument.createElement("strong");
      const sign = transaction.type === "expense" ? -1 : 1;
      native.textContent = displayNativeMoney(sign * transaction.amount, transaction.currency);
      amount.appendChild(native);
      if (
        transaction.currency &&
        bookCurrency &&
        transaction.currency !== bookCurrency &&
        Number.isFinite(transaction.baseAmount)
      ) {
        const base = financeDocument.createElement("small");
        base.textContent = `≈ ${displayMoney(sign * transaction.baseAmount)}`;
        amount.appendChild(base);
      }

      tr.append(date, description, category, type, amount);
      body.appendChild(tr);
    }
  }

  function renderWarnings() {
    const banner = q('[data-role="finance-warning"]');
    if (!banner) return;
    const messages = [];
    if (!bookCurrency) {
      messages.push(`Set BookCurrency to a three-letter ISO 4217 code in ${GLOBAL_SETTINGS_PATH} or this report.`);
    }
    messages.push(...warnings);


    banner.hidden = messages.length === 0;
    banner.replaceChildren();
    if (!messages.length) return;
    const title = financeDocument.createElement("strong");
    title.textContent = "Finance setup";
    const list = financeDocument.createElement("ul");
    for (const message of messages) {
      const item = financeDocument.createElement("li");
      item.textContent = message;
      list.appendChild(item);
    }
    banner.append(title, list);
  }

  const reportAnchor = parseDate(reportFrontmatter.ReportDate) ||
    new Date(financeFile?.stat?.mtime || Date.now());
  let activeRange = normalizeRange(reportFrontmatter.DefaultRange);

  function renderHeader(range, bounds) {
    const title = q('[data-role="finance-title"]');
    const subtitle = q('[data-role="finance-subtitle"]');
    const currency = q('[data-role="finance-currency"]');
    if (title) title.textContent = `${RANGE_LABELS[range]} financial report`;
    if (subtitle) subtitle.textContent = periodLabel(range, bounds);
    if (currency) {
      const localeLabel = settings.DisplayLocale === "auto"
        ? (financeDocument.defaultView?.navigator?.language || "system locale")
        : settings.DisplayLocale;
      currency.textContent = bookCurrency
        ? `${bookCurrency} · ${localeLabel}`
        : `Currency not configured · ${localeLabel}`;
    }
    for (const button of qa("[data-finance-range]")) {
      const active = button.dataset.financeRange === range;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    }
  }

  function renderKpis(range, bounds, metrics, previousMetrics) {
    const closingBalance = balanceAtEnd(bounds);
    const previous = previousBounds(range, bounds);
    const previousClosing = balanceAtEnd(previous);
    const balanceTrend = deltaPercent(closingBalance, previousClosing);
    const incomeTrend = deltaPercent(metrics.income, previousMetrics.income);
    const expenseTrend = deltaPercent(metrics.expenses, previousMetrics.expenses);

    setKpi(
      "balance",
      range === "week" ? "Current balance" : "Closing balance",
      displayMoney(closingBalance),
      `Net cash flow ${displayMoney(metrics.net)}`,
      balanceTrend
    );
    setKpi(
      "income",
      `${RANGE_LABELS[range]} income`,
      displayMoney(metrics.income),
      `${metrics.rows.filter(row => row.type === "income").length} income entries`,
      incomeTrend,
      "positive"
    );
    setKpi(
      "expenses",
      `${RANGE_LABELS[range]} expenses`,
      displayMoney(metrics.expenses),
      `${metrics.rows.filter(row => row.type === "expense").length} expense entries`,
      expenseTrend,
      "negative",
      -1
    );

    if (range === "week") {
      const upcoming = upcomingCommitments(reportAnchor, 7);
      const total = upcoming.reduce((sum, row) => sum + (Number.isFinite(row.baseAmount) ? row.baseAmount : 0), 0);
      setKpi(
        "rate",
        "Upcoming commitments",
        displayMoney(total),
        `${upcoming.length} due in the next 7 days`,
        NaN,
        "warning"
      );
    } else {
      const savingsDelta = Number.isFinite(metrics.savingsRate) && Number.isFinite(previousMetrics.savingsRate)
        ? metrics.savingsRate - previousMetrics.savingsRate
        : NaN;
      setKpi(
        "rate",
        "Savings rate",
        Number.isFinite(metrics.savingsRate) ? percentFormatter.format(metrics.savingsRate) : "—",
        `${displayMoney(metrics.net)} retained`,
        savingsDelta,
        metrics.savingsRate >= 0 ? "positive" : "negative"
      );
    }
  }

  function setPanelCopy(role, title, subtitle) {
    const panel = q(`[data-panel="${role}"]`);
    if (!panel) return;
    const titleEl = panel.querySelector("[data-panel-title]");
    const subtitleEl = panel.querySelector("[data-panel-subtitle]");
    if (titleEl) titleEl.textContent = title;
    if (subtitleEl) subtitleEl.textContent = subtitle;
  }

  function renderCharts(range, bounds) {
    const primary = q('[data-role="finance-primary-chart"]');
    const secondaryA = q('[data-role="finance-secondary-a"]');
    const secondaryB = q('[data-role="finance-secondary-b"]');

    if (range === "week") {
      setPanelCopy("primary", "Daily balance", "Closing balance for each day in the selected week.");
      renderLineChart(primary, balanceSeries(bounds, "day"), [
        { key: "balance", label: "Balance", area: true },
      ]);
      setPanelCopy("secondary-a", "Daily money in / out", "Discrete daily cash-flow totals.");
      renderGroupedBars(secondaryA, bucketSeries(bounds, "day"));
      setPanelCopy("secondary-b", "Spending by category", "Largest expense categories this week.");
      renderCategoryBars(secondaryB, categorySeries(bounds, 6));
      return;
    }

    if (range === "month") {
      setPanelCopy("primary", "Balance movement", "Daily closing balance across the selected month.");
      renderLineChart(primary, balanceSeries(bounds, "day"), [
        { key: "balance", label: "Balance", area: true },
      ]);
      setPanelCopy("secondary-a", "Income vs expenses by week", "Cash-flow timing inside the month.");
      renderGroupedBars(secondaryA, bucketSeries(bounds, "week"));
      setPanelCopy("secondary-b", "Expense categories", "Ordered by total spending.");
      renderCategoryBars(secondaryB, categorySeries(bounds, 8));
      return;
    }

    if (range === "quarter") {
      const monthly = bucketSeries(bounds, "month");
      setPanelCopy("primary", "Monthly income vs expenses", "Three monthly buckets inside the selected quarter.");
      renderGroupedBars(primary, monthly);
      setPanelCopy("secondary-a", "Savings-rate trend", "Net cash flow as a share of income.");
      renderLineChart(
        secondaryA,
        monthly.map(row => ({ ...row, savingsRatePct: Number.isFinite(row.savingsRate) ? row.savingsRate * 100 : NaN })),
        [{ key: "savingsRatePct", label: "Savings rate" }],
        { yFormat: value => `${Math.round(value)}%` }
      );
      setPanelCopy("secondary-b", "Fixed vs variable spending", "Expense composition by month.");
      renderComposition(secondaryB, monthly);
      return;
    }

    const monthly = bucketSeries(bounds, "month");
    setPanelCopy("primary", "Monthly income vs expenses", "Annual cash-flow rhythm across twelve months.");
    renderGroupedBars(primary, monthly);
    setPanelCopy("secondary-a", "Closing balance trend", "Month-end balance across the selected year.");
    renderLineChart(secondaryA, balanceSeries(bounds, "month"), [
      { key: "balance", label: "Closing balance" },
    ]);
    setPanelCopy("secondary-b", "Annual expense ranking", "Largest spending categories across the year.");
    renderCategoryBars(secondaryB, categorySeries(bounds, 10));
  }

  function render(range) {
    activeRange = range;
    const bounds = rangeBounds(range, reportAnchor);
    const previous = previousBounds(range, bounds);
    const metrics = periodMetrics(bounds);
    const previousMetrics = periodMetrics(previous);
    renderHeader(range, bounds);
    renderKpis(range, bounds, metrics, previousMetrics);
    renderCharts(range, bounds);
    renderLedger(bounds);
    renderWarnings();
  }

  function initRangeControls() {
    for (const button of qa("[data-finance-range]")) {
      button.addEventListener("click", () => {
        const range = normalizeRange(button.dataset.financeRange);
        if (!RANGE_ORDER.includes(range) || range === activeRange) return;
        render(range);
      });
    }
  }

  function initNoteEditor() {
    const renderHost = q('[data-role="finance-note-render"]');
    const state = q('[data-role="finance-note-state"]');
    if (!renderHost || !state) return;

    const nativePlaceholder = renderHost.querySelector("[data-cv-editable-placeholder]");
    if (nativePlaceholder) {
      financeRoot.classList.add("is-native-editor");
      state.textContent = "Autosaved by Obsidian";
      return;
    }

    renderHost.classList.toggle("is-empty", !reportBodyContent.trim());
    renderHost.setAttribute("tabindex", "0");
    state.textContent = "Click review notes to edit";

    let openingEditor = false;
    const openInlineEditor = async () => {
      if (openingEditor) return;
      const leaves = typeof financeApp?.workspace?.getLeavesOfType === "function"
        ? financeApp.workspace.getLeavesOfType("markdown")
        : [];
      const leaf = leaves.find(candidate =>
        candidate?.view?.file?.path === financeFile?.path &&
        candidate.view.contentEl?.contains(financeContainer)
      );
      if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
        state.textContent = "Open this report in Live Preview to edit here";
        return;
      }
      openingEditor = true;
      state.textContent = "Opening editor…";
      try {
        const viewState = leaf.getViewState();
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode: "source",
            source: false,
          },
        });
      } catch (error) {
        state.textContent = "Could not open inline editor";
        openingEditor = false;
        console.error("[custom-view:finance] Could not enter Live Preview", error);
      }
    };

    renderHost.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select")) return;
      void openInlineEditor();
    });
    renderHost.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void openInlineEditor();
    });
  }


  initRangeControls();
  initNoteEditor();
  render(activeRange);
}

(() => {
  const context = tp;
  const app = context?.app;
  const container = context?.container || this;
  const financeRoot = container?.querySelector?.('[data-role="finance-root"]');
  const ledger = financeRoot?.querySelector?.('.cv-finance-ledger');
  const ledgerHead = ledger?.querySelector?.('.cv-finance-panel-head');
  const tableWrap = ledger?.querySelector?.('.cv-finance-table-wrap');
  if (!app || !financeRoot || !ledger || !ledgerHead || !tableWrap) return;
  if (ledger.querySelector('[data-finance-ledger-add]')) return;

  const RECORDS_ROOT = "20_Personal_Life/22_Finance/Records";
  const TRANSACTION_FOLDER = `${RECORDS_ROOT}/Transactions`;
  const ACCOUNT_FOLDER = `${RECORDS_ROOT}/Accounts`;
  const SUBSCRIPTION_FOLDER = `${RECORDS_ROOT}/Subscription`;
  const FINANCE_BASE_PATH = "20_Personal_Life/22_Finance/Finance.base";
  const GLOBAL_SETTINGS_PATH = "90_System/93_Configuration/settings.md";
  const NEW_CATEGORY_VALUE = "__finance_new_category__";
  const TRANSACTION_KINDS = new Set(["expense", "income", "transfer"]);
  const ALL_KINDS = new Set(["expense", "income", "transfer", "account", "subscription"]);
  const doc = context.activeDocument || financeRoot.ownerDocument || document;

  const text = value => String(value ?? "").trim();
  const numberValue = (value, fallback = NaN) => {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    const raw = text(value).replaceAll(",", "");
    if (!raw) return fallback;
    const parsed = Number(raw);
    return Number.isFinite(parsed) ? parsed : fallback;
  };
  const boolValue = (value, fallback = false) => {
    if (typeof value === "boolean") return value;
    const raw = text(value).toLowerCase();
    if (["true", "yes", "1", "on"].includes(raw)) return true;
    if (["false", "no", "0", "off"].includes(raw)) return false;
    return fallback;
  };
  const currencyCode = value => {
    const code = text(value).toUpperCase();
    return /^[A-Z]{3}$/.test(code) ? code : "";
  };
  const yamlString = value => JSON.stringify(text(value));
  const yamlNumberOrBlank = value => Number.isFinite(value) ? String(value) : '""';
  const localDateString = (date = new Date()) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };
  const safeName = value => {
    const cleaned = text(value)
      .replace(/[\\/:*?"<>|#[\]^]/g, "-")
      .replace(/\s+/g, " ")
      .replace(/-+/g, "-")
      .trim();
    return (cleaned || "Finance record").slice(0, 96).trim();
  };
  const makeId = prefix => `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;

  const globalSettingsFile = app.vault.getAbstractFileByPath?.(GLOBAL_SETTINGS_PATH);
  const globalSettings = globalSettingsFile
    ? app.metadataCache?.getFileCache?.(globalSettingsFile)?.frontmatter || {}
    : {};
  const reportFrontmatter = context.frontmatter || {};
  const financeBook = text(reportFrontmatter.FinanceBook) || text(globalSettings.FinanceBook) || "default";
  const bookCurrency = currencyCode(globalSettings.BookCurrency) || currencyCode(reportFrontmatter.BookCurrency) || "VND";

  const knownCategories = new Set([
    "Food", "Groceries", "Housing", "Utilities", "Transport", "Health", "Education",
    "Entertainment", "Shopping", "Personal Care", "Travel", "Insurance", "Debt", "Gifts",
    "Salary", "Freelance", "Business", "Bonus", "Investment", "Interest", "Refund",
    "Subscription", "Transfer", "Other", "Uncategorised",
  ]);

  function scanFinanceCategories() {
    const files = typeof app.vault.getMarkdownFiles === "function" ? app.vault.getMarkdownFiles() : [];
    for (const file of files) {
      if (!file.path.startsWith(`${RECORDS_ROOT}/`)) continue;
      const fm = app.metadataCache?.getFileCache?.(file)?.frontmatter || {};
      if ((text(fm.FinanceBook) || "default") !== financeBook) continue;
      if (!["FinanceTransaction", "FinanceCommitment"].includes(text(fm.RecordType))) continue;
      const category = text(fm.Category);
      if (category) knownCategories.add(category);
    }
  }

  async function ensureFolder(path) {
    const parts = path.split("/").filter(Boolean);
    let current = "";
    for (const part of parts) {
      current = current ? `${current}/${part}` : part;
      if (app.vault.getAbstractFileByPath(current)) continue;
      try {
        await app.vault.createFolder(current);
      } catch (error) {
        if (!app.vault.getAbstractFileByPath(current)) throw error;
      }
    }
  }

  function uniquePath(folder, filename) {
    const stem = filename.toLowerCase().endsWith(".md") ? filename.slice(0, -3) : filename;
    let candidate = `${folder}/${stem}.md`;
    let suffix = 2;
    while (app.vault.getAbstractFileByPath(candidate)) {
      candidate = `${folder}/${stem} ${suffix}.md`;
      suffix += 1;
    }
    return candidate;
  }

  function normalizedBaseAmount(amount, currency, fxRate) {
    if (!Number.isFinite(amount)) return NaN;
    if (!currency || currency === bookCurrency) return amount;
    if (Number.isFinite(fxRate) && fxRate > 0) return amount * fxRate;
    return NaN;
  }

  function computedTransactionValues(data) {
    const computedBaseAmount = normalizedBaseAmount(data.amount, data.currency, data.fxRate);
    const baseAmount = Number.isFinite(data.baseAmountOverride) ? data.baseAmountOverride : computedBaseAmount;
    const feeCurrency = data.feeAmount > 0 ? (data.feeCurrency || data.currency) : "";
    const feeFxRate = data.feeAmount > 0
      ? (Number.isFinite(data.feeFxRate) ? data.feeFxRate : data.fxRate)
      : NaN;
    const computedFeeBaseAmount = data.feeAmount > 0
      ? normalizedBaseAmount(data.feeAmount, feeCurrency, feeFxRate)
      : NaN;
    const feeBaseAmount = Number.isFinite(data.feeBaseAmountOverride)
      ? data.feeBaseAmountOverride
      : computedFeeBaseAmount;
    return { baseAmount, feeCurrency, feeFxRate, feeBaseAmount };
  }

  function buildTransactionContent(data) {
    const { baseAmount, feeCurrency, feeFxRate, feeBaseAmount } = computedTransactionValues(data);
    return `---\nRecordType: FinanceTransaction\nFinanceSchema: 1\nFinanceBook: ${yamlString(financeBook)}\nTransactionId: ${yamlString(data.id)}\nDate: ${yamlString(data.date)}\nType: ${yamlString(data.type)}\nDescription: ${yamlString(data.description)}\nAmount: ${data.amount}\nCurrency: ${yamlString(data.currency)}\nAccount: ${yamlString(data.account)}\nToAccount: ${yamlString(data.toAccount)}\nCategory: ${yamlString(data.category)}\nFixed: ${data.fixed}\nCommitmentId: ${yamlString(data.commitmentId)}\nFxRateToBase: ${yamlNumberOrBlank(data.fxRate)}\nBaseAmount: ${yamlNumberOrBlank(baseAmount)}\nFeeAmount: ${data.feeAmount > 0 ? data.feeAmount : '""'}\nFeeCurrency: ${data.feeAmount > 0 ? yamlString(feeCurrency) : '""'}\nFeeFxRateToBase: ${data.feeAmount > 0 ? yamlNumberOrBlank(feeFxRate) : '""'}\nFeeBaseAmount: ${data.feeAmount > 0 ? yamlNumberOrBlank(feeBaseAmount) : '""'}\ncategories:\n  - \"[[Finance Transaction]]\"\n---\n\n# Transaction notes\n\n-\n`;
  }

  function buildAccountContent(data) {
    const computedBase = normalizedBaseAmount(data.openingBalance, data.currency, data.openingFxRate);
    const baseOpeningBalance = Number.isFinite(data.baseOpeningBalance) ? data.baseOpeningBalance : computedBase;
    return `---\nRecordType: FinanceAccount\nFinanceSchema: 1\nFinanceBook: ${yamlString(financeBook)}\nAccountId: ${yamlString(data.id)}\nAccount: ${yamlString(data.name)}\nAccountType: ${yamlString(data.type)}\nCurrency: ${yamlString(data.currency)}\nOpeningBalance: ${data.openingBalance}\nOpeningDate: ${yamlString(data.openingDate)}\nBaseOpeningBalance: ${yamlNumberOrBlank(baseOpeningBalance)}\nOpeningFxRateToBase: ${yamlNumberOrBlank(data.openingFxRate)}\nIncludeInNetWorth: ${data.includeInNetWorth}\nActive: ${data.active}\ncategories:\n  - \"[[Finance Account]]\"\n---\n\n# Account notes\n\n-\n`;
  }

  function buildSubscriptionContent(data) {
    const baseAmount = normalizedBaseAmount(data.amount, data.currency, data.fxRate);
    return `---\nRecordType: FinanceCommitment\nFinanceSchema: 1\nFinanceBook: ${yamlString(financeBook)}\nCommitmentId: ${yamlString(data.id)}\nName: ${yamlString(data.name)}\nAmount: ${data.amount}\nCurrency: ${yamlString(data.currency)}\nAccount: ${yamlString(data.account)}\nCategory: ${yamlString(data.category)}\nFrequency: monthly\nDueDay: ${data.dueDay}\nStartDate: ${yamlString(data.startDate)}\nEndDate: ${yamlString(data.endDate)}\nFxRateToBase: ${yamlNumberOrBlank(data.fxRate)}\nBaseAmount: ${yamlNumberOrBlank(baseAmount)}\nActive: true\ncategories:\n  - \"[[Finance Subscription]]\"\n---\n\n# Subscription notes\n\n-\n`;
  }

