  ledger.insertBefore(editor, tableWrap);

  const typeButtons = Array.from(editor.querySelectorAll('[data-finance-ledger-kind]'));
  const transactionForm = editor.querySelector('[data-finance-ledger-form="transaction"]');
  const accountForm = editor.querySelector('[data-finance-ledger-form="account"]');
  const subscriptionForm = editor.querySelector('[data-finance-ledger-form="subscription"]');
  const transactionCategory = transactionForm.elements.namedItem("category");
  const transactionCustomCategory = transactionForm.elements.namedItem("customCategory");
  const transactionCategoryField = editor.querySelector('[data-finance-ledger-category-field]');
  const transactionCustomCategoryField = editor.querySelector('[data-finance-ledger-custom-category]');
  const subscriptionCategory = subscriptionForm.elements.namedItem("category");
  const subscriptionCustomCategory = subscriptionForm.elements.namedItem("customCategory");
  const subscriptionCustomCategoryField = editor.querySelector('[data-finance-ledger-subscription-custom-category]');
  const transactionSubmit = editor.querySelector('[data-finance-ledger-transaction-submit]');
  const transactionHint = editor.querySelector('[data-finance-ledger-transaction-hint]');
  const status = editor.querySelector('[data-finance-ledger-status]');
  const cancelButton = editor.querySelector('[data-finance-ledger-cancel]');

  let activeKind = "expense";
  let editingPath = "";

  function setStatus(message, tone = "") {
    status.textContent = message;
    if (tone) status.dataset.tone = tone;
    else delete status.dataset.tone;
  }

  function setBusy(form, busy) {
    form.toggleAttribute("aria-busy", busy);
    for (const button of form.querySelectorAll("button")) button.disabled = busy;
  }

  function refreshCategorySelect(select, selected = "") {
    select.replaceChildren();
    const placeholder = doc.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "Choose category";
    placeholder.disabled = true;
    placeholder.selected = !selected;
    select.appendChild(placeholder);

    for (const category of [...knownCategories].sort((a, b) => a.localeCompare(b))) {
      const option = doc.createElement("option");
      option.value = category;
      option.textContent = category;
      if (category === selected) option.selected = true;
      select.appendChild(option);
    }

    const customOption = doc.createElement("option");
    customOption.value = NEW_CATEGORY_VALUE;
    customOption.textContent = "New category…";
    select.appendChild(customOption);
  }

  function updateTransactionCustomCategory() {
    const custom = activeKind !== "transfer" && transactionCategory.value === NEW_CATEGORY_VALUE;
    transactionCustomCategoryField.hidden = !custom;
    transactionCustomCategory.required = custom;
    if (custom) transactionCustomCategory.focus();
  }

  function updateSubscriptionCustomCategory() {
    const custom = subscriptionCategory.value === NEW_CATEGORY_VALUE;
    subscriptionCustomCategoryField.hidden = !custom;
    subscriptionCustomCategory.required = custom;
    if (custom) subscriptionCustomCategory.focus();
  }

  function updateTransactionSubmitCopy() {
    if (editingPath) {
      transactionSubmit.textContent = "Save changes";
      transactionHint.textContent = "Editing existing transaction";
      return;
    }
    transactionSubmit.textContent = `Create ${activeKind}`;
    transactionHint.textContent = `${activeKind[0].toUpperCase()}${activeKind.slice(1)} · Records/Transactions`;
  }

  function showKind(kind) {
    activeKind = ALL_KINDS.has(kind) ? kind : "expense";
    for (const button of typeButtons) {
      const active = button.dataset.financeLedgerKind === activeKind;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-selected", String(active));
    }

    const isTransaction = TRANSACTION_KINDS.has(activeKind);
    transactionForm.hidden = !isTransaction;
    accountForm.hidden = activeKind !== "account";
    subscriptionForm.hidden = activeKind !== "subscription";

    if (isTransaction) {
      const isTransfer = activeKind === "transfer";
      const isExpense = activeKind === "expense";
      for (const field of editor.querySelectorAll('[data-finance-ledger-transfer]')) field.hidden = !isTransfer;
      for (const field of editor.querySelectorAll('[data-finance-ledger-expense]')) field.hidden = !isExpense;
      transactionCategoryField.hidden = isTransfer;
      transactionCategory.required = !isTransfer;
      if (isTransfer) {
        transactionCategory.value = "Transfer";
        transactionCustomCategoryField.hidden = true;
        transactionCustomCategory.required = false;
      } else {
        if (transactionCategory.value === "Transfer") transactionCategory.value = "";
        updateTransactionCustomCategory();
      }
      updateTransactionSubmitCopy();
    }
  }

  function resetTransactionForm() {
    transactionForm.reset();
    transactionForm.elements.namedItem("date").value = localDateString();
    transactionForm.elements.namedItem("currency").value = bookCurrency;
    transactionForm.elements.namedItem("transactionId").value = makeId("TX");
    refreshCategorySelect(transactionCategory);
    transactionCustomCategoryField.hidden = true;
    transactionCustomCategory.required = false;
  }

  function resetAccountForm() {
    accountForm.reset();
    accountForm.elements.namedItem("currency").value = bookCurrency;
    accountForm.elements.namedItem("openingBalance").value = "0";
    accountForm.elements.namedItem("openingDate").value = localDateString();
    accountForm.elements.namedItem("includeInNetWorth").checked = true;
    accountForm.elements.namedItem("active").checked = true;
  }

  function resetSubscriptionForm() {
    subscriptionForm.reset();
    subscriptionForm.elements.namedItem("currency").value = bookCurrency;
    subscriptionForm.elements.namedItem("dueDay").value = "1";
    subscriptionForm.elements.namedItem("startDate").value = localDateString();
    refreshCategorySelect(subscriptionCategory, "Subscription");
    subscriptionCategory.value = "Subscription";
    subscriptionCustomCategoryField.hidden = true;
    subscriptionCustomCategory.required = false;
  }

  function resetEditor() {
    editingPath = "";
    resetTransactionForm();
    resetAccountForm();
    resetSubscriptionForm();
    showKind("expense");
  }

  function setOpen(open) {
    editor.hidden = !open;
    addButton.setAttribute("aria-expanded", String(open));
    addButton.classList.toggle("is-active", open);
    if (open) {
      const targetForm = activeKind === "account" ? accountForm : activeKind === "subscription" ? subscriptionForm : transactionForm;
      targetForm.querySelector("input, select")?.focus();
    }
  }

  function transactionDataFromForm() {
    const formData = new FormData(transactionForm);
    const type = TRANSACTION_KINDS.has(activeKind) ? activeKind : "expense";
    const selectedCategory = type === "transfer" ? "Transfer" : text(formData.get("category"));
    const category = selectedCategory === NEW_CATEGORY_VALUE ? text(formData.get("customCategory")) : selectedCategory;
    const amount = Math.abs(numberValue(formData.get("amount")));
    const account = text(formData.get("account"));
    const toAccount = type === "transfer" ? text(formData.get("toAccount")) : "";
    const date = text(formData.get("date")) || localDateString();
    const transferDescription = account && toAccount ? `${account} to ${toAccount}` : "Transfer";
    const description = text(formData.get("description")) || (type === "transfer" ? transferDescription : type === "income" ? "Income" : "Expense");
    const currency = currencyCode(formData.get("currency")) || bookCurrency;
    const fxRate = numberValue(formData.get("fxRate"));
    const feeAmount = type === "transfer" ? Math.abs(numberValue(formData.get("feeAmount"), 0)) : 0;
    const feeCurrency = type === "transfer" ? currencyCode(formData.get("feeCurrency")) : "";
    const feeFxRate = type === "transfer" ? numberValue(formData.get("feeFxRate")) : NaN;
    return {
      id: text(formData.get("transactionId")) || makeId("TX"),
      date,
      type,
      description,
      amount,
      currency,
      account,
      toAccount,
      category,
      fixed: type === "expense" && formData.get("fixed") === "on",
      commitmentId: text(formData.get("commitmentId")),
      fxRate,
      baseAmountOverride: numberValue(formData.get("baseAmount")),
      feeAmount,
      feeCurrency,
      feeFxRate,
      feeBaseAmountOverride: type === "transfer" ? numberValue(formData.get("feeBaseAmount")) : NaN,
    };
  }

  async function updateExistingTransaction(file, data) {
    const computed = computedTransactionValues(data);
    if (typeof app.fileManager?.processFrontMatter !== "function") {
      throw new Error("Obsidian frontmatter editor is unavailable.");
    }
    await app.fileManager.processFrontMatter(file, fm => {
      fm.RecordType = "FinanceTransaction";
      fm.FinanceSchema = 1;
      fm.FinanceBook = financeBook;
      fm.TransactionId = data.id;
      fm.Date = data.date;
      fm.Type = data.type;
      fm.Description = data.description;
      fm.Amount = data.amount;
      fm.Currency = data.currency;
      fm.Account = data.account;
      fm.ToAccount = data.toAccount;
      fm.Category = data.category;
      fm.Fixed = data.fixed;
      fm.CommitmentId = data.commitmentId;
      fm.FxRateToBase = Number.isFinite(data.fxRate) ? data.fxRate : "";
      fm.BaseAmount = Number.isFinite(computed.baseAmount) ? computed.baseAmount : "";
      fm.FeeAmount = data.feeAmount > 0 ? data.feeAmount : "";
      fm.FeeCurrency = data.feeAmount > 0 ? computed.feeCurrency : "";
      fm.FeeFxRateToBase = data.feeAmount > 0 && Number.isFinite(computed.feeFxRate) ? computed.feeFxRate : "";
      fm.FeeBaseAmount = data.feeAmount > 0 && Number.isFinite(computed.feeBaseAmount) ? computed.feeBaseAmount : "";
      fm.categories = ["[[Finance Transaction]]"];
    });
  }

  async function submitTransaction(event) {
    event.preventDefault();
    const data = transactionDataFromForm();
    if (!data.category) return setStatus("Choose a category or create a new one.", "error");
    if (!Number.isFinite(data.amount) || data.amount <= 0) return setStatus("Amount must be greater than zero.", "error");

    setBusy(transactionForm, true);
    setStatus(editingPath ? "Saving changes…" : "Saving…");
    try {
      if (editingPath) {
        const file = app.vault.getAbstractFileByPath(editingPath);
        if (!file) throw new Error("Original transaction file was not found.");
        await updateExistingTransaction(file, data);
        setStatus(`Updated ${data.type}: ${data.description}.`, "success");
      } else {
        await ensureFolder(TRANSACTION_FOLDER);
        const filename = `${data.date} - ${safeName(data.description)} - ${data.id.slice(-6)}`;
        const path = uniquePath(TRANSACTION_FOLDER, filename);
        await app.vault.create(path, buildTransactionContent(data));
        setStatus(`Created ${data.type}: ${data.description}.`, "success");
      }
      knownCategories.add(data.category);
      editingPath = "";
      resetTransactionForm();
      showKind(data.type);
    } catch (error) {
      console.error("[custom-view:finance-ledger] Could not save transaction", error);
      setStatus(`Could not save transaction: ${error?.message || error}`, "error");
    } finally {
      setBusy(transactionForm, false);
    }
  }

  async function submitAccount(event) {
    event.preventDefault();
    const formData = new FormData(accountForm);
    const name = text(formData.get("account"));
    const openingBalance = numberValue(formData.get("openingBalance"), 0);
    if (!name) return setStatus("Account name is required.", "error");
    if (!Number.isFinite(openingBalance)) return setStatus("Opening balance must be a number.", "error");

    const data = {
      id: makeId("ACC"),
      name,
      type: text(formData.get("accountType")) || "Bank",
      currency: currencyCode(formData.get("currency")) || bookCurrency,
      openingBalance,
      openingDate: text(formData.get("openingDate")) || localDateString(),
      openingFxRate: numberValue(formData.get("openingFxRate")),
      baseOpeningBalance: numberValue(formData.get("baseOpeningBalance")),
      includeInNetWorth: formData.get("includeInNetWorth") === "on",
      active: formData.get("active") === "on",
    };

    setBusy(accountForm, true);
    setStatus("Saving…");
    try {
      await ensureFolder(ACCOUNT_FOLDER);
      const path = uniquePath(ACCOUNT_FOLDER, safeName(name));
      await app.vault.create(path, buildAccountContent(data));
      resetAccountForm();
      setStatus(`Added account: ${name}.`, "success");
    } catch (error) {
      console.error("[custom-view:finance-ledger] Could not create account", error);
      setStatus(`Could not create account: ${error?.message || error}`, "error");
    } finally {
      setBusy(accountForm, false);
    }
  }

  async function submitSubscription(event) {
    event.preventDefault();
    const formData = new FormData(subscriptionForm);
    const selectedCategory = text(formData.get("category"));
    const category = selectedCategory === NEW_CATEGORY_VALUE ? text(formData.get("customCategory")) : selectedCategory || "Subscription";
    const name = text(formData.get("name"));
    const amount = Math.abs(numberValue(formData.get("amount")));
    if (!name) return setStatus("Subscription name is required.", "error");
    if (!Number.isFinite(amount) || amount <= 0) return setStatus("Subscription amount must be greater than zero.", "error");

    const data = {
      id: makeId("SUB"),
      name,
      amount,
      account: text(formData.get("account")),
      category,
      currency: currencyCode(formData.get("currency")) || bookCurrency,
      dueDay: Math.max(1, Math.min(31, Math.round(numberValue(formData.get("dueDay"), 1)))),
      startDate: text(formData.get("startDate")) || localDateString(),
      endDate: text(formData.get("endDate")),
      fxRate: numberValue(formData.get("fxRate")),
    };

    setBusy(subscriptionForm, true);
    setStatus("Saving…");
    try {
      await ensureFolder(SUBSCRIPTION_FOLDER);
      const path = uniquePath(SUBSCRIPTION_FOLDER, safeName(name));
      await app.vault.create(path, buildSubscriptionContent(data));
      knownCategories.add(category);
      resetSubscriptionForm();
      setStatus(`Added subscription: ${name}.`, "success");
    } catch (error) {
      console.error("[custom-view:finance-ledger] Could not create subscription", error);
      setStatus(`Could not create subscription: ${error?.message || error}`, "error");
    } finally {
      setBusy(subscriptionForm, false);
    }
  }

  async function loadTransactionForEdit(path) {
    const file = app.vault.getAbstractFileByPath(path);
    if (!file) return setStatus("Transaction file was not found.", "error");
    const fm = app.metadataCache?.getFileCache?.(file)?.frontmatter || {};
    if (text(fm.RecordType) !== "FinanceTransaction") return;

    const kind = TRANSACTION_KINDS.has(text(fm.Type).toLowerCase()) ? text(fm.Type).toLowerCase() : "expense";
    const category = text(fm.Category) || (kind === "transfer" ? "Transfer" : "Uncategorised");
    knownCategories.add(category);
    editingPath = path;
    resetTransactionForm();
    refreshCategorySelect(transactionCategory, category);
    transactionCategory.value = category;
    transactionForm.elements.namedItem("amount").value = text(fm.Amount);
    transactionForm.elements.namedItem("account").value = text(fm.Account);
    transactionForm.elements.namedItem("toAccount").value = text(fm.ToAccount);
    transactionForm.elements.namedItem("description").value = text(fm.Description);
    transactionForm.elements.namedItem("date").value = text(fm.Date).slice(0, 10) || localDateString();
    transactionForm.elements.namedItem("currency").value = currencyCode(fm.Currency) || bookCurrency;
    transactionForm.elements.namedItem("fxRate").value = text(fm.FxRateToBase);
    transactionForm.elements.namedItem("fixed").checked = boolValue(fm.Fixed, false);
    transactionForm.elements.namedItem("transactionId").value = text(fm.TransactionId) || makeId("TX");
    transactionForm.elements.namedItem("commitmentId").value = text(fm.CommitmentId);
    transactionForm.elements.namedItem("baseAmount").value = text(fm.BaseAmount);
    transactionForm.elements.namedItem("feeAmount").value = text(fm.FeeAmount);
    transactionForm.elements.namedItem("feeCurrency").value = text(fm.FeeCurrency);
    transactionForm.elements.namedItem("feeFxRate").value = text(fm.FeeFxRateToBase);
    transactionForm.elements.namedItem("feeBaseAmount").value = text(fm.FeeBaseAmount);
    showKind(kind);
    setOpen(true);
    setStatus(`Editing ${text(fm.Description) || file.basename}.`, "");
  }

  scanFinanceCategories();
  refreshCategorySelect(transactionCategory);
  refreshCategorySelect(subscriptionCategory, "Subscription");
  resetEditor();

  manageButton.addEventListener("click", () => {
    const file = app.vault.getAbstractFileByPath(FINANCE_BASE_PATH);
    if (!file) return setStatus("Finance.base was not found.", "error");
    const leaf = app.workspace?.getLeaf?.(true);
    if (leaf?.openFile) void leaf.openFile(file);
  });

  addButton.addEventListener("click", () => {
    if (editor.hidden) {
      resetEditor();
      setOpen(true);
    } else {
      setOpen(false);
    }
  });

  cancelButton.addEventListener("click", () => {
    resetEditor();
    setStatus("");
    setOpen(false);
  });

  for (const button of typeButtons) {
    button.addEventListener("click", () => {
      const kind = button.dataset.financeLedgerKind || "expense";
      if (editingPath && !TRANSACTION_KINDS.has(kind)) {
        editingPath = "";
        resetTransactionForm();
      }
      showKind(kind);
      setStatus("");
    });
  }

  transactionCategory.addEventListener("change", updateTransactionCustomCategory);
  subscriptionCategory.addEventListener("change", updateSubscriptionCustomCategory);
  transactionForm.addEventListener("submit", event => void submitTransaction(event));
  accountForm.addEventListener("submit", event => void submitAccount(event));
  subscriptionForm.addEventListener("submit", event => void submitSubscription(event));

  ledger.addEventListener("click", event => {
    if (event.target?.closest?.("button, a, input, select, textarea, summary")) return;
    const row = event.target?.closest?.("tr[data-file-path]");
    const path = row?.dataset?.filePath;
    if (path) void loadTransactionForEdit(path);
  });
})();

views.css:
/* Journal Daily Folio — writing-first daily note view. */

.obsidian-custom-view-render:has(> .cv-journal) {
  padding: 0 !important;
  background: var(--background-primary) !important;
}

.cv-journal {
  --cvj-bg: var(--background-primary);
  --cvj-surface: var(--background-primary);
  --cvj-surface-2: var(--background-secondary);
  --cvj-surface-3: var(--background-secondary-alt, var(--background-secondary));
  --cvj-text: var(--text-normal);
  --cvj-muted: var(--text-muted);
  --cvj-faint: var(--text-faint);
  --cvj-accent: var(--interactive-accent);
  --cvj-accent-soft: var(--text-accent);
  --cvj-border: var(--background-modifier-border);
  --cvj-border-strong: var(--background-modifier-border-hover, var(--background-modifier-border));
  --cvj-shadow: color-mix(in srgb, var(--shadow, #000) 22%, transparent);
  --cvj-paper-line: var(--vault-note-paper-line, 30px);
  --cvj-paper-margin-x: var(--vault-note-paper-margin-x, 44px);
  --cvj-paper: var(--vault-note-paper, color-mix(in srgb, var(--background-primary) 82%, var(--background-secondary) 18%));
  --cvj-paper-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--interactive-accent) 24%, transparent));
  --cvj-paper-margin-rule: var(--vault-note-paper-margin-rule, color-mix(in srgb, var(--interactive-accent) 24%, transparent));
  --cvj-pad: clamp(18px, 3.8cqi, 52px);

  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: clip;
  container-type: inline-size;
  background: var(--cvj-bg);
  color: var(--cvj-text);
  font-family: var(--font-interface);
}

.cv-journal *,
.cv-journal *::before,
.cv-journal *::after {
  box-sizing: border-box;
}

.cv-journal button,
.cv-journal textarea {
  font: inherit;
}

.cv-journal button:focus-visible,
.cv-journal textarea:focus-visible {
  outline: 2px solid var(--cvj-accent);
  outline-offset: 3px;
}

.cv-journal-masthead {
  width: min(100%, 1480px);
  margin: 0 auto;
  padding: clamp(24px, 4cqi, 58px) var(--cvj-pad) clamp(22px, 3cqi, 40px);
  border-bottom: 1px solid var(--cvj-border);
}

.cv-journal-brand-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
}

.cv-journal-brand,
.cv-journal-period,
.cv-journal-weekday,
.cv-journal-kicker,
.cv-journal-paper-label,
.cv-journal-quote-label {
  font-family: var(--font-monospace);
  font-weight: 700;
  text-transform: uppercase;
}

.cv-journal-brand {
  color: var(--cvj-accent-soft);
  font-size: clamp(.72rem, 1.1cqi, .86rem);
  letter-spacing: .2em;
}

.cv-journal-period {
  overflow: hidden;
  color: var(--cvj-muted);
  font-size: clamp(.64rem, .95cqi, .75rem);
  letter-spacing: .12em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-journal-date-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: clamp(24px, 5cqi, 72px);
  min-width: 0;
  margin-top: clamp(20px, 3cqi, 38px);
}

.cv-journal-date-lockup {
  min-width: 0;
}

.cv-journal-weekday {
  display: block;
  color: var(--cvj-muted);
  font-size: clamp(.72rem, 1.1cqi, .86rem);
  letter-spacing: .16em;
}

.cv-journal-date-line {
  display: flex;
  align-items: flex-end;
  gap: clamp(14px, 2.2cqi, 28px);
  margin-top: 7px;
}

.cv-journal-day-number {
  display: block;
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(4.6rem, 10.5cqi, 8.8rem);
  font-weight: 560;
  font-variant-numeric: tabular-nums;
  line-height: .78;
  letter-spacing: -.075em;
}

.cv-journal-month-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-bottom: .3em;
}

.cv-journal-month {
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(1.2rem, 2.25cqi, 2rem);
  font-weight: 650;
  line-height: 1.05;
}

.cv-journal-year {
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: clamp(.74rem, 1.1cqi, .88rem);
  letter-spacing: .1em;
}

.cv-journal-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}

.cv-journal-nav button {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 12px;
  border: 1px solid var(--cvj-border);
  border-radius: 999px;
  background: transparent;
  color: var(--cvj-muted);
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  transition: color .15s ease, border-color .15s ease, background-color .15s ease;
}

.cv-journal-nav button:hover:not(:disabled) {
  border-color: var(--cvj-border-strong);
  background: var(--background-modifier-hover);
  color: var(--cvj-text);
}

.cv-journal-nav .cv-journal-today {
  border-color: color-mix(in srgb, var(--cvj-accent) 54%, var(--cvj-border));
  color: var(--cvj-accent-soft);
}

.cv-journal-nav button:disabled {
  opacity: .36;
  cursor: default;
}

/* Quote is deliberately separated from the writable paper. */
.cv-journal-quote {
  position: relative;
  width: min(calc(100% - (2 * var(--cvj-pad))), 1380px);
  min-width: 0;
  margin: clamp(22px, 3.2cqi, 42px) auto 0;
  padding: clamp(28px, 3.8cqi, 48px) clamp(36px, 6cqi, 86px);
  overflow: hidden;
  border: 1px solid var(--cvj-border);
  border-left: 3px solid color-mix(in srgb, var(--cvj-accent) 78%, var(--cvj-border));
  border-radius: 8px;
  background:
    linear-gradient(145deg,
      color-mix(in srgb, var(--cvj-surface-3) 86%, var(--cvj-bg)) 0%,
      color-mix(in srgb, var(--cvj-surface-2) 92%, var(--cvj-bg)) 100%);
  box-shadow: 0 14px 34px color-mix(in srgb, var(--cvj-shadow) 72%, transparent);
}

.cv-journal-quote[hidden] {
  display: none;
}

.cv-journal-quote::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, color-mix(in srgb, var(--cvj-accent) 6%, transparent), transparent 26%);
}

.cv-journal-quote-label {
  position: relative;
  z-index: 1;
  display: block;
  margin-bottom: 13px;
  color: var(--cvj-accent-soft);
  font-size: .62rem;
  letter-spacing: .17em;
}

.cv-journal-quote blockquote {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: 0;
  border: 0;
  color: inherit;
}

.cv-journal-quote p {
  max-width: 82ch;
  margin: 0;
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(1.05rem, 2.1cqi, 1.55rem);
  font-weight: 600;
  line-height: 1.58;
  letter-spacing: .01em;
  text-wrap: pretty;
}

.cv-journal-quote footer {
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  margin-top: clamp(16px, 2cqi, 24px);
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: clamp(.66rem, 1cqi, .78rem);
  line-height: 1.45;
  letter-spacing: .04em;
  text-align: right;
}

.cv-journal-quote footer[hidden] {
  display: none;
}

.cv-journal-quote-mark {
  position: absolute;
  z-index: 0;
  color: color-mix(in srgb, var(--cvj-accent-soft) 16%, transparent);
  font-family: Georgia, var(--font-text);
  font-size: clamp(5.5rem, 11cqi, 10rem);
  font-weight: 700;
  line-height: 1;
  pointer-events: none;
  user-select: none;
}

.cv-journal-quote-mark--open {
  top: -10px;
  left: clamp(8px, 1.7cqi, 20px);
}

.cv-journal-quote-mark--close {
  right: clamp(8px, 1.7cqi, 20px);
  bottom: -54px;
}

.cv-journal-layout {
  width: min(100%, 1480px);
  margin: 0 auto;
  padding: clamp(28px, 4cqi, 58px) var(--cvj-pad) clamp(56px, 7cqi, 96px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(270px, 320px);
  align-items: start;
  gap: clamp(28px, 4cqi, 58px);
  min-width: 0;
}

/* The entire writing surface is one continuous ruled-paper sheet. */
.cv-journal-paper {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: clamp(680px, 82vh, 980px);
  overflow: hidden;
  border: 1px solid var(--vault-note-paper-edge, var(--cvj-border-strong));
  border-radius: 3px 6px 5px 2px;
  background: var(--vault-note-paper-background,
    linear-gradient(
      90deg,
      transparent 0 var(--cvj-paper-margin-x),
      var(--cvj-paper-margin-rule) var(--cvj-paper-margin-x) calc(var(--cvj-paper-margin-x) + 1px),
      transparent calc(var(--cvj-paper-margin-x) + 1px)
    ),
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--cvj-paper-line) - 7px),
      color-mix(in srgb, var(--cvj-paper-rule) 55%, transparent)
        calc(var(--cvj-paper-line) - 7px)
        calc(var(--cvj-paper-line) - 5px),
      transparent calc(var(--cvj-paper-line) - 5px) var(--cvj-paper-line)
    ),
    var(--cvj-paper));
  box-shadow: 0 18px 42px var(--cvj-shadow), inset 12px 0 30px color-mix(in srgb, var(--shadow, #000) 3%, transparent);
}

.cv-journal-paper::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  pointer-events: none;
  background: linear-gradient(90deg, color-mix(in srgb, var(--shadow, #000) 12%, transparent), transparent);
}

.cv-journal-paper::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--text-normal) 4%, transparent);
}

.cv-journal-paper-label {
  position: absolute;
  top: 17px;
  right: clamp(18px, 3cqi, 34px);
  z-index: 2;
  color: color-mix(in srgb, var(--cvj-muted) 58%, transparent);
  font-size: .61rem;
  letter-spacing: .16em;
  pointer-events: none;
}

.cv-journal-paper-content {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: inherit;
  padding: clamp(56px, 6cqi, 82px) clamp(26px, 4.3cqi, 58px) clamp(70px, 7cqi, 100px) clamp(72px, 7.2cqi, 98px);
  overflow-wrap: anywhere;
  background: transparent;
  color: var(--cvj-text);
  font-family: var(--font-text);
}

.cv-journal-paper-content .markdown-rendered-content,
.cv-journal-paper-content .markdown-preview-view,
.cv-journal-paper-content .markdown-preview-sizer,
.cv-journal-paper-content .markdown-preview-section {
  width: 100%;
  max-width: none;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  background: transparent;
}

.cv-journal-paper-content :is(p, li) {
  line-height: var(--cvj-paper-line);
}

.cv-journal-paper-content :is(img, video, canvas, svg, iframe) {
  max-width: 100%;
}

.cv-journal-paper-content :is(pre, table) {
  max-width: 100%;
}

.cv-journal-paper-content table {
  display: block;
  overflow-x: auto;
}

.cv-journal-paper-content > :first-child,
.cv-journal-paper-content .markdown-preview-section > :first-child {
  margin-top: 0;
}

.cv-journal-paper-content .cv-journal-source-quote {
  display: none !important;
}

.cv-journal-context {
  position: sticky;
  top: 20px;
  align-self: start;
  min-width: 0;
  padding-left: clamp(18px, 2.2cqi, 30px);
  border-left: 1px solid var(--cvj-border);
}

.cv-journal-context-section {
  min-width: 0;
  padding: 4px 0 clamp(24px, 3cqi, 34px);
}

.cv-journal-context-section + .cv-journal-context-section {
  padding-top: clamp(22px, 2.8cqi, 30px);
  border-top: 1px solid var(--cvj-border);
}

.cv-journal-kicker {
  display: block;
  margin-bottom: 14px;
  color: var(--cvj-accent-soft);
  font-size: .66rem;
  letter-spacing: .16em;
}

.cv-journal-state-group + .cv-journal-state-group {
  margin-top: 20px;
}

.cv-journal-state-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}

.cv-journal-state-head > span {
  color: var(--cvj-text);
  font-size: .78rem;
  font-weight: 650;
}

.cv-journal-state-head output {
  overflow: hidden;
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: .65rem;
  text-overflow: ellipsis;
  text-transform: capitalize;
  white-space: nowrap;
}

.cv-journal-choice-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
  min-width: 0;
}

.cv-journal-choice-grid button {
  min-width: 0;
  min-height: 32px;
  padding: 5px 3px;
  overflow: hidden;
  border: 1px solid var(--cvj-border);
  border-radius: 7px;
  background: transparent;
  color: var(--cvj-muted);
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: .56rem;
  font-weight: 700;
  line-height: 1.15;
  text-overflow: ellipsis;
  transition: background-color .14s ease, border-color .14s ease, color .14s ease;
  white-space: nowrap;
}

.cv-journal-choice-grid button:hover:not(:disabled) {
  border-color: var(--cvj-border-strong);
  background: var(--background-modifier-hover);
  color: var(--cvj-text);
}

.cv-journal-choice-grid button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--cvj-accent) 72%, var(--cvj-border));
  background: color-mix(in srgb, var(--cvj-accent) 16%, transparent);
  color: var(--cvj-accent-soft);
}

.cv-journal-choice-grid button:disabled {
  cursor: wait;
  opacity: .58;
}

.cv-journal-weather {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: baseline;
  gap: 12px;
}

.cv-journal-weather strong {
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(1.65rem, 3.4cqi, 2.25rem);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.cv-journal-weather span {
  min-width: 0;
  color: var(--cvj-muted);
  font-size: .76rem;
  line-height: 1.45;
  text-transform: capitalize;
}

.cv-journal-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}

.cv-journal-tag {
  max-width: 100%;
  padding: 5px 9px;
  overflow: hidden;
  border: 1px solid var(--cvj-border);
  border-radius: 999px;
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: .65rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-journal-reflection-label {
  display: block;
  margin-bottom: 9px;
  color: var(--cvj-muted);
  font-size: .72rem;
  line-height: 1.45;
}

.cv-journal-reflection {
  width: 100%;
  min-height: 96px;
  max-height: 260px;
  padding: 10px 11px;
  resize: vertical;
  border: 1px solid var(--cvj-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--cvj-surface-2) 72%, transparent);
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: .78rem;
  line-height: 1.55;
}

.cv-journal-reflection::placeholder {
  color: var(--cvj-faint);
}

.cv-journal-save-state {
  display: block;
  min-height: 1.2em;
  margin-top: 7px;
  color: var(--cvj-faint);
  font-family: var(--font-monospace);
  font-size: .58rem;
  line-height: 1.4;
}

.cv-journal-on-this-day {
  display: grid;
  gap: 10px;
}

.cv-journal-memory,
.cv-journal-memory:hover,
.cv-journal-memory:active {
  width: 100%;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 10px;
  margin: 0;
  padding: 2px 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cvj-text);
  cursor: pointer;
  text-align: left;
}

.cv-journal-memory:focus-visible {
  outline: 1px solid color-mix(in srgb, var(--cvj-accent) 48%, transparent);
  outline-offset: 4px;
}

.cv-journal-memory:hover .cv-journal-memory-year,
.cv-journal-memory:focus-visible .cv-journal-memory-year {
  color: var(--cvj-text);
}

.cv-journal-memory:hover .cv-journal-memory-arrow,
.cv-journal-memory:focus-visible .cv-journal-memory-arrow {
  color: var(--cvj-accent-soft);
}

.cv-journal-memory-year {
  color: var(--cvj-accent-soft);
  font-family: var(--font-monospace);
  font-size: .72rem;
  font-weight: 760;
}

.cv-journal-memory-day {
  overflow: hidden;
  color: var(--cvj-muted);
  font-size: .7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-journal-memory-arrow {
  color: var(--cvj-faint);
  font-size: .8rem;
}

.cv-journal-empty {
  display: block;
  color: var(--cvj-faint);
  font-size: .72rem;
  line-height: 1.45;
}

.cv-journal-folio-meta {
  margin: 0;
}

.cv-journal-folio-meta > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  padding: 9px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--cvj-border) 70%, transparent);
}

.cv-journal-folio-meta dt,
.cv-journal-folio-meta dd {
  margin: 0;
}

.cv-journal-folio-meta dt {
  color: var(--cvj-muted);
  font-size: .78rem;
}

.cv-journal-folio-meta dd {
  overflow: hidden;
  color: var(--cvj-text);
  font-family: var(--font-monospace);
  font-size: .72rem;
  font-weight: 700;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-journal-status {
  min-height: 1.4em;
  margin: 2px 0 0;
  color: var(--cvj-faint);
  font-family: var(--font-monospace);
  font-size: .63rem;
  line-height: 1.45;
}

.cv-journal-status:empty {
  display: none;
}

@container (max-width: 1020px) {
  .cv-journal-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .cv-journal-context {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
    padding: 24px 0 0;
    border-top: 1px solid var(--cvj-border);
    border-left: 0;
  }

  .cv-journal-context-section,
  .cv-journal-context-section + .cv-journal-context-section {
    padding: 0;
    border-top: 0;
  }

  .cv-journal-status {
    grid-column: 1 / -1;
  }
}

@container (max-width: 680px) {
  .cv-journal-brand-row {
    align-items: flex-start;
  }

  .cv-journal-date-row {
    align-items: stretch;
    flex-direction: column;
  }

  .cv-journal-day-number {
    font-size: clamp(4.2rem, 24cqi, 6.6rem);
  }

  .cv-journal-nav {
    justify-content: stretch;
    flex-wrap: nowrap;
  }

  .cv-journal-nav button {
    flex: 1 1 0;
    min-width: 0;
    padding-inline: 8px;
  }

  .cv-journal-quote {
    width: calc(100% - (2 * var(--cvj-pad)));
    padding: 26px 28px 28px 38px;
  }

  .cv-journal-paper {
    min-height: 600px;
  }

  .cv-journal-paper-content {
    padding: 56px 20px 70px 50px;
  }

  .cv-journal-context {
    grid-template-columns: minmax(0, 1fr);
    gap: 22px;
  }
}

@media (max-width: 560px) {
  .cv-journal-nav button span:not([aria-hidden="true"]) {
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .cv-journal-choice-grid {
    gap: 4px;
  }

  .cv-journal-choice-grid button {
    font-size: .53rem;
  }
}


/* CVJ_COMPACT_STATE_SNAPSHOT_START */
.cv-journal-state-list { margin: 0; }
.cv-journal-state-list > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 18px;
  padding: 9px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--cvj-border) 68%, transparent);
}
.cv-journal-state-list dt, .cv-journal-state-list dd { margin: 0; }
.cv-journal-state-list dt { color: var(--cvj-muted); font-size: .78rem; }
.cv-journal-state-cycle,
.cv-journal-state-cycle:hover,
.cv-journal-state-cycle:active {
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--cvj-accent-soft);
  cursor: pointer;
  font-family: var(--font-monospace);
  font-size: .72rem;
  font-weight: 700;
  line-height: 1.5;
  text-align: right;
  text-decoration: underline dotted color-mix(in srgb, var(--cvj-accent-soft) 38%, transparent) 1px;
  text-underline-offset: 4px;
}
.cv-journal-state-cycle:hover:not(:disabled) { color: var(--cvj-text); }
.cv-journal-state-cycle:disabled { cursor: wait; opacity: .55; }

.cv-journal-snapshot {
  width: min(calc(100% - (2 * var(--cvj-pad))), 1380px);
  min-width: 0;
  margin: clamp(22px, 3cqi, 38px) auto 0;
  border-block: 1px solid var(--cvj-border);
  background: color-mix(in srgb, var(--cvj-surface-2) 58%, transparent);
}
.cv-journal-snapshot[hidden] { display: none; }
.cv-journal-snapshot-head {
  display: flex; align-items: baseline; justify-content: space-between; gap: 18px;
  padding: 13px clamp(14px, 2cqi, 22px) 9px;
  border-bottom: 1px solid color-mix(in srgb, var(--cvj-border) 72%, transparent);
}
.cv-journal-snapshot-head .cv-journal-kicker { margin: 0; }
.cv-journal-snapshot-note { color: var(--cvj-faint); font-family: var(--font-monospace); font-size: .6rem; }
.cv-journal-snapshot-grid { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr) minmax(180px, .72fr); min-width: 0; }
.cv-journal-snapshot-pane { min-width: 0; padding: clamp(13px, 2cqi, 19px); }
.cv-journal-snapshot-pane + .cv-journal-snapshot-pane { border-left: 1px solid color-mix(in srgb, var(--cvj-border) 72%, transparent); }
.cv-journal-snapshot-pane > header {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  margin-bottom: 8px; color: var(--cvj-text); font-family: var(--font-monospace);
  font-size: .69rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
}
.cv-journal-snapshot-pane > header > :last-child { color: var(--cvj-faint); font-size: .57rem; font-weight: 650; letter-spacing: .03em; text-transform: none; }
.cv-journal-snapshot-list { display: grid; min-width: 0; }
.cv-journal-snapshot-row {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: start; gap: 12px;
  min-width: 0; padding: 6px 0; border-bottom: 1px solid color-mix(in srgb, var(--cvj-border) 44%, transparent);
}
.cv-journal-snapshot-row:last-of-type { border-bottom: 0; }
.cv-journal-snapshot-row--schedule { grid-template-columns: minmax(76px, 96px) minmax(0, 1fr); }
.cv-journal-snapshot-time, .cv-journal-snapshot-dose {
  color: var(--cvj-accent-soft); font-family: var(--font-monospace); font-size: .67rem;
  font-weight: 720; line-height: 1.4; font-variant-numeric: tabular-nums;
}
.cv-journal-snapshot-primary { min-width: 0; overflow: hidden; color: var(--cvj-text); font-size: .75rem; line-height: 1.4; text-overflow: ellipsis; }
.cv-journal-snapshot-secondary { display: block; margin-top: 2px; overflow: hidden; color: var(--cvj-faint); font-family: var(--font-monospace); font-size: .58rem; text-overflow: ellipsis; white-space: nowrap; }
.cv-journal-snapshot-more, .cv-journal-snapshot-empty { display: block; padding-top: 7px; color: var(--cvj-faint); font-family: var(--font-monospace); font-size: .6rem; }
.cv-journal-paper-content .cv-journal-source-daily-snapshot { display: none !important; }

.cv-journal-year-progress { margin-top: 18px; }
.cv-journal-year-progress-head { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 8px; color: var(--cvj-muted); font-size: .72rem; }
.cv-journal-year-progress-head output { color: var(--cvj-accent-soft); font-family: var(--font-monospace); font-size: .68rem; font-weight: 760; }
.cv-journal-year-progress-track { position: relative; width: 100%; height: 5px; overflow: hidden; border-radius: 999px; background: color-mix(in srgb, var(--cvj-border) 78%, transparent); }
.cv-journal-year-progress-track > span { position: absolute; inset: 0 auto 0 0; width: 0; border-radius: inherit; background: color-mix(in srgb, var(--cvj-accent) 70%, var(--cvj-accent-soft)); transition: width .24s ease; }

@container (max-width: 1000px) {
  .cv-journal-snapshot-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cv-journal-snapshot-pane--schedule { grid-column: 1 / -1; border-bottom: 1px solid var(--cvj-border); }
  .cv-journal-snapshot-pane:nth-child(2) { border-left: 0; }
}
@container (max-width: 640px) {
  .cv-journal-snapshot-head { align-items: flex-start; flex-direction: column; gap: 4px; }
  .cv-journal-snapshot-grid { grid-template-columns: minmax(0, 1fr); }
  .cv-journal-snapshot-pane, .cv-journal-snapshot-pane--schedule, .cv-journal-snapshot-pane:nth-child(2) { grid-column: auto; border-left: 0; border-bottom: 1px solid var(--cvj-border); }
  .cv-journal-snapshot-pane:last-child { border-bottom: 0; }
}
/* CVJ_COMPACT_STATE_SNAPSHOT_END */


/* CVJ_VISUAL_POLISH_2026_START */
/* Tighter paper/sidebar spacing. */
.cv-journal-layout {
  gap: clamp(18px, 2.4cqi, 34px);
}

/* Quote now belongs to the date/calendar masthead instead of a separate card. */
.cv-journal-quote {
  position: relative;
  width: 100%;
  min-width: 0;
  margin: clamp(18px, 2.2cqi, 30px) 0 0;
  padding: clamp(13px, 1.7cqi, 20px) 0 0 clamp(30px, 3.6cqi, 46px);
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.cv-journal-quote[hidden] { display: none; }
.cv-journal-quote::before {
  content: "";
  position: absolute;
  inset: auto;
  top: clamp(13px, 1.7cqi, 20px);
  bottom: 2px;
  left: 0;
  right: auto;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(to bottom,
    color-mix(in srgb, var(--cvj-accent) 74%, transparent),
    color-mix(in srgb, var(--cvj-accent-soft) 16%, transparent));
  pointer-events: none;
}
.cv-journal-quote-label {
  position: relative;
  z-index: 1;
  display: block;
  margin: 0 0 9px;
  color: var(--cvj-accent-soft);
  font-size: .59rem;
  letter-spacing: .17em;
}
.cv-journal-quote blockquote {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: 0;
  border: 0;
  color: inherit;
}
.cv-journal-quote p {
  max-width: 92ch;
  margin: 0;
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(.94rem, 1.32cqi, 1.14rem);
  font-weight: 560;
  line-height: 1.56;
  letter-spacing: .005em;
  text-wrap: pretty;
}
.cv-journal-quote footer {
  display: flex;
  justify-content: flex-start;
  gap: 8px;
  margin-top: 10px;
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: clamp(.61rem, .88cqi, .71rem);
  line-height: 1.4;
  letter-spacing: .035em;
  text-align: left;
}
.cv-journal-quote footer[hidden] { display: none; }
.cv-journal-quote-mark {
  position: absolute;
  z-index: 0;
  color: color-mix(in srgb, var(--cvj-accent-soft) 13%, transparent);
  font-family: Georgia, var(--font-text);
  font-weight: 700;
  line-height: 1;
  pointer-events: none;
  user-select: none;
}
.cv-journal-quote-mark--open {
  top: 4px;
  left: 8px;
  font-size: clamp(2.6rem, 4.2cqi, 4rem);
}
.cv-journal-quote-mark--close { display: none; }

/* Slightly larger Daily Snapshot typography. */
.cv-journal-snapshot-pane > header { font-size: .73rem; }
.cv-journal-snapshot-pane > header > :last-child { font-size: .61rem; }
.cv-journal-snapshot-time,
.cv-journal-snapshot-dose { font-size: .72rem; }
.cv-journal-snapshot-primary { font-size: .81rem; line-height: 1.42; }
.cv-journal-snapshot-secondary { font-size: .63rem; }
.cv-journal-snapshot-more,
.cv-journal-snapshot-empty { font-size: .64rem; }
/* CVJ_VISUAL_POLISH_2026_END */


/* CVJ_MASTHEAD_CONTEXT_V2_START */
/* Date, quote and navigation are one masthead composition. */
.cv-journal-date-row {
  display: grid;
  grid-template-columns: minmax(260px, .72fr) minmax(0, 1.28fr);
  grid-template-areas:
    "date quote"
    "date nav";
  column-gap: clamp(32px, 5cqi, 80px);
  row-gap: clamp(16px, 2cqi, 24px);
  align-items: end;
}

.cv-journal-date-lockup {
  grid-area: date;
  align-self: center;
}

.cv-journal-quote {
  grid-area: quote;
  align-self: end;
  width: 100%;
  margin: 0;
  padding: 0 0 0 clamp(30px, 3.6cqi, 46px);
}

.cv-journal-quote::before {
  top: 2px;
  bottom: 2px;
}

.cv-journal-quote-mark--open {
  top: -8px;
}

.cv-journal-nav {
  grid-area: nav;
  align-self: start;
  justify-content: flex-end;
}

/* Context sections use actual markdown-style dividers instead of section borders. */
.cv-journal-context-section,
.cv-journal-context-section + .cv-journal-context-section {
  padding: 0;
  border-top: 0;
}

.cv-journal .cv-journal-context-rule {
  --cu-hr-accent: var(--cvj-accent);
  --cu-hr-ink: color-mix(in srgb, var(--cvj-muted) 52%, transparent);
  position: relative;
  width: 100%;
  height: 26px;
  margin: 10px 0 12px;
  overflow: visible;
  border: 0;
  opacity: .78;
  background: linear-gradient(90deg,
    transparent 0%,
    var(--cu-hr-ink) 12%,
    color-mix(in srgb, var(--cu-hr-accent) 58%, var(--cu-hr-ink)) 38%,
    transparent 45% 55%,
    color-mix(in srgb, var(--cu-hr-accent) 58%, var(--cu-hr-ink)) 62%,
    var(--cu-hr-ink) 88%,
    transparent 100%) center / 100% 1px no-repeat;
}

.cv-journal .cv-journal-context-rule::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 10px;
  height: 10px;
  transform: translate(-50%, -50%) rotate(45deg);
  border: 1px solid color-mix(in srgb, var(--cu-hr-accent) 70%, var(--cvj-muted));
  border-radius: 2px;
  background: transparent;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--cu-hr-accent) 8%, transparent);
}

.cv-journal .cv-journal-context-rule::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 3px;
  height: 3px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: var(--cu-hr-accent);
  box-shadow:
    -18px 0 0 -1px color-mix(in srgb, var(--cu-hr-accent) 48%, transparent),
     18px 0 0 -1px color-mix(in srgb, var(--cu-hr-accent) 48%, transparent);
}

.cv-journal-context-rule:has(+ .cv-journal-context-section[hidden]) {
  display: none;
}

/* Keep only the line between Mood and Energy; no line below Energy. */
.cv-journal-state-list > div {
  border-bottom: 0;
}

.cv-journal-state-list > div + div {
  border-top: 1px solid color-mix(in srgb, var(--cvj-border) 68%, transparent);
}

@container (max-width: 1020px) {
  .cv-journal-context {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }

  .cv-journal-context-rule {
    grid-column: 1 / -1;
  }
}

@container (max-width: 860px) {
  .cv-journal-date-row {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "date"
      "quote"
      "nav";
    column-gap: 0;
    row-gap: 18px;
    align-items: start;
  }

  .cv-journal-date-lockup,
  .cv-journal-quote,
  .cv-journal-nav {
    align-self: auto;
  }

  .cv-journal-nav {
    justify-content: flex-start;
  }
}
/* CVJ_MASTHEAD_CONTEXT_V2_END */


/* CV_JOURNAL_SIDEBAR_HEALTH_V1 */
.cv-journal-paper-content { cursor: text; }
.cv-journal-paper-content:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--cvj-accent) 72%, transparent);
  outline-offset: -2px;
}
.cv-journal.is-opening-editor .cv-journal-paper-content { cursor: progress; }

.cv-journal-weight {
  --cvj-weight-up: var(--mint, var(--lake-accent, var(--interactive-accent)));
  --cvj-weight-down: var(--light-blue, var(--cc-p07, var(--text-accent)));
  --cvj-weight-stable: var(--cvj-muted);
  position: relative;
  min-width: 0;
}
.cv-journal-weight-summary,
.cv-journal-weight-summary:hover,
.cv-journal-weight-summary:active {
  width: 100%;
  min-width: 0;
  min-height: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cvj-text);
  cursor: text;
  text-align: left;
}
.cv-journal-weight-summary:hover .cv-journal-weight-copy strong {
  color: var(--cvj-accent-soft);
}
.cv-journal-weight-copy { min-width: 0; display: grid; gap: 4px; }
.cv-journal-weight-copy strong {
  color: var(--cvj-text);
  font-family: var(--font-text);
  font-size: clamp(1.65rem, 3.4cqi, 2.25rem);
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  transition: color .14s ease;
}
.cv-journal-weight-copy span {
  overflow: hidden;
  color: var(--cvj-muted);
  font-family: var(--font-monospace);
  font-size: .58rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cv-journal-weight-change {
  flex: 0 0 auto;
  font-family: var(--font-monospace);
  font-size: .66rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.cv-journal-weight :is(.is-up) { color: var(--cvj-weight-up); }
.cv-journal-weight :is(.is-down) { color: var(--cvj-weight-down); }
.cv-journal-weight :is(.is-stable, .is-unavailable) { color: var(--cvj-weight-stable); }
.cv-journal-weight-popover {
  position: absolute;
  right: 0;
  top: calc(100% + 8px);
  z-index: 50;
  width: min(320px, calc(100vw - 36px));
  padding: 12px;
  border: 1px solid var(--cvj-border-strong);
  border-radius: 9px;
  background: var(--cvj-surface-3);
  color: var(--cvj-text);
  box-shadow: 0 12px 30px var(--cvj-shadow);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  pointer-events: none;
  transition: opacity .12s ease, transform .12s ease, visibility .12s ease;
}
.cv-journal-weight:not(.is-editing):hover .cv-journal-weight-popover,
.cv-journal-weight:not(.is-editing):focus-within .cv-journal-weight-popover {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  pointer-events: auto;
}
.cv-journal-weight-popover-title {
  display: block;
  margin-bottom: 4px;
  color: var(--cvj-accent-soft);
  font-family: var(--font-monospace);
  font-size: .64rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.cv-journal-weight-row {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  gap: 2px 8px;
  align-items: baseline;
  padding: 8px 0;
  border-top: 1px solid color-mix(in srgb, var(--cvj-border) 70%, transparent);
  font-size: .68rem;
}
.cv-journal-weight-row > span,
.cv-journal-weight-row > small { color: var(--cvj-muted); }
.cv-journal-weight-row > em {
  font-family: var(--font-monospace);
  font-size: .62rem;
  font-style: normal;
  font-weight: 700;
}
.cv-journal-weight-row > small {
  grid-column: 2 / 4;
  font-family: var(--font-monospace);
  font-size: .55rem;
}
.cv-journal-weight-spark-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding-top: 8px;
  border-top: 1px solid color-mix(in srgb, var(--cvj-border) 70%, transparent);
  color: var(--cvj-muted);
  font-size: .6rem;
}
.cv-journal-weight-spark {
  display: block;
  margin-top: 4px;
  overflow: hidden;
  color: var(--cvj-weight-down);
  font-family: var(--font-monospace);
  font-size: .9rem;
  letter-spacing: .05em;
  white-space: nowrap;
}
.cv-journal-weight-note {
  display: block;
  margin-top: 6px;
  color: var(--cvj-faint);
  font-size: .54rem;
  line-height: 1.4;
}
.cv-journal-weight-editor {
  margin-top: 8px;
  padding: 9px;
  border: 1px solid var(--cvj-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--cvj-surface-2) 72%, transparent);
}
.cv-journal-weight-editor[hidden] { display: none; }
.cv-journal-weight-editor > label {
  display: block;
  margin-bottom: 6px;
  color: var(--cvj-muted);
  font-size: .62rem;
}
.cv-journal-weight-editor-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 5px;
}
.cv-journal-weight-editor-row input,
.cv-journal-weight-editor-row button {
  min-width: 0;
  min-height: 32px;
  border: 1px solid var(--cvj-border);
  border-radius: 7px;
  background: var(--cvj-surface);
  color: var(--cvj-text);
  font: inherit;
  font-size: .66rem;
}
.cv-journal-weight-editor-row input {
  width: 100%;
  padding: 5px 7px;
  font-family: var(--font-monospace);
  font-variant-numeric: tabular-nums;
}
.cv-journal-weight-editor-row button { padding: 5px 8px; cursor: pointer; }
.cv-journal-weight-editor-row button:hover:not(:disabled) {
  border-color: var(--cvj-border-strong);
  background: var(--background-modifier-hover);
}

