const journalContext = tp;
const journalContainer = journalContext.container || this;
const journalRoot = journalContainer.querySelector(".cv-journal");

if (journalRoot) {
  const journalApp = journalContext.app;
  const journalFile = journalContext.file;
  const journalFrontmatter = journalContext.frontmatter || {};
  const journalBodyContent = String(journalContext.bodyContent || "");
  const journalDocument = journalContext.activeDocument || journalContainer.ownerDocument;
  const journalWindow = journalContext.activeWindow || journalDocument.defaultView;
  const journalQuery = selector => journalRoot.querySelector(selector);
  const journalQueryAll = selector => Array.from(journalRoot.querySelectorAll(selector));
  const JOURNAL_ROOT = "00_Capture/01_Journal/";
  const SETTINGS_PATH = "90_System/93_Configuration/settings.md";
  const WEATHER_CACHE_MS = 10 * 60 * 1000;
  const MOOD_CHOICES = ["terrible", "bad", "okay", "good", "great"];
  const ENERGY_CHOICES = ["drained", "low", "medium", "high", "peak"];

  const text = value => String(value ?? "").trim();
  const asArray = value => {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return [value];
  };
  const numeric = value => {
    if (value === null || value === undefined || value === "") return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };
  const weightValue = value => {
    const parsed = numeric(value);
    return parsed !== null && parsed >= 20 && parsed <= 400 ? parsed : null;
  };
  const titleCase = value => text(value)
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, character => character.toUpperCase());

  function makeDate(year, month, day) {
    const date = new Date(Number(year), Number(month) - 1, Number(day), 12, 0, 0, 0);
    if (
      Number.isNaN(date.getTime()) ||
      date.getFullYear() !== Number(year) ||
      date.getMonth() !== Number(month) - 1 ||
      date.getDate() !== Number(day)
    ) return null;
    return date;
  }

  function parseJournalDate(value, basename = "") {
    const iso = text(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (iso) return makeDate(iso[1], iso[2], iso[3]);

    const named = text(basename).match(/(?:^|\D)(\d{2})-(\d{2})-(\d{4})(?:\D|$)/);
    if (named) return makeDate(named[3], named[2], named[1]);

    return null;
  }

  function dateKey(date) {
    if (!date) return "";
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function todayKey() {
    const now = new Date();
    return dateKey(new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12));
  }

  function isoWeek(date) {
    const utc = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    const weekday = utc.getUTCDay() || 7;
    utc.setUTCDate(utc.getUTCDate() + 4 - weekday);
    const yearStart = new Date(Date.UTC(utc.getUTCFullYear(), 0, 1));
    return Math.ceil((((utc - yearStart) / 86400000) + 1) / 7);
  }

  function dayOfYear(date) {
    const start = Date.UTC(date.getFullYear(), 0, 0);
    const current = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
    return Math.floor((current - start) / 86400000);
  }

  function daysInYear(year) {
    return new Date(year, 1, 29).getMonth() === 1 ? 366 : 365;
  }

  function setText(role, value) {
    const element = journalQuery(`[data-role="${role}"]`);
    if (element) element.textContent = value;
  }

  function setStatus(message) {
    setText("journal-status", message || "");
  }

  function makeElement(tag, className, value) {
    const element = journalDocument.createElement(tag);
    if (className) element.className = className;
    if (value !== undefined) element.textContent = String(value);
    return element;
  }

  const entryDate = parseJournalDate(journalFrontmatter["journal-date"], journalFile?.basename);
  const currentEntryKey = entryDate ? dateKey(entryDate) : "";

  const journalState = {
    mood: text(journalFrontmatter.mood).toLowerCase(),
    energy: text(journalFrontmatter.energy).toLowerCase(),
    weight: weightValue(journalFrontmatter.weight),
    reflection: text(journalFrontmatter.reflection),
    weather_temp: numeric(journalFrontmatter.weather_temp),
    weather_desc: text(journalFrontmatter.weather_desc),
    weather_unit: text(journalFrontmatter.weather_unit),
  };

  let frontmatterQueue = Promise.resolve();

  function updateFrontmatter(patch) {
    if (!journalApp?.fileManager || !journalFile) {
      return Promise.reject(new Error("Journal file is unavailable"));
    }

    const task = frontmatterQueue.then(async () => {
      await journalApp.fileManager.processFrontMatter(journalFile, draft => {
        for (const [property, value] of Object.entries(patch)) draft[property] = value;
      });
      Object.assign(journalFrontmatter, patch);
    });
    frontmatterQueue = task.catch(() => {});
    return task;
  }

  function renderDateIdentity() {
    if (!entryDate) {
      setText("journal-weekday", text(journalFrontmatter.Day) || "Journal");
      setText("journal-day-number", "—");
      setText("journal-month", "Undated");
      setText("journal-year", "");
      setText("journal-period", text(journalFrontmatter.journal) || "Daily notes");
      setStatus("This entry has no readable journal-date.");
      return;
    }

    const weekday = new Intl.DateTimeFormat("en-US", { weekday: "long" }).format(entryDate);
    const month = new Intl.DateTimeFormat("en-US", { month: "long" }).format(entryDate);
    const year = String(entryDate.getFullYear());
    const iso = dateKey(entryDate);
    const dayNumber = String(entryDate.getDate()).padStart(2, "0");
    const dayNumberElement = journalQuery('[data-role="journal-day-number"]');

    setText("journal-weekday", weekday);
    setText("journal-day-number", dayNumber);
    setText("journal-month", month);
    setText("journal-year", year);
    setText("journal-period", `${month} · ${year}`);
    setText("journal-archive-month", `${month} ${year}`);
    setText("journal-week", `W${String(isoWeek(entryDate)).padStart(2, "0")}`);
    const elapsedDays = dayOfYear(entryDate);
    const totalDays = daysInYear(entryDate.getFullYear());
    const yearProgress = Math.max(0, Math.min(100, (elapsedDays / totalDays) * 100));
    const yearProgressLabel = `${yearProgress.toFixed(1).replace(/\.0$/, "")}%`;
    setText("journal-day-of-year", `${elapsedDays} / ${totalDays}`);
    setText("journal-year-progress-value", yearProgressLabel);
    const yearProgressTrack = journalQuery('[data-role="journal-year-progress-track"]');
    const yearProgressBar = journalQuery('[data-role="journal-year-progress-bar"]');
    if (yearProgressTrack) yearProgressTrack.setAttribute("aria-valuenow", yearProgress.toFixed(1));
    if (yearProgressBar) yearProgressBar.style.width = `${yearProgress}%`;

    if (dayNumberElement?.tagName === "TIME") dayNumberElement.dateTime = iso;
    journalRoot.dataset.entryDate = iso;
  }

  function parseQuoteFromBody(body) {
    const lines = String(body || "").split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const match = lines[index].match(/^>\s*\[!quote\][+-]?\s*(.*)$/i);
      if (!match) continue;

      const quoteParts = [];
      if (text(match[1])) quoteParts.push(text(match[1]));
      const following = [];
      for (let cursor = index + 1; cursor < lines.length; cursor += 1) {
        const continuation = lines[cursor].match(/^>\s?(.*)$/);
        if (!continuation) break;
        const value = text(continuation[1]);
        if (value) following.push(value);
      }

      let author = "";
      if (following.length) {
        author = following.pop();
        quoteParts.push(...following);
      }
      return { quote: quoteParts.join(" ").trim(), author: text(author) };
    }
    return { quote: "", author: "" };
  }

  const bodyQuote = parseQuoteFromBody(journalBodyContent);

  function renderQuote() {
    const card = journalQuery('[data-role="journal-quote-card"]');
    if (!card) return;

    const quote = text(journalFrontmatter.quote || journalFrontmatter.journal_quote || bodyQuote.quote);
    const author = text(journalFrontmatter.quote_author || journalFrontmatter.journal_quote_author || bodyQuote.author);
    if (!quote) {
      card.hidden = true;
      return;
    }

    setText("journal-quote-text", quote);
    setText("journal-quote-author", author);
    const footer = journalQuery('[data-role="journal-quote-footer"]');
    if (footer) footer.hidden = !author;
    card.hidden = false;
  }

  function installSourceQuoteSuppression() {
    if (!bodyQuote.quote) return;
    const content = journalQuery('[data-role="journal-content"]');
    if (!content) return;

    const suppress = () => {
      const source = content.querySelector('.callout[data-callout="quote"], [data-callout="quote"].callout');
      if (!source) return false;
      source.classList.add("cv-journal-source-quote");
      source.setAttribute("aria-hidden", "true");
      return true;
    };

    if (suppress()) return;
    const Observer = journalWindow?.MutationObserver;
    if (typeof Observer !== "function") return;
    const observer = new Observer(() => {
      if (suppress()) observer.disconnect();
    });
    observer.observe(content, { childList: true, subtree: true });
    journalWindow?.setTimeout?.(() => observer.disconnect(), 5000);
  }

  function cleanTag(value) {
    return text(value)
      .replace(/^#/, "")
      .replace(/^\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/, "$1")
      .trim();
  }

  function renderTags() {
    const section = journalQuery('[data-role="journal-tags-section"]');
    const container = journalQuery('[data-role="journal-tags"]');
    if (!section || !container) return;

    const tags = asArray(journalFrontmatter.tags)
      .map(cleanTag)
      .filter(Boolean)
      .filter(tag => tag.toLowerCase() !== "daily-notes");

    container.replaceChildren();
    for (const tag of tags) {
      const chip = makeElement("span", "cv-journal-tag", `#${tag}`);
      container.appendChild(chip);
    }
    section.hidden = tags.length === 0;
  }

  function entryForFile(file) {
    if (!file?.path?.startsWith(JOURNAL_ROOT)) return null;
    const cache = journalApp?.metadataCache?.getFileCache?.(file);
    const frontmatter = cache?.frontmatter || {};
    const date = parseJournalDate(frontmatter["journal-date"], file.basename);
    if (!date) return null;
    return { file, date, key: dateKey(date) };
  }

  function journalEntries() {
    if (!journalApp?.vault?.getMarkdownFiles) return [];
    return journalApp.vault.getMarkdownFiles()
      .map(entryForFile)
      .filter(Boolean)
      .sort((left, right) => left.date - right.date || left.file.path.localeCompare(right.file.path));
  }

  async function openEntry(entry) {
    if (!entry?.file) return;
    const leaf = journalApp?.workspace?.getLeaf?.(false);
    if (!leaf?.openFile) throw new Error("Obsidian workspace leaf is unavailable");
    await leaf.openFile(entry.file);
  }

  function configureButton(selector, target) {
    const button = journalQuery(selector);
    if (!button) return;
    button.disabled = !target;
    if (!target) return;
    button.addEventListener("click", async () => {
      setStatus("");
      try {
        await openEntry(target);
      } catch (error) {
        setStatus("Could not open that journal entry.");
        console.error("[custom-view:journal] Could not open journal entry", error);
      }
    });
  }

  function initNavigation(entries) {
    const currentIndex = entries.findIndex(entry => entry.file.path === journalFile?.path);
    let previous = null;
    let next = null;

    if (currentIndex >= 0) {
      previous = entries[currentIndex - 1] || null;
      next = entries[currentIndex + 1] || null;
    } else if (entryDate) {
      previous = [...entries].reverse().find(entry => entry.date < entryDate) || null;
      next = entries.find(entry => entry.date > entryDate) || null;
    }

    const today = entries.find(entry => entry.key === todayKey()) || null;

    configureButton('[data-action="journal-previous"]', previous);
    configureButton('[data-action="journal-next"]', next);

    const todayButton = journalQuery('[data-action="journal-today"]');
    if (!todayButton) return;

    if (currentEntryKey === todayKey()) {
      todayButton.disabled = true;
      return;
    }

    todayButton.disabled = false;
    todayButton.addEventListener("click", async () => {
      setStatus("");
      try {
        if (today) {
          await openEntry(today);
          return;
        }
        if (typeof journalApp?.commands?.executeCommandById !== "function") {
          throw new Error("Daily Notes command is unavailable");
        }
        await journalApp.commands.executeCommandById("daily-notes");
      } catch (error) {
        setStatus("Could not open today's journal entry.");
        console.error("[custom-view:journal] Could not open today's journal entry", error);
      }
    });
  }

  function renderOnThisDay(entries) {
    const container = journalQuery('[data-role="journal-on-this-day"]');
    if (!container) return;
    container.replaceChildren();

    if (!entryDate) {
      container.appendChild(makeElement("span", "cv-journal-empty", "Unavailable for an undated entry."));
      return;
    }

    const memories = entries
      .filter(entry => (
        entry.date.getMonth() === entryDate.getMonth()
        && entry.date.getDate() === entryDate.getDate()
        && entry.date.getFullYear() < entryDate.getFullYear()
      ))
      .sort((left, right) => right.date - left.date)
      .slice(0, 6);

    if (!memories.length) {
      container.appendChild(makeElement("span", "cv-journal-empty", "No earlier entry for this date yet."));
      return;
    }

    for (const memory of memories) {
      const button = makeElement("button", "cv-journal-memory");
      button.type = "button";
      const year = makeElement("span", "cv-journal-memory-year", memory.date.getFullYear());
      const weekday = makeElement(
        "span",
        "cv-journal-memory-day",
        new Intl.DateTimeFormat("en-US", { weekday: "long" }).format(memory.date),
      );
      const arrow = makeElement("span", "cv-journal-memory-arrow", "↗");
      arrow.setAttribute("aria-hidden", "true");
      button.append(year, weekday, arrow);
      button.addEventListener("click", () => {
        void openEntry(memory).catch(error => {
          setStatus("Could not open that memory.");
          console.error("[custom-view:journal] Could not open On This Day entry", error);
        });
      });
      container.appendChild(button);
    }
  }

  function choiceLabel(field, value) {
  const labels = field === "mood"
    ? { terrible: "Awful", bad: "Low", okay: "Okay", good: "Good", great: "Great" }
    : { drained: "Drained", low: "Low", medium: "Mid", high: "High", peak: "Peak" };
  return labels[value] || (value ? titleCase(value) : "Not set");
}

function renderChoice(field, values) {
  const value = text(journalState[field]).toLowerCase();
  const button = journalQuery(`[data-journal-field="${field}"]`);
  if (!button) return;
  button.textContent = choiceLabel(field, value);
  button.dataset.value = value;
  if (value && !values.includes(value)) button.dataset.invalid = "true";
  else delete button.dataset.invalid;
}

function initChoice(field, values) {
  const button = journalQuery(`[data-journal-field="${field}"]`);
  if (!button) return;
  renderChoice(field, values);
  button.addEventListener("click", async event => {
    const current = text(journalState[field]).toLowerCase();
    const index = values.indexOf(current);
    const direction = event.shiftKey ? -1 : 1;
    const next = index < 0
      ? (field === "mood" ? "okay" : "medium")
      : values[(index + direction + values.length) % values.length];
    if (!next || next === current) return;
    const previous = journalState[field];
    journalState[field] = next;
    renderChoice(field, values);
    button.disabled = true;
    setStatus(`Saving ${field}…`);
    try {
      await updateFrontmatter({ [field]: next });
      setStatus(`${titleCase(field)} saved.`);
    } catch (error) {
      journalState[field] = previous;
      setStatus(`${titleCase(field)} was not saved.`);
      console.error(`[custom-view:journal] Could not save ${field}`, error);
    } finally {
      button.disabled = false;
      renderChoice(field, values);
    }
  });
}

  function renderReflection() {
    const input = journalQuery('[data-role="journal-reflection"]');
    if (input && journalDocument.activeElement !== input) input.value = journalState.reflection;
  }

  function initReflection() {
    const input = journalQuery('[data-role="journal-reflection"]');
    const state = journalQuery('[data-role="journal-reflection-state"]');
    if (!input) return;

    renderReflection();
    input.addEventListener("keydown", event => {
      if (event.key === "Escape") {
        event.preventDefault();
        input.value = journalState.reflection;
        input.blur();
      } else if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        input.blur();
      }
    });

    input.addEventListener("change", async () => {
      const next = text(input.value);
      if (next === journalState.reflection) return;
      const previous = journalState.reflection;
      journalState.reflection = next;
      if (state) state.textContent = "Saving…";
      try {
        await updateFrontmatter({ reflection: next });
        if (state) state.textContent = "Saved";
      } catch (error) {
        journalState.reflection = previous;
        renderReflection();
        if (state) state.textContent = "Not saved";
        console.error("[custom-view:journal] Could not save reflection", error);
      }
    });
  }

  const WEIGHT_STABLE_THRESHOLD_PCT = 0.2;

  function weightShiftDays(date, amount) {
    const next = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 12, 0, 0, 0);
    next.setDate(next.getDate() + amount);
    return next;
  }

  function weightDaysInMonth(year, monthIndex) {
    return new Date(year, monthIndex + 1, 0, 12).getDate();
  }

  function weightEquivalentPreviousYear(date) {
    const year = date.getFullYear() - 1;
    const month = date.getMonth();
    const day = Math.min(date.getDate(), weightDaysInMonth(year, month));
    return new Date(year, month, day, 12, 0, 0, 0);
  }

  function weightAverage(values) {
    return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
  }

  function formatWeight(value) {
    return Number.isFinite(value) ? value.toFixed(1).replace(/\.0$/, "") : "—";
  }

  function formatWeightSigned(value, suffix = "") {
    if (!Number.isFinite(value)) return "—";
    if (Math.abs(value) < 0.05) return `0${suffix}`;
    const absolute = Math.abs(value).toFixed(1).replace(/\.0$/, "");
    return `${value > 0 ? "+" : "−"}${absolute}${suffix}`;
  }

  function weightMeasurements() {
    if (!journalApp?.vault?.getMarkdownFiles) return [];
    return journalApp.vault.getMarkdownFiles()
      .filter(file => file?.path?.startsWith(JOURNAL_ROOT))
      .map(file => {
        const cache = journalApp?.metadataCache?.getFileCache?.(file);
        return {
          file,
          date: parseJournalDate("", file.basename),
          weight: file.path === journalFile?.path ? journalState.weight : weightValue(cache?.frontmatter?.weight),
        };
      })
      .filter(entry => entry.date && Number.isFinite(entry.weight))
      .sort((left, right) => left.date - right.date || left.file.path.localeCompare(right.file.path));
  }

  function weightSummarize(measurements, start, end) {
    const values = measurements
      .filter(entry => entry.date >= start && entry.date < end)
      .map(entry => entry.weight);
    return { avg: weightAverage(values), count: values.length };
  }

  function weightCompare(current, previous) {
    if (!Number.isFinite(current.avg) || !Number.isFinite(previous.avg) || previous.avg === 0) {
      return { available: false, direction: "unavailable", arrow: "→", pct: null, kg: null };
    }
    const kg = current.avg - previous.avg;
    const pct = (kg / previous.avg) * 100;
    if (Math.abs(pct) < WEIGHT_STABLE_THRESHOLD_PCT) {
      return { available: true, direction: "stable", arrow: "→", pct, kg };
    }
    return {
      available: true,
      direction: pct > 0 ? "up" : "down",
      arrow: pct > 0 ? "↑" : "↓",
      pct,
      kg,
    };
  }

  function weightSparkline(values) {
    const blocks = "▁▂▃▄▅▆▇█";
    const available = values.filter(Number.isFinite);
    if (!available.length) return "—";
    const min = Math.min(...available);
    const max = Math.max(...available);
    if (Math.abs(max - min) < 0.0001) {
      return values.map(value => Number.isFinite(value) ? "▄" : "·").join("");
    }
    return values.map(value => {
      if (!Number.isFinite(value)) return "·";
      const index = Math.max(0, Math.min(
        blocks.length - 1,
        Math.round(((value - min) / (max - min)) * (blocks.length - 1)),
      ));
      return blocks[index];
    }).join("");
  }

  function weightStatistics() {
    if (!entryDate) return null;
    const measurements = weightMeasurements();
    const endExclusive = weightShiftDays(entryDate, 1);
    const available = measurements.filter(entry => entry.date < endExclusive);
    const latest = available.at(-1) || null;

    const weekCurrent = weightSummarize(measurements, weightShiftDays(entryDate, -6), endExclusive);
    const weekPrevious = weightSummarize(measurements, weightShiftDays(entryDate, -13), weightShiftDays(entryDate, -6));
    const week = weightCompare(weekCurrent, weekPrevious);

    const monthStart = new Date(entryDate.getFullYear(), entryDate.getMonth(), 1, 12);
    const previousMonthStart = new Date(entryDate.getFullYear(), entryDate.getMonth() - 1, 1, 12);
    const monthCurrent = weightSummarize(measurements, monthStart, endExclusive);
    const monthPrevious = weightSummarize(measurements, previousMonthStart, monthStart);
    const month = weightCompare(monthCurrent, monthPrevious);

    const yearStart = new Date(entryDate.getFullYear(), 0, 1, 12);
    const previousYearStart = new Date(entryDate.getFullYear() - 1, 0, 1, 12);
    const previousYearEnd = weightShiftDays(weightEquivalentPreviousYear(entryDate), 1);
    const yearCurrent = weightSummarize(measurements, yearStart, endExclusive);
    const yearPrevious = weightSummarize(measurements, previousYearStart, previousYearEnd);
    const year = weightCompare(yearCurrent, yearPrevious);

    const weeks = [];
    for (let offset = 11; offset >= 0; offset -= 1) {
      const weekEnd = weightShiftDays(endExclusive, -offset * 7);
      const weekStart = weightShiftDays(weekEnd, -7);
      weeks.push(weightSummarize(measurements, weekStart, weekEnd).avg);
    }

    return {
      latest,
      weekCurrent,
      weekPrevious,
      week,
      monthCurrent,
      monthPrevious,
      month,
      yearCurrent,
      yearPrevious,
      year,
      sparkline: weightSparkline(weeks),
    };
  }

  function setWeightDirection(element, result) {
    if (!element) return;
    element.classList.remove("is-up", "is-down", "is-stable", "is-unavailable");
    element.classList.add(`is-${result?.direction || "unavailable"}`);
  }

  function weightChangeText(result, period) {
    if (!result?.available) return `—${period ? ` ${period}` : ""}`;
    const pct = Math.abs(result.pct).toFixed(1).replace(/\.0$/, "");
    return `${result.arrow} ${pct}%${period ? ` ${period}` : ""}`;
  }

  function renderWeight() {
    const root = journalQuery('[data-role="journal-weight"]');
    const valueElement = journalQuery('[data-role="journal-weight-value"]');
    const sourceElement = journalQuery('[data-role="journal-weight-source"]');
    const changeElement = journalQuery('[data-role="journal-weight-change"]');
    const popover = journalQuery('[data-role="journal-weight-popover"]');
    const input = journalQuery('[data-role="journal-weight-input"]');
    if (!root || !valueElement || !sourceElement || !changeElement || !popover) return;

    const stats = weightStatistics();
    const latest = stats?.latest || null;
    const displayWeight = Number.isFinite(journalState.weight) ? journalState.weight : latest?.weight ?? null;
    valueElement.textContent = Number.isFinite(displayWeight) ? `${formatWeight(displayWeight)} kg` : "— kg";

    const dateFormatter = new Intl.DateTimeFormat("en-US", { day: "2-digit", month: "short", year: "numeric" });
    if (Number.isFinite(journalState.weight)) sourceElement.textContent = "Current entry";
    else if (latest) sourceElement.textContent = `Latest · ${dateFormatter.format(latest.date)}`;
    else sourceElement.textContent = "No measurement yet";

    changeElement.textContent = weightChangeText(stats?.week, "W/W");
    setWeightDirection(changeElement, stats?.week);

    const row = (label, current, previous, result) => {
      const avg = Number.isFinite(current?.avg) ? `${formatWeight(current.avg)} kg` : "—";
      const delta = result?.available ? formatWeightSigned(result.kg, " kg") : "insufficient data";
      const change = weightChangeText(result, "");
      return `<div class="cv-journal-weight-row"><span>${label}</span><strong>${avg}</strong><em class="is-${result?.direction || "unavailable"}">${change}</em><small>${delta} · n=${current?.count || 0}/${previous?.count || 0}</small></div>`;
    };

    popover.innerHTML = stats ? `
      <span class="cv-journal-weight-popover-title">Weight trend</span>
      ${row("Week", stats.weekCurrent, stats.weekPrevious, stats.week)}
      ${row("Month", stats.monthCurrent, stats.monthPrevious, stats.month)}
      ${row("Year", stats.yearCurrent, stats.yearPrevious, stats.year)}
      <span class="cv-journal-weight-spark-head"><span>12 week trend</span><small>weekly averages</small></span>
      <span class="cv-journal-weight-spark">${stats.sparkline}</span>
      <small class="cv-journal-weight-note">Arrows indicate direction only; colors follow the Global System theme palette.</small>
    ` : '<span class="cv-journal-weight-popover-title">Weight trend</span><small>Journal date unavailable.</small>';

    if (input && journalDocument.activeElement !== input) {
      input.value = Number.isFinite(journalState.weight) ? String(journalState.weight) : "";
    }
  }

  function initWeight() {
    const root = journalQuery('[data-role="journal-weight"]');
    const summary = journalQuery('[data-action="journal-weight-edit"]');
    const editor = journalQuery('[data-role="journal-weight-editor"]');
    const input = journalQuery('[data-role="journal-weight-input"]');
    const save = journalQuery('[data-action="journal-weight-save"]');
    const cancel = journalQuery('[data-action="journal-weight-cancel"]');
    const state = journalQuery('[data-role="journal-weight-state"]');
    if (!root || !summary || !editor || !input || !save || !cancel) return;

    const closeEditor = () => {
      root.classList.remove("is-editing");
      editor.hidden = true;
      summary.setAttribute("aria-expanded", "false");
      input.value = Number.isFinite(journalState.weight) ? String(journalState.weight) : "";
    };

    const openEditor = () => {
      root.classList.add("is-editing");
      editor.hidden = false;
      summary.setAttribute("aria-expanded", "true");
      input.value = Number.isFinite(journalState.weight) ? String(journalState.weight) : "";
      input.focus();
      input.select();
    };

    const commit = async () => {
      const raw = text(input.value).replace(",", ".");
      const next = raw ? weightValue(raw) : null;
      if (raw && next === null) {
        if (state) state.textContent = "Enter a weight from 20 to 400 kg.";
        input.focus();
        return;
      }
      if (next === journalState.weight) {
        closeEditor();
        return;
      }

      const previous = journalState.weight;
      journalState.weight = next;
      save.disabled = true;
      input.disabled = true;
      if (state) state.textContent = "Saving…";
      renderWeight();
      try {
        await updateFrontmatter({ weight: next });
        if (state) state.textContent = "Saved";
        closeEditor();
        renderWeight();
      } catch (error) {
        journalState.weight = previous;
        if (state) state.textContent = "Not saved";
        renderWeight();
        console.error("[custom-view:journal] Could not save weight", error);
      } finally {
        save.disabled = false;
        input.disabled = false;
      }
    };

    summary.addEventListener("click", event => {
      event.preventDefault();
      openEditor();
    });
    save.addEventListener("click", () => void commit());
    cancel.addEventListener("click", closeEditor);
    input.addEventListener("keydown", event => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeEditor();
      } else if (event.key === "Enter") {
        event.preventDefault();
        void commit();
      }
    });

    renderWeight();
  }

  function settingsFrontmatter() {
    const file = journalApp?.vault?.getAbstractFileByPath?.(SETTINGS_PATH);
    if (!file) return {};
    return journalApp?.metadataCache?.getFileCache?.(file)?.frontmatter || {};
  }

  function weatherUnit(units) {
    const normalized = text(units || "metric").toLowerCase();
    if (normalized === "imperial") return "°F";
    if (normalized === "standard") return "K";
    return "°C";
  }

  function renderWeatherValue(temperature, description, unit) {
    const value = numeric(temperature);
    setText("journal-weather-temp", value === null ? "—" : `${Math.round(value)}${unit || ""}`);
    setText("journal-weather-desc", text(description) || "Weather unavailable");
  }

  async function persistWeatherSnapshot(temperature, description, unit) {
    const rounded = numeric(temperature) === null ? null : Math.round(Number(temperature));
    const normalizedDescription = text(description);
    const normalizedUnit = text(unit);
    const patch = {};

    if (rounded !== journalState.weather_temp) patch.weather_temp = rounded;
    if (normalizedDescription !== journalState.weather_desc) patch.weather_desc = normalizedDescription;
    if (normalizedUnit !== journalState.weather_unit) patch.weather_unit = normalizedUnit;
    if (!Object.keys(patch).length) return;

    Object.assign(journalState, patch);
    try {
      await updateFrontmatter(patch);
    } catch (error) {
      console.debug("[custom-view:journal] Could not persist weather snapshot", error);
    }
  }

  async function renderWeather() {
    const settings = settingsFrontmatter();
    const configuredUnit = weatherUnit(settings?.openweathermap_unit);
    const hasSnapshot = journalState.weather_temp !== null || Boolean(journalState.weather_desc);
    const snapshotUnit = journalState.weather_unit || configuredUnit;

    if (!entryDate || currentEntryKey !== todayKey()) {
      if (hasSnapshot) renderWeatherValue(journalState.weather_temp, journalState.weather_desc, snapshotUnit);
      else renderWeatherValue(null, "No weather snapshot", snapshotUnit);
      return;
    }

    const apiKey = text(settings?.openweathermap_key);
    const city = text(settings?.openweathermap_city);
    const units = text(settings?.openweathermap_unit || "metric").toLowerCase();
    const unit = weatherUnit(units);
    if (!apiKey || !city) {
      if (hasSnapshot) renderWeatherValue(journalState.weather_temp, journalState.weather_desc, snapshotUnit);
      else renderWeatherValue(null, "Weather not configured", unit);
      return;
    }

    const cacheKey = `${city}|${units}`;
    const cache = journalWindow?.__cvJournalWeatherCache;
    if (cache?.key === cacheKey && Date.now() - cache.ts < WEATHER_CACHE_MS) {
      renderWeatherValue(cache.temperature, cache.description, cache.unit);
      void persistWeatherSnapshot(cache.temperature, cache.description, cache.unit);
      return;
    }

    const fetchImpl = journalWindow?.fetch?.bind(journalWindow) || globalThis.fetch?.bind(globalThis);
    if (typeof fetchImpl !== "function") {
      if (hasSnapshot) renderWeatherValue(journalState.weather_temp, journalState.weather_desc, snapshotUnit);
      else renderWeatherValue(null, "Weather unavailable", unit);
      return;
    }

    const AbortControllerImpl = journalWindow?.AbortController || globalThis.AbortController;
    const controller = typeof AbortControllerImpl === "function" ? new AbortControllerImpl() : null;
    const timeout = controller && journalWindow?.setTimeout
      ? journalWindow.setTimeout(() => controller.abort(), 8000)
      : null;

    try {
      const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&units=${encodeURIComponent(units)}&appid=${encodeURIComponent(apiKey)}`;
      const response = await fetchImpl(url, controller ? { signal: controller.signal } : undefined);
      if (!response.ok) throw new Error(`Weather returned ${response.status}`);
      const data = await response.json();
      const temperature = numeric(data?.main?.temp);
      const description = text(data?.weather?.[0]?.description).replace(/^./, character => character.toUpperCase());
      if (temperature === null && !description) throw new Error("Weather response had no displayable data");

      renderWeatherValue(temperature, description, unit);
      if (journalWindow) {
        journalWindow.__cvJournalWeatherCache = {
          key: cacheKey,
          ts: Date.now(),
          temperature,
          description,
          unit,
        };
      }
      await persistWeatherSnapshot(temperature, description, unit);
    } catch (error) {
      if (hasSnapshot) renderWeatherValue(journalState.weather_temp, journalState.weather_desc, snapshotUnit);
      else renderWeatherValue(null, "Weather unavailable", unit);
      console.debug("[custom-view:journal] Weather unavailable", error);
    } finally {
      if (timeout !== null && timeout !== undefined) journalWindow?.clearTimeout?.(timeout);
    }
  }

  function normalizeSnapshotText(value) {
  return text(value).replace(/\s+/g, " ").toLowerCase();
}

function snapshotHeading(content, label) {
  const wanted = normalizeSnapshotText(label);
  return Array.from(content.querySelectorAll('h1,h2,h3,h4,h5,h6,[role="heading"],.markdown-embed-title'))
    .find(element => normalizeSnapshotText(element.textContent) === wanted) || null;
}

function snapshotSurface(heading, content) {
  if (!heading) return null;
  const selector = 'table,.bases-table-container,.bases-view[data-view-type="table"],.bases-view,[role="table"],[role="grid"]';
  const stop = 'h1,h2,h3,h4,h5,h6,[role="heading"]';
  for (let node = heading.nextElementSibling; node; node = node.nextElementSibling) {
    if (node.matches?.(stop)) break;
    if (node.matches?.(selector)) return node;
    const nested = node.querySelector?.(selector);
    if (nested) return nested;
  }
  for (let scope = heading.parentElement, depth = 0; scope && scope !== content && depth < 7; scope = scope.parentElement, depth += 1) {
    const candidates = Array.from(scope.querySelectorAll?.(selector) || []);
    const following = candidates.find(candidate => (heading.compareDocumentPosition(candidate) & 4) !== 0);
    if (following) return following;
  }
  return null;
}

function snapshotTable(surface) {
  if (!surface) return null;
  const table = surface.matches?.('table') ? surface : surface.querySelector?.('table');
  if (table) {
    const all = Array.from(table.querySelectorAll('tr'));
    if (!all.length) return null;
    const headerRow = all.find(row => row.querySelector('th')) || null;
    const headers = headerRow ? Array.from(headerRow.querySelectorAll('th,td')).map(cell => text(cell.textContent).replace(/\s+/g, ' ')) : [];
    const rows = all.filter(row => row !== headerRow).map(row => Array.from(row.querySelectorAll('th,td')).map(cell => text(cell.textContent).replace(/\s+/g, ' '))).filter(row => row.some(Boolean));
    return rows.length ? { headers, rows } : null;
  }

  const base = surface.matches?.('.bases-view,.bases-table-container') ? surface : surface.querySelector?.('.bases-view,.bases-table-container') || surface;
  const head = base.querySelector?.('.bases-thead .bases-tr');
  const baseRows = Array.from(base.querySelectorAll?.('.bases-tbody .bases-tr') || []);
  if (baseRows.length) {
    const readCells = row => Array.from(row.querySelectorAll(':scope > .bases-td, :scope > [role="cell"], :scope > [role="gridcell"]'))
      .map(cell => text(cell.textContent).replace(/\s+/g, ' '));
    const headers = head ? Array.from(head.querySelectorAll(':scope > .bases-td')).map(cell => {
      const name = cell.querySelector('.bases-table-header-name');
      return text(name?.textContent || cell.textContent).replace(/\s+/g, ' ');
    }) : [];
    const rows = baseRows.map(readCells).filter(row => row.some(Boolean));
    return rows.length ? { headers, rows } : null;
  }

  const ariaRows = Array.from(surface.querySelectorAll?.('[role="row"]') || []);
  if (!ariaRows.length) return null;
  const parsed = ariaRows.map(row => {
    const cells = Array.from(row.querySelectorAll(':scope > [role="columnheader"],:scope > [role="cell"],:scope > [role="gridcell"]'));
    return { header: cells.some(cell => cell.getAttribute('role') === 'columnheader'), values: cells.map(cell => text(cell.textContent).replace(/\s+/g, ' ')) };
  }).filter(row => row.values.some(Boolean));
  const header = parsed.find(row => row.header);
  const rows = parsed.filter(row => row !== header).map(row => row.values);
  return rows.length ? { headers: header?.values || [], rows } : null;
}

function snapshotDataset(content, label) {
  const heading = snapshotHeading(content, label);
  const surface = snapshotSurface(heading, content);
  const table = snapshotTable(surface);
  return heading && surface && table ? { heading, surface, ...table } : null;
}

function snapshotColumn(headers, needles, fallback) {
  const normalized = headers.map(normalizeSnapshotText);
  const index = normalized.findIndex(header => needles.some(needle => header.includes(needle)));
  return index >= 0 ? index : fallback;
}

function snapshotMore(container, count) {
  if (count > 0) container.appendChild(makeElement('span', 'cv-journal-snapshot-more', `+${count} more`));
}

function renderScheduleSnapshot(dataset) {
  const container = journalQuery('[data-role="journal-snapshot-schedule"]');
  container.replaceChildren();
  const timeIndex = snapshotColumn(dataset.headers, ['time'], 0);
  let taskIndex = dataset.headers.findIndex((_, index) => index !== timeIndex);
  if (taskIndex < 0) taskIndex = Math.min(1, Math.max(0, (dataset.rows[0]?.length || 1) - 1));
  let start = 0;
  if (currentEntryKey === todayKey()) {
    const now = new Date();
    const minute = now.getHours() * 60 + now.getMinutes();
    let active = -1;
    dataset.rows.forEach((row, index) => {
      const match = text(row[timeIndex]).match(/(\d{1,2}):(\d{2})/);
      if (match && Number(match[1]) * 60 + Number(match[2]) <= minute) active = index;
    });
    if (active >= 0) start = Math.max(0, active - 1);
  }
  const visible = dataset.rows.slice(start, start + 6);
  visible.forEach(row => {
    const item = makeElement('div', 'cv-journal-snapshot-row cv-journal-snapshot-row--schedule');
    item.append(makeElement('span', 'cv-journal-snapshot-time', row[timeIndex] || '—'), makeElement('span', 'cv-journal-snapshot-primary', row[taskIndex] || '—'));
    container.appendChild(item);
  });
  if (!visible.length) container.appendChild(makeElement('span', 'cv-journal-snapshot-empty', 'No schedule items.'));
  snapshotMore(container, Math.max(0, dataset.rows.length - visible.length));
  setText('journal-snapshot-schedule-count', `${dataset.rows.length} items`);
}

function renderTrainingSnapshot(dataset, kind) {
  const container = journalQuery(`[data-role="journal-snapshot-${kind}"]`);
  container.replaceChildren();
  const nameIndex = snapshotColumn(dataset.headers, ['exercise','activity','movement'], 0);
  const equipmentIndex = snapshotColumn(dataset.headers, ['equipment','gear'], -1);
  let doseIndex = snapshotColumn(dataset.headers, kind === 'cardio' ? ['rest','duration','time','set','rep'] : ['set','rep'], -1);
  if (doseIndex < 0) doseIndex = Math.max(0, (dataset.rows[0]?.length || 1) - 1);
  const limit = kind === 'cardio' ? 4 : 6;
  const visible = dataset.rows.slice(0, limit);
  visible.forEach(row => {
    const item = makeElement('div', 'cv-journal-snapshot-row');
    const copy = makeElement('div', 'cv-journal-snapshot-copy');
    copy.appendChild(makeElement('span', 'cv-journal-snapshot-primary', row[nameIndex] || '—'));
    if (equipmentIndex >= 0 && row[equipmentIndex]) copy.appendChild(makeElement('span', 'cv-journal-snapshot-secondary', row[equipmentIndex]));
    item.append(copy, makeElement('span', 'cv-journal-snapshot-dose', row[doseIndex] || ''));
    container.appendChild(item);
  });
  if (!visible.length) container.appendChild(makeElement('span', 'cv-journal-snapshot-empty', `No ${kind} items.`));
  snapshotMore(container, Math.max(0, dataset.rows.length - visible.length));
  setText(`journal-snapshot-${kind}-count`, `${dataset.rows.length} items`);
}

function suppressSnapshotSource(datasets) {
  const headings = datasets.map(dataset => dataset.heading);
  const multi = headings[0]?.closest?.('.callout[data-callout="multi-column"]');
  if (multi && headings.every(heading => multi.contains(heading))) {
    multi.classList.add('cv-journal-source-daily-snapshot');
    multi.setAttribute('aria-hidden', 'true');
  }
}

function initDailySnapshot() {
  const snapshot = journalQuery('[data-role="journal-daily-snapshot"]');
  const content = journalQuery('[data-role="journal-content"]');
  if (!snapshot || !content) return;
  const settings = settingsFrontmatter();
  const labels = {
    schedule: text(settings?.schedule_heading) || 'Daily Schedule',
    exercise: text(settings?.exercise_heading) || 'Calisthenics',
    cardio: text(settings?.cardio_heading) || 'Cardio',
  };
  const render = () => {
    const schedule = snapshotDataset(content, labels.schedule);
    const exercise = snapshotDataset(content, labels.exercise);
    const cardio = snapshotDataset(content, labels.cardio);
    if (!schedule || !exercise || !cardio) return false;
    renderScheduleSnapshot(schedule);
    renderTrainingSnapshot(exercise, 'exercise');
    renderTrainingSnapshot(cardio, 'cardio');
    suppressSnapshotSource([schedule, exercise, cardio]);
    snapshot.hidden = false;
    return true;
  };
  if (render()) return;
  const Observer = journalWindow?.MutationObserver;
  if (typeof Observer !== 'function') return;
  const observer = new Observer(() => { if (render()) observer.disconnect(); });
  observer.observe(content, { childList: true, subtree: true });
  journalWindow?.setTimeout?.(() => observer.disconnect(), 12000);
}

  let openingJournalEditor = false;

  async function enterJournalEditingMode() {
    if (openingJournalEditor) return;
    const leaves = typeof journalApp?.workspace?.getLeavesOfType === "function"
      ? journalApp.workspace.getLeavesOfType("markdown")
      : [];
    const leaf = leaves.find(candidate =>
      candidate?.view?.file?.path === journalFile?.path
      && candidate.view.contentEl?.contains(journalContainer)
    );

    if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
      console.warn("[custom-view:journal] Could not resolve the markdown leaf for source editing");
      return;
    }

    const viewState = leaf.getViewState();
    if (viewState?.state?.mode === "source" && viewState?.state?.source === true) {
      leaf.view?.editor?.focus?.();
      return;
    }

    openingJournalEditor = true;
    journalRoot.classList.add("is-opening-editor");
    try {
      await leaf.setViewState({
        ...viewState,
        active: true,
        state: {
          ...(viewState.state || {}),
          mode: "source",
          source: true,
        },
      });
      const focusEditor = () => leaf.view?.editor?.focus?.();
      journalWindow?.setTimeout?.(focusEditor, 0);
      journalWindow?.setTimeout?.(focusEditor, 100);
    } catch (error) {
      openingJournalEditor = false;
      journalRoot.classList.remove("is-opening-editor");
      console.error("[custom-view:journal] Could not switch note to Source Mode", error);
    }
  }

  function bindJournalClickToEdit() {
    const content = journalQuery('[data-role="journal-content"]');
    if (!content) return;
    content.setAttribute("tabindex", "0");

    content.addEventListener("click", event => {
      if (event.target?.closest?.('a, button, input, textarea, select, label, iframe, [contenteditable="true"], .internal-embed, .markdown-embed')) return;
      void enterJournalEditingMode();
    });
    content.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void enterJournalEditingMode();
    });
  }

  function detectNativeEditor() {
    const content = journalQuery('[data-role="journal-content"]');
    if (content?.querySelector("[data-cv-editable-placeholder]")) {
      journalRoot.classList.add("is-native-editor");
    }
  }

  const entries = journalEntries();
  renderDateIdentity();
  renderQuote();
  renderTags();
  initChoice("mood", MOOD_CHOICES);
  initChoice("energy", ENERGY_CHOICES);
  initReflection();
  initWeight();
  initNavigation(entries);
  renderOnThisDay(entries);
  detectNativeEditor();
  bindJournalClickToEdit();
  installSourceQuoteSuppression();
  initDailySnapshot();
  void renderWeather();
}

views.css:
.obsidian-custom-view-render:has(> .cv-game) {
  padding: 0 !important;
  background: var(--border-theme-pane, var(--background-primary)) !important;
}

.cv-game {
  --cvg-bg: var(--border-theme-pane, var(--background-primary));
  --cvg-surface: color-mix(in srgb, var(--background-secondary) 90%, #07373d 10%);
  --cvg-surface-deep: color-mix(in srgb, var(--background-primary) 92%, #031f24 8%);
  --cvg-surface-soft: color-mix(in srgb, var(--background-secondary-alt) 90%, #0a4046 10%);
  --cvg-hover: var(--background-modifier-hover);
  --cvg-accent: var(--highlight, var(--interactive-accent));
  --cvg-teal: var(--teal, var(--interactive-accent));
  --cvg-accent-soft: color-mix(in srgb, var(--cvg-accent) 72%, var(--text-normal) 28%);
  --cvg-silver: color-mix(in srgb, var(--text-muted) 72%, var(--text-normal) 28%);
  --cvg-text: var(--text-normal);
  --cvg-muted: var(--text-muted);
  --cvg-faint: var(--text-faint);
  --cvg-border: color-mix(in srgb, var(--cvg-teal) 28%, var(--background-modifier-border) 72%);
  --cvg-border-strong: color-mix(in srgb, var(--cvg-teal) 52%, var(--background-modifier-border-hover) 48%);
  --cvg-shadow: color-mix(in srgb, var(--shadow) 34%, transparent);
  --cvg-glow: color-mix(in srgb, var(--cvg-accent) 20%, transparent);

  /* Same canonical ruled-paper contract used by Recipes + Movies/TV. */
  --cvg-paper-line: var(--vault-note-paper-line, 30px);
  --cvg-paper: var(--vault-note-paper, color-mix(in srgb, var(--background-primary) 60%, var(--background-secondary) 40%));
  --cvg-paper-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--cvg-accent) 15%, transparent));
  --cvg-paper-margin: var(--vault-note-paper-margin-rule, color-mix(in srgb, var(--cvg-accent) 22%, transparent));
  --cvg-paper-edge: var(--vault-note-paper-edge, color-mix(in srgb, var(--cvg-border-strong) 72%, transparent));

  width: 100%;
  min-width: 0;
  min-height: 100%;
  color: var(--cvg-text);
  background: var(--cvg-bg);
  container-type: inline-size;
  font-family: var(--font-interface);
}

.cv-game *,
.cv-game *::before,
.cv-game *::after { box-sizing: border-box; }

.cv-game button,
.cv-game a,
.cv-game input { font: inherit; }

.cv-game :is(button, a, input, [tabindex]):focus-visible {
  outline: 2px solid var(--cvg-accent);
  outline-offset: 3px;
}

/* ========================================================================== */
/* HERO                                                                       */
/* ========================================================================== */
.cv-game-hero {
  position: relative;
  min-height: clamp(360px, 43cqi, 570px);
  overflow: hidden;
  border-bottom: 1px solid var(--cvg-border-strong);
  background: var(--cvg-surface-deep);
  isolation: isolate;
}

.cv-game-backdrop,
.cv-game-hero-shade {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.cv-game-backdrop {
  z-index: -4;
  object-fit: cover;
  opacity: .5;
  filter: saturate(.82) contrast(1.06) brightness(.68);
  transform: scale(1.012);
}

.cv-game-backdrop:not([src]) { display: none; }

.cv-game-hero-shade {
  z-index: -3;
  pointer-events: none;
  background:
    radial-gradient(circle at 78% 16%, color-mix(in srgb, var(--cvg-teal) 14%, transparent), transparent 38%),
    linear-gradient(90deg,
      color-mix(in srgb, var(--cvg-bg) 98%, transparent) 0%,
      color-mix(in srgb, var(--cvg-bg) 87%, transparent) 34%,
      color-mix(in srgb, var(--cvg-bg) 45%, transparent) 70%,
      color-mix(in srgb, var(--cvg-bg) 72%, transparent) 100%),
    linear-gradient(0deg, var(--cvg-bg), transparent 62%);
}

.cv-game-hero-inner {
  width: min(100%, 1380px);
  min-height: inherit;
  margin: 0 auto;
  padding: clamp(30px, 5cqi, 72px);
  display: grid;
  grid-template-columns: clamp(170px, 22cqi, 270px) minmax(0, 1fr);
  align-items: end;
  gap: clamp(28px, 4cqi, 58px);
}

.cv-game-cover-shell {
  position: relative;
  margin: 0;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border: 1px solid var(--cvg-border-strong);
  border-radius: 5px;
  background: var(--cvg-surface);
  box-shadow: 0 24px 56px var(--cvg-shadow), 0 0 32px var(--cvg-glow);
}

.cv-game-cover-shell::after {
  content: "";
  position: absolute;
  inset: 7px;
  pointer-events: none;
  border: 1px solid color-mix(in srgb, var(--cvg-silver) 18%, transparent);
}

.cv-game-cover,
.cv-game-cover-fallback { width: 100%; height: 100%; }

.cv-game-cover {
  display: block;
  object-fit: cover;
  filter: saturate(.92) contrast(1.02);
}

.cv-game-cover:not([src]) { display: none; }

.cv-game-cover-fallback {
  display: grid;
  place-items: center;
  color: var(--cvg-accent-soft);
  font-family: var(--font-monospace);
  font-size: 1rem;
  font-weight: 850;
  letter-spacing: .18em;
  background:
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--cvg-teal) 14%, transparent), transparent 46%),
    var(--cvg-surface-deep);
}

.cv-game-cover-fallback[hidden] { display: none; }

.cv-game-eyebrow,
.cv-game-kicker,
.cv-game-control-label,
.cv-game-meta dt,
.cv-game-metrics span {
  color: var(--cvg-silver);
  font-family: var(--font-monospace);
  font-size: .65rem;
  font-weight: 760;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.cv-game-identity { min-width: 0; padding-bottom: 3px; }

.cv-game-identity h1 {
  max-width: 17ch;
  margin: 10px 0 0;
  color: var(--cvg-text);
  font-size: clamp(2.45rem, 5.8cqi, 5.7rem);
  line-height: .98;
  font-weight: 780;
  letter-spacing: -.052em;
  text-wrap: balance;
}

.cv-game-byline {
  margin: 14px 0 0;
  color: var(--cvg-muted);
  font-size: clamp(.82rem, 1.35cqi, 1rem);
}

.cv-game-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 18px;
}

.cv-game-chip {
  padding: 5px 8px;
  border: 1px solid var(--cvg-border);
  border-radius: 3px;
  background: color-mix(in srgb, var(--cvg-surface-deep) 76%, transparent);
  color: var(--cvg-silver);
  font-family: var(--font-monospace);
  font-size: .67rem;
}

.cv-game-metrics {
  max-width: 720px;
  margin-top: 27px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-block: 1px solid var(--cvg-border);
}

.cv-game-metrics > div {
  min-width: 0;
  padding: 11px 14px 10px 0;
}

.cv-game-metrics > div + div {
  padding-left: 14px;
  border-left: 1px solid var(--cvg-border);
}

.cv-game-metrics span,
.cv-game-metrics strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cv-game-metrics strong {
  margin-top: 4px;
  color: var(--cvg-text);
  font-family: var(--font-monospace);
  font-size: .78rem;
  font-weight: 760;
}

.cv-game-inline-edit {
  min-width: 0;
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  margin: 0;
  padding: 0 0 2px;
  border: 0;
  border-bottom: 1px solid transparent;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  cursor: text;
}

.cv-game-inline-edit:hover,
.cv-game-inline-edit:focus-visible {
  border-bottom-color: color-mix(in srgb, var(--cvg-accent) 56%, transparent);
  background: transparent;
}

.cv-game-inline-edit small {
  color: var(--cvg-faint);
  font-family: var(--font-monospace);
  font-size: .52rem;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .14s ease;
}

.cv-game-inline-edit:hover small,
.cv-game-inline-edit:focus-visible small { opacity: 1; }

.cv-game-inline-number {
  width: min(100%, 92px);
  min-height: 26px;
  margin-top: 3px;
  padding: 2px 5px;
  border: 1px solid var(--cvg-border-strong);
  border-radius: 3px;
  background: var(--cvg-surface-deep);
  color: var(--cvg-text);
  font-family: var(--font-monospace);
  font-size: .75rem;
}

.cv-game-progress-copy {
  max-width: 720px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20px;
  color: var(--cvg-muted);
  font-family: var(--font-monospace);
  font-size: .68rem;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.cv-game-progress-copy strong { color: var(--cvg-silver); margin: 0; }

.cv-game-progress {
  max-width: 720px;
  height: 4px;
  margin-top: 7px;
  overflow: hidden;
  background: color-mix(in srgb, var(--cvg-muted) 15%, transparent);
}

.cv-game-progress > span {
  width: 0;
  height: 100%;
  display: block;
  background: linear-gradient(90deg, var(--cvg-teal), var(--cvg-accent));
  box-shadow: 0 0 12px var(--cvg-glow);
  transition: width 180ms ease;
}

/* ========================================================================== */
/* PAPER LOG — canonical Personal Log paper + circular punches                */
/* ========================================================================== */
.cv-game-layout {
  width: min(100%, 1380px);
  margin: 0 auto;
  padding: clamp(28px, 5cqi, 68px);
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(300px, .72fr);
  align-items: start;
  gap: clamp(34px, 5cqi, 72px);
}

.cv-game-journal,
.cv-game-log,
.cv-game-dossier { min-width: 0; }

.cv-game-section-head--outer {
  min-height: 0;
  align-items: end;
  padding: 0 0 clamp(14px, 2cqi, 24px);
  border-bottom: 0;
}

.cv-game-log {
  position: relative;
  min-height: calc(var(--cvg-paper-line) * 18);
  overflow: hidden;
  isolation: isolate;
  border: 1px solid var(--cvg-paper-edge);
  border-radius: 8px;
  background: var(--vault-note-paper-background,
    linear-gradient(90deg, transparent 0 44px, var(--cvg-paper-margin) 44px 45px, transparent 45px),
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--cvg-paper-line) - 7px),
      color-mix(in srgb, var(--cvg-paper-rule) 55%, transparent) calc(var(--cvg-paper-line) - 7px) calc(var(--cvg-paper-line) - 5px),
      transparent calc(var(--cvg-paper-line) - 5px) var(--cvg-paper-line)
    ),
    var(--cvg-paper));
  box-shadow: 0 8px 24px color-mix(in srgb, var(--cvg-shadow) 64%, transparent), 0 3px 10px color-mix(in srgb, var(--cvg-shadow) 44%, transparent);
}

/* Circular punches retain the Recipes / Movies / TV note-family language. */
.cv-game-paper-circles {
  position: absolute;
  z-index: 4;
  top: calc(var(--cvg-paper-line) * 2.4);
  bottom: calc(var(--cvg-paper-line) * 1.2);
  left: 12px;
  width: 22px;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 11px,
      color-mix(in srgb, var(--cvg-bg) 96%, transparent) 0 5px,
      color-mix(in srgb, var(--cvg-paper-edge) 78%, transparent) 5.5px 6.5px,
      transparent 7px)
    center top / 22px calc(var(--cvg-paper-line) * 3) repeat-y;
  opacity: .9;
}

.cv-game-section-head,
.cv-game-note-render {
  position: relative;
  z-index: 6;
}

.cv-game-section-head {
  min-height: calc(var(--cvg-paper-line) * 2);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 0 clamp(18px, 3cqi, 32px) 0 clamp(54px, 5cqi, 66px);
  border-bottom: 2px solid color-mix(in srgb, var(--cvg-accent) 34%, var(--cvg-border-strong) 66%);
  background: transparent;
}

.cv-game-section-head--outer {
  min-height: 0;
  align-items: end;
  padding: 0 0 clamp(14px, 2cqi, 24px);
  border-bottom: 0;
}

.cv-game-section-head h2 {
  margin: 4px 0 0;
  color: var(--cvg-text);
  font-size: 1.18rem;
  font-weight: 720;
}

.cv-game-note-state,
.cv-game-save-state {
  color: var(--cvg-faint);
  font-family: var(--font-monospace);
  font-size: .61rem;
}

.cv-game-note-render {
  min-height: calc(var(--cvg-paper-line) * 15);
  padding: 0 clamp(22px, 4cqi, 48px) var(--cvg-paper-line) clamp(54px, 5cqi, 66px);
  color: var(--cvg-text);
  cursor: text;
  line-height: var(--cvg-paper-line);
}

.cv-game-note-render.is-empty::before {
  content: "Record sessions, builds, quests, discoveries, and your final verdict…";
  display: block;
  min-height: var(--cvg-paper-line);
  color: var(--cvg-faint);
  font-style: italic;
  line-height: var(--cvg-paper-line);
}

.cv-game-note-render > :is(h1, h2, h3, h4, h5, h6, p, ul, ol),
.cv-game-note-render :is(.markdown-rendered-content, .markdown-preview-sizer) > :is(h1, h2, h3, h4, h5, h6, p, ul, ol),
.cv-game-note-render .cm-line {
  min-height: var(--cvg-paper-line);
  margin-block: 0 !important;
  line-height: var(--cvg-paper-line) !important;
}

.cv-game-note-render :is(h1, h2, h3, h4) {
  color: var(--cvg-text);
  letter-spacing: -.025em;
}

.cv-game-note-render h2 {
  padding: 0 !important;
  border-bottom: 0;
  font-size: 1.15rem;
}

.cv-game-note-render :is(a, .internal-link) {
  color: var(--cvg-accent-soft);
  text-decoration-color: color-mix(in srgb, var(--cvg-accent) 36%, transparent);
}

.cv-game-note-render blockquote {
  margin-block: 0;
  padding-left: 16px;
  border-left: 2px solid var(--cvg-teal);
  color: var(--cvg-muted);
}

.cv-game-note-render :is(
  [data-cv-editable-placeholder],
  .markdown-rendered-content,
  .markdown-preview-sizer,
  .markdown-preview-section,
  .markdown-source-view,
  .cm-editor,
  .cm-scroller,
  .cm-content,
  .cm-line
) {
  max-width: none !important;
  background: transparent !important;
  box-shadow: none !important;
}

.cv-game-note-render :is(.markdown-source-view, .cm-editor, .cm-scroller, .cm-content),
.cv-game-note-render [data-cv-editable-placeholder] {
  width: 100% !important;
  min-height: calc(var(--cvg-paper-line) * 13) !important;
}

/* ========================================================================== */
/* DOSSIER CONTROLS                                                           */
/* ========================================================================== */
.cv-game-dossier {
  position: sticky;
  top: 18px;
  border-left: 1px solid var(--cvg-border-strong);
  background: transparent;
}

.cv-game-dossier-section {
  padding: 19px 0 21px clamp(20px, 3cqi, 30px);
  border-bottom: 1px solid var(--cvg-border);
}

.cv-game-summary {
  margin: 11px 0 0;
  color: var(--cvg-muted);
  font-size: .78rem;
  line-height: 1.65;
  text-wrap: pretty;
}

.cv-game-status {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}

.cv-game-status button {
  min-height: 32px;
  border: 1px solid var(--cvg-border);
  border-radius: 3px;
  background: transparent;
  color: var(--cvg-muted);
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease, color .15s ease;
}

.cv-game-status button:hover,
.cv-game-links a:hover {
  border-color: var(--cvg-border-strong);
  background: color-mix(in srgb, var(--cvg-teal) 8%, transparent);
  color: var(--cvg-text);
}

.cv-game-status button.is-active {
  border-color: color-mix(in srgb, var(--cvg-accent) 60%, var(--cvg-border) 40%);
  background: color-mix(in srgb, var(--cvg-accent) 12%, transparent);
  color: var(--cvg-accent-soft);
}

/* Movies/TV-style 5-star presentation with ten invisible half-step hit zones. */
.cv-game-rating {
  --cvg-rating-fill: 0%;
  --cvg-rating-label: "0/10";
  width: min(100%, 242px);
  min-width: 0;
  min-height: 30px;
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr)) minmax(3.7em, max-content);
  grid-template-rows: 30px;
  align-items: center;
  margin-top: 11px;
}

.cv-game-rating::before {
  content: "";
  z-index: 1;
  grid-column: 1 / 11;
  grid-row: 1;
  width: 100%;
  height: 100%;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    var(--cvg-accent) 0 var(--cvg-rating-fill),
    var(--cvg-border-strong) var(--cvg-rating-fill) 100%
  );
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 22 12 18.56 5.82 22 7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") left center / 20% 100% repeat-x;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 2l3.09 6.26L22 9.27l-5 4.87L18.18 22 12 18.56 5.82 22 7 14.14 2 9.27l6.91-1.01L12 2z'/></svg>") left center / 20% 100% repeat-x;
}

.cv-game-rating::after {
  content: var(--cvg-rating-label);
  z-index: 2;
  grid-column: 11;
  grid-row: 1;
  min-width: 3.7em;
  margin-left: 12px;
  color: var(--cvg-accent-soft);
  font-family: var(--font-monospace);
  font-size: .82rem;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.cv-game-rating button {
  z-index: 3;
  grid-row: 1;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  appearance: none !important;
  -webkit-appearance: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: transparent !important;
  cursor: pointer;
  overflow: hidden;
}

.cv-game-rating button:nth-child(1) { grid-column: 1; }
.cv-game-rating button:nth-child(2) { grid-column: 2; }
.cv-game-rating button:nth-child(3) { grid-column: 3; }
.cv-game-rating button:nth-child(4) { grid-column: 4; }
.cv-game-rating button:nth-child(5) { grid-column: 5; }
.cv-game-rating button:nth-child(6) { grid-column: 6; }
.cv-game-rating button:nth-child(7) { grid-column: 7; }
.cv-game-rating button:nth-child(8) { grid-column: 8; }
.cv-game-rating button:nth-child(9) { grid-column: 9; }
.cv-game-rating button:nth-child(10) { grid-column: 10; }

.cv-game-rating button:hover,
.cv-game-rating button:active,
.cv-game-rating button:focus,
.cv-game-rating button:disabled,
.cv-game-rating button.is-active {
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: transparent !important;
}

.cv-game-rating button:focus-visible {
  outline: 1px solid var(--cvg-accent) !important;
  outline-offset: 1px !important;
}

.cv-game-rating:has(button[data-rating="1"].is-active) { --cvg-rating-fill: 10%; --cvg-rating-label: "1/10"; }
.cv-game-rating:has(button[data-rating="2"].is-active) { --cvg-rating-fill: 20%; --cvg-rating-label: "2/10"; }
.cv-game-rating:has(button[data-rating="3"].is-active) { --cvg-rating-fill: 30%; --cvg-rating-label: "3/10"; }
.cv-game-rating:has(button[data-rating="4"].is-active) { --cvg-rating-fill: 40%; --cvg-rating-label: "4/10"; }
.cv-game-rating:has(button[data-rating="5"].is-active) { --cvg-rating-fill: 50%; --cvg-rating-label: "5/10"; }
.cv-game-rating:has(button[data-rating="6"].is-active) { --cvg-rating-fill: 60%; --cvg-rating-label: "6/10"; }
.cv-game-rating:has(button[data-rating="7"].is-active) { --cvg-rating-fill: 70%; --cvg-rating-label: "7/10"; }
.cv-game-rating:has(button[data-rating="8"].is-active) { --cvg-rating-fill: 80%; --cvg-rating-label: "8/10"; }
.cv-game-rating:has(button[data-rating="9"].is-active) { --cvg-rating-fill: 90%; --cvg-rating-label: "9/10"; }
.cv-game-rating:has(button[data-rating="10"].is-active) { --cvg-rating-fill: 100%; --cvg-rating-label: "10/10"; }

.cv-game-meta { margin: 12px 0 0; }

.cv-game-meta-row {
  min-height: 37px;
  display: grid;
  grid-template-columns: minmax(82px, .78fr) minmax(0, 1.22fr);
  align-items: center;
  gap: 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--cvg-border) 72%, transparent);
}

.cv-game-meta-row:last-child { border-bottom: 0; }
.cv-game-meta :is(dt, dd) { min-width: 0; margin: 0; }

.cv-game-meta dd {
  overflow-wrap: anywhere;
  color: var(--cvg-muted);
  font-size: .72rem;
  line-height: 1.35;
}

.cv-game-links {
  display: grid;
  gap: 6px;
  margin-top: 12px;
}

.cv-game-links a {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--cvg-border);
  border-radius: 3px;
  color: var(--cvg-silver);
  font-family: var(--font-monospace);
  font-size: .67rem;
  text-decoration: none;
  transition: border-color .15s ease, background .15s ease, color .15s ease;
}

.cv-game-links a::after { content: "↗"; color: var(--cvg-accent); }

.cv-game-links-section[hidden],
.cv-game-summary-section[hidden] { display: none; }

.cv-game-save-state {
  display: block;
  min-height: 38px;
  padding: 12px 0 12px clamp(20px, 3cqi, 30px);
}

@container (max-width: 860px) {
  .cv-game-layout { grid-template-columns: 1fr; }
  .cv-game-dossier {
    position: static;
    border-left: 0;
    border-top: 1px solid var(--cvg-border-strong);
  }
  .cv-game-dossier-section,
  .cv-game-save-state { padding-inline: 0; }
}

@container (max-width: 620px) {
  .cv-game-hero { min-height: 430px; }
  .cv-game-hero-inner {
    grid-template-columns: 116px minmax(0, 1fr);
    align-items: end;
    padding: 24px 18px 28px;
    gap: 18px;
  }
  .cv-game-identity h1 { font-size: clamp(2rem, 9cqi, 3rem); }
  .cv-game-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cv-game-metrics > div:nth-child(3) {
    padding-left: 0;
    border-left: 0;
    border-top: 1px solid var(--cvg-border);
  }
  .cv-game-metrics > div:nth-child(4) { border-top: 1px solid var(--cvg-border); }
  .cv-game-layout { padding: 26px 16px 40px; }
  .cv-game-note-render { padding-right: 18px; }
  .cv-game-rating { width: min(100%, 226px); }
}

@container (max-width: 430px) {
  .cv-game-hero-inner { grid-template-columns: 92px minmax(0, 1fr); }
  .cv-game-chips { display: none; }
  .cv-game-metrics { margin-top: 18px; }
  .cv-game-status { grid-template-columns: 1fr 1fr; }
  .cv-game-paper-circles { opacity: .65; }
}

@media (prefers-reduced-motion: reduce) {
  .cv-game *,
  .cv-game *::before,
  .cv-game *::after { transition-duration: .01ms !important; }
}

