const gameContext = tp;
const gameContainer = gameContext.container || this;
const gameRoot = gameContainer.querySelector('[data-role="game-root"]');

if (gameRoot) {
  const gameApp = gameContext.app;
  const gameFile = gameContext.file;
  const gameFrontmatter = gameContext.frontmatter || {};
  const gameBodyContent = String(gameContext.bodyContent || "");
  const gameDocument = gameContext.activeDocument || gameRoot.ownerDocument;
  const q = selector => gameRoot.querySelector(selector);
  const qa = selector => Array.from(gameRoot.querySelectorAll(selector));
  const text = value => String(value ?? "").trim();
  const asArray = value => Array.isArray(value)
    ? value
    : (value === null || value === undefined || value === "" ? [] : [value]);
  const valueOf = (...keys) => {
    for (const key of keys) {
      if (gameFrontmatter[key] !== undefined && gameFrontmatter[key] !== null) return gameFrontmatter[key];
    }
    return "";
  };

  const PLATFORM_FONT = '"JetBrainsMono Nerd Font", "JetBrainsMonoNL Nerd Font Mono", var(--font-monospace)';

  function cleanWiki(value) {
    return text(value).replace(/^!?(?:\[\[)(.*?)(?:\|.*?)?\]\]$/, "$1");
  }

  function safeUrl(value) {
    const raw = text(value);
    if (!raw) return "";
    try {
      const parsed = new URL(raw);
      return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.href : "";
    } catch {
      return "";
    }
  }

  function resolveImage(value) {
    const raw = text(asArray(value).find(item => text(item)) || "");
    if (!raw) return "";
    if (/^https?:\/\//i.test(raw)) return raw;
    if (!/^!?\[\[/.test(raw)) {
      const linked = gameApp.metadataCache?.getFirstLinkpathDest?.(raw, gameFile?.path || "");
      return linked ? gameApp.vault.getResourcePath(linked) : raw;
    }
    const linked = gameApp.metadataCache?.getFirstLinkpathDest?.(cleanWiki(raw), gameFile?.path || "");
    return linked ? gameApp.vault.getResourcePath(linked) : "";
  }

  function setImage(image, source, fallback) {
    if (!image) return;
    if (!source) {
      image.removeAttribute("src");
      if (fallback) fallback.hidden = false;
      return;
    }
    image.src = source;
    if (fallback) fallback.hidden = true;
    image.addEventListener("error", () => {
      image.removeAttribute("src");
      if (fallback) fallback.hidden = false;
    }, { once: true });
  }

  function setState(message = "") {
    const state = q('[data-role="game-save-state"]');
    if (state) state.textContent = message;
  }

  async function updateFrontmatter(property, value) {
    if (!gameApp?.fileManager || !gameFile) throw new Error("Game file is unavailable");
    await gameApp.fileManager.processFrontMatter(gameFile, draft => {
      draft[property] = value;
    });
    gameFrontmatter[property] = value;
  }

  function platformGlyph(value) {
    const normalized = cleanWiki(value).toLowerCase();
    if (normalized.includes("windows")) return "\uf17a";
    if (normalized.includes("macos") || normalized.includes("mac os") || normalized.includes("apple") || normalized === "mac") return "\uf179";
    if (normalized.includes("linux")) return "\uf17c";
    if (normalized.includes("steam deck") || normalized === "steam") return "\uf1b6";
    if (normalized.includes("playstation") || /^ps\d/.test(normalized)) return "\uf3df";
    if (normalized.includes("xbox")) return "\uf412";
    if (normalized.includes("switch") || normalized.includes("nintendo")) return "\uf418";
    return "\uf11b";
  }

  function makePlatformIcon(value, { chip = false } = {}) {
    const label = cleanWiki(value) || "Unknown platform";
    const icon = gameDocument.createElement("span");
    icon.textContent = platformGlyph(label);
    icon.title = label;
    icon.setAttribute("aria-label", label);
    icon.dataset.platform = label;
    if (chip) icon.className = "cv-game-chip";
    icon.style.fontFamily = PLATFORM_FONT;
    icon.style.fontSize = chip ? "1rem" : ".96rem";
    icon.style.lineHeight = "1";
    icon.style.display = "inline-grid";
    icon.style.placeItems = "center";
    icon.style.minWidth = chip ? "34px" : "20px";
    if (chip) {
      icon.style.padding = "6px 9px";
      icon.style.textAlign = "center";
    }
    return icon;
  }

  function platformValues() {
    return asArray(valueOf("Platform", "platform", "platforms")).map(cleanWiki).filter(Boolean);
  }

  function renderIdentity() {
    const title = text(valueOf("Title", "title")) || gameFile?.basename || "Untitled game";
    const developer = text(valueOf("Developer", "developer"));
    const publisher = text(valueOf("Publisher", "publisher"));
    const byline = [developer || "Developer not set", publisher && publisher !== developer ? publisher : ""]
      .filter(Boolean)
      .join(" · ");

    const titleElement = q('[data-role="game-title"]');
    if (titleElement) {
      titleElement.textContent = title;
      titleElement.removeAttribute("title");
    }
    const bylineElement = q('[data-role="game-byline"]');
    if (bylineElement) bylineElement.textContent = byline;

    const cover = q('[data-role="game-cover"]');
    const fallback = q('[data-role="game-cover-fallback"]');
    if (cover) cover.alt = title ? `${title} cover` : "Game cover";
    setImage(cover, resolveImage(valueOf("Cover", "cover")), fallback);
    setImage(q('[data-role="game-backdrop"]'), resolveImage(valueOf("Backdrop", "backdrop")));

    const platforms = q('[data-role="game-platforms"]');
    if (platforms) {
      platforms.replaceChildren();
      const values = platformValues();
      if (values.length) {
        platforms.setAttribute("aria-label", values.join(", "));
        values.forEach(value => platforms.appendChild(makePlatformIcon(value, { chip: true })));
      } else {
        const unset = gameDocument.createElement("span");
        unset.className = "cv-game-chip";
        unset.textContent = "—";
        unset.title = "Platform unset";
        platforms.appendChild(unset);
      }
    }

    const completion = Math.max(0, Math.min(100, Number(valueOf("Completion", "completion")) || 0));
    const completionValue = q('[data-role="game-completion-value"]');
    if (completionValue) completionValue.textContent = `${completion}%`;
    const progressFill = q('[data-role="game-progress-fill"]');
    if (progressFill) progressFill.style.width = `${completion}%`;
    const progress = q('[data-role="game-progress"]');
    if (progress) progress.setAttribute("aria-valuenow", String(completion));

    const status = text(valueOf("Status", "status")) || "Backlog";
    const rating = Math.max(0, Math.min(10, Number(valueOf("Rating", "rating")) || 0));
    const playtime = Math.max(0, Number(valueOf("PlaytimeHours", "playtime_hours", "playtime")) || 0);
    const released = text(valueOf("ReleaseDate", "release_date", "released"));
    const statusMetric = q('[data-role="game-status-metric"]');
    const ratingMetric = q('[data-role="game-rating-metric"]');
    const playtimeMetric = q('[data-role="game-playtime-metric"]');
    const releaseMetric = q('[data-role="game-release-metric"]');
    if (statusMetric) statusMetric.textContent = status;
    if (ratingMetric) ratingMetric.textContent = rating ? `${rating}/10` : "—";
    if (playtimeMetric) playtimeMetric.textContent = `${playtime}h`;
    if (releaseMetric) releaseMetric.textContent = released ? released.slice(0, 10) : "—";
  }

  function renderSummary() {
    const section = q('[data-role="game-summary-section"]');
    const summary = q('[data-role="game-summary"]');
    if (!section || !summary) return;
    const description = text(valueOf("Description", "description"));
    section.hidden = !description;
    if (description) summary.textContent = description;
  }

  function createMetaRow(label) {
    const list = q('[data-role="game-metadata"]');
    if (!list) return null;
    const row = gameDocument.createElement("div");
    row.className = "cv-game-meta-row";
    const term = gameDocument.createElement("dt");
    const detail = gameDocument.createElement("dd");
    term.textContent = label;
    row.append(term, detail);
    list.appendChild(row);
    return detail;
  }

  function addMeta(label, value) {
    const content = text(value);
    if (!content) return;
    const detail = createMetaRow(label);
    if (detail) detail.textContent = content;
  }

  function addPlatformMeta(values) {
    if (!values.length) return;
    const detail = createMetaRow("Platforms");
    if (!detail) return;
    detail.style.display = "flex";
    detail.style.alignItems = "center";
    detail.style.flexWrap = "wrap";
    detail.style.gap = "10px";
    detail.setAttribute("aria-label", values.join(", "));
    values.forEach(value => detail.appendChild(makePlatformIcon(value)));
  }

  function renderMetadata() {
    const list = q('[data-role="game-metadata"]');
    if (!list) return;
    list.replaceChildren();
    addPlatformMeta(platformValues());
    addMeta("Developer", valueOf("Developer", "developer"));
    addMeta("Publisher", valueOf("Publisher", "publisher"));
    addMeta("Genres", asArray(valueOf("Genre", "genre", "genres")).map(cleanWiki).filter(Boolean).join(", "));
    addMeta("Released", valueOf("ReleaseDate", "release_date", "released"));
    const metacritic = Number(valueOf("Metacritic", "metacritic")) || 0;
    if (metacritic) addMeta("Metacritic", `${metacritic}/100`);
    const store = text(valueOf("Store", "store"));
    if (store) addMeta("Store", store);
    const source = text(valueOf("Source", "source"));
    if (source && source !== store) addMeta("Source", source);
  }

  function renderLinks() {
    const section = q('[data-role="game-links-section"]');
    const host = q('[data-role="game-links"]');
    if (!section || !host) return;
    host.replaceChildren();
    const candidates = [
      [text(valueOf("Store", "store")) || "Store", safeUrl(valueOf("StoreUrl", "store_url"))],
      ["Official website", safeUrl(valueOf("Website", "website"))],
      [text(valueOf("Source", "source")) || "Metadata source", safeUrl(valueOf("SourceUrl", "source_url"))],
    ];
    const seen = new Set();
    for (const [label, url] of candidates) {
      if (!url || seen.has(url)) continue;
      seen.add(url);
      const link = gameDocument.createElement("a");
      link.href = url;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      link.textContent = label;
      link.dataset.interactive = "true";
      host.appendChild(link);
    }
    section.hidden = host.childElementCount === 0;
  }

  function initStatus() {
    const buttons = qa('[data-role="game-status"] [data-status]');
    let committed = text(valueOf("Status", "status")) || "Backlog";
    const metric = q('[data-role="game-status-metric"]');
    const paint = value => buttons.forEach(button => {
      const active = button.dataset.status === value;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
      button.dataset.interactive = "true";
    });
    paint(committed);

    buttons.forEach(button => button.addEventListener("click", async () => {
      const next = button.dataset.status || "Backlog";
      if (next === committed || buttons.some(item => item.disabled)) return;
      const previous = committed;
      committed = next;
      paint(next);
      if (metric) metric.textContent = next;
      buttons.forEach(item => { item.disabled = true; });
      setState("Saving status…");
      try {
        await updateFrontmatter("Status", next);
        setState("Status saved");
      } catch (error) {
        committed = previous;
        paint(previous);
        if (metric) metric.textContent = previous;
        setState("Status was not saved");
        console.error("[custom-view:game] Could not save status", error);
      } finally {
        buttons.forEach(item => { item.disabled = false; });
      }
    }));
  }

  function initRating() {
    const host = q('[data-role="game-rating"]');
    const metric = q('[data-role="game-rating-metric"]');
    if (!host) return;
    host.replaceChildren();
    let committed = Math.max(0, Math.min(10, Number(valueOf("Rating", "rating")) || 0));
    const paint = value => qa(".cv-game-rating button").forEach(button => {
      const numeric = Number(button.dataset.rating);
      button.classList.toggle("is-active", numeric <= value);
      button.setAttribute("aria-pressed", String(numeric === value));
    });

    for (let rating = 1; rating <= 10; rating += 1) {
      const button = gameDocument.createElement("button");
      button.type = "button";
      button.dataset.rating = String(rating);
      button.dataset.interactive = "true";
      button.textContent = String(rating);
      button.setAttribute("aria-label", `Rate ${rating} out of 10`);
      button.addEventListener("mouseenter", () => paint(rating));
      button.addEventListener("focus", () => paint(rating));
      button.addEventListener("blur", () => paint(committed));
      button.addEventListener("click", async () => {
        const previous = committed;
        committed = rating;
        paint(rating);
        if (metric) metric.textContent = `${rating}/10`;
        setState("Saving rating…");
        try {
          await updateFrontmatter("Rating", rating);
          setState("Rating saved");
        } catch (error) {
          committed = previous;
          paint(previous);
          if (metric) metric.textContent = previous ? `${previous}/10` : "—";
          setState("Rating was not saved");
          console.error("[custom-view:game] Could not save rating", error);
        }
      });
      host.appendChild(button);
    }
    host.addEventListener("mouseleave", () => paint(committed));
    paint(committed);
  }

  function initInlineNumberEditor({ hostRole, buttonRole, property, current, min, max, step, onCommit }) {
    const host = q(`[data-role="${hostRole}"]`);
    const button = q(`[data-role="${buttonRole}"]`);
    if (!host || !button) return;
    button.dataset.interactive = "true";
    let editing = false;

    const open = () => {
      if (editing) return;
      editing = true;
      button.hidden = true;
      const input = gameDocument.createElement("input");
      input.type = "number";
      input.className = "cv-game-inline-number";
      input.dataset.interactive = "true";
      input.min = String(min);
      input.max = String(max);
      input.step = String(step);
      input.value = String(current());
      input.setAttribute("aria-label", `Edit ${property}`);
      host.appendChild(input);
      input.focus();
      input.select();

      let finished = false;
      const finish = async save => {
        if (finished) return;
        finished = true;
        let next = Number(input.value);
        if (!Number.isFinite(next)) next = current();
        next = Math.max(min, Math.min(max, next));
        input.remove();
        button.hidden = false;
        editing = false;
        if (!save) return;
        setState(`Saving ${property.toLowerCase()}…`);
        try {
          await updateFrontmatter(property, next);
          onCommit(next);
          setState(`${property} saved`);
        } catch (error) {
          setState(`${property} was not saved`);
          console.error(`[custom-view:game] Could not save ${property}`, error);
        }
      };

      input.addEventListener("keydown", event => {
        if (event.key === "Enter") {
          event.preventDefault();
          void finish(true);
        } else if (event.key === "Escape") {
          event.preventDefault();
          void finish(false);
        }
      });
      input.addEventListener("blur", () => { void finish(true); }, { once: true });
    };

    button.addEventListener("click", open);
  }

  function initQuickEditors() {
    initInlineNumberEditor({
      hostRole: "game-playtime-editor",
      buttonRole: "game-playtime-edit",
      property: "PlaytimeHours",
      current: () => Math.max(0, Number(valueOf("PlaytimeHours", "playtime_hours", "playtime")) || 0),
      min: 0,
      max: 100000,
      step: .5,
      onCommit: value => {
        gameFrontmatter.PlaytimeHours = value;
        const metric = q('[data-role="game-playtime-metric"]');
        if (metric) metric.textContent = `${value}h`;
      },
    });

    initInlineNumberEditor({
      hostRole: "game-completion-editor",
      buttonRole: "game-completion-edit",
      property: "Completion",
      current: () => Math.max(0, Math.min(100, Number(valueOf("Completion", "completion")) || 0)),
      min: 0,
      max: 100,
      step: 1,
      onCommit: value => {
        gameFrontmatter.Completion = value;
        const label = q('[data-role="game-completion-value"]');
        const fill = q('[data-role="game-progress-fill"]');
        const progress = q('[data-role="game-progress"]');
        if (label) label.textContent = `${value}%`;
        if (fill) fill.style.width = `${value}%`;
        if (progress) progress.setAttribute("aria-valuenow", String(value));
      },
    });
  }

  function initNoteEditor() {
    const render = q('[data-role="game-note-render"]');
    const state = q('[data-role="game-note-state"]');
    if (!render || !state) return;

    if (render.querySelector("[data-cv-editable-placeholder]")) {
      gameRoot.classList.add("is-native-editor");
      state.textContent = "Editing in Obsidian";
      return;
    }

    render.classList.toggle("is-empty", !text(gameBodyContent));
    render.tabIndex = 0;
    state.textContent = "Click prose · Enter/F2 for Live Preview";
    let openingEditor = false;

    const focusEditor = leaf => {
      const focus = () => {
        try {
          if (leaf?.view?.editor?.focus) {
            leaf.view.editor.focus();
            return;
          }
          leaf?.view?.contentEl?.querySelector?.(".cm-content")?.focus?.();
        } catch {
          // Best-effort focus after native view-state switch.
        }
      };
      setTimeout(focus, 0);
      setTimeout(focus, 100);
    };

    const enterLivePreview = async () => {
      if (openingEditor) return;
      const leaves = gameApp.workspace.getLeavesOfType?.("markdown") || [];
      const leaf = leaves.find(candidate =>
        candidate?.view?.file?.path === gameFile?.path &&
        candidate?.view?.contentEl?.contains?.(gameContainer)
      ) || leaves.find(candidate => candidate?.view?.file?.path === gameFile?.path);

      if (!leaf?.getViewState || !leaf?.setViewState) {
        state.textContent = "Could not resolve native editor";
        console.warn("[custom-view:game] Could not resolve markdown leaf for Live Preview");
        return;
      }

      const viewState = leaf.getViewState();
      if (viewState?.state?.mode === "source" && viewState?.state?.source === false) {
        focusEditor(leaf);
        return;
      }

      openingEditor = true;
      state.textContent = "Opening Live Preview…";
      try {
        await leaf.setViewState({
          ...viewState,
          active: true,
          state: {
            ...(viewState.state || {}),
            mode: "source",
            source: false,
          },
        });
        focusEditor(leaf);
      } catch (error) {
        openingEditor = false;
        state.textContent = "Could not open Live Preview";
        console.error("[custom-view:game] Could not enter Live Preview", error);
      }
    };

    const hasSelection = () => Boolean(text(gameDocument.getSelection?.()?.toString?.()));
    const interactiveSelector = [
      "a", "button", "input", "textarea", "select", "option", "label", "summary", "details",
      "audio", "video", "iframe", "canvas", "[contenteditable='true']", "[role='button']",
      "[role='link']", "[data-interactive]", "[data-no-edit]", ".clickable-icon",
      ".task-list-item-checkbox", ".internal-link", ".external-link"
    ].join(",");
    const isInteractive = target => Boolean(target?.closest?.(interactiveSelector));
    const isEditableProse = target => {
      if (target === render) return true;
      return Boolean(target?.closest?.(
        "p, li, blockquote, h1, h2, h3, h4, h5, h6, pre, code, table, .markdown-rendered-content, .markdown-preview-sizer"
      ));
    };

    render.addEventListener("click", event => {
      if (event.defaultPrevented || isInteractive(event.target) || hasSelection() || !isEditableProse(event.target)) return;
      void enterLivePreview();
    });

    render.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      if (isInteractive(event.target)) return;
      event.preventDefault();
      void enterLivePreview();
    });
  }

  renderIdentity();
  renderSummary();
  renderMetadata();
  renderLinks();
  initStatus();
  initRating();
  initQuickEditors();
  initNoteEditor();
}

views.css:
/* Zettelkasten Atomic Slip — one idea with connection/source rail. */
.obsidian-custom-view-render:has(> .cv-zettel) { padding: 0 !important; background: var(--background-primary) !important; }
.cv-zettel {
  --cvz-bg: var(--background-primary); --cvz-surface: var(--background-secondary); --cvz-card: color-mix(in srgb, var(--background-primary) 94%, var(--background-secondary) 6%);
  --cvz-text: var(--text-normal); --cvz-muted: var(--text-muted); --cvz-faint: var(--text-faint); --cvz-accent: var(--interactive-accent); --cvz-accent-text: var(--text-accent);
  --cvz-border: var(--background-modifier-border); --cvz-border-strong: var(--background-modifier-border-hover, var(--background-modifier-border)); --cvz-shadow: color-mix(in srgb, var(--shadow, #000) 24%, transparent);
  --cvz-type-accent: var(--cvz-accent); --cvz-type-border: solid; --cvz-pad: clamp(18px, 3.8cqi, 54px);
  width: 100%; max-width: 100%; min-width: 0; overflow-x: clip; container-type: inline-size; background: var(--cvz-bg); color: var(--cvz-text); font-family: var(--font-interface);
}
.cv-zettel[data-zettel-type="literature"] { --cvz-type-accent: var(--color-purple, var(--interactive-accent)); --cvz-type-border: double; }
.cv-zettel[data-zettel-type="fleeting"] { --cvz-type-accent: var(--color-orange, var(--interactive-accent)); --cvz-type-border: dashed; }
.cv-zettel[data-zettel-type="permanent"] { --cvz-type-accent: var(--color-green, var(--interactive-accent)); }
.cv-zettel *, .cv-zettel *::before, .cv-zettel *::after { box-sizing: border-box; }
.cv-zettel-header { width: min(100%, 1220px); margin: 0 auto; padding: clamp(30px, 5cqi, 68px) var(--cvz-pad) clamp(22px, 3.4cqi, 42px); display: grid; grid-template-columns: minmax(135px, .22fr) minmax(0, 1fr) minmax(280px, .42fr); align-items: end; gap: clamp(20px, 3.2cqi, 42px); border-bottom: 1px solid var(--cvz-border); }
.cv-zettel-index { align-self: stretch; display: flex; flex-direction: column; justify-content: space-between; gap: 28px; padding-left: 12px; border-left: 4px var(--cvz-type-border) var(--cvz-type-accent); }
.cv-zettel-eyebrow, .cv-zettel-id, .cv-zettel-meta dt, .cv-zettel-footer { font-family: var(--font-monospace); text-transform: uppercase; letter-spacing: .12em; font-weight: 720; }
.cv-zettel-eyebrow { color: var(--cvz-type-accent); font-size: .68rem; } .cv-zettel-id { color: var(--cvz-muted); font-size: .7rem; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.cv-zettel-title-block { min-width: 0; } .cv-zettel-title { max-width: 30ch; margin: 0; color: var(--cvz-text); font-family: var(--font-text); font-size: clamp(1.85rem, 4.1cqi, 4.1rem); line-height: 1.03; letter-spacing: -.04em; text-wrap: balance; overflow-wrap: break-word; word-break: normal; }
.cv-zettel-title.is-long { font-size: clamp(1.65rem, 3.5cqi, 3.35rem); max-width: 34ch; }
.cv-zettel-title.is-very-long { font-size: clamp(1.45rem, 3cqi, 2.85rem); max-width: 38ch; }
.cv-zettel-principle { margin: 12px 0 0; color: var(--cvz-muted); font-size: .82rem; }
.cv-zettel-meta { margin: 0; display: grid; gap: 10px; } .cv-zettel-meta div { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 12px; padding-top: 8px; border-top: 1px solid var(--cvz-border); }
.cv-zettel-meta dt, .cv-zettel-meta dd { margin: 0; } .cv-zettel-meta dt { color: var(--cvz-faint); font-size: .59rem; } .cv-zettel-meta dd { min-width: 0; overflow: hidden; color: var(--cvz-muted); font-size: .78rem; font-weight: 650; text-overflow: ellipsis; white-space: nowrap; }
.cv-zettel-slip { position: relative; width: min(calc(100% - (2 * var(--cvz-pad))), 1120px); margin: clamp(34px, 5.2cqi, 72px) auto 0; border: 1px solid var(--cvz-border-strong); border-top: 5px var(--cvz-type-border) var(--cvz-type-accent); border-radius: 3px 3px 7px 5px; background: var(--cvz-card); box-shadow: 0 18px 48px var(--cvz-shadow); }
.cv-zettel-slip::before { content: ""; position: absolute; top: -5px; right: clamp(24px, 5cqi, 58px); width: 74px; height: 9px; background: color-mix(in srgb, var(--cvz-type-accent) 24%, var(--cvz-card)); opacity: .85; transform: translateY(-46%) rotate(.8deg); pointer-events: none; }
.cv-zettel-content { min-width: 0; padding: clamp(18px, 2.7cqi, 34px); color: var(--cvz-text); font-family: var(--font-text); overflow-wrap: anywhere; }
.cv-zettel-template-title, .cv-zettel-content > br:first-child { display: none !important; }
.cv-zettel .cv-zettel-core-idea { margin: 0 0 clamp(28px, 4cqi, 48px); padding: clamp(18px, 2.8cqi, 30px); border: 0; border-left: 5px solid var(--cvz-type-accent); border-radius: 0; background: color-mix(in srgb, var(--cvz-type-accent) 7%, var(--cvz-card)); box-shadow: none; }
.cv-zettel .cv-zettel-core-idea > .callout-title { color: var(--cvz-type-accent); font-family: var(--font-monospace); font-size: .68rem; letter-spacing: .12em; text-transform: uppercase; }
.cv-zettel .cv-zettel-core-idea > .callout-content { padding-top: 8px; color: var(--cvz-text); font-size: clamp(1.12rem, 2cqi, 1.42rem); line-height: 1.55; }
.cv-zettel-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(240px, 31%); align-items: start; gap: clamp(28px, 4.2cqi, 52px); }
.cv-zettel-main, .cv-zettel-rail, .cv-zettel-section { min-width: 0; } .cv-zettel-main { padding-right: clamp(4px, 1.3cqi, 16px); } .cv-zettel-rail { display: grid; gap: 0; border-left: 1px solid var(--cvz-border-strong); }
.cv-zettel-main .cv-zettel-section { padding: 0 0 clamp(20px, 3cqi, 34px); } .cv-zettel-main .cv-zettel-section > h2 { margin-top: 0; font-size: clamp(1.15rem, 2cqi, 1.42rem); }
.cv-zettel-rail .cv-zettel-section, .cv-zettel-backlinks { padding: 18px 0 20px clamp(20px, 2.8cqi, 30px); border-bottom: 1px solid var(--cvz-border); }
.cv-zettel-rail .cv-zettel-section:last-child, .cv-zettel-backlinks:last-child { border-bottom: 0; }
.cv-zettel-rail .cv-zettel-section > h2, .cv-zettel-backlinks h2 { margin: 0 0 12px; color: var(--cvz-type-accent); font-family: var(--font-monospace); font-size: .67rem; line-height: 1.3; letter-spacing: .12em; text-transform: uppercase; }
