@container (max-width: 850px) { .cv-zettel-header { grid-template-columns: 130px minmax(0, 1fr); } .cv-zettel-meta { grid-column: 1 / -1; grid-template-columns: repeat(3, minmax(0, 1fr)); } .cv-zettel-meta div { grid-template-columns: 1fr; gap: 4px; } }
