/* CV_ZETTEL_TITLE_PAPER_V3 */
.cv-zettel {
  --cvz-paper-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--cvz-type-accent) 18%, transparent));
  --cvz-paper-line: var(--vault-note-paper-line, 30px);
}

.cv-zettel-title-block {
  min-width: 0;
  overflow: hidden;
}

.cv-zettel-title,
.cv-zettel-title.is-long,
.cv-zettel-title.is-very-long {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-wrap: nowrap;
  overflow-wrap: normal;
  word-break: normal;
  font-size: clamp(1.9rem, 4.15cqi, 4.15rem);
}

.cv-zettel-title.is-title-short {
  font-size: clamp(2.3rem, 4.8cqi, 4.7rem);
}

.cv-zettel-title.is-title-long {
  font-size: clamp(1.7rem, 3.5cqi, 3.35rem);
}

.cv-zettel-title.is-title-very-long {
  font-size: clamp(1.55rem, 3cqi, 2.8rem);
}

.cv-zettel-slip {
  background:
    repeating-linear-gradient(
      to bottom,
      transparent 0 calc(var(--cvz-paper-line) - 7px),
      color-mix(in srgb, var(--cvz-paper-rule) 55%, transparent)
        calc(var(--cvz-paper-line) - 7px)
        calc(var(--cvz-paper-line) - 5px),
      transparent calc(var(--cvz-paper-line) - 5px) var(--cvz-paper-line)
    ),
    var(--cvz-card);
}

.cv-zettel-main,
.cv-zettel-rail,
.cv-zettel-core-idea {
  position: relative;
  z-index: 1;
}

.cv-zettel-main,
.cv-zettel-rail {
  text-shadow:
    1px 0 0 var(--cvz-card),
    -1px 0 0 var(--cvz-card),
    0 1px 0 var(--cvz-card),
    0 -1px 0 var(--cvz-card);
}

.cv-zettel-main code,
.cv-zettel-rail code {
  text-shadow: none;
}


/* CV_ZETTEL_PAPER_LAYER_V4
   Dedicated ruled-paper layer below the atomic note content. */
.cv-zettel-slip {
  isolation: isolate;
  background: var(--cvz-card) !important;
}

.cv-zettel-slip::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0 calc(var(--cvz-paper-line) - 7px),
    color-mix(in srgb, var(--cvz-paper-rule) 55%, transparent)
      calc(var(--cvz-paper-line) - 7px)
      calc(var(--cvz-paper-line) - 5px),
    transparent calc(var(--cvz-paper-line) - 5px) var(--cvz-paper-line)
  );
}

.cv-zettel-slip::before { z-index: 2; }
.cv-zettel-content { position: relative; z-index: 1; }


/* CV_ZETTEL_HEADER_COLLISION_V5
   Preserve the existing title lane and adaptive ellipsis without allowing the
