.cv-zettel-header {
  grid-template-columns: minmax(120px, .2fr) minmax(0, 1fr) minmax(260px, .4fr);
  overflow: hidden;
}
.cv-zettel-title-block {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}
.cv-zettel-title {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.cv-zettel-meta {
  min-width: 0;
  position: relative;
  z-index: 4;
}
@container (max-width: 850px) {
  .cv-zettel-header { grid-template-columns: 130px minmax(0, 1fr); }
}


/* CV_ZETTEL_LAYOUT_RATIO_V6 */
.cv-zettel {
  --cvz-main-ratio: 70fr;
  --cvz-rail-ratio: 30fr;
}

.cv-zettel-slip {
  margin: clamp(22px, 3.2cqi, 44px) auto 0;
}

/* Remove the decorative sellotape; the ruled slip itself is the visual object. */
.cv-zettel-slip::before {
  content: none !important;
  display: none !important;
}

.cv-zettel-layout {
  grid-template-columns: minmax(0, var(--cvz-main-ratio)) minmax(220px, var(--cvz-rail-ratio));
}

@container (max-width: 650px) {
  .cv-zettel-layout {
    grid-template-columns: 1fr;
  }
}

