const zettelContext = tp;
const zettelContainer = zettelContext.container || this;
const zettelRoot = zettelContainer.querySelector(".cv-zettel");

if (zettelRoot) {
  const zettelApp = zettelContext.app;
  const zettelFile = zettelContext.file;
  const zettelFrontmatter = zettelContext.frontmatter || {};
  const zettelDocument = zettelContext.activeDocument || zettelContainer.ownerDocument;
  const zettelWindow = zettelContext.activeWindow || zettelDocument.defaultView;
  const q = selector => zettelRoot.querySelector(selector);

  const text = value => String(value ?? "").trim();
  const slug = value => text(value).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

  function noteIdentity() {
    const basename = text(zettelFile?.basename);
    const match = basename.match(/^(\d{14})\s*-\s*(.+)$/);
    return {
      id: text(zettelFrontmatter.id) || text(match?.[1]),
      title: text(match?.[2]) || basename || "Untitled",
      basename,
    };
  }

  function setText(role, value, fallback = "—") {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = text(value) || fallback;
  }

  function normalizedType(value) {
    const candidate = text(value).toLowerCase();
    return ["permanent", "literature", "fleeting"].includes(candidate) ? candidate : "permanent";
  }

  function configureLayoutWidth() {
    const raw = zettelFrontmatter["zettelkasten-width"] ?? zettelFrontmatter.zettelkasten_width ?? 70;
    const parsed = Number.parseFloat(String(raw).replace("%", ""));
    const mainWidth = Number.isFinite(parsed) ? Math.min(88, Math.max(55, parsed)) : 70;
    const railWidth = 100 - mainWidth;
    zettelRoot.style.setProperty("--cvz-main-ratio", `${mainWidth}fr`);
    zettelRoot.style.setProperty("--cvz-rail-ratio", `${railWidth}fr`);
    zettelRoot.dataset.zettelkastenWidth = String(mainWidth);
  }

  function renderHeader() {
    configureLayoutWidth();
    const type = normalizedType(zettelFrontmatter.type);
    const identity = noteIdentity();
    zettelRoot.dataset.zettelType = type;
    setText("zettel-id", identity.id, "No ID");
    setText("zettel-title", identity.title, "Untitled");
    const titleElement = q('[data-role="zettel-title"]');
    if (titleElement) {
      titleElement.classList.remove("is-long", "is-very-long");
      titleElement.classList.toggle("is-title-short", identity.title.length <= 24);
      titleElement.classList.toggle("is-title-long", identity.title.length > 44 && identity.title.length <= 68);
      titleElement.classList.toggle("is-title-very-long", identity.title.length > 68);
      titleElement.removeAttribute("title");
    }
    setText("zettel-type", type.charAt(0).toUpperCase() + type.slice(1));
    setText("zettel-date", zettelFrontmatter.date);
    setText("zettel-link-count", "0", "0");
    setText("zettel-related-count", "0 connections", "0 connections");
  }

  function markdownSurface(content) {
    const rendered = content.querySelector(":scope > .markdown-rendered-content")
      || content.querySelector(":scope > .markdown-preview-view")
      || content.querySelector(":scope > .markdown-rendered")
      || content;
    return rendered.querySelector?.(":scope > .markdown-preview-sizer, :scope > .markdown-preview-section") || rendered;
  }

  function markTemplateTitle(surface) {
    const identity = noteIdentity();
    const candidates = new Set([identity.basename, identity.title].map(value => text(value).toLowerCase()).filter(Boolean));
    const headings = Array.from(surface.querySelectorAll("h1"));
    const heading = headings.find(node => candidates.has(text(node.textContent).toLowerCase())) || headings[0];
    if (heading) heading.classList.add("cv-zettel-template-title");
  }

  function collectSections(surface) {
    const children = Array.from(surface.children);
    const sections = [];
    let current = null;

    for (const node of children) {
      const heading = node.matches?.("h2")
        ? node
        : node.querySelector?.(":scope > h2");
      if (heading) {
        current = { name: text(heading.textContent), nodes: [node] };
        sections.push(current);
      } else if (current) {
        current.nodes.push(node);
      }
    }
    return sections;
  }

  function makeSection(section) {
    const wrapper = zettelDocument.createElement("section");
    const sectionName = slug(section.name) || "section";
    wrapper.className = `cv-zettel-section cv-zettel-section--${sectionName}`;
    if (sectionName === "core-idea") wrapper.classList.add("cv-zettel-core-idea");
    wrapper.dataset.section = sectionName;
    for (const node of section.nodes) wrapper.appendChild(node);
    return wrapper;
  }

  function makeBacklinksPanel() {
    const panel = zettelDocument.createElement("section");
    panel.className = "cv-zettel-backlinks";
    panel.dataset.generated = "backlinks";

    const heading = zettelDocument.createElement("h2");
    heading.textContent = "Backlinks";
    panel.appendChild(heading);

    const resolved = zettelApp?.metadataCache?.resolvedLinks || {};
    const targetPath = text(zettelFile?.path);
    const sources = Object.entries(resolved)
      .filter(([sourcePath, destinations]) => sourcePath !== targetPath && Number(destinations?.[targetPath] || 0) > 0)
      .map(([sourcePath, destinations]) => ({ sourcePath, count: Number(destinations[targetPath] || 0) }))
      .sort((a, b) => b.count - a.count || a.sourcePath.localeCompare(b.sourcePath));

    setText("zettel-backlink-count", `${sources.length} backlinks`);

    if (!sources.length) {
      const empty = zettelDocument.createElement("p");
      empty.className = "cv-zettel-empty";
      empty.textContent = "No backlinks yet.";
      panel.appendChild(empty);
      return panel;
    }

    const list = zettelDocument.createElement("div");
    list.className = "cv-zettel-backlinks-list";
    for (const item of sources.slice(0, 12)) {
      const file = zettelApp?.vault?.getAbstractFileByPath?.(item.sourcePath);
      const button = zettelDocument.createElement("button");
      button.type = "button";
      button.className = "cv-zettel-backlink";
      button.textContent = `${text(file?.basename) || item.sourcePath}${item.count > 1 ? ` · ${item.count}` : ""}`;
      button.addEventListener("click", async () => {
        if (file && zettelApp?.workspace?.getLeaf) await zettelApp.workspace.getLeaf(false).openFile(file);
      });
      list.appendChild(button);
    }
    panel.appendChild(list);
    return panel;
  }

  function buildAtomicLayout(content) {
    const surface = markdownSurface(content);
    if (!surface || surface.querySelector(":scope > .cv-zettel-layout")) return false;

    markTemplateTitle(surface);

    const sections = collectSections(surface);
    if (!sections.length) return false;

    const firstNode = sections[0].nodes[0];
    const layout = zettelDocument.createElement("div");
    layout.className = "cv-zettel-layout";
    const main = zettelDocument.createElement("div");
    main.className = "cv-zettel-main";
    const rail = zettelDocument.createElement("aside");
    rail.className = "cv-zettel-rail";

    firstNode.before(layout);
    for (const section of sections) {
      const wrapper = makeSection(section);
      const name = slug(section.name);
      if (["connections", "context-connections", "sources-references"].includes(name)) rail.appendChild(wrapper);
      else main.appendChild(wrapper);
    }

    const connectionSection = rail.querySelector('.cv-zettel-section--connections, .cv-zettel-section--context-connections');
    const connectionCount = connectionSection?.querySelectorAll('a.internal-link').length || 0;
    setText("zettel-link-count", String(connectionCount), "0");
    setText(
      "zettel-related-count",
      `${connectionCount} connection${connectionCount === 1 ? "" : "s"}`,
      "0 connections"
    );

    rail.appendChild(makeBacklinksPanel());
    layout.append(main, rail);
    return true;
  }

  function decorateContent() {
    const content = q('[data-role="zettel-content"]');
    if (!content) return false;
    return buildAtomicLayout(content);
  }

  function installDecorator() {
    const content = q('[data-role="zettel-content"]');
    if (!content) return;
    decorateContent();

    const Observer = zettelWindow?.MutationObserver;
    if (typeof Observer !== "function") return;
    let queued = false;
    const observer = new Observer(() => {
      if (queued) return;
      queued = true;
      (zettelWindow.requestAnimationFrame || zettelWindow.setTimeout)?.(() => {
        queued = false;
        decorateContent();
      });
    });
    observer.observe(content, { childList: true, subtree: true });
  }

  let openingEditor = false;

  async function enterEditingMode() {
    if (openingEditor) return;

    const leaves = typeof zettelApp?.workspace?.getLeavesOfType === "function"
      ? zettelApp.workspace.getLeavesOfType("markdown")
      : [];
    const leaf = leaves.find(candidate =>
      candidate?.view?.file?.path === zettelFile?.path
      && candidate.view.contentEl?.contains(zettelContainer)
    );

    if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
      console.warn("[custom-view:zettelkasten] Could not resolve the markdown leaf for source editing");
      return;
    }

    const viewState = leaf.getViewState();
    if (viewState?.state?.mode === "source" && viewState?.state?.source === true) {
      leaf.view?.editor?.focus?.();
      return;
    }

    openingEditor = true;
    try {
      await leaf.setViewState({
        ...viewState,
        active: true,
        state: {
          ...(viewState.state || {}),
          mode: "source",
          source: true,
        },
      });
      const focusEditor = () => leaf.view?.editor?.focus?.();
      zettelWindow.setTimeout?.(focusEditor, 0);
      zettelWindow.setTimeout?.(focusEditor, 100);
    } catch (error) {
      openingEditor = false;
      console.error("[custom-view:zettelkasten] Could not switch note to Source Mode", error);
    }
  }

  function bindClickToEdit() {
    const content = q('[data-role="zettel-content"]');
    if (!content) return;

    content.setAttribute("tabindex", "0");
    content.addEventListener("click", event => {
      if (event.target?.closest?.('a, button, input, textarea, select, label, [contenteditable="true"], [data-generated="backlinks"]')) return;
      if (text(zettelWindow?.getSelection?.()?.toString())) return;
      void enterEditingMode();
    });
    content.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void enterEditingMode();
    });
  }

  renderHeader();
  installDecorator();
  bindClickToEdit();
}

