  --cvc-bg: var(--background-primary); --cvc-surface: var(--background-secondary);
  --cvc-paper: var(--vault-note-paper-bg, color-mix(in srgb, var(--background-primary) 91%, var(--background-secondary) 9%));
  --cvc-rule: var(--vault-note-paper-rule, color-mix(in srgb, var(--interactive-accent) 18%, transparent));
  --cvc-line: var(--vault-note-paper-line, 30px); --cvc-text: var(--text-normal); --cvc-muted: var(--text-muted);
