.cv-cornell-study-toggle:hover, .cv-cornell-study-toggle[aria-pressed="true"] { background: color-mix(in srgb, var(--cvc-accent) 12%, transparent); }
.cv-cornell-study-toggle:focus-visible { outline: 2px solid var(--cvc-accent); outline-offset: 3px; }
.cv-cornell-sheet { position: relative; width: min(calc(100% - (2 * var(--cvc-pad))), 1320px); min-height: clamp(700px, 78vh, 1050px); margin: clamp(28px, 4.4cqi, 62px) auto 0; overflow: hidden; border: 1px solid var(--vault-note-paper-edge, var(--cvc-border-strong)); border-radius: 3px; background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--cvc-line) - 7px), color-mix(in srgb, var(--cvc-rule) 55%, transparent) calc(var(--cvc-line) - 7px) calc(var(--cvc-line) - 5px), transparent calc(var(--cvc-line) - 5px) var(--cvc-line)), var(--cvc-paper); box-shadow: 0 18px 46px var(--cvc-shadow); }
.cv-cornell-sheet::after { content: ""; position: absolute; inset: 0; pointer-events: none; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvc-text) 4%, transparent); }
