.cv-cornell-row-body ul { margin: .18em 0 .1em; }

.cv-cornell-row[data-cornell-kind="meta"] { --cvc-row-accent: var(--color-cyan, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="goals"] { --cvc-row-accent: var(--color-yellow, var(--color-orange, var(--cvc-accent))); }
.cv-cornell-row[data-cornell-kind="cue"],
.cv-cornell-row[data-cornell-kind="recall"] { --cvc-row-accent: var(--color-purple, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="concept"] { --cvc-row-accent: var(--color-blue, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="example"] { --cvc-row-accent: var(--color-orange, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="verified"],
.cv-cornell-row[data-cornell-kind="review"] { --cvc-row-accent: var(--color-green, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="mistake"] { --cvc-row-accent: var(--color-red, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="related"] { --cvc-row-accent: var(--color-cyan, var(--cvc-accent)); }
.cv-cornell-row[data-cornell-kind="summary"] { --cvc-row-accent: var(--color-pink, var(--color-purple, var(--cvc-accent))); }

.cv-cornell-row[data-cornell-kind="summary"] {
  margin-top: clamp(22px, 3cqi, 36px);
  padding-top: clamp(8px, 1.2cqi, 14px);
}

.cv-cornell-row[data-cornell-kind="summary"]::before {
  content: "";
  position: absolute;
  top: 0;
  left: calc(27% + clamp(24px, 3.2cqi, 42px));
  right: clamp(24px, 3.2cqi, 42px);
  height: 1px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--cvc-row-accent) 50%, transparent), transparent);
}

.cv-cornell.is-study-mode .cv-cornell-row:not([data-cornell-kind="meta"]):not([data-cornell-kind="goals"]):not([data-cornell-kind="recall"]):not([data-cornell-kind="review"]) .cv-cornell-row-body {
  opacity: .07;
  filter: blur(4px);
  pointer-events: none;
  user-select: none;
}

@container (max-width: 680px) {
  .cv-cornell-sheet::before { display: none; }
  .cv-cornell-column-guide { grid-template-columns: 1fr; }
  .cv-cornell-column-guide span:first-child {
    border-right: 0;
    text-align: left;
    padding: 11px 16px 9px;
  }
  .cv-cornell-column-guide span:last-child { display: none; }
  .cv-cornell-content .cv-cornell-section-heading { margin: 24px 16px 6px; }
  .cv-cornell-row { grid-template-columns: 1fr; margin-bottom: 18px; }
  .cv-cornell-row-cue {
    justify-content: flex-start;
    padding: 12px 16px 8px 20px;
    background: transparent;
    text-align: left;
  }
  .cv-cornell-row-body { padding: 8px 16px 16px 20px; }
}


/* CV_CORNELL_INTERACTION_V5
   Adjustable 25/75 default ratio, click-to-edit, dimmed study answers, and
   per-entry reveal controls while preserving the continuous paper folio. */
.cv-cornell {
  --cvc-cue-width: 25%;
}

.cv-cornell-sheet::before {
  left: var(--cvc-cue-width);
}

.cv-cornell-column-guide,
.cv-cornell-row {
  grid-template-columns: minmax(145px, var(--cvc-cue-width)) minmax(0, 1fr);
}

.cv-cornell-content .cv-cornell-section-heading {
  margin-left: calc(var(--cvc-cue-width) + clamp(22px, 3cqi, 38px));
}

.cv-cornell-row[data-cornell-kind="summary"]::before {
  left: calc(var(--cvc-cue-width) + clamp(24px, 3.2cqi, 42px));
}

.cv-cornell-row-cue {
  flex-direction: column;
  align-items: flex-end;
}

.cv-cornell-row-body {
  cursor: text;
}

.cv-cornell-reveal {
  display: none;
  align-items: center;
  justify-content: center;
  min-height: 25px;
  margin-top: 9px;
  padding: 4px 9px;
  border: 1px solid color-mix(in srgb, var(--cvc-row-accent) 46%, var(--cvc-border));
  border-radius: 999px;
  background: color-mix(in srgb, var(--cvc-paper) 90%, transparent);
  color: color-mix(in srgb, var(--cvc-row-accent) 78%, var(--cvc-text));
  font: 720 .58rem/1 var(--font-monospace);
  letter-spacing: .055em;
  cursor: pointer;
  opacity: .86;
}

.cv-cornell-reveal:hover,
.cv-cornell-reveal:focus-visible {
  border-color: color-mix(in srgb, var(--cvc-row-accent) 72%, var(--cvc-border));
  background: color-mix(in srgb, var(--cvc-row-accent) 9%, var(--cvc-paper));
  opacity: 1;
}

.cv-cornell-reveal:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--cvc-row-accent) 72%, transparent);
  outline-offset: 2px;
}

.cv-cornell.is-study-mode .cv-cornell-row:not([data-cornell-kind="meta"]) .cv-cornell-reveal {
  display: inline-flex;
}

/* Study mode keeps answers visibly present, but unreadable at a glance. */
.cv-cornell.is-study-mode .cv-cornell-row:not([data-cornell-kind="meta"]) .cv-cornell-row-body {
  opacity: .28 !important;
  filter: blur(2.35px) saturate(.72) !important;
  pointer-events: none;
  user-select: none;
  transition: opacity .16s ease, filter .16s ease;
}

.cv-cornell.is-study-mode .cv-cornell-row.is-revealed .cv-cornell-row-body {
  opacity: 1 !important;
  filter: none !important;
  pointer-events: auto;
  user-select: text;
}

.cv-cornell.is-study-mode .cv-cornell-row-body {
  cursor: default;
}

@container (max-width: 680px) {
  .cv-cornell-row-cue {
    align-items: flex-start;
  }
  .cv-cornell-reveal {
    margin-top: 7px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cv-cornell.is-study-mode .cv-cornell-row-body {
    transition: none;
  }
}

/* CV_CORNELL_STUDY_POLISH_V6
   Restore the pre-Reveal cue position, strengthen answer masking, keep review
   readable, and make the two Cornell columns use their intended alignment. */
.cv-cornell-row-cue {
  justify-content: flex-start;
  align-items: flex-end;
  text-align: right;
}

.cv-cornell-row-label {
  text-align: right;
}

.cv-cornell-row-body {
  text-align: justify;
  text-justify: inter-word;
}

.cv-cornell.is-study-mode .cv-cornell-row:not([data-cornell-kind="meta"]):not([data-cornell-kind="review"]) .cv-cornell-row-body {
  opacity: .16 !important;
  filter: blur(7.5px) saturate(.55) contrast(.78) !important;
  pointer-events: none;
  user-select: none;
}

.cv-cornell.is-study-mode .cv-cornell-row[data-cornell-kind="review"] .cv-cornell-row-body {
  opacity: 1 !important;
  filter: none !important;
  pointer-events: auto;
  user-select: text;
}

.cv-cornell.is-study-mode .cv-cornell-row[data-cornell-kind="review"] .cv-cornell-reveal {
  display: none !important;
}

.cv-cornell.is-study-mode .cv-cornell-row.is-revealed:not([data-cornell-kind="review"]) .cv-cornell-row-body {
  opacity: 1 !important;
  filter: none !important;
  pointer-events: auto;
  user-select: text;
}

@container (max-width: 680px) {
  .cv-cornell-row-cue {
    justify-content: flex-start;
    align-items: flex-start;
    text-align: left;
  }
  .cv-cornell-row-label {
    text-align: left;
  }
  .cv-cornell-row-body {
    text-align: left;
  }
}


/* CV_CORNELL_TITLE_SOURCE_V7 */
/* Keep the title inside its existing header allocation: scale down only to a
   readable floor, then ellipsize. Paper ruling remains 2px / 30px-pitch and is
   optically knocked out immediately around glyphs so the ink stays dominant. */
.cv-cornell-heading {
  min-width: 0;
  overflow: hidden;
}

.cv-cornell-title {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  margin-right: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-wrap: nowrap;
  overflow-wrap: normal;
  word-break: normal;
  font-size: clamp(2.15rem, 4.7cqi, 4.7rem);
}

.cv-cornell-title.is-title-short {
  font-size: clamp(2.55rem, 5.25cqi, 5.2rem);
}

.cv-cornell-title.is-title-long {
  font-size: clamp(1.95rem, 3.75cqi, 3.65rem);
}

.cv-cornell-title.is-title-very-long {
  font-size: clamp(1.8rem, 3.2cqi, 3.05rem);
}

.cv-cornell-meta,
.cv-cornell-study-toggle {
  position: relative;
  z-index: 3;
  min-width: 0;
}

.cv-cornell-row-label,
.cv-cornell-row-body,
.cv-cornell-content .cv-cornell-section-heading {
  text-shadow:
    1px 0 0 var(--cvc-paper),
    -1px 0 0 var(--cvc-paper),
    0 1px 0 var(--cvc-paper),
    0 -1px 0 var(--cvc-paper);
}

.cv-cornell-row-body code {
  text-shadow: none;
}


/* CV_CORNELL_PAPER_LAYER_V8
   Paint notebook ruling on a dedicated layer underneath the Cornell ink. */
.cv-cornell-sheet {
  isolation: isolate;
  background: var(--cvc-paper) !important;
}

.cv-cornell-sheet::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0 calc(var(--cvc-line) - 7px),
    color-mix(in srgb, var(--cvc-rule) 55%, transparent)
      calc(var(--cvc-line) - 7px)
      calc(var(--cvc-line) - 5px),
    transparent calc(var(--cvc-line) - 5px) var(--cvc-line)
  );
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--cvc-text) 4%, transparent);
}

.cv-cornell-sheet::before { z-index: 1; }
.cv-cornell-column-guide,
.cv-cornell-content { position: relative; z-index: 2; }


/* CV_CORNELL_HEADER_COLLISION_V9
   Keep the title inside a fixed grid lane so even hostile filenames can never
   paint over metadata. Existing adaptive title sizing/ellipsis remains intact. */
.cv-cornell-header {
  grid-template-columns: minmax(0, 1fr) minmax(320px, .72fr) auto;
  overflow: hidden;
}
.cv-cornell-heading {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}
.cv-cornell-title {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.cv-cornell-meta,
.cv-cornell-study-toggle {
  min-width: 0;
  position: relative;
  z-index: 4;
}
@container (max-width: 900px) {
  .cv-cornell-header { grid-template-columns: minmax(0, 1fr) auto; }
}


/* CV_CORNELL_HEADER_COMPACT_V10 */
.cv-cornell-header {
  grid-template-columns: minmax(0, 1fr) minmax(240px, clamp(280px, 32cqi, 440px));
  align-items: end;
  column-gap: clamp(18px, 2.8cqi, 38px);
  overflow: hidden;
}

.cv-cornell-heading {
  min-width: 0;
}

.cv-cornell-course-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: .55em;
  margin-top: 10px;
  color: var(--cvc-muted);
  font-size: clamp(.9rem, 1.3cqi, 1.05rem);
}

.cv-cornell-course {
  margin: 0;
  color: inherit;
  font-size: 1em;
  line-height: 1.35;
}

.cv-cornell-study-toggle {
  min-height: 0;
  margin: 0;
  padding: .12em .42em;
  border: 1px solid color-mix(in srgb, var(--cvc-accent) 48%, var(--cvc-border));
  border-radius: .42em;
  background: transparent;
  color: var(--cvc-accent-text);
  font: 650 .7em/1.25 var(--font-monospace);
  letter-spacing: .035em;
  vertical-align: middle;
}

.cv-cornell-study-toggle:hover,
.cv-cornell-study-toggle[aria-pressed="true"] {
  background: color-mix(in srgb, var(--cvc-accent) 10%, transparent);
}

.cv-cornell-meta {
  grid-column: auto;
  grid-row: auto;
  justify-self: end;
  width: 100%;
  max-width: 440px;
  min-width: 0;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px clamp(12px, 1.8cqi, 20px);
}

.cv-cornell-sheet {
  margin: clamp(22px, 3.2cqi, 44px) auto 0;
}

@container (max-width: 900px) {
  .cv-cornell-header {
    grid-template-columns: minmax(0, 1fr) minmax(220px, 40%);
  }
  .cv-cornell-meta {
    grid-column: auto;
    grid-row: auto;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@container (max-width: 720px) {
  .cv-cornell-header {
    grid-template-columns: 1fr;
    align-items: start;
  }
  .cv-cornell-meta {
    justify-self: stretch;
    max-width: none;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* CV_CORNELL_META_SHRINK_V11
   Shrink metadata to its actual content instead of filling a 280–440px track. */
.cv-cornell-header {
  grid-template-columns: minmax(0, 1fr) fit-content(310px);
  column-gap: clamp(16px, 2.2cqi, 30px);
}

.cv-cornell-meta {
  grid-column: auto;
  grid-row: auto;
  justify-self: end;
  justify-content: end;
  width: fit-content;
  max-width: 310px;
  min-width: 0;
  grid-template-columns: repeat(2, minmax(96px, 132px));
  gap: 8px clamp(12px, 1.5cqi, 18px);
  text-align: right;
}

.cv-cornell-meta div,
.cv-cornell-meta span,
.cv-cornell-meta strong {
  text-align: right;
}

@container (max-width: 900px) {
  .cv-cornell-header {
    grid-template-columns: minmax(0, 1fr) fit-content(290px);
  }
  .cv-cornell-meta {
    width: fit-content;
    max-width: 290px;
    grid-template-columns: repeat(2, minmax(90px, 124px));
  }
}

@container (max-width: 720px) {
  .cv-cornell-header {
    grid-template-columns: 1fr;
  }
  .cv-cornell-meta {
    justify-self: end;
    width: fit-content;
    max-width: min(100%, 290px);
    grid-template-columns: repeat(2, minmax(90px, 124px));
  }
}


/* CV_CORNELL_STUDY_CENTER_V12
   Keep the compact Study Mode control on the course baseline, centered across the note. */
.cv-cornell-header {
  position: relative;
}

.cv-cornell-course-row {
  display: block;
}

.cv-cornell-study-toggle.cv-cornell-study-toggle--center {
  position: absolute;
  left: 50%;
  bottom: clamp(22px, 3.2cqi, 42px);
  z-index: 6;
  margin: 0;
  transform: translateX(-50%);
  justify-self: auto;
}

@container (max-width: 720px) {
  .cv-cornell-study-toggle.cv-cornell-study-toggle--center {
    position: static;
    grid-column: 1;
    justify-self: center;
    margin-top: 4px;
    transform: none;
  }
}


/* CV_CORNELL_HEADER_CYCLE_V13
   Compact header, real markdown-style separator, lower Study Mode, and content-height prompt accents. */
.cv-cornell-header {
  padding: clamp(20px, 3.1cqi, 44px) var(--cvc-pad) clamp(14px, 1.8cqi, 24px);
  border-bottom: 0;
}

.cv-cornell-header-rule {
  width: min(calc(100% - (2 * var(--cvc-pad))), 1320px);
  margin: 0 auto !important;
}

.cv-cornell-study-toggle.cv-cornell-study-toggle--center {
  bottom: clamp(6px, .9cqi, 12px);
}

@container (max-width: 720px) {
  .cv-cornell-header {
    padding-block: 18px;
  }

  .cv-cornell-study-toggle.cv-cornell-study-toggle--center {
    margin-top: 8px;
  }
}


/* CV_CORNELL_PROMPT_ACCENT_V14
   Bind the semantic accent to the prompt label itself, so its height follows
   wrapped cue text instead of the whole row or the notes column. */
.cv-cornell-row-label {
  position: relative;
}

.cv-cornell-row-label::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  right: clamp(-36px, calc(-2.8cqi - 2px), -22px);
  width: 3px;
  min-height: 1.48em;
  border-radius: 999px;
  background: var(--cvc-row-accent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--cvc-row-accent) 24%, transparent);
  pointer-events: none;
}

@container (max-width: 680px) {
  .cv-cornell-row-label::after {
    right: auto;
    left: -12px;
  }
}

