const cornellContext = tp;
const cornellContainer = cornellContext.container || this;
const cornellRoot = cornellContainer.querySelector(".cv-cornell");

if (cornellRoot) {
  const cornellFrontmatter = cornellContext.frontmatter || {};
  const cornellFile = cornellContext.file;
  const cornellApp = cornellContext.app;
  const cornellDocument = cornellContext.activeDocument || cornellContainer.ownerDocument;
  const cornellWindow = cornellContext.activeWindow || cornellDocument.defaultView;
  const q = selector => cornellRoot.querySelector(selector);

  const text = value => String(value ?? "").trim();
  const cleanLink = value => text(value)
    .replace(/^\[\[([^\]|]+)(?:\|([^\]]+))?\]\]$/, (_, target, alias) => text(alias || target));

  function setText(role, value, fallback = "—") {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = text(value) || fallback;
  }

  function configureColumnRatio() {
    const raw = cornellFrontmatter["cornell-cue-width"] ?? cornellFrontmatter.cornell_cue_width ?? 25;
    const parsed = Number.parseFloat(String(raw).replace("%", ""));
    const cueWidth = Number.isFinite(parsed) ? Math.min(42, Math.max(18, parsed)) : 25;
    cornellRoot.style.setProperty("--cvc-cue-width", `${cueWidth}%`);
    cornellRoot.dataset.cornellCueWidth = String(cueWidth);
  }

  // CV_TITLE_LENGTH_V7 — bounded responsive title; never overlaps metadata.
  function configureTitle() {
    const titleElement = q('.cv-cornell-title');
    if (!titleElement) return;
    const basename = text(cornellFile?.basename) || 'Untitled';
    titleElement.textContent = basename;
    titleElement.classList.toggle('is-title-short', basename.length <= 24);
    titleElement.classList.toggle('is-title-long', basename.length > 44 && basename.length <= 68);
    titleElement.classList.toggle('is-title-very-long', basename.length > 68);
    titleElement.removeAttribute('title');
  }

  function renderHeader() {
    configureColumnRatio();
    configureTitle();
    setText("cornell-course", cleanLink(cornellFrontmatter.course), "Course not set");
    setText("cornell-date", cornellFrontmatter.date);
    setText("cornell-context", cornellFrontmatter.context);
    setText("cornell-status", cornellFrontmatter.status);
    setText(
      "cornell-type",
      text(cornellFrontmatter.type) === "cornell-note" ? "Cornell" : cornellFrontmatter.type,
      "Cornell"
    );
  }

  // CV_CORNELL_META_CYCLE_V13
  const CORNELL_CONTEXT_CYCLE = ["Lecture", "Reading", "Research", "Meeting"];
  const CORNELL_STATUS_CYCLE = ["draft", "reviewing", "complete"];

  async function writeFrontmatterField(field, value) {
    const path = text(cornellFile?.path);
    const file = path ? cornellApp?.vault?.getAbstractFileByPath?.(path) : null;
    const processFrontMatter = cornellApp?.fileManager?.processFrontMatter;
    if (!file || typeof processFrontMatter !== "function") return false;

    try {
      await processFrontMatter.call(cornellApp.fileManager, file, frontmatter => {
        frontmatter[field] = value;
      });
      cornellFrontmatter[field] = value;
      return true;
    } catch (error) {
      console.error(`[custom-view:cornell] Could not update ${field}`, error);
      return false;
    }
  }

  function nextCycleValue(values, current) {
    const normalized = text(current).toLowerCase();
    const index = values.findIndex(value => value.toLowerCase() === normalized);
    return values[(index + 1 + values.length) % values.length];
  }

  function bindMetadataCycles() {
    const configs = [
      { role: "cornell-context", field: "context", values: CORNELL_CONTEXT_CYCLE },
      { role: "cornell-status", field: "status", values: CORNELL_STATUS_CYCLE },
    ];

    for (const config of configs) {
      const element = q(`[data-role="${config.role}"]`);
      if (!element || element.dataset.cornellCycleBound === "true") continue;
      element.dataset.cornellCycleBound = "true";
      element.setAttribute("role", "button");
      element.setAttribute("tabindex", "0");
      element.setAttribute("aria-label", `Cycle ${config.field}`);

      const cycle = async event => {
        event?.preventDefault?.();
        event?.stopPropagation?.();
        const next = nextCycleValue(config.values, cornellFrontmatter[config.field]);
        if (await writeFrontmatterField(config.field, next)) element.textContent = next;
      };

      element.addEventListener("click", cycle);
      element.addEventListener("keydown", event => {
        if (event.key !== "Enter" && event.key !== " ") return;
        void cycle(event);
      });
    }
  }

  function markTemplateTitle(content) {
    const basename = text(cornellFile?.basename).toLowerCase();
    const headings = Array.from(content.querySelectorAll("h1"));
    for (const heading of headings) {
      const value = text(heading.textContent).toLowerCase();
      if (!basename || value === basename || value.includes(basename)) heading.classList.add("cv-cornell-template-title");
    }
    const centered = Array.from(content.querySelectorAll('p[align="center"]'));
    for (const paragraph of centered) {
      const value = text(paragraph.textContent).toLowerCase();
      if (!basename || value === basename || value.includes(basename)) paragraph.classList.add("cv-cornell-template-title");
    }
  }

  function markerInfo(raw) {
    let value = text(raw).replace(/;;\s*$/, "").trim();
    let symbol = "·";
    if (/^[EVXR]-/.test(value)) {
      symbol = value.charAt(0);
      value = value.slice(2).trim();
    } else if (/^[!?.*]/.test(value)) {
      symbol = value.charAt(0);
      value = value.slice(1).trim();
    }

    const key = value.toLowerCase();
    let kind = "note";
    if (key.includes("session metadata")) kind = "meta";
    else if (key.includes("learning goals")) kind = "goals";
    else if (key.includes("guiding question")) kind = "cue";
    else if (key.includes("key concept")) kind = "concept";
    else if (key.includes("example")) kind = "example";
    else if (key.includes("verified")) kind = "verified";
    else if (key.includes("common mistake")) kind = "mistake";
    else if (key.includes("related")) kind = "related";
    else if (key.includes("feynman summary")) kind = "summary";
    else if (key.includes("self-test")) kind = "recall";
    else if (key.includes("review schedule")) kind = "review";

    return { symbol, label: value || "Cornell note", kind };
  }

  function appendInline(parent, source) {
    const pattern = /(\*\*[^*]+\*\*|\[\[[^\]]*\]\]|`[^`]+`)/g;
    let cursor = 0;
    let match;
    while ((match = pattern.exec(source)) !== null) {
      if (match.index > cursor) parent.append(cornellDocument.createTextNode(source.slice(cursor, match.index)));
      const token = match[0];
      if (token.startsWith("**")) {
        const strong = cornellDocument.createElement("strong");
        strong.textContent = token.slice(2, -2);
        parent.appendChild(strong);
      } else if (token.startsWith("[[")) {
        const inner = token.slice(2, -2).trim();
        const [targetRaw, aliasRaw] = inner.split("|");
        const target = text(targetRaw);
        if (target) {
          const link = cornellDocument.createElement("a");
          link.className = "internal-link";
          link.setAttribute("data-href", target);
          link.setAttribute("href", target);
          link.textContent = text(aliasRaw) || target;
          parent.appendChild(link);
        } else {
          const placeholder = cornellDocument.createElement("span");
          placeholder.className = "cv-cornell-empty-link";
          placeholder.textContent = "Related note";
          parent.appendChild(placeholder);
        }
      } else {
        const code = cornellDocument.createElement("code");
        code.textContent = token.slice(1, -1);
        parent.appendChild(code);
      }
      cursor = match.index + token.length;
    }
    if (cursor < source.length) parent.append(cornellDocument.createTextNode(source.slice(cursor)));
  }

  function renderCornellBody(lines) {
    const body = cornellDocument.createElement("div");
    body.className = "cv-cornell-row-body";
    let list = null;
    let paragraphLines = [];

    const flushParagraph = () => {
      if (!paragraphLines.length) return;
      const paragraph = cornellDocument.createElement("p");
      appendInline(paragraph, paragraphLines.join(" "));
      body.appendChild(paragraph);
      paragraphLines = [];
    };

    const flushList = () => { list = null; };

    for (const rawLine of lines) {
      const line = rawLine.replace(/\s+$/, "");
      if (!line.trim()) {
        flushParagraph();
        flushList();
        continue;
      }

      const bullet = line.match(/^\s*-\s+(.*)$/);
      if (bullet) {
        flushParagraph();
        if (!list) {
          list = cornellDocument.createElement("ul");
          body.appendChild(list);
        }
        const item = cornellDocument.createElement("li");
        const task = bullet[1].match(/^\[([ xX])\]\s*(.*)$/);
        if (task) {
          item.classList.add("cv-cornell-task");
          const checkbox = cornellDocument.createElement("input");
          checkbox.type = "checkbox";
          checkbox.disabled = true;
          checkbox.checked = task[1].toLowerCase() === "x";
          item.appendChild(checkbox);
          const label = cornellDocument.createElement("span");
          appendInline(label, task[2]);
          item.appendChild(label);
        } else {
          appendInline(item, bullet[1]);
        }
        list.appendChild(item);
        continue;
      }

      flushList();
      paragraphLines.push(line.trim());
    }

    flushParagraph();
    return body;
  }

  function parseCornellCode(code) {
    const lines = String(code.textContent || "").replace(/\r/g, "").split("\n");
    const markerIndex = lines.findIndex(line => /^\s*%%>\s*.+?\s*%%\s*$/.test(line));
    if (markerIndex < 0) return null;
    const markerMatch = lines[markerIndex].match(/^\s*%%>\s*(.+?)\s*%%\s*$/);
    if (!markerMatch) return null;
    return { info: markerInfo(markerMatch[1]), lines: lines.slice(markerIndex + 1) };
  }

  function blockCarrier(node) {
    const parent = node?.parentElement;
    if (parent && Array.from(parent.classList || []).some(name => /^el-(?:pre|h[1-6]|p|hr)$/.test(name))) return parent;
    return node;
  }

  function headingFromBlock(node) {
    if (node?.matches?.("h2, h3")) return node;
    return node?.querySelector?.(":scope > h2, :scope > h3") || null;
  }

  function nearestHeadingBefore(node) {
    let cursor = blockCarrier(node)?.previousElementSibling;
    for (let steps = 0; cursor && steps < 4; steps += 1, cursor = cursor.previousElementSibling) {
      const heading = headingFromBlock(cursor);
      if (heading) return heading;
      if (!cursor.matches?.("hr, br, .el-hr")) break;
    }
    return null;
  }

  function transformCornellFence(code) {
    const pre = code.closest("pre");
    if (!pre || pre.dataset.cornellProcessed === "true") return false;
    const parsed = parseCornellCode(code);
    if (!parsed) return false;

    const row = cornellDocument.createElement("section");
    row.className = "cv-cornell-row";
    row.dataset.cornellKind = parsed.info.kind;

    const cue = cornellDocument.createElement("aside");
    cue.className = "cv-cornell-row-cue";
    cue.dataset.cornellSymbol = parsed.info.symbol;
    const label = cornellDocument.createElement("span");
    label.className = "cv-cornell-row-label";
    label.textContent = parsed.info.label;
    cue.append(label);

    const reveal = cornellDocument.createElement("button");
    reveal.type = "button";
    reveal.className = "cv-cornell-reveal";
    reveal.textContent = "Reveal";
    reveal.setAttribute("aria-expanded", "false");
    reveal.addEventListener("click", event => {
      event.preventDefault();
      event.stopPropagation();
      const revealed = row.classList.toggle("is-revealed");
      reveal.textContent = revealed ? "Hide" : "Reveal";
      reveal.setAttribute("aria-expanded", String(revealed));
    });
    cue.append(reveal);

    row.append(cue, renderCornellBody(parsed.lines));
    pre.dataset.cornellProcessed = "true";
    const carrier = blockCarrier(pre);
    if (carrier && carrier !== pre) carrier.classList.add("cv-cornell-row-wrap");
    const heading = nearestHeadingBefore(pre);
    if (heading) heading.classList.add("cv-cornell-section-heading");
    pre.replaceWith(row);
    return true;
  }

  function decorateLegacyCallouts(content) {
    const contextCallout = content.querySelector('.callout[data-callout="info"]');
    if (contextCallout) contextCallout.classList.add("cv-cornell-context-callout");
    const summaryCallout = content.querySelector('.callout[data-callout="summary"]');
    if (summaryCallout) summaryCallout.classList.add("cv-cornell-summary-callout");
    return Boolean(contextCallout || summaryCallout);
  }

  function decorateContent() {
    const content = q('[data-role="cornell-content"]');
    if (!content) return false;

    markTemplateTitle(content);
    let changed = false;
    const fences = Array.from(content.querySelectorAll("pre > code")).filter(code =>
      code.classList.contains("language-cornell")
      || Array.from(code.classList).some(name => name.includes("language-cornell"))
      || /^\s*%%>\s*.+?%%/m.test(String(code.textContent || ""))
    );
    for (const code of fences) changed = transformCornellFence(code) || changed;
    changed = decorateLegacyCallouts(content) || changed;

    if (content.querySelector(".cm-editor")) cornellRoot.classList.add("is-cornell-editing");
    else cornellRoot.classList.remove("is-cornell-editing");
    return changed;
  }

  function installDecorator() {
    const content = q('[data-role="cornell-content"]');
    if (!content) return;
    decorateContent();

    const Observer = cornellWindow?.MutationObserver;
    if (typeof Observer !== "function") return;
    let queued = false;
    const schedule = cornellWindow.requestAnimationFrame || (callback => cornellWindow.setTimeout(callback, 16));
    const observer = new Observer(() => {
      if (queued) return;
      queued = true;
      schedule(() => {
        queued = false;
        decorateContent();
      });
    });
    observer.observe(content, { childList: true, subtree: true });
  }

  function resetReveals() {
    for (const row of cornellRoot.querySelectorAll(".cv-cornell-row.is-revealed")) row.classList.remove("is-revealed");
    for (const reveal of cornellRoot.querySelectorAll(".cv-cornell-reveal")) {
      reveal.textContent = "Reveal";
      reveal.setAttribute("aria-expanded", "false");
    }
  }

  function bindStudyMode() {
    const button = q('[data-action="cornell-study"]');
    if (!button) return;
    button.addEventListener("click", event => {
      event.preventDefault();
      event.stopPropagation();
      const active = cornellRoot.classList.toggle("is-study-mode");
      resetReveals();
      button.setAttribute("aria-pressed", String(active));
      setText("cornell-study-label", active ? "Exit study mode" : "Study mode", "Study mode");
    });
  }

  let openingEditor = false;

  async function enterEditingMode() {
    if (cornellRoot.classList.contains("is-study-mode") || openingEditor) return;

    const leaves = typeof cornellApp?.workspace?.getLeavesOfType === "function"
      ? cornellApp.workspace.getLeavesOfType("markdown")
      : [];
    const leaf = leaves.find(candidate =>
      candidate?.view?.file?.path === cornellFile?.path &&
      candidate.view.contentEl?.contains(cornellContainer)
    );

    if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
      console.warn("[custom-view:cornell] Could not resolve the markdown leaf for source editing");
      return;
    }

    const viewState = leaf.getViewState();
    if (viewState?.state?.mode === "source" && viewState?.state?.source === true) {
      leaf.view?.editor?.focus?.();
      return;
    }

    // CV_CORNELL_TRUE_SOURCE_EDIT_V9
    // Custom Views 0.3.2 restores the native Markdown editor when source=true.
    // This deliberately avoids its editable-placeholder/CM6 reparenting path,
    // which conflicts with Cornell's rendered fenced-code transformation.
    openingEditor = true;
    cornellRoot.classList.add("is-opening-editor");
    try {
      await leaf.setViewState({
        ...viewState,
        active: true,
        state: {
          ...(viewState.state || {}),
          mode: "source",
          source: true,
        },
      });
      const focusEditor = () => leaf.view?.editor?.focus?.();
      cornellWindow.setTimeout?.(focusEditor, 0);
      cornellWindow.setTimeout?.(focusEditor, 100);
    } catch (error) {
      openingEditor = false;
      cornellRoot.classList.remove("is-opening-editor");
      console.error("[custom-view:cornell] Could not switch note to Source Mode", error);
    }
  }

  function bindClickToEdit() {
    const content = q('[data-role="cornell-content"]');
    if (!content) return;

    content.setAttribute('tabindex', '0');
    content.addEventListener('click', event => {
      if (cornellRoot.classList.contains('is-study-mode')) return;
      if (event.target?.closest?.('a, button, input, textarea, select, label, [contenteditable="true"]')) return;
      if (!event.target?.closest?.('.cv-cornell-row, .cv-cornell-section-heading')) return;
      void enterEditingMode();
    });
    content.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== 'F2') return;
      if (cornellRoot.classList.contains('is-study-mode')) return;
      event.preventDefault();
      void enterEditingMode();
    });
  }

  renderHeader();
  bindMetadataCycles();
  installDecorator();
  bindStudyMode();
  bindClickToEdit();
}

views.css:
/* Clipping Source Dossier — editorial reader + research rail. */
.obsidian-custom-view-render:has(> .cv-clipping) {
  padding: 0 !important;
  background: var(--background-primary) !important;
}

.cv-clipping {
  --cvl-bg: var(--background-primary);
  --cvl-surface: var(--background-secondary);
  --cvl-text: var(--text-normal);
  --cvl-muted: var(--text-muted);
  --cvl-faint: var(--text-faint);
  --cvl-accent: var(--interactive-accent);
  --cvl-accent-text: var(--text-accent);
  --cvl-border: var(--background-modifier-border);
  --cvl-border-strong: var(--background-modifier-border-hover, var(--background-modifier-border));
  --cvl-pad: clamp(18px, 3.8cqi, 56px);
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: clip;
  container-type: inline-size;
  background: var(--cvl-bg);
  color: var(--cvl-text);
  font-family: var(--font-interface);
}

.cv-clipping *,
.cv-clipping *::before,
.cv-clipping *::after {
  box-sizing: border-box;
}

.cv-clipping-progress {
  position: sticky;
  top: 0;
  z-index: 30;
  width: 100%;
  height: 2px;
  overflow: hidden;
  pointer-events: none;
}

.cv-clipping-progress > span {
  display: block;
  width: 100%;
  height: 100%;
  transform: scaleX(0);
  transform-origin: left center;
  background: var(--cvl-accent);
  transition: transform 90ms linear;
}

.cv-clipping-header {
  width: min(100%, 1420px);
  margin: 0 auto;
  padding: clamp(28px, 4.6cqi, 66px) var(--cvl-pad) clamp(28px, 4cqi, 54px);
  border-bottom: 1px solid var(--cvl-border);
}

.cv-clipping-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: clamp(22px, 3cqi, 38px);
}

.cv-clipping-eyebrow,
.cv-clipping-status,
.cv-clipping-section-label,
.cv-clipping-rail-section > h2,
.cv-clipping-source-meta dt,
.cv-clipping-footer {
  font-family: var(--font-monospace);
  text-transform: uppercase;
  letter-spacing: .13em;
  font-weight: 720;
}

.cv-clipping-eyebrow {
  color: var(--cvl-accent-text);
  font-size: .69rem;
}

.cv-clipping-status {
  min-height: 28px;
  margin: 0;
  padding: 4px 0 3px;
  border: 0;
  border-bottom: 1px solid transparent;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cvl-accent-text);
  cursor: pointer;
  font-size: .64rem;
  line-height: 1;
}

.cv-clipping-status:hover,
.cv-clipping-status:focus-visible {
  border-bottom-color: color-mix(in srgb, var(--cvl-accent) 62%, var(--cvl-border));
  background: transparent;
  color: var(--cvl-text);
}

.cv-clipping-status:focus-visible,
.cv-clipping-source-link:focus-visible,
.cv-clipping-outline button:focus-visible,
.cv-clipping-content:focus-visible,
.cv-clipping-notes-host:focus-visible {
  outline: 2px solid var(--cvl-accent);
  outline-offset: 3px;
}

.cv-clipping-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 340px);
  align-items: end;
  gap: clamp(28px, 5cqi, 72px);
}

.cv-clipping-identity {
  min-width: 0;
}

.cv-clipping-title {
  max-width: 24ch;
  margin: 0;
  color: var(--cvl-text);
  font-family: var(--font-text);
  font-size: clamp(2.2rem, 5.1cqi, 5rem);
  font-weight: 760;
  line-height: .98;
  letter-spacing: -.045em;
  text-wrap: balance;
  overflow-wrap: break-word;
}

.cv-clipping-title.is-long {
  max-width: 29ch;
  font-size: clamp(1.9rem, 4.2cqi, 4rem);
}

.cv-clipping-title.is-very-long {
  max-width: 34ch;
  font-size: clamp(1.65rem, 3.5cqi, 3.25rem);
}

.cv-clipping-byline {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  margin: clamp(15px, 2cqi, 22px) 0 0;
  color: var(--cvl-muted);
  font-size: .82rem;
  line-height: 1.5;
}

.cv-clipping-byline-date {
  display: inline-flex;
  gap: 8px;
}

.cv-clipping-description {
  max-width: 72ch;
  margin: 14px 0 0;
  color: var(--cvl-muted);
  font-family: var(--font-text);
  font-size: clamp(.96rem, 1.35cqi, 1.08rem);
  line-height: 1.62;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.cv-clipping-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 11px 18px;
  margin-top: clamp(18px, 2.6cqi, 28px);
}

.cv-clipping-source-link {
  padding-bottom: 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--cvl-accent) 48%, var(--cvl-border));
  color: var(--cvl-accent-text);
  font-family: var(--font-monospace);
  font-size: .66rem;
  font-weight: 720;
  letter-spacing: .07em;
  text-decoration: none;
  text-transform: uppercase;
}

.cv-clipping-source-link:hover {
  border-bottom-color: var(--cvl-accent);
  color: var(--cvl-text);
  text-decoration: none;
}

.cv-clipping-reading-stat {
  color: var(--cvl-faint);
  font-family: var(--font-monospace);
  font-size: .63rem;
  font-weight: 650;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.cv-clipping-image-shell {
  position: relative;
  aspect-ratio: 16 / 10;
  width: 100%;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--cvl-border-strong);
  border-radius: 3px;
  background: var(--cvl-surface);
}

.cv-clipping-image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cv-clipping-workspace {
  width: min(calc(100% - (2 * var(--cvl-pad))), 1340px);
  margin: clamp(30px, 4.7cqi, 66px) auto 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 30%);
  align-items: start;
  gap: clamp(34px, 5cqi, 68px);
}

.cv-clipping-reader,
.cv-clipping-rail,
.cv-clipping-content,
.cv-clipping-notes-host,
.cv-clipping-highlights-host {
  min-width: 0;
}

.cv-clipping-reader {
  padding-top: 13px;
  border-top: 1px solid var(--cvl-border-strong);
}

.cv-clipping-section-label {
  margin-bottom: clamp(20px, 3cqi, 34px);
  color: var(--cvl-faint);
  font-size: .6rem;
}

.cv-clipping-content {
  width: 100%;
  max-width: 78ch;
  margin-right: auto;
  color: var(--cvl-text);
  cursor: text;
  font-family: var(--font-text);
  font-size: clamp(.98rem, 1.25cqi, 1.07rem);
  line-height: 1.78;
  overflow-wrap: anywhere;
}

.cv-clipping-content > .markdown-rendered-content,
.cv-clipping-content > .markdown-preview-view,
.cv-clipping-content > .markdown-rendered,
.cv-clipping-content > .markdown-rendered-content > .markdown-preview-sizer,
.cv-clipping-content > .markdown-preview-view > .markdown-preview-sizer,
.cv-clipping-content > .markdown-rendered > .markdown-preview-sizer,
.cv-clipping-content > .markdown-rendered-content > .markdown-preview-section,
.cv-clipping-content > .markdown-preview-view > .markdown-preview-section,
.cv-clipping-content > .markdown-rendered > .markdown-preview-section {
  width: 100% !important;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cv-clipping-content .cv-clipping-marker,
.cv-clipping-content .cv-clipping-duplicate-title {
  display: none !important;
}

.cv-clipping-content h1,
.cv-clipping-content h2,
.cv-clipping-content h3,
.cv-clipping-content h4 {
  scroll-margin-top: 26px;
  color: var(--cvl-text);
  text-wrap: balance;
}

.cv-clipping-content h1 {
  margin: 2.2em 0 .7em;
  font-size: clamp(1.7rem, 3cqi, 2.65rem);
  line-height: 1.08;
}

.cv-clipping-content h2 {
  margin: 2.25em 0 .72em;
  padding-top: .45em;
  border-top: 1px solid color-mix(in srgb, var(--cvl-border) 70%, transparent);
  font-size: clamp(1.35rem, 2.25cqi, 1.9rem);
  line-height: 1.16;
}

.cv-clipping-content h3 {
  margin: 1.9em 0 .65em;
  font-size: clamp(1.13rem, 1.65cqi, 1.4rem);
  line-height: 1.25;
}

.cv-clipping-content p,
.cv-clipping-content ul,
.cv-clipping-content ol,
.cv-clipping-content blockquote {
  margin-top: 0;
  margin-bottom: 1.2em;
}

.cv-clipping-content blockquote {
  padding: .1em 0 .1em 1.2em;
  border-left: 3px solid color-mix(in srgb, var(--cvl-accent) 54%, var(--cvl-border));
  color: var(--cvl-muted);
}

.cv-clipping-content img {
  max-width: min(100%, 980px);
  height: auto;
  border-radius: 3px;
}

.cv-clipping-content table {
  width: 100%;
  overflow-x: auto;
}

.cv-clipping-rail {
  position: sticky;
  top: 24px;
  display: grid;
  gap: 0;
  align-self: start;
}

.cv-clipping-rail-section {
  padding: 16px 0 clamp(22px, 3.2cqi, 34px);
  border-top: 1px solid var(--cvl-border-strong);
}

.cv-clipping-rail-section > h2 {
  margin: 0 0 14px;
  color: var(--cvl-faint);
  font-size: .6rem;
  line-height: 1.3;
}

.cv-clipping-notes-host {
  min-height: 34px;
  color: var(--cvl-text);
  cursor: text;
  font-family: var(--font-text);
  font-size: .9rem;
  line-height: 1.58;
}

.cv-clipping-notes-host > :first-child,
.cv-clipping-highlights-host > :first-child {
  margin-top: 0 !important;
}

.cv-clipping-notes-host > :last-child,
.cv-clipping-highlights-host > :last-child {
  margin-bottom: 0 !important;
}

.cv-clipping-empty {
  margin: 0;
  color: var(--cvl-faint);
  font-family: var(--font-interface);
  font-size: .78rem;
  line-height: 1.45;
}

.cv-clipping-highlights-host {
  display: grid;
  gap: 12px;
  color: var(--cvl-muted);
  font-family: var(--font-text);
  font-size: .84rem;
  line-height: 1.55;
}

.cv-clipping-highlights-host blockquote,
.cv-clipping-highlights-host > ul > li,
.cv-clipping-highlights-host > ol > li,
.cv-clipping-highlights-host > p {
  margin: 0;
  padding: 2px 0 2px 13px;
  border: 0;
  border-left: 2px solid color-mix(in srgb, var(--cvl-accent) 54%, var(--cvl-border));
  background: transparent;
  color: var(--cvl-muted);
}

.cv-clipping-highlights-host ul,
.cv-clipping-highlights-host ol {
  display: grid;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.cv-clipping-outline {
  display: grid;
  gap: 3px;
}

.cv-clipping-outline button {
  width: 100%;
  min-height: 30px;
  margin: 0;
  padding: 5px 0;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--cvl-muted);
  cursor: pointer;
  font: 600 .76rem/1.38 var(--font-interface);
  text-align: left;
}

.cv-clipping-outline button[data-outline-level="3"] {
  padding-left: 12px;
  font-size: .72rem;
}

.cv-clipping-outline button:hover,
.cv-clipping-outline button.is-active {
  background: transparent;
  color: var(--cvl-text);
}

.cv-clipping-outline button.is-active .cv-clipping-outline-index {
  color: var(--cvl-accent-text);
}

.cv-clipping-outline-index {
  color: var(--cvl-faint);
  font-family: var(--font-monospace);
  font-size: .61rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: .05em;
}

.cv-clipping-source-meta {
  margin: 0;
  display: grid;
  gap: 11px;
}

.cv-clipping-source-meta div {
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr);
  gap: 12px;
}

.cv-clipping-source-meta dt,
.cv-clipping-source-meta dd {
  min-width: 0;
  margin: 0;
}

.cv-clipping-source-meta dt {
  color: var(--cvl-faint);
  font-size: .55rem;
}

.cv-clipping-source-meta dd {
  color: var(--cvl-muted);
  font-size: .76rem;
  font-weight: 620;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.cv-clipping-footer {
  width: min(calc(100% - (2 * var(--cvl-pad))), 1340px);
  margin: 0 auto;
  padding: 18px 0 clamp(42px, 6cqi, 78px);
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  color: var(--cvl-faint);
  font-size: .56rem;
}

.cv-clipping-footer a {
  color: var(--cvl-muted);
  text-decoration: none;
}

.cv-clipping-footer a:hover {
  color: var(--cvl-accent-text);
  text-decoration: none;
}

@container (max-width: 980px) {
  .cv-clipping-hero {
    grid-template-columns: minmax(0, 1fr) minmax(200px, 270px);
    gap: 32px;
  }

  .cv-clipping-workspace {
    grid-template-columns: minmax(0, 1fr) minmax(230px, 31%);
    gap: 38px;
  }
}

@container (max-width: 760px) {
  .cv-clipping-hero {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .cv-clipping-image-shell {
    max-width: 520px;
  }

  .cv-clipping-workspace {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .cv-clipping-rail {
    position: static;
    display: contents;
  }

  .cv-clipping-notes-section { order: 0; }
  .cv-clipping-highlights-section { order: 1; }
  .cv-clipping-reader { order: 2; width: 100%; margin-top: 14px; }
  .cv-clipping-outline-section { order: 3; width: 100%; margin-top: 34px; }
  .cv-clipping-source-section { order: 4; width: 100%; }

  .cv-clipping-rail-section {
    width: 100%;
  }

  .cv-clipping-content {
    max-width: none;
  }
}

@container (max-width: 500px) {
  .cv-clipping-header {
    padding-inline: 18px;
  }

  .cv-clipping-workspace,
  .cv-clipping-footer {
    width: calc(100% - 36px);
  }

  .cv-clipping-title,
  .cv-clipping-title.is-long,
  .cv-clipping-title.is-very-long {
    max-width: 100%;
    font-size: clamp(1.8rem, 9cqi, 2.8rem);
  }

  .cv-clipping-image-shell {
    display: none !important;
  }

  .cv-clipping-source-meta div {
    grid-template-columns: 72px minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cv-clipping-progress > span {
    transition: none;
  }
}

