const clippingContext = tp;
const clippingContainer = clippingContext.container || this;
const clippingRoot = clippingContainer.querySelector(".cv-clipping");

if (clippingRoot) {
  const clippingApp = clippingContext.app;
  const clippingFile = clippingContext.file;
  const clippingFrontmatter = clippingContext.frontmatter || {};
  const clippingDocument = clippingContext.activeDocument || clippingContainer.ownerDocument;
  const clippingWindow = clippingContext.activeWindow || clippingDocument.defaultView;
  const q = selector => clippingRoot.querySelector(selector);

  const text = value => String(value ?? "").trim();
  const asArray = value => Array.isArray(value) ? value : value === null || value === undefined || value === "" ? [] : [value];
  const scalarText = value => {
    const first = asArray(value)[0];
    if (first === null || first === undefined) return "";
    if (typeof first === "object") return text(first.path ?? first.link ?? first.value ?? first.display ?? "");
    return text(first);
  };
  const numberValue = value => {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    const parsed = Number(text(value).replaceAll(",", ""));
    return Number.isFinite(parsed) ? parsed : NaN;
  };

  const STATUS_VALUES = ["inbox", "reading", "processed"];
  let currentStatus = (() => {
    const raw = text(clippingFrontmatter.status).toLowerCase();
    if (["read", "reading", "in progress"].includes(raw)) return "reading";
    if (["processed", "done", "complete", "completed"].includes(raw)) return "processed";
    return "inbox";
  })();

  let outlineObserver = null;
  let openingEditor = false;

  function setText(role, value, fallback = "—") {
    const element = q(`[data-role="${role}"]`);
    if (element) element.textContent = text(value) || fallback;
  }

  function formatDate(value) {
    const raw = scalarText(value);
    if (!raw) return "";
    const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
    const parsed = iso
      ? new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]))
      : new Date(raw);
    if (Number.isNaN(parsed.getTime())) return raw;
    try {
      return new Intl.DateTimeFormat(undefined, { day: "2-digit", month: "short", year: "numeric" }).format(parsed);
    } catch {
      return raw;
    }
  }

  function safeHttpUrl(value) {
    let raw = scalarText(value);
    if (!raw) return "";
    if (/^www\./i.test(raw)) raw = `https://${raw}`;
    if (!/^https?:\/\//i.test(raw)) return "";
    try {
      return new URL(raw).href;
    } catch {
      return "";
    }
  }

  function domainFromUrl(value) {
    const url = safeHttpUrl(value);
    if (!url) return "";
    try {
      return new URL(url).hostname.replace(/^www\./i, "");
    } catch {
      return "";
    }
  }

  function localImagePath(value) {
    let raw = scalarText(value);
    if (!raw) return "";
    if (/^(?:https?:|data:|blob:|app:)/i.test(raw)) return raw;

    const markdownImage = raw.match(/^!\[[^\]]*\]\((.+?)\)$/);
    if (markdownImage) {
      raw = markdownImage[1].trim().replace(/^<|>$/g, "");
      if (/^https?:/i.test(raw)) return raw;
    }

    const wiki = raw.match(/^!?\[\[([^\]|]+)(?:\|[^\]]+)?\]\]$/);
    const candidate = text(wiki ? wiki[1] : raw);
    if (!candidate || !clippingApp?.metadataCache || !clippingFile) return "";

    const target = clippingApp.metadataCache.getFirstLinkpathDest(candidate, clippingFile.path);
    if (target) return clippingApp.vault.getResourcePath(target);

    if (typeof clippingApp.vault.getFileByPath === "function") {
      const direct = clippingApp.vault.getFileByPath(candidate);
      if (direct) return clippingApp.vault.getResourcePath(direct);
      const parentPath = clippingFile.parent?.path || "";
      const relative = parentPath ? `${parentPath}/${candidate}` : candidate;
      const sibling = clippingApp.vault.getFileByPath(relative);
      if (sibling) return clippingApp.vault.getResourcePath(sibling);
    }

    return "";
  }

  function statusLabel(value) {
    return value.charAt(0).toUpperCase() + value.slice(1);
  }

  function renderStatus() {
    clippingRoot.dataset.clippingStatus = currentStatus;
    setText("clipping-status", statusLabel(currentStatus), "Inbox");
  }

  async function writeFrontmatterField(field, value) {
    const processFrontMatter = clippingApp?.fileManager?.processFrontMatter;
    if (!clippingFile || typeof processFrontMatter !== "function") return false;
    try {
      await processFrontMatter.call(clippingApp.fileManager, clippingFile, frontmatter => {
        frontmatter[field] = value;
      });
      clippingFrontmatter[field] = value;
      return true;
    } catch (error) {
      console.error(`[custom-view:clipping] Could not update ${field}`, error);
      return false;
    }
  }

  function bindStatusCycle() {
    const button = q('[data-role="clipping-status"]');
    if (!button || button.dataset.clippingBound === "true") return;
    button.dataset.clippingBound = "true";
    button.addEventListener("click", async event => {
      event.preventDefault();
      event.stopPropagation();
      const index = STATUS_VALUES.indexOf(currentStatus);
      const next = STATUS_VALUES[(index + 1) % STATUS_VALUES.length];
      if (await writeFrontmatterField("status", next)) {
        currentStatus = next;
        renderStatus();
      }
    });
  }

  function setMetaRow(name, value) {
    const row = clippingRoot.querySelector(`[data-meta-row="${name}"]`);
    const target = row?.querySelector("dd");
    const clean = text(value);
    if (!row || !target) return false;
    row.hidden = !clean;
    if (clean) target.textContent = clean;
    return Boolean(clean);
  }

  function renderImage(title) {
    const shell = q('[data-role="clipping-image-shell"]');
    const image = q('[data-role="clipping-image"]');
    if (!shell || !image) return;
    const source = localImagePath(clippingFrontmatter.image);
    if (!source) {
      shell.hidden = true;
      image.removeAttribute("src");
      return;
    }

    shell.hidden = false;
    image.alt = title ? `Preview image for ${title}` : "Clipping preview image";
    image.onload = () => { shell.hidden = false; };
    image.onerror = () => {
      shell.hidden = true;
      image.removeAttribute("src");
    };
    image.src = source;
  }

  function renderHeader() {
    const title = scalarText(clippingFrontmatter.title) || text(clippingFile?.basename) || "Untitled clipping";
    const author = scalarText(clippingFrontmatter.author);
    const sourceRaw = scalarText(clippingFrontmatter.source) || scalarText(clippingFrontmatter.url);
    const sourceUrl = safeHttpUrl(sourceRaw);
    const site = scalarText(clippingFrontmatter.site)
      || scalarText(clippingFrontmatter.domain)
      || domainFromUrl(sourceRaw);
    const published = formatDate(clippingFrontmatter.published);
    const captured = formatDate(clippingFrontmatter.captured);
    const description = scalarText(clippingFrontmatter.description);
    const language = scalarText(clippingFrontmatter.language);
    const words = numberValue(clippingFrontmatter.words);

    setText("clipping-title", title, "Untitled clipping");
    const titleElement = q('[data-role="clipping-title"]');
    if (titleElement) {
      titleElement.classList.toggle("is-long", title.length > 48 && title.length <= 78);
      titleElement.classList.toggle("is-very-long", title.length > 78);
      titleElement.removeAttribute("title");
    }

    setText("clipping-author", author, "Unknown author");
    setText("clipping-site", site, "Unknown source");
    const publishedWrap = q('[data-role="clipping-published-wrap"]');
    if (publishedWrap) publishedWrap.hidden = !published;
    if (published) setText("clipping-published", published);

    const descriptionElement = q('[data-role="clipping-description"]');
    if (descriptionElement) {
      descriptionElement.hidden = !description;
      descriptionElement.textContent = description;
    }

    const sourceLink = q('[data-role="clipping-source-link"]');
    if (sourceLink) {
      sourceLink.hidden = !sourceUrl;
      if (sourceUrl) sourceLink.href = sourceUrl;
      else sourceLink.removeAttribute("href");
    }

    renderImage(title);
    renderStatus();

    const visibleMeta = [
      setMetaRow("author", author),
      setMetaRow("published", published),
      setMetaRow("site", site),
      setMetaRow("language", language),
      setMetaRow("captured", captured),
      setMetaRow("words", Number.isFinite(words) && words > 0 ? Math.round(words).toLocaleString() : ""),
    ].some(Boolean);
    const sourceSection = q('[data-role="clipping-source-section"]');
    if (sourceSection) sourceSection.hidden = !visibleMeta;

    const footer = q('[data-role="clipping-footer"]');
    const footerSource = q('[data-role="clipping-footer-source"]');
    if (footer && footerSource) {
      footer.hidden = !sourceUrl;
      if (sourceUrl) {
        footerSource.href = sourceUrl;
        footerSource.textContent = site || domainFromUrl(sourceUrl) || "Original source";
      } else {
        footerSource.removeAttribute("href");
        footerSource.textContent = "";
      }
    }
  }

  function markdownSurface(content) {
    const rendered = content.querySelector(":scope > .markdown-rendered-content")
      || content.querySelector(":scope > .markdown-preview-view")
      || content.querySelector(":scope > .markdown-rendered")
      || content;
    return rendered.querySelector?.(":scope > .markdown-preview-sizer, :scope > .markdown-preview-section") || rendered;
  }

  function headingFromBlock(node) {
    if (node?.matches?.("h1, h2, h3, h4")) return node;
    return node?.querySelector?.(":scope > h1, :scope > h2, :scope > h3, :scope > h4") || null;
  }

  function markerHeading(block) {
    const heading = headingFromBlock(block);
    if (!heading || !heading.matches("h2")) return "";
    return text(heading.textContent).toLowerCase();
  }

  function hasMeaningfulContent(nodes) {
    return nodes.some(node => {
      const value = text(node.textContent);
      if (value) return true;
      return Boolean(node.querySelector?.("img, video, audio, table, pre, li, blockquote, iframe, canvas, svg"));
    });
  }

  function markDuplicateTitle(surface) {
    const title = (scalarText(clippingFrontmatter.title) || text(clippingFile?.basename)).toLowerCase();
    if (!title) return;
    const heading = Array.from(surface.querySelectorAll("h1")).find(node => text(node.textContent).toLowerCase() === title);
    if (heading) {
      const carrier = heading.parentElement && heading.parentElement.children.length === 1 ? heading.parentElement : heading;
      carrier.classList.add("cv-clipping-duplicate-title");
    }
  }

  function moveSectionNodes(nodes, host, emptyRole = "") {
    if (!host || !hasMeaningfulContent(nodes)) return false;
    if (emptyRole) host.querySelector(`[data-role="${emptyRole}"]`)?.remove();
    host.replaceChildren(...nodes);
    return true;
  }

  function structureSections(surface) {
    const children = Array.from(surface.children);
    const articleIndex = children.findIndex(block => markerHeading(block) === "article");
    if (articleIndex < 0) return false;

    const highlightsIndex = children.findIndex((block, index) => index < articleIndex && markerHeading(block) === "highlights");
    let notesIndex = -1;
    for (let index = children.length - 1; index > articleIndex; index -= 1) {
      if (markerHeading(children[index]) === "notes") {
        notesIndex = index;
        break;
      }
    }

    const articleMarker = children[articleIndex];
    articleMarker.classList.add("cv-clipping-marker");

    const highlightsHost = q('[data-role="clipping-highlights-host"]');
    const highlightsSection = q('[data-role="clipping-highlights-section"]');
    if (highlightsIndex >= 0) {
      const highlightMarker = children[highlightsIndex];
      highlightMarker.classList.add("cv-clipping-marker");
      const highlightNodes = children.slice(highlightsIndex + 1, articleIndex);
      const hasHighlights = moveSectionNodes(highlightNodes, highlightsHost);
      if (highlightsSection) highlightsSection.hidden = !hasHighlights;
    } else if (highlightsSection) {
      highlightsSection.hidden = true;
    }

    const notesHost = q('[data-role="clipping-notes-host"]');
    if (notesIndex > articleIndex) {
      const notesMarker = children[notesIndex];
      notesMarker.classList.add("cv-clipping-marker");
      const noteNodes = children.slice(notesIndex + 1);
      moveSectionNodes(noteNodes, notesHost, "clipping-notes-empty");
    }

    return true;
  }

  function outlineCandidates(surface) {
    const title = (scalarText(clippingFrontmatter.title) || text(clippingFile?.basename)).toLowerCase();
    return Array.from(surface.querySelectorAll("h1, h2, h3"))
      .filter(heading => !heading.closest(".cv-clipping-marker, .cv-clipping-duplicate-title"))
      .filter(heading => text(heading.textContent))
      .filter(heading => !(heading.matches("h1") && text(heading.textContent).toLowerCase() === title))
      .slice(0, 18);
  }

  function renderOutline(surface) {
    const section = q('[data-role="clipping-outline-section"]');
    const host = q('[data-role="clipping-outline"]');
    if (!section || !host) return;

    const headings = outlineCandidates(surface);
    section.hidden = headings.length < 2;
    host.replaceChildren();
    outlineObserver?.disconnect?.();
    outlineObserver = null;
    if (headings.length < 2) return;

    const buttons = [];
    headings.forEach((heading, index) => {
      const id = heading.dataset.clippingOutlineId || `clipping-section-${index + 1}`;
      heading.dataset.clippingOutlineId = id;

      const button = clippingDocument.createElement("button");
      button.type = "button";
      button.dataset.outlineLevel = heading.tagName.slice(1);

      const number = clippingDocument.createElement("span");
      number.className = "cv-clipping-outline-index";
      number.textContent = String(index + 1).padStart(2, "0");

      const label = clippingDocument.createElement("span");
      label.textContent = text(heading.textContent);
      button.append(number, label);
      button.addEventListener("click", event => {
        event.preventDefault();
        event.stopPropagation();
        for (const item of buttons) item.classList.remove("is-active");
        button.classList.add("is-active");
        const reduced = clippingWindow?.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
        heading.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "start" });
      });
      host.appendChild(button);
      buttons.push(button);
    });

    const Observer = clippingWindow?.IntersectionObserver;
    if (typeof Observer !== "function") return;
    const scrollHost = clippingContainer.closest?.(".view-content");
    outlineObserver = new Observer(entries => {
      const visible = entries
        .filter(entry => entry.isIntersecting)
        .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
      if (!visible) return;
      const index = headings.indexOf(visible.target);
      if (index < 0) return;
      for (const item of buttons) item.classList.remove("is-active");
      buttons[index]?.classList.add("is-active");
    }, {
      root: scrollHost || null,
      rootMargin: "-12% 0px -72% 0px",
      threshold: [0, 1],
    });
    headings.forEach(heading => outlineObserver.observe(heading));
  }

  function estimateWords(surface) {
    const configured = numberValue(clippingFrontmatter.words);
    if (Number.isFinite(configured) && configured > 0) return Math.round(configured);
    const value = text(surface?.textContent);
    if (!value) return 0;
    return value.split(/\s+/).filter(Boolean).length;
  }

  function renderReadingStat(surface) {
    const words = estimateWords(surface);
    const stat = q('[data-role="clipping-reading-stat"]');
    if (!stat) return;
    stat.hidden = words <= 0;
    if (words <= 0) return;
    const minutes = Math.max(1, Math.round(words / 250));
    stat.textContent = `${words.toLocaleString()} words · ~${minutes} min read`;
    const metaWords = clippingRoot.querySelector('[data-meta-row="words"]');
    const metaValue = metaWords?.querySelector("dd");
    if (metaWords && metaValue && metaWords.hidden) {
      metaWords.hidden = false;
      metaValue.textContent = words.toLocaleString();
      const sourceSection = q('[data-role="clipping-source-section"]');
      if (sourceSection) sourceSection.hidden = false;
    }
  }

  function decorateContent() {
    const content = q('[data-role="clipping-content"]');
    if (!content) return false;
    const surface = markdownSurface(content);
    if (!surface) return false;

    if (surface.dataset.clippingStructured !== "true") {
      surface.dataset.clippingStructured = "true";
      markDuplicateTitle(surface);
      structureSections(surface);
    }

    renderOutline(surface);
    renderReadingStat(surface);
    return true;
  }

  function installDecorator() {
    const content = q('[data-role="clipping-content"]');
    if (!content) return;
    decorateContent();

    const Observer = clippingWindow?.MutationObserver;
    if (typeof Observer !== "function") return;
    let queued = false;
    const schedule = clippingWindow.requestAnimationFrame || (callback => clippingWindow.setTimeout(callback, 16));
    const observer = new Observer(() => {
      if (queued || !clippingRoot.isConnected) return;
      queued = true;
      schedule(() => {
        queued = false;
        decorateContent();
      });
    });
    observer.observe(content, { childList: true, subtree: true });
  }

  function installReadingProgress() {
    const fill = q('[data-role="clipping-progress-fill"]');
    const article = clippingRoot.querySelector(".cv-clipping-reader");
    if (!fill || !article) return;
    const scrollHost = clippingContainer.closest?.(".view-content") || clippingDocument.scrollingElement;
    if (!scrollHost) return;

    const update = () => {
      if (!clippingRoot.isConnected) {
        scrollHost.removeEventListener?.("scroll", update);
        return;
      }
      const articleRect = article.getBoundingClientRect();
      const hostRect = scrollHost === clippingDocument.scrollingElement
        ? { top: 0, height: clippingWindow.innerHeight || clippingDocument.documentElement.clientHeight }
        : scrollHost.getBoundingClientRect();
      const viewportHeight = scrollHost === clippingDocument.scrollingElement
        ? hostRect.height
        : scrollHost.clientHeight;
      const distance = Math.max(1, articleRect.height - viewportHeight * .28);
      const progressed = hostRect.top - articleRect.top;
      const ratio = Math.max(0, Math.min(1, progressed / distance));
      fill.style.transform = `scaleX(${ratio})`;
    };

    scrollHost.addEventListener?.("scroll", update, { passive: true });
    clippingWindow.addEventListener?.("resize", update, { passive: true });
    update();
  }

  async function enterEditingMode() {
    if (openingEditor) return;
    const leaves = typeof clippingApp?.workspace?.getLeavesOfType === "function"
      ? clippingApp.workspace.getLeavesOfType("markdown")
      : [];
    const leaf = leaves.find(candidate =>
      candidate?.view?.file?.path === clippingFile?.path
      && candidate.view.contentEl?.contains(clippingContainer)
    );

    if (!leaf || typeof leaf.getViewState !== "function" || typeof leaf.setViewState !== "function") {
      console.warn("[custom-view:clipping] Could not resolve the markdown leaf for source editing");
      return;
    }

    const viewState = leaf.getViewState();
    if (viewState?.state?.mode === "source" && viewState?.state?.source === true) {
      leaf.view?.editor?.focus?.();
      return;
    }

    openingEditor = true;
    try {
      await leaf.setViewState({
        ...viewState,
        active: true,
        state: {
          ...(viewState.state || {}),
          mode: "source",
          source: true,
        },
      });
      const focusEditor = () => leaf.view?.editor?.focus?.();
      clippingWindow.setTimeout?.(focusEditor, 0);
      clippingWindow.setTimeout?.(focusEditor, 100);
    } catch (error) {
      openingEditor = false;
      console.error("[custom-view:clipping] Could not switch note to Source Mode", error);
    }
  }

  function bindEditableSurface(element) {
    if (!element || element.dataset.clippingEditBound === "true") return;
    element.dataset.clippingEditBound = "true";
    element.addEventListener("click", event => {
      if (event.target?.closest?.("a, button, input, textarea, select, label, [contenteditable=\"true\"]")) return;
      if (text(clippingWindow?.getSelection?.()?.toString())) return;
      void enterEditingMode();
    });
    element.addEventListener("keydown", event => {
      if (event.key !== "Enter" && event.key !== "F2") return;
      event.preventDefault();
      void enterEditingMode();
    });
  }

  function bindClickToEdit() {
    bindEditableSurface(q('[data-role="clipping-content"]'));
    bindEditableSurface(q('[data-role="clipping-notes-host"]'));
  }

  renderHeader();
  bindStatusCycle();
  installDecorator();
  installReadingProgress();
  bindClickToEdit();
}

