.obsidian-custom-view-render:has(> .cv-settings) {
  padding: 0 !important;
  background: var(--border-theme-pane, var(--background-primary)) !important;
}

.cv-settings {
  --cvs-bg: var(--border-theme-pane, var(--background-primary));
  --cvs-surface: color-mix(in srgb, var(--background-secondary) 86%, var(--background-primary) 14%);
  --cvs-surface-soft: color-mix(in srgb, var(--background-secondary-alt) 82%, var(--background-primary) 18%);
  --cvs-hover: var(--background-modifier-hover);
  --cvs-active: var(--background-modifier-active-hover);
  --cvs-border: var(--background-modifier-border);
  --cvs-border-hover: var(--background-modifier-border-hover);
  --cvs-accent: var(--interactive-accent);
  --cvs-accent-soft: color-mix(in srgb, var(--interactive-accent) 16%, transparent);
  --cvs-text: var(--text-normal);
  --cvs-muted: var(--text-muted);
  --cvs-faint: var(--text-faint);
  --cvs-error: var(--text-error);
  width: min(100%, 1280px);
  min-height: 100%;
  margin: 0 auto;
  padding: clamp(22px, 3.4cqi, 46px);
  color: var(--cvs-text);
  font-family: var(--font-interface);
  container-type: inline-size;
}

.cv-settings *,
.cv-settings *::before,
.cv-settings *::after { box-sizing: border-box; }

.cv-settings button,
.cv-settings input,
.cv-settings textarea,
.cv-settings select { font: inherit; }

.cv-settings :is(button, input, textarea, select):focus-visible {
  outline: 2px solid var(--cvs-accent);
  outline-offset: 2px;
}

.cv-settings-source { display: none !important; }

.cv-settings-hero {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: clamp(24px, 4cqi, 48px);
  padding: 0 2px 24px;
  border-bottom: 1px solid var(--cvs-border);
}

.cv-settings-heading { min-width: 0; }

.cv-settings-eyebrow,
.cv-settings-panel-kicker,
.cv-settings-key,
.cv-settings-summary,
.cv-settings-footer,
.cv-settings-panel-count,
.cv-settings-nav-count,
.cv-settings-secret-badge,
.cv-settings-control-hint,
.cv-settings-sidebar-head,
.cv-settings-sidebar-note,
.cv-settings-misc-guide,
.cv-settings-custom-form { font-family: var(--font-monospace); }

.cv-settings-eyebrow {
  display: block;
  color: var(--cvs-faint);
  font-size: .65rem;
  font-weight: 760;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.cv-settings-heading h1 {
  margin: 7px 0 0;
  font-size: clamp(2.15rem, 4.5cqi, 3.85rem);
  line-height: .98;
  letter-spacing: -.05em;
}

.cv-settings-heading p {
  max-width: 68ch;
  margin: 12px 0 0;
  color: var(--cvs-muted);
  font-size: .9rem;
  line-height: 1.55;
}

.cv-settings-summary {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(72px, auto));
  overflow: hidden;
  border: 1px solid var(--cvs-border);
  border-radius: 9px;
  background: color-mix(in srgb, var(--cvs-surface) 66%, transparent);
}

.cv-settings-summary > span {
  display: grid;
  justify-items: end;
  gap: 2px;
  min-width: 82px;
  padding: 9px 11px;
}

.cv-settings-summary > span + span { border-left: 1px solid var(--cvs-border); }
.cv-settings-summary strong { color: var(--cvs-text); font-size: .78rem; font-weight: 780; }
.cv-settings-summary small { color: var(--cvs-faint); font-size: .55rem; letter-spacing: .08em; text-transform: uppercase; }
.cv-settings-summary .is-live strong { color: var(--cvs-accent); }

.cv-settings-shell {
  display: grid;
  grid-template-columns: minmax(190px, 230px) minmax(0, 1fr);
  gap: clamp(24px, 4cqi, 50px);
  align-items: start;
  margin-top: 30px;
}

.cv-settings-sidebar { position: sticky; top: 18px; min-width: 0; }

.cv-settings-sidebar-head {
  display: grid;
  gap: 3px;
  padding: 0 11px 12px;
  color: var(--cvs-muted);
  font-size: .66rem;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.cv-settings-sidebar-head small { color: var(--cvs-faint); font-size: .55rem; letter-spacing: .04em; text-transform: none; }

.cv-settings-nav { display: grid; gap: 8px; }

.cv-settings-nav-button {
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 10px 11px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--cvs-muted);
  text-align: left;
  cursor: pointer;
}

.cv-settings-nav-button:hover {
  border-color: color-mix(in srgb, var(--cvs-border) 78%, transparent);
  background: var(--cvs-hover);
  color: var(--cvs-text);
}

.cv-settings-nav-button[aria-current="page"] {
  border-color: var(--cvs-border);
  background: var(--cvs-accent-soft);
  color: var(--cvs-text);
}

.cv-settings-nav-icon {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  color: inherit;
}

.cv-settings-nav-icon svg,
.cv-settings-add-button svg,
.cv-settings-danger-button svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.cv-settings-nav-label { overflow: hidden; font-size: .78rem; font-weight: 630; text-overflow: ellipsis; white-space: nowrap; }
.cv-settings-nav-count { color: var(--cvs-faint); font-size: .56rem; }

.cv-settings-sidebar-note {
  margin: 18px 10px 0;
  padding-top: 14px;
  border-top: 1px solid var(--cvs-border);
  color: var(--cvs-faint);
  font-size: .58rem;
  line-height: 1.55;
}

.cv-settings-sidebar-note code,
.cv-settings-sidebar-note kbd { color: var(--cvs-muted); font-family: var(--font-monospace); font-size: inherit; }

.cv-settings-panel { min-width: 0; }

.cv-settings-panel-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  min-height: 82px;
  padding: 0 2px 14px;
  border-bottom: 1px solid var(--cvs-border);
}

.cv-settings-panel-kicker { display: block; color: var(--cvs-faint); font-size: .59rem; letter-spacing: .11em; text-transform: uppercase; }
.cv-settings-panel-head h2 { margin: 5px 0 0; font-size: clamp(1.25rem, 2.3cqi, 1.7rem); line-height: 1.08; letter-spacing: -.025em; }
.cv-settings-panel-head p { max-width: 66ch; margin: 8px 0 0; color: var(--cvs-muted); font-size: .79rem; line-height: 1.5; }

.cv-settings-panel-meta {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.cv-settings-panel-count { color: var(--cvs-faint); font-size: .61rem; white-space: nowrap; }
.cv-settings-category-actions:empty { display: none; }

.cv-settings-add-button,
.cv-settings-primary-button,
.cv-settings-secondary-button,
.cv-settings-danger-button {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid var(--cvs-border);
  border-radius: 6px;
  box-shadow: none;
  cursor: pointer;
  font-size: .65rem;
  font-weight: 650;
}

.cv-settings-add-button,
.cv-settings-secondary-button { background: transparent; color: var(--cvs-muted); }
.cv-settings-add-button:hover,
.cv-settings-secondary-button:hover { background: var(--cvs-hover); color: var(--cvs-text); }
.cv-settings-primary-button { border-color: color-mix(in srgb, var(--cvs-accent) 72%, var(--cvs-border)); background: var(--cvs-accent-soft); color: var(--cvs-text); }
.cv-settings-primary-button:hover { background: color-mix(in srgb, var(--cvs-accent) 24%, transparent); }
.cv-settings-danger-button { margin-right: auto; border-color: color-mix(in srgb, var(--cvs-error) 42%, var(--cvs-border)); background: transparent; color: var(--cvs-error); }
.cv-settings-danger-button:hover { background: color-mix(in srgb, var(--cvs-error) 10%, transparent); }

.cv-settings-list { display: grid; }

.cv-settings-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(235px, .9fr) minmax(310px, 1.1fr);
  align-items: center;
  gap: clamp(22px, 3.2cqi, 42px);
  min-height: 78px;
  padding: 14px 2px;
  border-bottom: 1px solid var(--cvs-border);
}

.cv-settings-row:hover {
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--cvs-hover) 70%, transparent) 8%, color-mix(in srgb, var(--cvs-hover) 70%, transparent) 92%, transparent);
}

.cv-settings-row.is-custom-editor {
  display: block;
  padding: 16px 0;
  background: transparent;
}

.cv-settings-label { min-width: 0; padding-left: 6px; }
.cv-settings-label-main { display: flex; align-items: center; gap: 7px; min-width: 0; }
.cv-settings-label strong { min-width: 0; overflow: hidden; color: var(--cvs-text); font-size: .83rem; font-weight: 690; text-overflow: ellipsis; white-space: nowrap; }
.cv-settings-description { max-width: 58ch; margin: 4px 0 0; color: var(--cvs-muted); font-size: .69rem; line-height: 1.45; }
.cv-settings-key { display: block; margin-top: 5px; overflow: hidden; color: var(--cvs-faint); font-size: .55rem; text-overflow: ellipsis; white-space: nowrap; }

.cv-settings-secret-badge {
  flex: 0 0 auto;
  padding: 2px 5px;
  border: 1px solid color-mix(in srgb, var(--cvs-accent) 28%, var(--cvs-border) 72%);
  border-radius: 999px;
  color: var(--cvs-faint);
  font-size: .48rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.cv-settings-control { min-width: 0; display: flex; align-items: center; justify-content: flex-end; gap: 6px; }

.cv-settings-value {
  min-width: 0;
  max-width: min(100%, 560px);
  padding: 7px 8px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  box-shadow: none;
  color: var(--cvs-text);
  font-family: var(--font-monospace);
  font-size: .73rem;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: text;
}

.cv-settings-value:hover,
.cv-settings-value:focus-visible { border-color: var(--cvs-border); background: var(--cvs-hover); }
.cv-settings-value.is-empty { color: var(--cvs-faint); font-family: var(--font-interface); font-style: italic; }
.cv-settings-value.is-secret { letter-spacing: .14em; }

.cv-settings-secret-actions { display: flex; flex: 0 0 auto; align-items: center; gap: 4px; }

.cv-settings-icon-button {
  width: 30px;
  height: 30px;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--cvs-muted);
  cursor: pointer;
}

.cv-settings-icon-button svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.cv-settings-icon-button:hover,
.cv-settings-icon-button:focus-visible,
.cv-settings-icon-button[data-active="true"] { border-color: var(--cvs-border); background: var(--cvs-hover); color: var(--cvs-text); }
.cv-settings-icon-button[data-active="true"] { color: var(--cvs-accent); }
.cv-settings-icon-button:disabled { opacity: .35; cursor: default; }
.cv-settings-manage-button { margin-left: 3px; }

.cv-settings-editor {
  width: min(100%, 560px);
  min-height: 34px;
  padding: 7px 9px;
  border: 1px solid var(--cvs-border-hover);
  border-radius: 5px;
  background: var(--background-primary);
  color: var(--cvs-text);
  font-family: var(--font-monospace);
  font-size: .72rem;
  text-align: right;
}

select.cv-settings-editor { cursor: pointer; }
textarea.cv-settings-editor { min-height: 112px; resize: vertical; line-height: 1.5; text-align: left; tab-size: 2; }
.cv-settings-editor.is-invalid { border-color: var(--cvs-error); }
.cv-settings-control-hint { flex: 0 0 auto; color: var(--cvs-faint); font-size: .55rem; }

.cv-settings-switch-wrap { display: flex; align-items: center; gap: 9px; }
.cv-settings-switch {
  position: relative;
  width: 42px;
  height: 24px;
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid var(--cvs-border-hover);
  border-radius: 999px;
  background: var(--background-modifier-border);
  box-shadow: none;
  cursor: pointer;
  transition: background-color .15s ease, border-color .15s ease;
}
.cv-settings-switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: transform .15s ease, background-color .15s ease;
}
.cv-settings-switch[aria-checked="true"] { border-color: color-mix(in srgb, var(--cvs-accent) 72%, var(--cvs-border-hover) 28%); background: color-mix(in srgb, var(--cvs-accent) 68%, var(--background-primary) 32%); }
.cv-settings-switch[aria-checked="true"]::after { transform: translateX(18px); background: var(--text-on-accent, white); }
.cv-settings-switch-state { min-width: 22px; color: var(--cvs-faint); font-family: var(--font-monospace); font-size: .59rem; }

.cv-settings-misc-guide {
  display: grid;
  grid-template-columns: minmax(210px, .85fr) minmax(300px, 1.15fr);
  gap: clamp(20px, 3cqi, 34px);
  margin: 16px 0 4px;
  padding: 18px 20px;
  border: 1px dashed color-mix(in srgb, var(--cvs-border-hover) 80%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--cvs-surface) 48%, transparent);
}

.cv-settings-misc-guide > div:first-child > span,
.cv-settings-custom-form-head span {
  display: block;
  color: var(--cvs-faint);
  font-size: .55rem;
  font-weight: 730;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.cv-settings-misc-guide > div:first-child > strong,
.cv-settings-custom-form-head strong { display: block; margin-top: 5px; color: var(--cvs-text); font-size: .76rem; }
.cv-settings-misc-guide p { margin: 7px 0 0; color: var(--cvs-muted); font-family: var(--font-interface); font-size: .69rem; line-height: 1.5; }

.cv-settings-misc-examples { display: grid; gap: 5px; align-content: center; }
.cv-settings-misc-examples > div {
  display: grid;
  grid-template-columns: minmax(110px, 1fr) minmax(120px, 1.1fr) auto;
  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 7px 9px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--cvs-surface-soft) 72%, transparent);
  color: var(--cvs-muted);
  font-size: .61rem;
}
.cv-settings-misc-examples code { overflow: hidden; color: var(--cvs-text); font-family: var(--font-monospace); text-overflow: ellipsis; white-space: nowrap; }
.cv-settings-misc-examples span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cv-settings-misc-examples small { color: var(--cvs-faint); font-size: .52rem; text-transform: uppercase; }

.cv-settings-custom-form {
  width: 100%;
  padding: 18px;
  border: 1px solid var(--cvs-border-hover);
  border-radius: 8px;
  background: color-mix(in srgb, var(--cvs-surface) 74%, transparent);
}

.cv-settings-custom-form-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.cv-settings-custom-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.cv-settings-custom-field { min-width: 0; display: grid; gap: 6px; color: var(--cvs-faint); font-size: .56rem; letter-spacing: .04em; }
.cv-settings-custom-field.is-wide { width: 100%; }

.cv-settings-custom-input {
  width: 100%;
  min-width: 0;
  min-height: 34px;
  padding: 7px 9px;
  border: 1px solid var(--cvs-border);
  border-radius: 5px;
  background: var(--background-primary);
  color: var(--cvs-text);
  font-family: var(--font-monospace);
  font-size: .69rem;
  letter-spacing: 0;
}

textarea.cv-settings-custom-input { min-height: 104px; resize: vertical; line-height: 1.45; }
.cv-settings-custom-value-field { margin-top: 12px; }
.cv-settings-custom-secret-shell { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; align-items: center; }
.cv-settings-custom-secret-actions { display: flex; gap: 4px; }
.cv-settings-custom-error { min-height: 1.2em; margin: 9px 0 0; color: var(--cvs-error); font-family: var(--font-interface); font-size: .66rem; }
.cv-settings-custom-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--cvs-border); }

.cv-settings-empty { padding: 42px 12px; color: var(--cvs-faint); font-size: .78rem; text-align: center; }

.cv-settings-footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 28px;
  padding: 14px 2px 0;
  border-top: 1px solid var(--cvs-border);
  color: var(--cvs-faint);
  font-size: .58rem;
}
.cv-settings-footer [data-role="settings-state"] { color: var(--cvs-muted); }
.cv-settings-footer [data-role="settings-state"].is-error { color: var(--cvs-error); }

@container (max-width: 820px) {
  .cv-settings-hero { align-items: start; flex-direction: column; }
  .cv-settings-shell { grid-template-columns: 1fr; gap: 22px; }
  .cv-settings-sidebar { position: static; }
  .cv-settings-sidebar-head,
  .cv-settings-sidebar-note { display: none; }
  .cv-settings-nav { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: thin; }
  .cv-settings-nav-button { width: auto; grid-template-columns: 16px auto auto; flex: 0 0 auto; border-color: var(--cvs-border); }
  .cv-settings-misc-guide { grid-template-columns: 1fr; }
}

@container (max-width: 640px) {
  .cv-settings { padding-inline: 16px; }
  .cv-settings-summary { width: 100%; grid-template-columns: repeat(3, 1fr); }
  .cv-settings-summary > span { min-width: 0; justify-items: start; }
  .cv-settings-row { grid-template-columns: 1fr; gap: 10px; padding-block: 16px; }
  .cv-settings-control { justify-content: flex-start; }
  .cv-settings-value,
  .cv-settings-editor { max-width: 100%; text-align: left; }
  .cv-settings-panel-head { align-items: start; }
  .cv-settings-panel-meta { align-items: flex-end; flex-direction: column; }
  .cv-settings-misc-examples > div { grid-template-columns: 1fr auto; }
  .cv-settings-misc-examples span { grid-column: 1 / -1; grid-row: 2; }
  .cv-settings-custom-grid { grid-template-columns: 1fr; }
  .cv-settings-custom-actions { flex-wrap: wrap; justify-content: flex-start; }
  .cv-settings-danger-button { width: 100%; margin-right: 0; }
  .cv-settings-footer { flex-direction: column; gap: 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .cv-settings-switch,
  .cv-settings-switch::after { transition-duration: .01ms !important; }
}

