const c = tp.container || this;
const root = c.querySelector('[data-role="settings-root"]');
if (root) {
  const app = tp.app, file = tp.file, doc = tp.activeDocument || root.ownerDocument, win = tp.activeWindow || doc.defaultView;
  const fm = { ...(tp.frontmatter || {}) }, META = "_settings_custom_meta";
  const hidden = new Set(["type", "cssclasses", "aliases", "tags", META]);
  const q = s => root.querySelector(s), obj = v => !!v && typeof v === "object" && !Array.isArray(v);
  const copyObj = v => obj(v) ? { ...v } : {};
  const el = (tag, cls, text) => { const n = doc.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; };

  const GROUPS = [
    ["general", "General", "Vault identity", "Identity and dates shared by vault-wide views.", "home"],
    ["daily", "Daily context", "Schedule sources", "Paths and headings used by Homepage and Journal daily snapshots.", "calendar"],
    ["weather", "Weather", "OpenWeatherMap", "Weather provider settings shared by Homepage and Journal.", "cloud"],
    ["services", "Media & recipes", "Metadata services", "Provider credentials and preferences used by media and recipe importers.", "sparkles"],
    ["games", "Games", "Game services", "RAWG, Steam and GOG metadata or platform-stat configuration.", "gamepad"],
    ["finance", "Finance & locale", "Finance defaults", "Book, currency, locale, fiscal calendar and budget defaults.", "wallet"],
    ["misc", "Misc", "Custom storage", "Keep additional vault-wide values here. Custom properties remain editable in Live Preview.", "box"],
    ["advanced", "Advanced", "Technical settings", "Known technical values that usually do not need frequent changes.", "sliders"],
  ].map(([id,label,kicker,description,icon]) => ({id,label,kicker,description,icon}));

  const months = ["January","February","March","April","May","June","July","August","September","October","November","December"]
    .map((label, i) => ({ value: i + 1, label: `${label} · ${i + 1}` }));
  const opt = pairs => pairs.map(([value,label]) => ({value,label}));
  const S = {
    vault_name:["general","Vault name","text","Display name used by vault-wide views and Obsidian links."],
    username:["general","Username","text","Name used in Homepage identity and greeting text."],
    start_date:["general","Vault start date","date","Reference date used to calculate vault age."],
    callout_path:["daily","Daily schedule folder","text","Folder containing the seven weekday schedule notes."],
    schedule_heading:["daily","Schedule heading","text","Heading parsed as the daily schedule table."],
    exercise_heading:["daily","Exercise heading","text","Heading parsed as the training or exercise table."],
    cardio_heading:["daily","Cardio heading","text","Heading parsed as the cardio table."],
